publish_settlement(target_id uuid):
declare
  existing_slug text;
  new_slug      text;
  state         jsonb;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  -- Trust-boundary gate (059): a banned/disabled/soft-deleted account cannot
  -- publish, even with a still-valid JWT.
  if not public.account_is_active(auth.uid()) then
    raise exception 'account is not active';
  end if;

  -- Owner check — the row must belong to the calling user.
  select public_slug, campaign_state into existing_slug, state
    from public.settlements
    where id = target_id and user_id = auth.uid();
  if not found then
    raise exception 'Not found or not owned by caller';
  end if;

  -- Canon gate (018, restored by 105): a settlement with a campaign lifecycle
  -- may only be shared once canonized. Mirrors the client's isCampaignCanonized:
  -- NULL campaign_state = no lifecycle = publishable.
  if state is not null
     and coalesce(state->>'phase', '') <> 'canon'
     and coalesce(state->>'canonizedAt', '') = ''
     and coalesce(state->'worldState'->>'canonizedAt', '') = ''
  then
    raise exception 'Only canonized settlements can be shared publicly';
  end if;

  if existing_slug is null then
    -- Mint a fresh slug; retry on the (vanishingly rare) collision.
    loop
      new_slug := public._make_public_slug();
      begin
        update public.settlements
          set is_public = true,
              public_slug = new_slug,
              published_at = now()
          where id = target_id;
        existing_slug := new_slug;
        exit;
      exception when unique_violation then
        -- spin until we get one
      end;
    end loop;
  else
    -- Re-publish (was unshared, now sharing again): keep the existing
    -- slug so old links continue to resolve.
    update public.settlements
      set is_public = true,
          published_at = now()
      where id = target_id;
  end if;

  return existing_slug;
end;

unpublish_settlement(target_id uuid):
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if not public.account_is_active(auth.uid()) then
    raise exception 'account is not active';
  end if;

  perform 1 from public.settlements
    where id = target_id and user_id = auth.uid();
  if not found then
    raise exception 'Not found or not owned by caller';
  end if;

  update public.settlements
    set is_public = false
    where id = target_id;
  -- Note: we deliberately keep public_slug and published_at so future
  -- re-publishes restore the same URL. Setting is_public=false alone
  -- makes the RLS policy stop returning the row to anon callers.
end;

_audit_action(p_actor_id uuid, p_target_:
begin
  insert into public.admin_actions
    (actor_id, target_id, action, before_value, after_value, reason)
  values
    (p_actor_id, p_target_id, p_action, p_before, p_after, p_reason);
end;

update_display_name(new_name text):
declare
  trimmed_name text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  trimmed_name := btrim(coalesce(new_name, ''));
  if length(trimmed_name) > 64 then
    raise exception 'display name too long (max 64 chars)';
  end if;
  -- 195: THE CIVILITY GUARD. The name is refused and NOTHING ELSE happens to the
  -- account — no lockout, no strike, no shadow penalty. The guard rejects a
  -- string, never a person.
  if public.civility_blocked(trimmed_name) then
    raise exception 'That name can''t be used here. Think this is wrong? Feedback & support.';
  end if;
  if trimmed_name = '' then
    trimmed_name := null;
  end if;

  update public.profiles
    set display_name = trimmed_name,
        updated_at   = now()
    where id = auth.uid();

  return trimmed_name;
end;

admin_grant_credits(target_user uuid, am:
declare
  new_balance integer;
begin
  if not public.current_user_is_privileged() then
    raise exception 'not authorized';
  end if;
  if amount <= 0 then
    raise exception 'amount must be positive';
  end if;
  if amount > 10000 then
    raise exception 'amount exceeds per-call limit (10000)';
  end if;

  insert into public.credit_ledger (user_id, kind, amount, source, metadata)
    values (target_user, 'grant', amount, 'admin_grant', jsonb_build_object('reason', reason));

  insert into public.credit_transactions (user_id, amount, reason)
    values (target_user, amount, 'admin_grant');

  update public.profiles
    set credits = credits + amount,
        updated_at = now()
    where id = target_user
    returning credits into new_balance;

  perform public._audit_action(
    auth.uid(),
    target_user,
    'grant_credits',
    null,
    jsonb_build_object('amount', amount, 'new_balance', new_balance),
    reason
  );

  return new_balance;
end;

admin_set_role(target_user uuid, new_rol:
declare
  old_role text;
begin
  if not public.current_user_is_privileged() then
    raise exception 'not authorized';
  end if;
  if new_role not in ('user', 'developer', 'admin') then
    raise exception 'invalid role: %', new_role;
  end if;

  select role into old_role from public.profiles where id = target_user;

  update public.profiles
    set role = new_role, updated_at = now()
    where id = target_user;

  perform public._audit_action(
    auth.uid(),
    target_user,
    'set_role',
    jsonb_build_object('role', old_role),
    jsonb_build_object('role', new_role),
    null
  );

  return new_role;
end;

founder_seats_taken():
