set_curated(target_id uuid, curated bool:
declare
  caller_role text;
  before_state jsonb;
begin
  -- Gate: only developer / admin roles can curate.
  select role into caller_role
    from public.profiles
    where id = auth.uid();

  if caller_role not in ('developer', 'admin') then
    raise exception 'Only admins can change curation status';
  end if;

  -- Capture before-state for the audit log.
  select jsonb_build_object(
    'is_curated', is_curated,
    'curated_order', curated_order,
    'name', name
  ) into before_state
    from public.settlements
    where id = target_id;

  if before_state is null then
    raise exception 'Settlement not found';
  end if;

  -- Apply the change. If marking as curated, the row must also be public.
  if curated then
    update public.settlements
      set is_curated    = true,
          curated_order = sort_order
      where id = target_id and is_public = true;
    if not found then
      raise exception 'Cannot curate a non-public settlement. Publish it first.';
    end if;
  else
    update public.settlements
      set is_curated    = false,
          curated_order = null
      where id = target_id;
  end if;

  -- Audit log entry via the existing _audit_action helper. The
  -- admin_actions table's target_id column references auth.users(id),
  -- so we can't put a settlement_id there directly — instead we pass
  -- target_id=NULL and store the settlement context inside the
  -- before/after JSON payloads (with the settlement id explicit).
  perform public._audit_action(
    auth.uid(),
    null,
    case when curated then 'gallery_curate' else 'gallery_uncurate' end,
    before_state || jsonb_build_object('settlement_id', target_id),
    jsonb_build_object(
      'settlement_id', target_id,
      'is_curated',    curated,
      'curated_order', sort_order
    ),
    null
  );
end;

enforce_save_limit():
declare
  user_tier text;
  user_role text;
  save_count integer;
  save_limit integer;
begin
  select tier, role into user_tier, user_role
    from public.profiles where id = new.user_id;

  if auth.uid() is not null and new.user_id is distinct from auth.uid() then
    raise exception 'cannot save a settlement for another user';
  end if;
  if coalesce(new.access_state, 'active') <> 'active'
     and coalesce(current_setting('request.jwt.claim.role', true), auth.role()) <> 'service_role' then
    raise exception 'new settlements must be active';
  end if;
  if user_role in ('developer', 'admin') then return new; end if;

  save_limit := case user_tier
    when 'premium' then null
    when 'cartographer' then null
    when 'founder' then null
    else 3
  end;
  if save_limit is null or coalesce(new.access_state, 'active') <> 'active' then
    return new;
  end if;

  -- Serialize concurrent inserts for the SAME user so the count-then-insert
  -- below can't race two parallel saves past the limit (TOCTOU). The lock is
  -- released at transaction end.
  perform pg_advisory_xact_lock(hashtext('save_limit:' || new.user_id::text));

  select count(*)::integer into save_count
    from public.settlements
    where user_id = new.user_id and access_state = 'active';
  if save_count >= save_limit then
    raise exception 'save limit reached: % allows % active saves. Upgrade for unlimited saves.',
      coalesce(user_tier, 'free'), save_limit;
  end if;
  return new;
end;

