welcome_credit_available(target_user uui:
declare
  welcome_created_at timestamptz;
  current_balance integer;
begin
  if auth.uid() is null then
    return false;
  end if;
  if target_user is null then
    return false;
  end if;
  if auth.uid() <> target_user and not public.current_user_is_privileged() then
    raise exception 'not authorized';
  end if;

  select cl.created_at into welcome_created_at
  from public.credit_ledger cl
  where cl.user_id = target_user
    and cl.kind = 'grant'
    and cl.source = 'welcome'
  order by cl.created_at asc
  limit 1;

  if welcome_created_at is null then
    return false;
  end if;

  if exists (
    select 1
    from public.credit_ledger cl
    where cl.user_id = target_user
      and cl.kind = 'spend'
      and cl.source in ('narrative', 'dailyLife', 'daily_life', 'progression')
      and cl.created_at >= welcome_created_at
  ) then
    return false;
  end if;

  select public.get_credit_balance(target_user) into current_balance;
  return coalesce(current_balance, 0) > 0;
end;

_assert_service_admin_actor(actor_user u:
declare
  caller_role text;
  actor_role text;
begin
  caller_role := current_setting('request.jwt.claim.role', true);
  if caller_role is null then
    caller_role := auth.role();
  end if;
  if caller_role <> 'service_role' then
    raise exception 'service role required (got: %)', caller_role;
  end if;

  select role into actor_role
  from public.profiles
  where id = actor_user;

  if actor_role not in ('developer', 'admin') then
    raise exception 'actor is not privileged';
  end if;
end;

service_update_profile_metadata(actor_us:
declare
  before_row jsonb;
  after_row jsonb;
  patch_keys text[];
  bad_keys text[];
  new_role text;
  new_tier text;
begin
  perform public._assert_service_admin_actor(actor_user);

  if target_user is null then
    raise exception 'target_user is required';
  end if;
  if profile_patch is null or jsonb_typeof(profile_patch) <> 'object' then
    raise exception 'profile_patch must be a JSON object';
  end if;

  select array_agg(key order by key) into patch_keys
  from jsonb_object_keys(profile_patch) as keys(key);

  select array_agg(key order by key) into bad_keys
  from jsonb_object_keys(profile_patch) as keys(key)
  where key not in ('role', 'tier', 'display_name', 'is_founder');

  if bad_keys is not null then
    raise exception 'unsupported profile metadata keys: %', array_to_string(bad_keys, ', ');
  end if;

  if profile_patch ? 'role' then
    new_role := profile_patch->>'role';
    if new_role not in ('user', 'developer', 'admin') then
      raise exception 'invalid role: %', new_role;
    end if;
  end if;

  if profile_patch ? 'tier' then
    new_tier := profile_patch->>'tier';
    if new_tier not in ('free', 'premium') then
      raise exception 'invalid tier: %', new_tier;
    end if;
  end if;

  if profile_patch ? 'is_founder'
     and jsonb_typeof(profile_patch->'is_founder') <> 'boolean' then
    raise exception 'is_founder must be boolean';
  end if;

  select to_jsonb(p.*) into before_row
  from public.profiles p
  where p.id = target_user;

  if before_row is null then
    raise exception 'target profile not found';
  end if;

  update public.profiles
    set role = case when profile_patch ? 'role' then new_role else role end,
        tier = case when profile_patch ? 'tier' then new_tier else tier end,
        display_name = case
          when profile_patch ? 'display_name' then nullif(btrim(profile_patch->>'display_name'), '')
          else display_name
        end,
        is_founder = case
          when profile_patch ? 'is_founder' then (profile_patch->>'is_founder')::boolean
          else is_founder
        end,
        updated_at = now()
    where id = target_user;

  select to_jsonb(p.*) into after_row
  from public.profiles p
  where p.id = target_user;

  insert into public.admin_actions
    (actor_id, target_id, action, before_value, after_value, reason)
  values
    (
      actor_user,
      target_user,
      'update_user_metadata',
      before_row,
      jsonb_build_object('patch', profile_patch, 'profile', after_row, 'keys', coalesce(patch_keys, array[]::text[])),
      reason
    );

  return jsonb_build_object('before', before_row, 'after', after_row);
end;

service_set_credits(actor_user uuid, tar:
declare
  prev_credits integer;
  delta integer;
  after_row jsonb;
begin
  perform public._assert_service_admin_actor(actor_user);

  if target_user is null then
    raise exception 'target_user is required';
  end if;
  if new_credits is null or new_credits < 0 then
    raise exception 'new_credits must be a non-negative integer';
  end if;
  if new_credits > 100000 then
    raise exception 'new_credits exceeds per-call limit (100000)';
  end if;

  -- 103: lock the row (spend_credits takes the same lock first) so the
  -- read-compute-write below cannot interleave with a concurrent user spend.
  perform 1 from public.profiles where id = target_user for update;
  if not found then
    raise exception 'target profile not found';
  end if;

  -- 103: ledger truth, not the legacy cached counter — so the ledger row
  -- written below is the TRUE delta even when the cache has drifted (e.g. an
  -- expired grant the cache never learned about).
  prev_credits := public.get_credit_balance(target_user);

  delta := new_credits - prev_credits;

  if delta <> 0 then
    insert into public.credit_ledger (user_id, kind, amount, source, metadata)
    values (
      target_user,
      case when delta > 0 then 'grant' else 'spend' end,
      abs(delta),
      'admin_set',
      jsonb_build_object(
        'admin_actor', actor_user,
        'previous_balance', prev_credits,
        'new_balance', new_credits,
        'reason', reason
      )
    );

    insert into public.credit_transactions (user_id, amount, reason)
    values (target_user, delta, 'admin_set');
  end if;

  update public.profiles p
    set credits = new_credits,
        updated_at = now()
    where p.id = target_user
    returning to_jsonb(p.*) into after_row;

  insert into public.admin_actions
    (actor_id, target_id, action, before_value, after_value, reason)
  values
    (
      actor_user,
      target_user,
      'admin_set_credits',
      jsonb_build_object('credits', prev_credits),
      jsonb_build_object('credits', new_credits, 'delta', delta, 'profile', after_row),
      reason
    );

  return jsonb_build_object('prev', prev_credits, 'next', new_credits, 'delta', delta);
end;

toggle_gallery_vote(target_settlement_id:
begin
  if auth.uid() is null then
    raise exception 'Sign in to vote';
  end if;
  if not public.account_is_active(auth.uid()) then
    raise exception 'account is not active';
  end if;

  -- Velocity guard (125): at most 60 accepted toggles/hour/user. Wire-speed
  -- toggling is bot behaviour; a human votes a handful of times.
  if public._consume_action_rate_limit(auth.uid(), 'gallery_vote', 3600) > 60 then
    raise exception 'You are voting too quickly — please slow down and try again shortly.';
  end if;

  perform 1 from public.settlements
    where id = target_settlement_id and is_public = true;
  if not found then
    raise exception 'Settlement is not public';
  end if;

  if exists (
    select 1 from public.gallery_votes
    where settlement_id = target_settlement_id and user_id = auth.uid()
  ) then
    delete from public.gallery_votes
      where settlement_id = target_settlement_id and user_id = auth.uid();
    return query
      select count(*)::integer, false
      from public.gallery_votes
      where settlement_id = target_settlement_id;
  else
    insert into public.gallery_votes(settlement_id, user_id)
      values (target_settlement_id, auth.uid())
      on conflict do nothing;
    return query
      select count(*)::integer, true
      from public.gallery_votes
      where settlement_id = target_settlement_id;
  end if;
end;

add_gallery_comment(target_settlement_id:
declare
  comment_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Sign in to comment';
  end if;
  if not public.account_is_active(auth.uid()) then
    raise exception 'account is not active';
  end if;

  -- Velocity guard (125): at most 20 accepted comments/hour/user. Comment storage
  -- is otherwise unbounded (the display list caps at 100 but the rows persist);
  -- 20/hour is generous for a human and useless as a flood vector.
  if public._consume_action_rate_limit(auth.uid(), 'gallery_comment', 3600) > 20 then
    raise exception 'You are commenting too quickly — please slow down and try again shortly.';
  end if;

  if char_length(trim(coalesce(comment_body, ''))) < 1 then
    raise exception 'Comment cannot be empty';
  end if;
  if char_length(trim(comment_body)) > 2000 then
    raise exception 'Comment is too long';
  end if;

  -- 195: THE CIVILITY GUARD. Checked AFTER the cheap length gates and BEFORE the
  -- settlement lookup, so a refused comment costs one function call and touches
  -- no other row. The rate-limit consume above already happened, which is
  -- correct: a client hammering the endpoint with refused text is still traffic.
  if public.civility_blocked(comment_body) then
    raise exception 'That comment can''t be posted. Think this is wrong? Feedback & support.';
  end if;

  perform 1 from public.settlements
    where id = target_settlement_id and is_public = true;
  if not found then
    raise exception 'Settlement is not public';
  end if;

  insert into public.gallery_comments(settlement_id, user_id, body)
    values (target_settlement_id, auth.uid(), trim(comment_body))
    returning id into comment_id;
  return comment_id;
end;

delete_gallery_comment(target_comment_id:
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if not public.account_is_active(auth.uid()) then
    raise exception 'account is not active';
  end if;

  update public.gallery_comments
    set deleted_at = now(), updated_at = now()
    where id = target_comment_id and user_id = auth.uid() and deleted_at is null;
  if not found then
    raise exception 'Comment not found or not owned by caller';
  end if;
end;

_gallery_sanitize_public_json(value json:
declare
  key text;
  child jsonb;
  sanitized jsonb;
  out jsonb;
  is_toplevel boolean;
  is_npc_obj boolean;
  -- 206: the card's veil bit, read once per NPC object
  house_is_object boolean;
  house_is_public boolean;
  -- 206 (second seat): the root pass's two sets, read from the ORIGINAL record
  hidden_names text[];
  veiled_ids text[];
  txt text;
  -- R5 (2026-11-10): the mask's walk — one string leaf at a time
  leaf_path text[];
  leaf_text text;
  masked text;
  -- ══ PUBLIC TOP-LEVEL ALLOWLIST ══
  -- Character-identical (order-independent) to publicSafe.js PUBLIC_TOPLEVEL_KEYS.
  -- tests/security/gallerySanitizeAllowlist.contract.test.js parses the NET-CURRENT
  -- literal and pins it to the JS twin — the drift pin. (123/128/130/142/189's list;
  -- 205 drops 'factions', the people car's retired NPC grouping; 206 leaves it as 205's.)
  public_toplevel constant text[] := array[
    'activeConditions','arrivalScene','availableServices','coherenceNotes','config',
    'conflicts','crossSettlementConflicts','dailyLife','defenseProfile','economicState',
    'economicViability','generatorVersion','history','id',
    'institutions','interSettlementRelationships','name','neighborRelationship','neighbourNetwork',
    'npcs','population','populationHistory','powerStructure','pressureSentence',
    'prominentRelationship','relationships','resourceAnalysis','schemaVersion','settlementReason',
    'simulationVersion','spatialLayout','stress','stressors','structuralSuggestions',
    'structuralViolations','thesis','tier','publicProse'
  ];
  -- Mirrors src/domain/display/publicSafe.js publicNpc() / NPC_PUBLIC_KEYS (033;
  -- 205 drops 'factionAffiliation','secondaryAffiliation', the people car's retired
  -- per-NPC faction fields).
  npc_allowed constant text[] := array[
    'id','name','role','title','category','personality','physical',
    'presentation','influence'
  ];
  -- 206: THE VEIL BIT. Character-identical to publicSafe.js NPC_HOUSE_KEYS: public on an
  -- NPC object only where its `institution` is an object with `veiled` = JSON false.
  npc_house_keys constant text[] := array['institution','memberships'];
  -- 206: character-identical to publicSafe.js NPC_HOUSE_NAMED_KEYS: stripped on an NPC
  -- object whose `institution` is an object with `veiled` true or absent (fail-closed).
  npc_house_named constant text[] := array['title','role'];
begin
  if value is null then
    return null;
  end if;

  if jsonb_typeof(value) = 'object' then
    -- The settlement ROOT is the only object reached with an empty path.
    is_toplevel := array_length(path, 1) is null;
    -- True when this object must take the NPC field allowlist: a direct element
    -- of an `npcs` array (parent key 'npcs') OR — 189 — a roster member (parent
    -- key 'members' with a 'factions' ancestor anywhere above). 205: the retired
    -- grouping `factions[].members[]` is no longer reached (its top-level key left
    -- the allowlist above); the arm is KEPT for a roster under a deeper 'factions'
    -- ancestor (powerStructure.factions[].members — no generator writes one, a DM
    -- edit or a legacy record may), fail-closed: such a member takes the SAME
    -- public reduction as npcs[].
    is_npc_obj := array_length(path, 1) is not null
              and (path[array_length(path, 1)] = 'npcs'
                   or (path[array_length(path, 1)] = 'members'
                       and 'factions' = any(path)));
    -- COVERT DROP (142, W-DOCTRINE-3 §6): an object explicitly flagged covert:true is
    -- hidden DM state (e.g. a covert corruption impairment on institutions[].impairments
    -- whose description NAMES the corrupted NPC). Drop the WHOLE object — returning null
    -- removes it from both a parent object and a parent array. Stripping only the
    -- `covert` key would leave the naming description exposed. Non-root only (a settlement
    -- root is never covert; the client covert-checks nested objects only). Mirrors
    -- publicSafe.js sanitizePublicValue.
    if not is_toplevel and (value -> 'covert') = 'true'::jsonb then
      return null;
    end if;
    -- 206: THE VEIL BIT, read (never re-derived) on an NPC object. A card with no
    -- institution RECORD — an object of kind 'house' | 'power' naming its house by `key`
    -- (or `name`), as the client's people/cardPowers.js :: cardInstitutionOf reads it — is
    -- a pre-car card, a DM's person or a malformed value, and takes npc_allowed as at 205.
    -- coalesce: an ABSENT `veiled` (or key) reads NULL, and NULL must never pass for public.
    house_is_object := coalesce(
      is_npc_obj
      and jsonb_typeof(value -> 'institution') = 'object'
      and (value -> 'institution' ->> 'kind') in ('house', 'power')
      and coalesce(nullif(value -> 'institution' ->> 'key', ''), nullif(value -> 'institution' ->> 'name', '')) is not null,
      false);
    house_is_public := coalesce(house_is_object and (value -> 'institution' -> 'veiled') = 'false'::jsonb, false);
    out := '{}'::jsonb;
    for key, child in select * from jsonb_each(value) loop
      -- TOP LEVEL: allowlist (fail closed). An unknown/future top-level key is
      -- dropped even if it misses the denylist — the whole point of the flip.
      if is_toplevel and not (key = any(public_toplevel)) then
        continue;
      end if;
      -- DEEPER LEVELS: keep the recursive DM-private denylist (defense-in-depth
      -- for private keys nested inside an allowed subtree). dm/gm use word
      -- boundaries (\m) so they match dmNotes/gm* but NOT landmarks/admin. `seed`
      -- (bare, conservative) + `_config` kill the generation seed / raw config at
      -- ANY depth — critical because `config` is allowlisted at top level, so
      -- config._seed would otherwise ride through (matches 099's denylist). 128:
      -- `latentPantheon` kills the UNREVEALED starting-pantheon channel (Phase 4
      -- premium gate) — config.latentPantheon would otherwise ride through the same
      -- allowlisted `config`. The ACTIVATED embeds carry no such key and stay.
      -- 130: the note token is NARROWED to the genuinely-private note keys
      -- (dossierNotes|tabNotes|\ynotes?\y) so public economics-attribution notes
      -- (magicFoodNote / upstreamNote / storageNote — no \y before "Note") survive,
      -- while dmNotes (\m(dm|gm)) / narrativeNotes (explicit) / a bare notes field
      -- still strip.
      if not is_toplevel and key ~* '(secret|private|\m(dm|gm)|guidance|dossierNotes|tabNotes|\ynotes?\y|plotHook|plot_hooks|hook|compass|chronicle|pinnedNpc|aiData|aiSettlement|aiDailyLife|narrativeNotes|identityMarkers|frictionPoints|connectionsMap|latentPantheon|seed|_config)' then
        continue;
      end if;
      -- NPC objects (npcs[] elements AND — 189 — roster members under a 'factions'
      -- ancestor): keep ONLY the public allowlist (033's list less 205's two keys).
      -- 206: the per-row house rule. NPC_HOUSE_KEYS ride only on a public house; a
      -- veiled (or unstamped) house's face loses its title and role too.
      if is_npc_obj and key = any(npc_house_keys) then
        if not house_is_public then
          continue;
        end if;
      elsif is_npc_obj and house_is_object and not house_is_public and key = any(npc_house_named) then
        continue;
      elsif is_npc_obj and not (key = any(npc_allowed)) then
        continue;
      end if;

      sanitized := public._gallery_sanitize_public_json(child, path || key);
      -- 206: THE SAME LAW PER ENTRY (the chair's ruling). On a public house, a membership rides only
      -- where its OWN `veiled` is the JSON false; an entry stamped true or not stamped is dropped, and
      -- a `memberships` that is not an array is dropped whole (fail-closed). Order is kept.
      if is_npc_obj and key = 'memberships' then
        if jsonb_typeof(sanitized) is distinct from 'array' then
          continue;
        end if;
        select coalesce(jsonb_agg(entry order by ord), '[]'::jsonb) into sanitized
          from jsonb_array_elements(sanitized) with ordinality as entries(entry, ord)
         where coalesce((entry -> 'veiled') = 'false'::jsonb, false);
      end if;
      if sanitized is not null then
        out := out || jsonb_build_object(key, sanitized);
      end if;
    end loop;
    -- 206 (second seat): THE ROOT PASS. The hidden powers' names (each row's own stamped
    -- `hidden`) and the veiled faces' ids (each card's own bit, by the house-record test
    -- above, stamped true or absent), from the ORIGINAL record.
    if is_toplevel then
      select coalesce(array_agg(distinct nm), '{}') into hidden_names
        from jsonb_array_elements(case when jsonb_typeof(value -> 'powerStructure' -> 'factions') = 'array'
                                       then value -> 'powerStructure' -> 'factions' else '[]'::jsonb end) as f(row)
             cross join lateral (values (row ->> 'faction')) as n(nm)
       where jsonb_typeof(row) = 'object' and (row -> 'hidden') = 'true'::jsonb
         -- R11 (2026-11-10): blank is ONE explicit class, the same as the client's (JavaScript's \s set):
         -- a name made only of these characters (a no-break space included) masks nothing.
         and nm is not null and nm ~ '[^ \t\n\r\f\v   -     　﻿]';
      select coalesce(array_agg(n ->> 'id'), '{}') into veiled_ids
        from jsonb_array_elements(case when jsonb_typeof(value -> 'npcs') = 'array'
                                       then value -> 'npcs' else '[]'::jsonb end) as t(n)
       where jsonb_typeof(n) = 'object'
         and (n ->> 'id') is not null
         and jsonb_typeof(n -> 'institution') = 'object'
         and (n -> 'institution' ->> 'kind') in ('house', 'power')
         and coalesce(nullif(n -> 'institution' ->> 'key', ''), nullif(n -> 'institution' ->> 'name', '')) is not null
         and not coalesce((n -> 'institution' -> 'veiled') = 'false'::jsonb, false);
      -- a veiled face's title by its ties: the `from` end's npc1Role, the `to` end's npc2Role
      if coalesce(array_length(veiled_ids, 1), 0) > 0 and jsonb_typeof(out -> 'relationships') = 'array' then
        out := jsonb_set(out, '{relationships}', (
          select coalesce(jsonb_agg(
                   case when jsonb_typeof(r) = 'object' then
                     (case when coalesce((r ->> 'from') = any(veiled_ids), false) then r - 'npc1Role' else r end)
                     - (case when coalesce((r ->> 'to') = any(veiled_ids), false) then 'npc2Role' else '' end)
                   else r end
                   order by ord), '[]'::jsonb)
            from jsonb_array_elements(out -> 'relationships') with ordinality as t(r, ord)));
      end if;
      -- 207 (ALLEGIANCE-CAR2, J-20): THE HALL'S HOLD IS DM-ONLY. The capture state is derived from the ruling three's
      -- HIDDEN allegiances, so the public page carries none of it: `criminalCaptureState` leaves the power structure,
      -- the governing row's `captureState` seed leaves every power row, and every relation row that carries a
      -- `captureState` or is typed 'corrupted' is DROPPED whole (never re-typed). Character for character the client's
      -- publicSafe.js :: publicVeilPass.
      if jsonb_typeof(out -> 'powerStructure') = 'object' then
        out := jsonb_set(out, '{powerStructure}', (out -> 'powerStructure') - 'criminalCaptureState');
        if jsonb_typeof(out -> 'powerStructure' -> 'factions') = 'array' then
          out := jsonb_set(out, '{powerStructure,factions}', (
            select coalesce(jsonb_agg(case when jsonb_typeof(f) = 'object' then f - 'captureState' else f end order by ord), '[]'::jsonb)
              from jsonb_array_elements(out -> 'powerStructure' -> 'factions') with ordinality as t(f, ord)));
        end if;
        if jsonb_typeof(out -> 'powerStructure' -> 'factionRelationships') = 'array' then
          out := jsonb_set(out, '{powerStructure,factionRelationships}', (
            select coalesce(jsonb_agg(r order by ord), '[]'::jsonb)
              from jsonb_array_elements(out -> 'powerStructure' -> 'factionRelationships') with ordinality as t(r, ord)
             where not coalesce(jsonb_typeof(r) = 'object'
                        and ((r ? 'captureState') or (r ->> 'type') = 'corrupted'), false)));
        end if;
      end if;
      -- the hidden power's own row leaves the powers (another row naming it — a niche contest, a
      -- description — keeps its key and has the name masked below). R5 (2026-11-10): OUTSIDE the
      -- name check, so a row stamped hidden whose `faction` is missing or empty leaves too.
      if jsonb_typeof(out -> 'powerStructure' -> 'factions') = 'array' then
        out := jsonb_set(out, '{powerStructure,factions}', (
          select coalesce(jsonb_agg(f order by ord), '[]'::jsonb)
            from jsonb_array_elements(out -> 'powerStructure' -> 'factions') with ordinality as t(f, ord)
           where not coalesce(jsonb_typeof(f) = 'object'
                      and (coalesce((f -> 'hidden') = 'true'::jsonb, false)
                           or coalesce((f ->> 'faction') = any(hidden_names), false)), false)));
      end if;
      if coalesce(array_length(hidden_names, 1), 0) > 0 then
        -- every conflict whose parties name a hidden power, at both homes
        foreach key in array array['conflicts', 'powerStructure.conflicts'] loop
          if jsonb_typeof(out #> string_to_array(key, '.')) = 'array' then
            out := jsonb_set(out, string_to_array(key, '.'), (
              select coalesce(jsonb_agg(c order by ord), '[]'::jsonb)
                from jsonb_array_elements(out #> string_to_array(key, '.')) with ordinality as t(c, ord)
               where not coalesce(jsonb_typeof(c) = 'object'
                          and jsonb_typeof(c -> 'parties') = 'array'
                          and exists (select 1 from jsonb_array_elements_text(c -> 'parties') as p(party)
                                       where p.party = any(hidden_names)), false)));
          end if;
        end loop;
        -- the crisis cast's stakes naming a hidden power, at both stress homes (one entry, or an array)
        foreach key in array array['stress', 'stressors'] loop
          if jsonb_typeof(out -> key) = 'object' and jsonb_typeof(out -> key -> 'cast' -> 'stakes') = 'array' then
            out := jsonb_set(out, array[key, 'cast', 'stakes'], (
              select coalesce(jsonb_agg(st order by ord), '[]'::jsonb)
                from jsonb_array_elements(out -> key -> 'cast' -> 'stakes') with ordinality as t(st, ord)
               where not coalesce(jsonb_typeof(st) = 'object' and (st ->> 'factionId') = any(hidden_names), false)));
          elsif jsonb_typeof(out -> key) = 'array' then
            out := jsonb_set(out, array[key], (
              select coalesce(jsonb_agg(
                       case when jsonb_typeof(e) = 'object' and jsonb_typeof(e -> 'cast' -> 'stakes') = 'array' then
                         jsonb_set(e, '{cast,stakes}', (
                           select coalesce(jsonb_agg(st order by so), '[]'::jsonb)
                             from jsonb_array_elements(e -> 'cast' -> 'stakes') with ordinality as s2(st, so)
                            where not coalesce(jsonb_typeof(st) = 'object' and (st ->> 'factionId') = any(hidden_names), false)))
                       else e end
                       order by eo), '[]'::jsonb)
                from jsonb_array_elements(out -> key) with ordinality as t(e, eo)));
          end if;
        end loop;
        -- last: the name anywhere else a public string VALUE carries it, masked. R5 (2026-11-10): the
        -- document is WALKED — every string leaf, at any depth, by its path — and each leaf is masked
        -- as text and set back as a JSON string; a key is never touched, nor the settlement's own
        -- top-level `name`. (206/207 replaced over the JSON text, which raised on a name matching
        -- text outside a string and rewrote a key equal to a name.)
        for leaf_path, leaf_text in
          with recursive walk(p, v) as (
            select array[]::text[], out
            union all
            select w.p || e.k, e.v
              from walk w
              cross join lateral (
                select o.key as k, o.value as v
                  from jsonb_each(case when jsonb_typeof(w.v) = 'object' then w.v else '{}'::jsonb end) as o
                union all
                select (a.ord - 1)::text, a.el
                  from jsonb_array_elements(case when jsonb_typeof(w.v) = 'array' then w.v else '[]'::jsonb end)
                       with ordinality as a(el, ord)
              ) as e
          )
          select p, v #>> '{}' from walk
           where jsonb_typeof(v) = 'string' and p is distinct from array['name']
             -- R11 (2026-11-10): an identifier and the prose format tag are never text to mask
             -- (a hidden power named "1" rewrote every id and `publicProse.v`).
             and p[cardinality(p)] is distinct from 'id'
             and p is distinct from array['publicProse', 'v']
        loop
          masked := leaf_text;
          foreach txt in array hidden_names loop
            masked := replace(masked, txt, 'an unseen interest');
          end loop;
          if masked is distinct from leaf_text then
            out := jsonb_set(out, leaf_path, to_jsonb(masked));
          end if;
        end loop;
      end if;
    end if;
    return out;
  end if;

  if jsonb_typeof(value) = 'array' then
    out := '[]'::jsonb;
    for child in select jsonb_array_elements(value) loop
      sanitized := public._gallery_sanitize_public_json(child, path);
      if sanitized is not null then
        out := out || jsonb_build_array(sanitized);
      end if;
    end loop;
    return out;
  end if;

  return value;
end;

report_gallery_dossier(target_settlement:
declare
  report_id uuid;
  clean_reason text := left(trim(coalesce(report_reason, 'other')), 80);
  clean_body text := left(trim(coalesce(report_body, '')), 2000);
begin
  if auth.uid() is null then
    raise exception 'Sign in to report a dossier';
  end if;
  if not public.account_is_active(auth.uid()) then
    raise exception 'account is not active';
  end if;
  if clean_reason = '' then
    clean_reason := 'other';
  end if;

  perform 1 from public.settlements
    where id = target_settlement_id and is_public = true;
  if not found then
    raise exception 'Settlement is not public';
  end if;

  insert into public.gallery_reports(settlement_id, user_id, reason, body, status)
    values (target_settlement_id, auth.uid(), clean_reason, clean_body, 'open')
    on conflict (settlement_id, user_id)
    do update set
      reason = excluded.reason,
      body = excluded.body,
      status = 'open',
      updated_at = now()
    returning id into report_id;

  return report_id;
end;

resolve_gallery_report(target_report_id:
declare
  before_state jsonb;
  clean_status text := lower(trim(coalesce(next_status, 'resolved')));
  clean_note text := left(trim(coalesce(resolution_note, '')), 2000);
begin
  if not public.current_user_is_privileged() then
    raise exception 'Only admins can resolve gallery reports';
  end if;

  if clean_status not in ('open', 'resolved', 'dismissed') then
    raise exception 'Invalid report status: %', clean_status;
  end if;

  select to_jsonb(r) into before_state
    from public.gallery_reports r
    where r.id = target_report_id;

  if before_state is null then
    raise exception 'Report not found';
  end if;

  update public.gallery_reports
    set status = clean_status,
        resolved_at = case when clean_status = 'open' then null else now() end,
        resolved_by = case when clean_status = 'open' then null else auth.uid() end,
        resolution_note = case when clean_status = 'open' then '' else clean_note end,
        updated_at = now()
    where id = target_report_id;

  perform public._audit_action(
    auth.uid(),
    null,
    'gallery_report_' || clean_status,
    before_state,
    jsonb_build_object(
      'report_id', target_report_id,
      'status', clean_status,
      'resolution_note', clean_note
    ),
    clean_note
  );
end;

handle_premium_downgrade(target_user uui:
declare
  expires_at timestamptz := now() + interval '3 months';
  settlement_count integer := 0;
  campaign_count integer := 0;
  founder boolean := false;
begin
  if target_user is null then raise exception 'target_user is required'; end if;
  select coalesce(is_founder, false) into founder from public.profiles where id = target_user;
  if founder then
    return jsonb_build_object('ok', true, 'inactive_count', 0, 'inactive_campaign_count', 0, 'founder', true);
  end if;

  update public.profiles
    set tier = 'free', premium_downgraded_at = now(), premium_retention_expires_at = expires_at
    where id = target_user and coalesce(is_founder, false) = false;

  update public.settlements
    set access_state = 'inactive_plan', inactive_reason = 'premium_downgrade',
        inactive_since = coalesce(inactive_since, now()),
        retention_expires_at = coalesce(retention_expires_at, expires_at),
        reactivated_free_at = null
    where user_id = target_user and access_state = 'active';
  get diagnostics settlement_count = row_count;

  update public.saved_maps
    set access_state = 'inactive_plan', inactive_reason = 'premium_downgrade',
        inactive_since = coalesce(inactive_since, now()),
        retention_expires_at = coalesce(retention_expires_at, expires_at)
    where user_id = target_user and access_state = 'active';
  get diagnostics campaign_count = row_count;

  return jsonb_build_object(
    'ok', true, 'inactive_count', settlement_count,
    'inactive_campaign_count', campaign_count, 'retention_expires_at', expires_at
  );
end;

reactivate_free_settlement(target_settle:
declare
  owner_id uuid;
  owner_tier text;
  active_count integer;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  select user_id into owner_id
    from public.settlements
    where id = target_settlement_id
    for update;

  if owner_id is null or owner_id <> auth.uid() then
    raise exception 'settlement not found';
  end if;

  select tier into owner_tier from public.profiles where id = auth.uid();
  if owner_tier <> 'free' then
    raise exception 'reactivation is only needed for free accounts';
  end if;

  select count(*)::integer into active_count
    from public.settlements
    where user_id = auth.uid()
      and access_state = 'active';

  if active_count >= 3 then
    return jsonb_build_object('ok', false, 'reason', 'free_limit_reached', 'active_count', active_count);
  end if;

  update public.settlements
    set access_state = 'active',
        inactive_reason = null,
        inactive_since = null,
        retention_expires_at = null,
        reactivated_free_at = now()
    where id = target_settlement_id
      and user_id = auth.uid();

  return jsonb_build_object('ok', true, 'active_count', active_count + 1);
end;

restore_premium_settlements(target_user:
declare
  settlement_count integer := 0;
  campaign_count integer := 0;
begin
  if target_user is null then
    raise exception 'target_user is required';
  end if;

  perform 1
    from public.profiles
   where id = target_user
   for update;
  if not found or not public.account_is_active(target_user) then
    raise exception 'inactive_target_account';
  end if;

  update public.profiles
     set premium_downgraded_at = null,
         premium_retention_expires_at = null
   where id = target_user;
  update public.settlements
     set access_state = 'active',
         inactive_reason = null,
         inactive_since = null,
         retention_expires_at = null
   where user_id = target_user
     and access_state in ('inactive_plan', 'pending_delete');
  get diagnostics settlement_count = row_count;
  update public.saved_maps
     set access_state = 'active',
         inactive_reason = null,
         inactive_since = null,
         retention_expires_at = null
   where user_id = target_user
     and access_state in ('inactive_plan', 'pending_delete');
  get diagnostics campaign_count = row_count;
  return settlement_count + campaign_count;
end;

purge_expired_plan_inactive_settlements(:
declare
  purged integer := 0;
begin
  delete from public.settlements
    where access_state in ('inactive_plan', 'pending_delete')
      and retention_expires_at is not null
      and retention_expires_at <= now();

  get diagnostics purged = row_count;
  return purged;
end;

current_user_has_premium_access():
select exists (
  select 1 from public.profiles
  where id = auth.uid()
    and (tier = 'premium' or is_founder = true or role in ('developer', 'admin'))
);

purge_expired_plan_inactive_assets():
declare
  settlement_count integer := 0;
  campaign_count integer := 0;
begin
  delete from public.settlements
    where access_state in ('inactive_plan', 'pending_delete')
      and retention_expires_at is not null and retention_expires_at <= now()
      -- SPARE the settlement while its owner holds a live paid dossier right; the
      -- ON DELETE CASCADE would otherwise destroy that purchased entitlement.
      and not exists (
        select 1 from public.dossier_entitlements e
        where e.save_id = settlements.id and e.status = 'active'
      );
  get diagnostics settlement_count = row_count;
  delete from public.saved_maps
    where access_state in ('inactive_plan', 'pending_delete')
      and retention_expires_at is not null and retention_expires_at <= now();
  get diagnostics campaign_count = row_count;
  return jsonb_build_object('settlements', settlement_count, 'campaigns', campaign_count);
end;

bump_public_view(slug text, viewer_token:
declare
  v_id  uuid;
  v_ua  text;
  v_key text;
begin
  -- Resolve the target public dossier; bail quietly if it isn't public.
  select id into v_id
    from public.settlements
    where public_slug = slug and is_public = true;
  if v_id is null then
    return;
  end if;

  -- Best-effort User-Agent (PostgREST exposes request headers as a JSON GUC).
  begin
    v_ua := nullif(current_setting('request.headers', true), '')::json ->> 'user-agent';
  exception when others then
    v_ua := null;
  end;

  -- Skip obvious bots/crawlers/scripts — they shouldn't inflate vanity counts.
  if v_ua is not null and v_ua ~* '(bot|crawl|spider|slurp|bingpreview|facebookexternalhit|embedly|preview|headless|monitor|uptime|curl|wget|python-requests|go-http|axios|node-fetch|libwww|okhttp)' then
    return;
  end if;

  -- Pick the most-trusted available identity.
  v_key := coalesce(
    case when auth.uid() is not null then 'u:' || auth.uid()::text end,
    case when viewer_token is not null and length(viewer_token) between 8 and 200
         then 't:' || viewer_token end,
    'a:' || md5(coalesce(v_ua, 'anon'))
  );

  -- New viewer/day → count it; repeat within the day → no-op.
  insert into public.gallery_views (settlement_id, viewer_key)
    values (v_id, v_key)
    on conflict (settlement_id, viewer_key, viewed_on) do nothing;

  if found then
    update public.settlements
      set view_count = coalesce(view_count, 0) + 1
      where id = v_id;
  end if;
end;

_gallery_chronicle_json(entries jsonb):
select case
  when entries is null or jsonb_typeof(entries) <> 'array' then null
  else coalesce(
    (
      select jsonb_agg(public._gallery_chronicle_entry(elem.value) order by elem.ord)
      from jsonb_array_elements(entries) with ordinality as elem(value, ord)
      where elem.ord > jsonb_array_length(entries) - 50
        and jsonb_typeof(elem.value) = 'object'
    ),
    '[]'::jsonb
  )
end;

enforce_version_history_cap():
begin
  if new.version_history is not null
     and jsonb_typeof(new.version_history) = 'array'
     and jsonb_array_length(new.version_history) > 50 then
    -- Keep the most recent 50 entries (newest is appended last) in order.
    new.version_history := (
      select coalesce(jsonb_agg(elem order by ord), '[]'::jsonb)
      from (
        select elem, ord
        from jsonb_array_elements(new.version_history) with ordinality as t(elem, ord)
        order by ord desc
        limit 50
      ) recent
    );
  end if;
  return new;
end;

consume_email_rate_limit(p_ip text, p_re:
declare
  v_window    timestamptz;
  v_ip_key    text;
  v_rcpt_key  text;
  v_ip_count  integer;
  v_rcpt_count integer;
begin
  -- Guard against nonsense parameters that would disable the limit.
  if p_window_seconds is null or p_window_seconds < 1 then
    p_window_seconds := 3600;
  end if;

  v_window := to_timestamp(
    floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds
  );

  -- Normalize keys so trivial variants don't dodge the counter. IP falls back
  -- to the same sentinel send-email uses when no forwarded IP is present.
  v_ip_key   := coalesce(nullif(btrim(p_ip), ''), '0.0.0.0');
  v_rcpt_key := lower(btrim(coalesce(p_recipient, '')));

  insert into public.email_rate_limits as erl (scope_type, scope_key, window_start, count)
  values ('ip', v_ip_key, v_window, 1)
  on conflict (scope_type, scope_key, window_start)
    do update set count = erl.count + 1
  returning erl.count into v_ip_count;

  insert into public.email_rate_limits as erl (scope_type, scope_key, window_start, count)
  values ('recipient', v_rcpt_key, v_window, 1)
  on conflict (scope_type, scope_key, window_start)
    do update set count = erl.count + 1
  returning erl.count into v_rcpt_count;

  return jsonb_build_object(
    'allowed',         (v_ip_count <= p_ip_limit and v_rcpt_count <= p_recipient_limit),
    'ip_count',        v_ip_count,
    'recipient_count', v_rcpt_count,
    'ip_limit',        p_ip_limit,
    'recipient_limit', p_recipient_limit,
    'window_start',    v_window,
    'window_seconds',  p_window_seconds
  );
end;

cleanup_email_rate_limits(p_retention_se:
