consume_dossier_verify_rate_limit(p_ip t:
declare
  v_window   timestamptz;
  v_ip_key   text;
  v_ip_count integer;
begin
  -- Guard against nonsense parameters that would disable the limit.
  if p_window_seconds is null or p_window_seconds < 1 then
    p_window_seconds := 3600;
  end if;

  v_window := to_timestamp(
    floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds
  );

  -- Normalize the IP so trivial variants don't dodge the counter. Falls back to
  -- the same sentinel send-email uses when no forwarded IP is present.
  v_ip_key := coalesce(nullif(btrim(p_ip), ''), '0.0.0.0');

  insert into public.dossier_verify_rate_limits as drl (ip_key, window_start, count)
  values (v_ip_key, v_window, 1)
  on conflict (ip_key, window_start)
    do update set count = drl.count + 1
  returning drl.count into v_ip_count;

  return jsonb_build_object(
    'allowed',        (v_ip_count <= p_ip_limit),
    'ip_count',       v_ip_count,
    'ip_limit',       p_ip_limit,
    'window_start',   v_window,
    'window_seconds', p_window_seconds
  );
end;

cleanup_dossier_verify_rate_limits(p_ret:
declare
  v_deleted integer := 0;
begin
  if p_retention_seconds is null or p_retention_seconds < 1 then
    p_retention_seconds := 86400;
  end if;
  delete from public.dossier_verify_rate_limits
    where window_start < now() - make_interval(secs => p_retention_seconds);
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;

ingest_check_rate(p_key text, p_max inte:
declare
  v_window timestamptz;
  v_count  integer;
begin
  if p_window_seconds is null or p_window_seconds < 1 then p_window_seconds := 3600; end if;
  v_window := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);
  insert into public.ingest_rate_buckets as b (bucket_key, window_start, count)
  values (coalesce(nullif(btrim(p_key), ''), 'anon'), v_window, 1)
  on conflict (bucket_key, window_start) do update set count = b.count + 1
  returning count into v_count;
  return v_count <= p_max;
end;

purge_analytics_for_user(p_user_id uuid):
declare
  v_actor uuid;
  v_events integer := 0;
  v_edits  integer := 0;
begin
  select actor_id into v_actor from public.analytics_identity_links where user_id = p_user_id;
  if v_actor is null then
    return jsonb_build_object('events', 0, 'edits', 0, 'note', 'no actor mapping');
  end if;
  delete from public.analytics_events where actor_id = v_actor;
  get diagnostics v_events = row_count;
  delete from public.edit_events where actor_id = v_actor;
  get diagnostics v_edits = row_count;
  -- settlement_snapshots (037) are scrubbed there if present; soft no-op if absent.
  begin
    execute 'delete from public.settlement_snapshots where actor_id = $1' using v_actor;
  exception when undefined_table then null;
  end;
  delete from public.analytics_device_links where actor_id = v_actor;
  delete from public.analytics_identity_links where user_id = p_user_id;
  return jsonb_build_object('events', v_events, 'edits', v_edits, 'actor', v_actor);
end;

