mask_email(p_email text):
select case
  when p_email is null or position('@' in p_email) = 0 then null
  else (
    case when length(split_part(p_email, '@', 1)) <= 1
      then '*'
      else left(split_part(p_email, '@', 1), 1) || '***'
    end
  ) || '@' || split_part(p_email, '@', 2)
end;

admin_user_summary(target_user uuid):
declare
  p record;
  settlement_count int;
  public_count     int;
  campaign_count   int;
  ticket_count     int;
  warning_count    int;
begin
  if not public.current_user_is_support_or_higher() then
    raise exception 'not authorized';
  end if;
  if target_user is null then
    raise exception 'target_user is required';
  end if;

  select id, role, tier, is_founder, display_name, email, credits,
         created_at, disabled_at, banned_at
    into p
    from public.profiles
    where id = target_user;

  if not found then
    raise exception 'target profile not found';
  end if;

  select count(*)::int into settlement_count
    from public.settlements where user_id = target_user;
  -- gallery items = the user's public dossiers.
  select count(*)::int into public_count
    from public.settlements where user_id = target_user and is_public = true;
  -- campaigns: settlements carrying campaign state (campaign_state, added in
  -- 013 — 053 mistakenly counted a `campaign_id` column that never existed, so
  -- this metric was permanently NULL). Guard the column so this summary still
  -- works on a pre-013 schema (e.g. test rigs).
  begin
    select count(*)::int into campaign_count
      from public.settlements
      where user_id = target_user and campaign_state is not null;
  exception when undefined_column then
    campaign_count := null;
  end;
  begin
    select count(*)::int into ticket_count
      from public.support_messages where user_id = target_user;
  exception when undefined_table then
    ticket_count := null;
  end;
  select count(*)::int into warning_count
    from public.warnings where user_id = target_user;

  -- Redacted shape: masked email, status flags, counts. NEVER raw email / any
  -- payment id. account_age_days is derived (account age, not the raw ts).
  return jsonb_build_object(
    'id',              p.id,
    'role',            p.role,
    'tier',            p.tier,
    'is_founder',      p.is_founder,
    'display_name',    p.display_name,
    'email_masked',    public.mask_email(p.email),
    'credits',         p.credits,
    'created_at',      p.created_at,
    'account_age_days', greatest(0, (extract(epoch from (now() - p.created_at)) / 86400)::int),
    'settlements',     settlement_count,
    'gallery_items',   public_count,
    'campaigns',       campaign_count,
    'tickets',         ticket_count,
    'warnings',        warning_count,
    'disabled',        (p.disabled_at is not null),
    'banned',          (p.banned_at is not null),
    'disabled_at',     p.disabled_at,
    'banned_at',       p.banned_at,
    'redacted',        true
  );
end;

admin_user_full(target_user uuid, p_reas:
declare
  p record;
  reason_clean text;
  has_write_audit boolean;
begin
  if not public.current_user_is_highest() then
    raise exception 'not authorized: full PII requires admin or developer';
  end if;
  reason_clean := nullif(btrim(coalesce(p_reason, '')), '');
  if reason_clean is null then
    raise exception 'a reason is required to read full PII';
  end if;
  if target_user is null then
    raise exception 'target_user is required';
  end if;

  select id, role, tier, is_founder, display_name, email, credits, created_at, updated_at
    into p
    from public.profiles
    where id = target_user;

  if not found then
    raise exception 'target profile not found';
  end if;

  -- Audit BEFORE returning the PII. Prefer the 051 append-only log; fall back to
  -- the 009 admin_actions audit if 051 isn't applied yet.
  select exists (
    select 1 from pg_proc pr join pg_namespace n on n.oid = pr.pronamespace
    where n.nspname = 'public' and pr.proname = 'write_audit'
  ) into has_write_audit;

  if has_write_audit then
    perform public.write_audit(
      p_action          => 'read_full_pii',
      p_target_user_id  => target_user,
      p_target_type     => 'profile',
      p_target_id       => target_user::text,
      p_reason          => reason_clean,
      p_before          => null,
      p_after           => jsonb_build_object('fields', array['email','credits'], 'email_masked', public.mask_email(p.email)),
      p_was_destructive => false,
      p_was_reversible  => true,
      p_user_notified   => false
    );
  else
    perform public._audit_action(
      auth.uid(), target_user, 'read_full_pii',
      null,
      jsonb_build_object('fields', array['email','credits']),
      reason_clean
    );
  end if;

  return jsonb_build_object(
    'id',           p.id,
    'role',         p.role,
    'tier',         p.tier,
    'is_founder',   p.is_founder,
    'display_name', p.display_name,
    'email',        p.email,         -- RAW email — the audited unmasking
    'credits',      p.credits,
    'created_at',   p.created_at,
    'updated_at',   p.updated_at,
    'redacted',     false
  );
end;

write_audit(p_action text, p_target_user:
declare
  v_actor uuid;
  v_role  text;
  v_id    uuid;
begin
  if p_action is null or btrim(p_action) = '' then
    raise exception 'audit action is required';
  end if;

  v_actor := coalesce(p_actor_id, auth.uid());
  select role into v_role from public.profiles where id = v_actor;

  insert into public.audit_log (
    actor_id, actor_role, target_user_id, target_type, target_id,
    action, reason, before_state, after_state,
    was_destructive, was_reversible, user_notified
  ) values (
    v_actor, v_role, p_target_user_id, p_target_type, p_target_id,
    p_action, nullif(btrim(coalesce(p_reason, '')), ''), p_before, p_after,
    coalesce(p_was_destructive, false), coalesce(p_was_reversible, true),
    coalesce(p_user_notified, false)
  )
  returning id into v_id;

  return v_id;
end;

issue_warning(p_actor uuid, p_target uui:
declare
  v_id uuid;
  v_sev text;
  v_reason text;
begin
  if not public.has_role(p_actor, array['support', 'admin', 'developer']) then
    raise exception 'not authorized';
  end if;
  if p_target is null then raise exception 'target is required'; end if;
  v_reason := nullif(btrim(coalesce(p_reason, '')), '');
  if v_reason is null then raise exception 'a warning reason is required'; end if;
  v_sev := coalesce(nullif(btrim(p_severity), ''), 'notice');
  if v_sev not in ('notice', 'minor', 'major', 'final') then
    raise exception 'invalid severity: %', v_sev;
  end if;

  insert into public.warnings (user_id, issued_by, severity, reason, user_notified)
    values (p_target, p_actor, v_sev, v_reason, coalesce(p_notified, false))
    returning id into v_id;

  perform public.write_audit(
    p_action          => 'issue_warning',
    p_target_user_id  => p_target,
    p_target_type     => 'warning',
    p_target_id       => v_id::text,
    p_reason          => v_reason,
    p_before          => null,
    p_after           => jsonb_build_object('severity', v_sev),
    p_was_destructive => false,
    p_was_reversible  => true,
    p_user_notified   => coalesce(p_notified, false),
    p_actor_id        => p_actor
  );

  return v_id;
end;

