admin_billing_summary(p_actor uuid, p_ta:
declare
  p record;
  cust_masked text;
begin
  if not public.has_role(p_actor, array['support', 'admin', 'developer']) then
    raise exception 'not authorized';
  end if;
  if p_target is null then raise exception 'target is required'; end if;

  select tier, credits, is_founder, stripe_customer_id
    into p
    from public.profiles where id = p_target;
  if not found then raise exception 'target profile not found'; end if;

  -- Mask the customer id: keep only a tail so an admin can correlate with the
  -- Stripe dashboard WITHOUT the raw id leaving the DB.
  cust_masked := case
    when p.stripe_customer_id is null then null
    when length(p.stripe_customer_id) <= 4 then '***'
    else '***' || right(p.stripe_customer_id, 4)
  end;

  perform public.write_audit(
    p_action          => 'review_billing',
    p_target_user_id  => p_target,
    p_target_type     => 'profile',
    p_target_id       => p_target::text,
    p_reason          => null,
    p_before          => null,
    p_after           => jsonb_build_object('customer_masked', cust_masked),
    p_was_destructive => false,
    p_was_reversible  => true,
    p_user_notified   => false,
    p_actor_id        => p_actor
  );

  return jsonb_build_object(
    'tier',            p.tier,
    'is_founder',      p.is_founder,
    'credits',         p.credits,
    'customer_masked', cust_masked,
    'redacted',        true
  );
end;

admin_diagnostic_bundle(p_actor uuid, p_:
declare
  p record;
  reason_clean text;
  bundle jsonb;
begin
  -- Redacted bundle: support+. Full bundle: HIGHEST role + a reason.
  if p_full then
    if not public.has_role(p_actor, array['admin', 'developer']) then
      raise exception 'not authorized: a full debug copy requires admin or developer';
    end if;
    reason_clean := nullif(btrim(coalesce(p_reason, '')), '');
    if reason_clean is null then
      raise exception 'a justification is required for a full debug copy';
    end if;
  else
    if not public.has_role(p_actor, array['support', 'admin', 'developer']) then
      raise exception 'not authorized';
    end if;
  end if;
  if p_target is null then raise exception 'target is required'; end if;

  select id, role, tier, is_founder, display_name, email, credits,
         created_at, disabled_at, banned_at
    into p
    from public.profiles where id = p_target;
  if not found then raise exception 'target profile not found'; end if;

  if p_full then
    -- FULL: includes the raw email (the audited unmasking).
    bundle := jsonb_build_object(
      'id', p.id, 'role', p.role, 'tier', p.tier, 'is_founder', p.is_founder,
      'display_name', p.display_name, 'email', p.email, 'credits', p.credits,
      'created_at', p.created_at, 'disabled_at', p.disabled_at, 'banned_at', p.banned_at,
      'redacted', false
    );
  else
    -- REDACTED: masked email only.
    bundle := jsonb_build_object(
      'id', p.id, 'role', p.role, 'tier', p.tier, 'is_founder', p.is_founder,
      'display_name', p.display_name, 'email_masked', public.mask_email(p.email),
      'credits', p.credits, 'created_at', p.created_at,
      'disabled', (p.disabled_at is not null), 'banned', (p.banned_at is not null),
      'redacted', true
    );
  end if;

  perform public.write_audit(
    p_action          => case when p_full then 'export_full_debug' else 'export_diagnostic' end,
    p_target_user_id  => p_target,
    p_target_type     => 'profile',
    p_target_id       => p_target::text,
    p_reason          => reason_clean,
    p_before          => null,
    -- The audit row NEVER carries the raw email — only the masked form + the
    -- variant produced.
    p_after           => jsonb_build_object('full', p_full, 'email_masked', public.mask_email(p.email)),
    p_was_destructive => false,
    p_was_reversible  => true,
    p_user_notified   => false,
    p_actor_id        => p_actor
  );

  return bundle;
end;

process_account_deletions(p_actor uuid,:
declare
  r            record;
  v_grace      int;
  v_limit      int;
  v_cutoff     timestamptz;
  v_email      text;
  v_dname      text;
  v_before     jsonb;
  v_queued     int := 0;
  v_ids        uuid[] := array[]::uuid[];
begin
  if p_actor is not null
     and not public.has_role(p_actor, array['admin', 'developer']) then
    raise exception 'not authorized: processing deletions requires admin or developer';
  end if;

  v_grace  := greatest(0, least(coalesce(p_grace_days, 7), 365));
  v_limit  := greatest(1, least(coalesce(p_limit, 100), 1000));
  v_cutoff := now() - make_interval(days => v_grace);

  -- A queue row and the anonymisation are one transaction. SKIP LOCKED permits
  -- cron/manual overlap without duplicate work; the request-id UNIQUE constraint
  -- is the final idempotency boundary.
  for r in
    select dr.id, dr.user_id
      from public.deletion_requests dr
      where dr.status = 'requested'
        and dr.user_id is not null
        and dr.requested_at <= v_cutoff
      order by dr.requested_at asc, dr.id asc
      limit v_limit
      for update skip locked
  loop
    v_email := null;
    v_dname := null;
    if r.user_id is not null then
      select email, display_name into v_email, v_dname
        from public.profiles where id = r.user_id for update;
    end if;
    v_before := jsonb_build_object(
      'email_masked', public.mask_email(v_email),
      'had_display_name', (v_dname is not null)
    );

    if r.user_id is not null then
      update public.profiles
         set display_name = null,
             email        = null,
             deleted_at   = coalesce(deleted_at, now()),
             disabled_at  = coalesce(disabled_at, now()),
             updated_at   = now()
       where id = r.user_id;
    end if;

    update public.deletion_requests
       set status       = 'processing',
           processed_by = p_actor,
           processed_at = now(),
           email        = null
     where id = r.id;

    insert into public.account_deletion_cleanup_jobs (
      deletion_request_id, user_id, audit_before, audit_actor_id
    ) values (
      r.id, r.user_id, v_before, p_actor
    )
    on conflict (deletion_request_id) do nothing;
    v_queued := v_queued + 1;
    v_ids := array_append(v_ids, r.id);
  end loop;

  return jsonb_build_object(
    'processed', v_queued,
    'queued', v_queued,
    'ids', v_ids,
    'cutoff', v_cutoff,
    'grace_days', v_grace
  );
end;

