list_ticket_thread(p_id uuid):
declare
  v_owner uuid;
  v_agent boolean;
begin
  if p_id is null then raise exception 'a ticket id is required'; end if;
  v_agent := public.current_user_is_support_or_higher();
  select sm.user_id into v_owner from public.support_messages sm where sm.id = p_id;
  if v_owner is null then
    -- ticket missing or (for a non-agent) not theirs → empty
    if not v_agent then return; end if;
  end if;
  if not v_agent and v_owner <> auth.uid() then
    return; -- not the owner, not an agent → nothing
  end if;

  return query
    select e.id, e.author_role, e.kind, e.visibility, e.body, e.created_at
      from public.support_ticket_events e
     where e.ticket_id = p_id
       -- the OWNER never sees an internal note; an agent sees everything.
       and (v_agent or e.visibility = 'user')
     order by e.created_at asc;
end;

enforce_account_active_write():
declare
  acting uuid := auth.uid();
begin
  if coalesce(
       nullif(current_setting('request.jwt.claim.role', true), ''),
       auth.role()
     ) = 'service_role' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  -- Null-auth system triggers remain exempt exactly as in migration 059.
  if acting is not null then
    perform 1
    from public.profiles p
    where p.id = acting
      and p.banned_at is null
      and p.disabled_at is null
      and p.deleted_at is null
    for update;
    if not found then
      raise exception 'account is not active'
        using errcode = 'check_violation';
    end if;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;

bump_map_import(p_slug text):
declare
  v_id    uuid;
  v_owner uuid;
begin
  -- Fire-and-forget counter: every reject is a quiet no-op, never an error
  -- (the client swallows failures anyway; an exception would only add noise).
  if auth.uid() is null then
    return;
  end if;

  -- An import is only POSSIBLE for a public, owner-opted-in map (072's
  -- import_gallery_map gate). Anything else is not a plausible import.
  select id, user_id into v_id, v_owner
    from public.saved_maps
    where public_slug = p_slug
      and is_public = true
      and coalesce(gallery_importable, false);
  if v_id is null then
    return;
  end if;

  -- The owner importing their own map is not a ranking signal.
  if v_owner = auth.uid() then
    return;
  end if;

  -- New (map, importer, day) → count it; a repeat within the day → no-op.
  insert into public.map_imports (map_id, importer_id)
    values (v_id, auth.uid())
    on conflict (map_id, importer_id, imported_on) do nothing;

  if found then
    update public.saved_maps
      set import_count = import_count + 1
      where id = v_id;
  end if;
end;

set_my_security_answers(p_q1 text, p_a1:
declare
  v_uid uuid := auth.uid();
  v_a1  text := lower(btrim(coalesce(p_a1, '')));
  v_a2  text := lower(btrim(coalesce(p_a2, '')));
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;
  if not public.is_allowed_security_question_id(p_q1)
     or not public.is_allowed_security_question_id(p_q2) then
    raise exception 'unknown security question id';
  end if;
  if p_q1 = p_q2 then
    raise exception 'the two security questions must be different';
  end if;
  if length(v_a1) < 1 or length(v_a2) < 1 then
    raise exception 'both security answers are required';
  end if;

  insert into public.security_answers (user_id, slot, question_id, answer_hash, updated_at)
  values
    (v_uid, 1, p_q1, crypt(v_a1, gen_salt('bf')), now()),
    (v_uid, 2, p_q2, crypt(v_a2, gen_salt('bf')), now())
  on conflict (user_id, slot) do update
    set question_id = excluded.question_id,
        answer_hash = excluded.answer_hash,
        updated_at  = now();
end;

pick_recovery_question(p_email text):
declare
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_uid   uuid;
  v_slot  smallint;
  v_qid   text;
begin
  if v_email = '' then
    return query select false, null::smallint, null::text;
    return;
  end if;

  select u.id into v_uid
  from auth.users u
  where lower(u.email) = v_email
  limit 1;

  if v_uid is null then
    return query select false, null::smallint, null::text;
    return;
  end if;

  -- Pick ONE of the configured slots at random. If the account has no security
  -- answers (OAuth-only or pre-feature), report exists=true but no question so the
  -- caller can route to a different recovery path without leaking more.
  select sa.slot, sa.question_id
    into v_slot, v_qid
  from public.security_answers sa
  where sa.user_id = v_uid
  order by random()
  limit 1;

  if v_slot is null then
    return query select true, null::smallint, null::text;
    return;
  end if;

  return query select true, v_slot, v_qid;
end;

verify_recovery_answer(p_email text, p_s:
declare
  v_email  text := lower(btrim(coalesce(p_email, '')));
  v_answer text := lower(btrim(coalesce(p_answer, '')));
  v_uid    uuid;
  v_hash   text;
begin
  if v_email = '' or p_slot not in (1, 2) or length(v_answer) < 1 then
    return false;
  end if;

  select u.id into v_uid
  from auth.users u
  where lower(u.email) = v_email
  limit 1;
  if v_uid is null then
    return false;
  end if;

  select sa.answer_hash into v_hash
  from public.security_answers sa
  where sa.user_id = v_uid and sa.slot = p_slot
  limit 1;
  if v_hash is null then
    return false;
  end if;

  return crypt(v_answer, v_hash) = v_hash;
end;

consume_recovery_rate_limit(p_ip text, p:
declare
  v_window     timestamptz;
  v_ip_key     text;
  v_email_key  text;
  v_ip_count   integer;
  v_email_count integer;
begin
  if p_window_seconds is null or p_window_seconds < 1 then
    p_window_seconds := 900;
  end if;

  v_window := to_timestamp(
    floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds
  );

  v_ip_key    := coalesce(nullif(btrim(p_ip), ''), '0.0.0.0');
  v_email_key := lower(btrim(coalesce(p_email, '')));

  insert into public.recovery_rate_limits as rrl (scope_type, scope_key, window_start, count)
  values ('ip', v_ip_key, v_window, 1)
  on conflict (scope_type, scope_key, window_start)
    do update set count = rrl.count + 1
  returning rrl.count into v_ip_count;

  insert into public.recovery_rate_limits as rrl (scope_type, scope_key, window_start, count)
  values ('email', v_email_key, v_window, 1)
  on conflict (scope_type, scope_key, window_start)
    do update set count = rrl.count + 1
  returning rrl.count into v_email_count;

  return jsonb_build_object(
    'allowed',        (v_ip_count <= p_ip_limit and v_email_count <= p_email_limit),
    'ip_count',       v_ip_count,
    'email_count',    v_email_count,
    'ip_limit',       p_ip_limit,
    'email_limit',    p_email_limit,
    'window_start',   v_window,
    'window_seconds', p_window_seconds
  );
end;

cleanup_recovery_rate_limits(p_retention:
declare
  v_deleted integer := 0;
begin
  if p_retention_seconds is null or p_retention_seconds < 1 then
    p_retention_seconds := 86400;
  end if;
  delete from public.recovery_rate_limits
    where window_start < now() - make_interval(secs => p_retention_seconds);
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;

recovery_is_locked(p_email text):
declare
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_uid   uuid;
  v_until timestamptz;
begin
  if v_email = '' then
    return false;
  end if;

  select u.id into v_uid from auth.users u where lower(u.email) = v_email limit 1;
  if v_uid is null then
    return false;
  end if;

  select rl.locked_until into v_until
  from public.recovery_lockouts rl
  where rl.user_id = v_uid
  limit 1;

  -- Locked only while the current backoff window is still in the future. A null or
  -- past locked_until means the window has elapsed and the gate has reopened.
  return v_until is not null and now() < v_until;
end;

note_recovery_verify_failure(p_email tex:
declare
  -- Per-cycle wrong-answer budget before the window slams shut. Smaller than the
  -- old flat cap of 10 because each cycle now COSTS the attacker an escalating wait.
  c_threshold constant integer := 5;
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_uid   uuid;
  v_fails integer;
  v_cycle integer;
  v_cfails integer;
  v_until timestamptz;
begin
  if v_email = '' then
    return jsonb_build_object('locked', false, 'fails', 0);
  end if;

  select u.id into v_uid from auth.users u where lower(u.email) = v_email limit 1;
  if v_uid is null then
    return jsonb_build_object('locked', false, 'fails', 0);
  end if;

  insert into public.recovery_lockouts as rl (user_id, fail_count, cycle_fails, updated_at)
  values (v_uid, 1, 1, now())
  on conflict (user_id) do update
    set fail_count = rl.fail_count + 1,
        cycle_fails = rl.cycle_fails + 1,
        updated_at = now()
  returning rl.fail_count, rl.cycle, rl.cycle_fails, rl.locked_until
    into v_fails, v_cycle, v_cfails, v_until;

  -- Per-cycle budget exhausted -> open a NEW, longer window and start a fresh cycle.
  if v_cfails >= c_threshold then
    v_cycle := v_cycle + 1;
    -- Exponential backoff keyed to the cycle count, capped at 24h.
    v_until := now() + case
      when v_cycle <= 1 then interval '15 minutes'
      when v_cycle = 2 then interval '1 hour'
      when v_cycle = 3 then interval '6 hours'
      else interval '24 hours'
    end;
    update public.recovery_lockouts
      set cycle = v_cycle,
          cycle_fails = 0,          -- reset the per-cycle counter for the next window
          locked_until = v_until,
          locked_at = coalesce(locked_at, now()),
          updated_at = now()
      where user_id = v_uid;
  end if;

  return jsonb_build_object(
    'locked', (v_until is not null and now() < v_until),
    'fails', v_fails
  );
end;

clear_recovery_lockout(p_user_id uuid):
begin
  if p_user_id is null then
    return;
  end if;
  delete from public.recovery_lockouts where user_id = p_user_id;
end;

clear_recovery_lockout_by_email(p_email:
declare
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_uid   uuid;
begin
  if v_email = '' then
    return;
  end if;
  select u.id into v_uid from auth.users u where lower(u.email) = v_email limit 1;
  if v_uid is null then
    return;
  end if;
  delete from public.recovery_lockouts where user_id = v_uid;
end;

persist_world_pulse_advance(p_campaign_i:
declare
  v_uid uuid := auth.uid();
  v_campaign public.saved_maps%rowtype;
  v_current_tick bigint;
  v_update jsonb;
  v_save_id uuid;
  v_owned_count integer;
  v_update_count integer;
  v_distinct_count integer;
  v_applied_settlements integer := 0;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;

  -- Account-status gate (the 059 invariant): EVERY SECURITY DEFINER write RPC that
  -- mutates settlements/maps/profiles must reject a banned/disabled/soft-deleted
  -- account even with a valid JWT. persist_world_pulse_advance is a settlement+
  -- campaign write, so it carries the standard guard like 057/059/073.
  if not public.account_is_active(v_uid) then
    raise exception 'account is not active' using errcode = '42501';
  end if;

  -- Ownership: the caller must own the campaign. Lock the row so a concurrent
  -- advance of the SAME campaign serialises behind this transaction (the optional
  -- tick guard below then sees a consistent current tick).
  -- Row-state gate (102): the campaign row must be BILLING-active — a downgraded
  -- (inactive_plan / pending_delete) campaign is read-only, matching the 024/059
  -- direct-write RLS. An inactive row reads as not-found, same as an RLS deny.
  select * into v_campaign
    from public.saved_maps
   where id = p_campaign_id
     and user_id = v_uid
     and access_state = 'active'
   for update;

  if not found then
    raise exception 'campaign % not found for current user', p_campaign_id
      using errcode = '42501';
  end if;

  -- Normalise the settlement update set to an array (empty array is a valid
  -- campaign-only advance, e.g. a single-settlement realm with nothing to write).
  if p_settlement_updates is null then
    p_settlement_updates := '[]'::jsonb;
  end if;
  if jsonb_typeof(p_settlement_updates) <> 'array' then
    raise exception 'p_settlement_updates must be a JSON array'
      using errcode = '22023';
  end if;

  v_update_count := jsonb_array_length(p_settlement_updates);

  -- Ownership: EVERY settlement named in the update set must belong to the caller.
  -- A single foreign id aborts before any write — no cross-owner advance.
  -- Compare owned rows against the count of DISTINCT referenced saveIds (NOT the
  -- raw array length): a duplicate saveId in the payload must not make the owned
  -- count fall short and trip a false "not owned" abort (084).
  -- Row-state gate (102): only BILLING-active rows count as writable, mirroring
  -- mutate_settlement_batch's in-body re-check — a frozen settlement in the
  -- write-set aborts the whole advance before any write.
  if v_update_count > 0 then
    select count(distinct (elem ->> 'saveId')) into v_distinct_count
      from jsonb_array_elements(p_settlement_updates) as elem
     where elem ->> 'saveId' is not null;

    select count(*) into v_owned_count
      from public.settlements s
     where s.user_id = v_uid
       and s.access_state = 'active'
       and s.id in (
         select (elem ->> 'saveId')::uuid
           from jsonb_array_elements(p_settlement_updates) as elem
          where elem ->> 'saveId' is not null
       );

    if v_owned_count <> v_distinct_count then
      raise exception 'one or more settlements are not active or not owned by the current user'
        using errcode = '42501';
    end if;
  end if;

  -- Optional stale-apply guard: only advance if this tick is strictly ahead of the
  -- stored one. A duplicate re-apply of an already-landed tick is a no-op. The
  -- envelope mirrors mapDataForCampaign: the campaign lives under map_data.campaign,
  -- so the tick is at {campaign,worldState,tick} (legacy unwrapped rows fall back).
  if p_expected_tick is not null then
    v_current_tick := coalesce(
      nullif(v_campaign.map_data #>> '{campaign,worldState,tick}', '')::bigint,
      nullif(v_campaign.map_data #>> '{worldState,tick}', '')::bigint,
      -1
    );
    if v_current_tick >= p_expected_tick then
      return jsonb_build_object(
        'applied', false,
        'reason', 'stale_tick',
        'currentTick', v_current_tick,
        'expectedTick', p_expected_tick
      );
    end if;
  end if;

  -- ── Single-transaction write-set ──────────────────────────────────────────
  -- 1) Each affected settlement. Only keys PRESENT in the update object are
  --    written, so an absent campaignState/versionHistory keeps the stored value.
  for v_update in
    select * from jsonb_array_elements(p_settlement_updates)
  loop
    v_save_id := nullif(v_update ->> 'saveId', '')::uuid;
    if v_save_id is null then
      continue;
    end if;

    update public.settlements s
       set data            = case when v_update ? 'settlement'
                                  then v_update -> 'settlement' else s.data end,
           campaign_state  = case when v_update ? 'campaignState'
                                  then v_update -> 'campaignState' else s.campaign_state end,
           version_history = case when v_update ? 'versionHistory'
                                  then v_update -> 'versionHistory' else s.version_history end,
           updated_at      = now()
     where s.id = v_save_id
       and s.user_id = v_uid
       and s.access_state = 'active';

    if found then
      v_applied_settlements := v_applied_settlements + 1;
    end if;
  end loop;

  -- 2) The campaign snapshot. Mirrors rowForCampaign EXACTLY: the full map_data
  --    envelope (mapDataForCampaign → { kind, version, campaign }) is stored
  --    verbatim, and each derived column is refreshed from the SAME paths
  --    rowForCampaign reads — campaign.name, campaign.mapState.seed/placements,
  --    campaign.regionalGraph.channels — so the atomic write lands a row
  --    byte-identical to the serial upsert path.
  if p_campaign_snapshot is not null and jsonb_typeof(p_campaign_snapshot) = 'object' then
    update public.saved_maps m
       set map_data            = p_campaign_snapshot,
           name                = coalesce(p_campaign_snapshot #>> '{campaign,name}', m.name),
           map_seed            = coalesce(p_campaign_snapshot #>> '{campaign,mapState,seed}', m.map_seed),
           burg_settlement_map = coalesce(p_campaign_snapshot #> '{campaign,mapState,placements}', m.burg_settlement_map),
           supply_chain_config = coalesce(p_campaign_snapshot #> '{campaign,regionalGraph,channels}', m.supply_chain_config),
           updated_at          = now()
     where m.id = p_campaign_id
       and m.user_id = v_uid
       and m.access_state = 'active';
  end if;

  return jsonb_build_object(
    'applied', true,
    'settlementsWritten', v_applied_settlements,
    'settlementsRequested', v_update_count
  );
end;

import_gallery_map(p_slug text):
declare v_ok boolean;
begin
  select (is_public and coalesce(gallery_importable, false))
    into v_ok
    from public.saved_maps
   where public_slug = p_slug;
  if not coalesce(v_ok, false) or auth.uid() is null then
    return null;
  end if;
  return public.get_gallery_map(p_slug);
end

gen_account_number():
declare
  alphabet constant text := '23456789ABCDEFGHJKMNPQRSTVWXYZ'; -- Crockford-base32 minus ambiguous chars
  candidate text;
  i int;
  attempt int := 0;
begin
  loop
    attempt := attempt + 1;
    candidate := 'SF-';
    for i in 1..7 loop
      candidate := candidate || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
    end loop;
    -- Fail-closed: only return a value proven free of the unique index.
    if not exists (select 1 from public.profiles where account_number = candidate) then
      return candidate;
    end if;
    if attempt >= 8 then
      raise exception 'could not generate a unique account_number after % attempts', attempt;
    end if;
  end loop;
end;

gen_external_name():
declare
  adjectives constant text[] := array[
    'Quiet','Amber','Hollow','Distant','Gilded','Weathered','Patient','Hidden',
    'Northern','Ember','Silent','Wandering','Steady','Verdant','Ashen','Bright',
    'Stoic','Wry','Candid','Tidal','Lonely','Mossy','Cobalt','Russet'];
  nouns constant text[] := array[
    'Cartographer','Archivist','Steward','Lantern','Compass','Chronicle','Warden',
    'Beacon','Ledger','Harbor','Almanac','Cairn','Sentinel','Marsh','Foundry',
    'Atlas','Vellum','Quill','Meridian','Bastion','Thicket','Hearth','Spire','Glade'];
  candidate text;
  attempt int := 0;
begin
  loop
    attempt := attempt + 1;
    candidate :=
      adjectives[1 + floor(random() * array_length(adjectives, 1))::int]
      || nouns[1 + floor(random() * array_length(nouns, 1))::int]
      || (100 + floor(random() * 900))::int::text;
    if not exists (
      select 1 from public.profiles
      where lower(external_name) = lower(candidate)
    ) then
      return candidate;
    end if;
    if attempt >= 12 then
      raise exception 'could not generate a unique external_name after % attempts', attempt;
    end if;
  end loop;
end;

update_external_name(new_name text):
declare
  trimmed text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  trimmed := btrim(coalesce(new_name, ''));

  if length(trimmed) < 3 or length(trimmed) > 24 then
    raise exception 'Display author name must be 3 to 24 characters';
  end if;
  if trimmed !~ '^[A-Za-z0-9_]+$' then
    raise exception 'Display author name may use only letters, numbers, and underscores';
  end if;
  if exists (
    select 1 from public.reserved_external_names
    where name = public.normalize_external_name(trimmed)
  ) then
    raise exception 'That name is reserved';
  end if;
  if exists (
    select 1 from public.profiles
    where lower(external_name) = public.normalize_external_name(trimmed)
      and id <> auth.uid()
  ) then
    raise exception 'That name is taken';
  end if;

  update public.profiles
    set external_name = trimmed,
        updated_at    = now()
    where id = auth.uid();

  return trimmed;
exception
  when unique_violation then
    -- The unique index is the authoritative race backstop; translate to the
    -- same friendly message the pre-check would have raised.
    raise exception 'That name is taken';
end;

update_profile_names(p_first text, p_las:
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  update public.profiles
    set first_name     = nullif(btrim(coalesce(p_first, '')), ''),
        last_name      = nullif(btrim(coalesce(p_last, '')), ''),
        preferred_name = nullif(btrim(coalesce(p_preferred, '')), ''),
        updated_at     = now()
    where id = auth.uid();
end;

consume_ai_generate_rate_limit(p_user uu:
declare
  v_window     timestamptz;
  v_user_key   text;
  v_user_count integer;
  v_cfg        jsonb;
begin
  -- When the caller doesn't override, read the operator-tunable config row.
  if p_window_seconds is null or p_user_limit is null then
    select value into v_cfg from public.system_config where key = 'ai_user_rate_limit';
    -- Defensive cast: a malformed (non-integer) config value must FALL BACK to the
    -- default, not RAISE — a raise propagates to the edge caller, which fails OPEN
    -- on RPC error and would silently DISABLE the per-user rate limiter.
    if p_window_seconds is null then
      p_window_seconds := coalesce((case when (v_cfg ->> 'window_seconds') ~ '^[0-9]+$' then (v_cfg ->> 'window_seconds')::integer end), 86400);
    end if;
    if p_user_limit is null then
      p_user_limit := coalesce((case when (v_cfg ->> 'per_user_limit') ~ '^[0-9]+$' then (v_cfg ->> 'per_user_limit')::integer end), 60);
    end if;
  end if;

  if p_window_seconds is null or p_window_seconds < 1 then p_window_seconds := 86400; end if;
  if p_user_limit is null or p_user_limit < 1 then p_user_limit := 60; end if;

  v_window := to_timestamp(
    floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds
  );
  v_user_key := coalesce(nullif(btrim(p_user::text), ''), '00000000-0000-0000-0000-000000000000');

  insert into public.ai_generate_rate_limits as arl (user_key, window_start, count)
  values (v_user_key, v_window, 1)
  on conflict (user_key, window_start)
    do update set count = arl.count + 1
  returning arl.count into v_user_count;

  return jsonb_build_object(
    'allowed',        (v_user_count <= p_user_limit),
    'count',          v_user_count,
    'limit',          p_user_limit,
    'window_start',   v_window,
    'window_seconds', p_window_seconds
  );
end;

cleanup_ai_generate_rate_limits(p_retent:
declare
  v_deleted integer := 0;
begin
  if p_retention_seconds is null or p_retention_seconds < 1 then
    p_retention_seconds := 172800;
  end if;
  delete from public.ai_generate_rate_limits
    where window_start < now() - make_interval(secs => p_retention_seconds);
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;

reconcile_credit_balances():
declare
  drift_count integer;
begin
  delete from public.credit_drift_log;

  insert into public.credit_drift_log (user_id, cached_credits, ledger_balance, drift, role, is_founder)
  select
    p.id,
    p.credits,
    public.get_credit_balance(p.id) as ledger_balance,
    p.credits - public.get_credit_balance(p.id) as drift,
    p.role,
    p.is_founder
  from public.profiles p
  where coalesce(p.credits, 0) >= 0
    -- Exclude elevated/unlimited accounts whose cache deliberately diverges (see
    -- header): key on the ledger's own elevated-spend signature, not a role list.
    and not exists (
      select 1 from public.credit_ledger l
      where l.user_id = p.id
        and l.kind = 'spend'
        and l.metadata->>'elevated' = 'true'
    )
    and p.credits is distinct from public.get_credit_balance(p.id);

  get diagnostics drift_count = row_count;
  if drift_count > 0 then
    raise notice 'credit reconciliation: % account(s) drifting between profiles.credits and get_credit_balance()', drift_count;
  end if;
  return drift_count;
end;

prune_client_error_events():
declare
  pruned integer;
begin
  delete from public.client_error_events where created_at < now() - interval '30 days';
  get diagnostics pruned = row_count;
  return pruned;
end;

reserve_ai_spend(p_user uuid, p_estimate:
declare
  v_cfg          jsonb;
  v_enabled      boolean;
  v_daily_cap    numeric;
  v_monthly_cap  numeric;
  v_estimate     numeric;
  v_res_id       uuid;
  v_daily_spend  numeric;
  v_month_spend  numeric;
  v_allowed      boolean;
begin
  -- Pin the daily/monthly cap windows to UTC regardless of the session timezone.
  -- The admission + reporting sums below all use date_trunc('day'|'month', now());
  -- without this they would truncate in the SESSION tz, silently shifting the cap
  -- window off the documented UTC boundary. SET LOCAL scopes this to the call.
  set local time zone 'UTC';

  -- A negative / null / non-numeric estimate must never CREDIT headroom; clamp
  -- to zero so a bad caller can't widen the cap, only consume against it.
  v_estimate := greatest(coalesce(p_estimate, 0), 0);

  select value into v_cfg from public.system_config where key = 'ai_spend_cap';
  -- Missing config ⇒ conservative defaults (fail toward protection), matching 079.
  v_enabled     := coalesce((v_cfg ->> 'enabled')::boolean, true);
  v_daily_cap   := coalesce((v_cfg ->> 'daily_usd')::numeric, 50);
  v_monthly_cap := coalesce((v_cfg ->> 'monthly_usd')::numeric, 750);

  if not v_enabled then
    -- Operator explicitly disabled the cap: allow, hold no reservation.
    select coalesce(sum(estimated_cost_usd), 0) into v_daily_spend
      from public.ai_usage_events where created_at >= date_trunc('day', now());
    select coalesce(sum(estimated_cost_usd), 0) into v_month_spend
      from public.ai_usage_events where created_at >= date_trunc('month', now());
    return jsonb_build_object(
      'allowed', true, 'enabled', false, 'reservation_id', null,
      'daily_spend', round(v_daily_spend, 6),  'daily_cap', v_daily_cap,
      'monthly_spend', round(v_month_spend, 6), 'monthly_cap', v_monthly_cap
    );
  end if;

  -- SERIALIZE admission against the GLOBAL cap. The INSERT...SELECT...WHERE below
  -- is NOT atomic on its own under READ COMMITTED: two concurrent calls each read a
  -- snapshot that excludes the other's uncommitted reservation row, so both can see
  -- the same headroom and both insert, overshooting the cap (the exact race this
  -- migration exists to close). A transaction-scoped advisory lock on the cap key
  -- forces concurrent reservers to serialize — the second blocks until the first
  -- COMMITs and then sees its reservation in the sums below. Released automatically
  -- at transaction end. Taken AFTER the disabled-cap early-return above, so an
  -- operator who turned the cap OFF never serializes on it.
  perform pg_advisory_xact_lock(hashtext('ai_spend_cap')::bigint);

  -- Admission (serialized by the advisory lock above): the WHERE compares
  -- (committed + outstanding + estimate) against BOTH caps in the same statement
  -- that inserts the reservation. If it would cross either cap, the SELECT yields
  -- no row and nothing is inserted. The lock guarantees the outstanding-reservation
  -- sum a concurrent caller reads already includes any just-committed reservation.
  insert into public.ai_spend_reservations (user_id, estimate_usd)
  select p_user, v_estimate
  where (
    -- prospective DAILY total stays under the daily cap
    coalesce((
      select sum(estimated_cost_usd) from public.ai_usage_events
       where created_at >= date_trunc('day', now())
    ), 0)
    + coalesce((
      select sum(estimate_usd) from public.ai_spend_reservations
       where created_at >= date_trunc('day', now()) and expires_at > now()
    ), 0)
    + v_estimate
  ) < v_daily_cap
  and (
    -- prospective MONTHLY total stays under the monthly cap
    coalesce((
      select sum(estimated_cost_usd) from public.ai_usage_events
       where created_at >= date_trunc('month', now())
    ), 0)
    + coalesce((
      select sum(estimate_usd) from public.ai_spend_reservations
       where created_at >= date_trunc('month', now()) and expires_at > now()
    ), 0)
    + v_estimate
  ) < v_monthly_cap
  returning id into v_res_id;

  v_allowed := v_res_id is not null;

  -- Report the post-reservation totals (committed + outstanding) so callers /
  -- dashboards see the true in-flight picture, not the stale committed sum.
  select coalesce((
      select sum(estimated_cost_usd) from public.ai_usage_events
       where created_at >= date_trunc('day', now())
    ), 0)
    + coalesce((
      select sum(estimate_usd) from public.ai_spend_reservations
       where created_at >= date_trunc('day', now()) and expires_at > now()
    ), 0)
  into v_daily_spend;
  select coalesce((
      select sum(estimated_cost_usd) from public.ai_usage_events
       where created_at >= date_trunc('month', now())
    ), 0)
    + coalesce((
      select sum(estimate_usd) from public.ai_spend_reservations
       where created_at >= date_trunc('month', now()) and expires_at > now()
    ), 0)
  into v_month_spend;

  return jsonb_build_object(
    'allowed',        v_allowed,
    'enabled',        true,
    'reservation_id', v_res_id,
    'daily_spend',    round(v_daily_spend, 6),
    'daily_cap',      v_daily_cap,
    'monthly_spend',  round(v_month_spend, 6),
    'monthly_cap',    v_monthly_cap
  );
end;

release_ai_spend_reservation(p_id uuid):
declare
  v_deleted integer := 0;
begin
  if p_id is null then return false; end if;
  delete from public.ai_spend_reservations where id = p_id;
  get diagnostics v_deleted = row_count;
  return v_deleted > 0;
end;

cleanup_ai_spend_reservations(p_retentio:
declare
  v_deleted integer := 0;
begin
  if p_retention_seconds is null or p_retention_seconds < 1 then
    p_retention_seconds := 86400;
  end if;
  -- Delete rows whose hold already lapsed AND are old enough that no in-flight
  -- run could still be holding them.
  delete from public.ai_spend_reservations
    where expires_at < now() - make_interval(secs => p_retention_seconds);
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;

publish_map(target_id uuid, p_kind text,:
declare
  existing_slug text;
  new_slug      text;
  v_kind        text := case when p_kind = 'map_with_campaign' then 'map_with_campaign' else 'map' end;
  v_map         jsonb;
  v_unowned     int;
  -- 088: unpack the gallery facets from p_facets so a re-share that omits a facet
  -- preserves the prior column value (coalesce(..., current) in the UPDATE below).
  v_f_member_band      text    := nullif(p_facets->>'memberBand', '');
  v_f_dominant_culture text    := nullif(p_facets->>'dominantCulture', '');
  v_f_tier_spread      text    := nullif(p_facets->>'tierSpread', '');
  v_f_at_war           boolean := case when p_facets ? 'atWar' then (p_facets->>'atWar')::boolean else null end;
  -- 149: the phase-2 facets (147 columns). Digits-only + clamp for aliveness and
  -- the canonical age-band vocabulary for worldAge, so a malformed bag degrades
  -- to null (preserve-on-omit) instead of aborting the publish; the 147 CHECKs
  -- remain the DB backstop.
  v_f_aliveness        integer := case
    when p_facets ? 'aliveness' and p_facets->>'aliveness' ~ '^[0-9]+$'
    then least(greatest((p_facets->>'aliveness')::integer, 0), 100)
    else null
  end;
  v_f_world_age        text    := case
    when p_facets->>'worldAge' in ('this-week', 'this-month', 'this-season', 'this-year', 'years-past')
    then p_facets->>'worldAge'
    else null
  end;
begin
  -- Account-status gates (059, restored by 073): a banned / disabled / soft-deleted
  -- account may not publish.
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if not public.account_is_active(auth.uid()) then
    raise exception 'account is not active';
  end if;

  select map_data into v_map from public.saved_maps where id = target_id and user_id = auth.uid();
  if not found then raise exception 'Not found or not owned by caller'; end if;

  -- map_with_campaign member-ownership IDOR guard (046): every member settlement
  -- must be owned by the caller.
  if v_kind = 'map_with_campaign' then
    select count(*) into v_unowned
      from jsonb_array_elements_text(coalesce(v_map->'campaign'->'settlementIds', v_map->'settlementIds', '[]'::jsonb)) as sid
      where not exists (select 1 from public.settlements s where s.id::text = sid and s.user_id = auth.uid());
    if v_unowned > 0 then
      raise exception 'Cannot share a campaign containing settlements you do not own';
    end if;
  end if;

  -- 088 DEFENSE-IN-DEPTH: a client-supplied world snapshot is no longer trusted
  -- verbatim. When present it MUST be a versioned (schemaVersion = 1) object that
  -- carries NO HARD-DENY / covert key at any depth — otherwise reject the publish
  -- rather than store a snapshot get_gallery_map would later serve to anon. (Null =
  -- no shared-world panel, which is fine; the opt-in gate handles projection.)
  if p_world_snapshot is not null then
    if jsonb_typeof(p_world_snapshot) <> 'object'
       or (p_world_snapshot->>'schemaVersion') is distinct from '1' then
      raise exception 'World snapshot is malformed or has an unsupported schemaVersion (expected 1)';
    end if;
    if not public._gallery_world_snapshot_is_safe(p_world_snapshot) then
      raise exception 'World snapshot contains a forbidden private key and cannot be shared';
    end if;
  end if;
  -- The world-sections array gets the same depth scan (it is the second stored,
  -- anon-served artifact). schemaVersion is snapshot-only, so sections is scanned
  -- for forbidden keys but not version-gated.
  if p_world_sections is not null and not public._gallery_world_snapshot_is_safe(p_world_sections) then
    raise exception 'World sections contain a forbidden private key and cannot be shared';
  end if;

  select public_slug into existing_slug from public.saved_maps where id = target_id;
  if existing_slug is null then
    loop
      new_slug := public._make_public_slug();
      begin
        update public.saved_maps
          set is_public = true, public_slug = new_slug, published_at = now(),
              share_kind = v_kind, gallery_share_campaign = (v_kind = 'map_with_campaign'),
              -- 088: widened to an 8000-char sanitized-HTML budget (client sanitizes).
              gallery_description = left(coalesce(p_description, ''), 8000), gallery_tags = p_tags,
              gallery_importable = coalesce(p_importable, gallery_importable),
              -- 088 new columns — coalesce(..., current) preserves a prior choice
              -- on a re-share that omits the field.
              gallery_image_url          = coalesce(p_image_url, gallery_image_url),
              gallery_image_alt          = coalesce(p_image_alt, gallery_image_alt),
              gallery_share_world        = coalesce(p_share_world, gallery_share_world, false),
              gallery_world_sections     = coalesce(p_world_sections, gallery_world_sections, '[]'::jsonb),
              gallery_world_snapshot     = coalesce(p_world_snapshot, gallery_world_snapshot),
              gallery_realm_arc_summary  = coalesce(p_realm_arc_summary, gallery_realm_arc_summary),
              gallery_facet_member_band     = coalesce(v_f_member_band, gallery_facet_member_band),
              gallery_facet_at_war          = coalesce(v_f_at_war, gallery_facet_at_war),
              gallery_facet_dominant_culture = coalesce(v_f_dominant_culture, gallery_facet_dominant_culture),
              gallery_facet_tier_spread     = coalesce(v_f_tier_spread, gallery_facet_tier_spread),
              -- 149: the phase-2 facets (147) — same preserve-on-omit.
              gallery_facet_aliveness       = coalesce(v_f_aliveness, gallery_facet_aliveness),
              gallery_facet_world_age       = coalesce(v_f_world_age, gallery_facet_world_age)
          where id = target_id;
        existing_slug := new_slug;
        exit;
      exception when unique_violation then /* retry */
      end;
    end loop;
  else
    update public.saved_maps
      set is_public = true, published_at = now(), share_kind = v_kind,
          gallery_share_campaign = (v_kind = 'map_with_campaign'),
          gallery_description = left(coalesce(p_description, ''), 8000), gallery_tags = p_tags,
          gallery_importable = coalesce(p_importable, gallery_importable),
          gallery_image_url          = coalesce(p_image_url, gallery_image_url),
          gallery_image_alt          = coalesce(p_image_alt, gallery_image_alt),
          gallery_share_world        = coalesce(p_share_world, gallery_share_world, false),
          gallery_world_sections     = coalesce(p_world_sections, gallery_world_sections, '[]'::jsonb),
          gallery_world_snapshot     = coalesce(p_world_snapshot, gallery_world_snapshot),
          gallery_realm_arc_summary  = coalesce(p_realm_arc_summary, gallery_realm_arc_summary),
          gallery_facet_member_band     = coalesce(v_f_member_band, gallery_facet_member_band),
          gallery_facet_at_war          = coalesce(v_f_at_war, gallery_facet_at_war),
          gallery_facet_dominant_culture = coalesce(v_f_dominant_culture, gallery_facet_dominant_culture),
          gallery_facet_tier_spread     = coalesce(v_f_tier_spread, gallery_facet_tier_spread),
          -- 149: the phase-2 facets (147) — same preserve-on-omit.
          gallery_facet_aliveness       = coalesce(v_f_aliveness, gallery_facet_aliveness),
          gallery_facet_world_age       = coalesce(v_f_world_age, gallery_facet_world_age)
      where id = target_id;
  end if;
  return existing_slug;
end

_saved_maps_world_snapshot_guard():
begin
  -- The stored snapshot the gallery serves to anon: it MUST be a versioned object
  -- carrying no private key at any depth. Mirrors the publish_map (089) check so
  -- the DIRECT owner-RLS edit path can never store what publish_map rejects.
  if new.gallery_world_snapshot is not null then
    if jsonb_typeof(new.gallery_world_snapshot) <> 'object'
       or (new.gallery_world_snapshot->>'schemaVersion') is distinct from '1' then
      raise exception 'World snapshot is malformed or has an unsupported schemaVersion (expected 1)';
    end if;
    if not public._gallery_world_snapshot_is_safe(new.gallery_world_snapshot) then
      raise exception 'World snapshot contains a forbidden private key and cannot be stored';
    end if;
  end if;

  -- The world-sections array is the second anon-served artifact, so it gets the
  -- same depth scan. schemaVersion is snapshot-only, so sections is scanned for
  -- forbidden keys but never version-gated (matching publish_map).
  if new.gallery_world_sections is not null
     and not public._gallery_world_snapshot_is_safe(new.gallery_world_sections) then
    raise exception 'World sections contain a forbidden private key and cannot be stored';
  end if;

  return new;
end;

_gallery_npc_key(npc jsonb):
select coalesce(
  nullif(npc ->> 'id', ''),
  'npc.' || lower(trim(both '_' from regexp_replace(coalesce(npc ->> 'name', ''), '[^a-zA-Z0-9]+', '_', 'g')))
);

merge_neighbour_backlink(p_partner_id uu:
declare
  v_uid     uuid := auth.uid();
  v_data    jsonb;
  v_network jsonb;
  v_rels    jsonb;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;
  if not public.account_is_active(v_uid) then
    raise exception 'account is not active';
  end if;

  -- Lock the partner row (serializes concurrent back-links) + ownership check.
  -- Row-state gate (102): the partner must be BILLING-active — a downgraded
  -- (inactive_plan / pending_delete) partner is read-only, matching the 024/059
  -- direct-write RLS.
  select data
    into v_data
    from public.settlements
   where id = p_partner_id
     and user_id = v_uid
     and access_state = 'active'
   for update;

  -- Partner gone / not owned by caller / not billing-active → no-op. The
  -- reciprocal link self-heals on the partner's next save (which itself requires
  -- the row active again); the caller's own (forward) link is unaffected.
  if v_data is null then
    return;
  end if;

  -- neighbourNetwork: drop any prior entry for this link OR this new-save id, then
  -- PREPEND the fresh entry (mirrors the JS buildNeighbourBackLink ordering).
  v_network := coalesce(v_data -> 'neighbourNetwork', '[]'::jsonb);
  v_network := (
    select coalesce(jsonb_agg(e), '[]'::jsonb)
      from jsonb_array_elements(v_network) e
     where coalesce(e ->> 'id', '')     <> p_new_save_id::text
       and coalesce(e ->> 'linkId', '') <> p_link_id
  );
  v_network := jsonb_build_array(p_network_entry) || v_network;

  -- interSettlementRelationships: drop this link's entries, then append the new ones.
  v_rels := coalesce(v_data -> 'interSettlementRelationships', '[]'::jsonb);
  v_rels := (
    select coalesce(jsonb_agg(e), '[]'::jsonb)
      from jsonb_array_elements(v_rels) e
     where coalesce(e ->> 'linkId', '') <> p_link_id
  );
  v_rels := v_rels || coalesce(p_relationship_entries, '[]'::jsonb);

  v_data := jsonb_set(
              jsonb_set(v_data, '{neighbourNetwork}', v_network, true),
              '{interSettlementRelationships}', v_rels, true
            );

  update public.settlements
     set data            = v_data,
         neighbour_links = v_network      -- keep the mirror column in sync
   where id = p_partner_id
     and user_id = v_uid
     and access_state = 'active';
end

enforce_allocation_within_grant():
declare
  grant_amount integer;
  grant_kind   text;
  allocated    integer;
begin
  -- Lock the grant row so concurrent allocation inserts to the same grant
  -- serialize here (not only inside spend_credits' `for update of g`).
  select amount, kind into grant_amount, grant_kind
    from public.credit_ledger
    where id = new.grant_id
    for update;

  if grant_amount is null then
    raise exception 'credit allocation references missing ledger row %', new.grant_id;
  end if;
  if grant_kind <> 'grant' then
    raise exception 'credit allocation grant_id % is a % row, not a grant', new.grant_id, grant_kind;
  end if;

  -- AFTER trigger: this sum already includes the row that fired it — the new
  -- row on INSERT, the updated (NEW.amount) row on UPDATE — so it IS the
  -- post-write total. No OLD/NEW adjustment (that was 097's double-count).
  select coalesce(sum(amount), 0) into allocated
    from public.credit_spend_allocations
    where grant_id = new.grant_id;

  if allocated > grant_amount then
    raise exception
      'credit over-allocation: grant % has amount % but allocations would total %',
      new.grant_id, grant_amount, allocated;
  end if;

  return new;
end;

service_adjust_credits(actor_user uuid,:
declare
  prev_balance integer;
  effective_delta integer;
  new_balance integer;
begin
  perform public._assert_service_admin_actor(actor_user);

  if target_user is null then
    raise exception 'target_user is required';
  end if;
  if delta is null or delta = 0 then
    raise exception 'delta must be a non-zero integer';
  end if;
  if abs(delta) > 100000 then
    raise exception 'delta exceeds per-call limit (100000)';
  end if;

  -- Serialize against concurrent balance writers: spend_credits (018) opens by
  -- locking the spender's profiles row FOR UPDATE, so taking the same lock here
  -- makes the read-compute-write below atomic w.r.t. user spends and other
  -- admin adjustments.
  perform 1 from public.profiles where id = target_user for update;
  if not found then
    raise exception 'target profile not found';
  end if;

  -- Ledger truth, not the legacy cached counter.
  prev_balance := public.get_credit_balance(target_user);

  -- Clamp: a refund/deduction never drives the balance below zero (the edge
  -- function's previous Math.max(0, prev + delta) behavior, kept).
  effective_delta := greatest(delta, -greatest(prev_balance, 0));

  if effective_delta = 0 then
    return jsonb_build_object(
      'prev', prev_balance,
      'next', prev_balance,
      'delta', 0,
      'requested_delta', delta
    );
  end if;

  insert into public.credit_ledger (user_id, kind, amount, source, metadata)
  values (
    target_user,
    case when effective_delta > 0 then 'grant' else 'spend' end,
    abs(effective_delta),
    'admin_adjust',
    jsonb_build_object(
      'admin_actor', actor_user,
      'previous_balance', prev_balance,
      'requested_delta', delta,
      'reason', reason
    )
  );

  insert into public.credit_transactions (user_id, amount, reason)
  values (target_user, effective_delta, 'admin_adjust');

  new_balance := public.get_credit_balance(target_user);

  update public.profiles
    set credits = new_balance,
        updated_at = now()
    where id = target_user;

  insert into public.admin_actions
    (actor_id, target_id, action, before_value, after_value, reason)
  values (
    actor_user,
    target_user,
    'admin_adjust_credits',
    jsonb_build_object('credits', prev_balance),
    jsonb_build_object('credits', new_balance, 'delta', effective_delta),
    reason
  );

  return jsonb_build_object(
    'prev', prev_balance,
    'next', new_balance,
    'delta', effective_delta,
    'requested_delta', delta
  );
end;

record_referral_intent(p_referrer_accoun:
declare
  v_caller       uuid;
  v_referrer     uuid;
  v_account      text;
  v_open_count   integer;
  v_referral_id  uuid;
begin
  v_caller := auth.uid();
  if v_caller is null then
    raise exception 'not authenticated';
  end if;

  -- 057 discipline: banned/disabled/deleted accounts do not write.
  if not public.account_is_active(v_caller) then
    return jsonb_build_object('ok', false, 'reason', 'account_inactive');
  end if;

  -- Normalize: account numbers are SF- + 7 uppercase Crockford chars (075), so
  -- upper(btrim()) lets a pasted-lowercase handle resolve without ever creating
  -- a second matchable form (the generator never emits lowercase).
  v_account := upper(btrim(coalesce(p_referrer_account_number, '')));
  if v_account = '' then
    return jsonb_build_object('ok', false, 'reason', 'unknown_account_number');
  end if;

  select id into v_referrer
    from public.profiles
    where account_number = v_account;

  -- Unknown AND banned/disabled/deleted referrers collapse into ONE reason:
  -- account numbers are private (075), but a leaked one must still not reveal
  -- moderation state through the referral prompt.
  if v_referrer is null or not public.account_is_active(v_referrer) then
    return jsonb_build_object('ok', false, 'reason', 'unknown_account_number');
  end if;

  if v_referrer = v_caller then
    return jsonb_build_object('ok', false, 'reason', 'self_referral');
  end if;

  -- UX pre-check; the UNIQUE(referee_user_id) below is the real gate (see the
  -- unique_violation handler).
  if exists (select 1 from public.referrals where referee_user_id = v_caller) then
    return jsonb_build_object('ok', false, 'reason', 'already_referred');
  end if;

  -- Per-referrer cap (anti-farming): at most 50 open-or-rewarded referrals.
  -- count-then-insert is not atomic under READ COMMITTED on its own — two
  -- concurrent referees could both read 49 — so the cap is serialized with a
  -- transaction-scoped advisory lock on the referrer key (the 086
  -- reserve_ai_spend idiom). Rejected/clawed-back rows do NOT count: a
  -- clawback frees the seat.
  perform pg_advisory_xact_lock(hashtext('referral_cap:' || v_referrer::text));
  select count(*)::integer into v_open_count
    from public.referrals
    where referrer_user_id = v_referrer
      and status in ('pending', 'granted');
  if v_open_count >= 50 then
    return jsonb_build_object('ok', false, 'reason', 'referrer_cap_reached');
  end if;

  insert into public.referrals (referrer_user_id, referee_user_id, referrer_account_number)
    values (v_referrer, v_caller, v_account)
    returning id into v_referral_id;

  return jsonb_build_object('ok', true, 'referral_id', v_referral_id);
exception
  when unique_violation then
    -- The UNIQUE(referee_user_id) race backstop: two concurrent intents from
    -- the same referee resolve to exactly one row, the loser lands here.
    return jsonb_build_object('ok', false, 'reason', 'already_referred');
end;

grant_referral(p_referee uuid, p_invoice:
declare
  caller_role text;
  v_referral_id uuid;
  v_referrer    uuid;
begin
  -- In-body service-role assertion (024's system_grant_credits idiom): the
  -- GRANT posture below already restricts execution, this makes a future
  -- grant-posture regression fail loudly instead of moving value.
  caller_role := coalesce(current_setting('request.jwt.claim.role', true), auth.role());
  if caller_role <> 'service_role' then
    raise exception 'grant_referral is service-role only (got: %)', caller_role;
  end if;

  if p_referee is null then
    return jsonb_build_object('ok', false, 'reason', 'referee_required');
  end if;
  -- The invoice id is the clawback key — a grant without one could never be
  -- clawed back, so refuse it.
  if coalesce(btrim(p_invoice_id), '') = '' then
    return jsonb_build_object('ok', false, 'reason', 'invoice_id_required');
  end if;
  -- Zero-dollar red-team gate, RE-ASSERTED server-side: a fully-discounted or
  -- trialing first invoice (amount_paid = 0) must never mint a reward, even if
  -- the webhook's own check regresses. Money must actually have moved.
  if p_amount_paid_cents is null or p_amount_paid_cents <= 0 then
    return jsonb_build_object('ok', false, 'reason', 'non_positive_amount');
  end if;

  -- ATOMIC CLAIM (the 024 idiom): exactly one caller flips pending → granted.
  -- A webhook redelivery — or a concurrent duplicate — finds status <>
  -- 'pending', claims no row, and no-ops. The row lock taken by the winning
  -- UPDATE serializes racers; the re-evaluated WHERE starves the loser.
  update public.referrals
     set status = 'granted',
         stripe_invoice_id = p_invoice_id,
         granted_at = now()
   where referee_user_id = p_referee
     and status = 'pending'
   returning id, referrer_user_id into v_referral_id, v_referrer;

  if v_referral_id is null then
    return jsonb_build_object('ok', false, 'reason', 'no_pending_referral');
  end if;

  return jsonb_build_object(
    'ok', true,
    'referral_id', v_referral_id,
    'referrer_user_id', v_referrer
  );
exception
  when unique_violation then
    -- idx_referrals_invoice_id backstop: one invoice can never reward two
    -- referrals (a replayed invoice id under a different referee).
    return jsonb_build_object('ok', false, 'reason', 'invoice_already_used');
end;

record_referral_grant_detail(p_referral_:
declare
  caller_role text;
  v_id uuid;
begin
  caller_role := coalesce(current_setting('request.jwt.claim.role', true), auth.role());
  if caller_role <> 'service_role' then
    raise exception 'record_referral_grant_detail is service-role only (got: %)', caller_role;
  end if;

  -- Programmer error, not user input — raise, don't return a reason.
  if p_party not in ('referrer', 'referee') then
    raise exception 'p_party must be referrer or referee (got: %)', p_party;
  end if;

  if p_party = 'referrer' then
    update public.referrals
       set referrer_reward = p_reward,
           referrer_coupon_applied = p_coupon_id
     where id = p_referral_id
     returning id into v_id;
  else
    update public.referrals
       set referee_reward = p_reward,
           referee_coupon_applied = p_coupon_id
     where id = p_referral_id
     returning id into v_id;
  end if;

  if v_id is null then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  return jsonb_build_object('ok', true);
end;

clawback_referral(p_invoice_id text):
declare
  caller_role text;
  v_id               uuid;
  v_referrer         uuid;
  v_referee          uuid;
  v_referrer_reward  text;
  v_referee_reward   text;
  v_referrer_coupon  text;
  v_referee_coupon   text;
begin
  caller_role := coalesce(current_setting('request.jwt.claim.role', true), auth.role());
  if caller_role <> 'service_role' then
    raise exception 'clawback_referral is service-role only (got: %)', caller_role;
  end if;

  if coalesce(btrim(p_invoice_id), '') = '' then
    return jsonb_build_object('ok', false, 'reason', 'invoice_id_required');
  end if;

  -- ATOMIC CLAIM, keyed by the invoice the grant stamped: only a GRANTED
  -- referral flips (pending/rejected rows are untouched — nothing was ever
  -- rewarded), and a redelivered refund event finds no claimable row.
  update public.referrals
     set status = 'clawed_back',
         clawed_back_at = now()
   where stripe_invoice_id = p_invoice_id
     and status = 'granted'
   returning id, referrer_user_id, referee_user_id,
             referrer_reward, referee_reward,
             referrer_coupon_applied, referee_coupon_applied
    into v_id, v_referrer, v_referee,
         v_referrer_reward, v_referee_reward,
         v_referrer_coupon, v_referee_coupon;

  if v_id is null then
    return jsonb_build_object('ok', false, 'reason', 'no_granted_referral');
  end if;

  -- The webhook uses these to remove the Stripe coupons / adjust credits.
  return jsonb_build_object(
    'ok', true,
    'referral_id', v_id,
    'referrer_user_id', v_referrer,
    'referee_user_id', v_referee,
    'referrer_reward', v_referrer_reward,
    'referee_reward', v_referee_reward,
    'referrer_coupon_applied', v_referrer_coupon,
    'referee_coupon_applied', v_referee_coupon
  );
end;

validate_redeem_code(p_code text):
declare
  v_code public.redeem_codes%rowtype;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not public.account_is_active(auth.uid()) then
    return jsonb_build_object('valid', false, 'kind', null, 'reason', 'account_inactive');
  end if;

  select * into v_code
    from public.redeem_codes
    where code = btrim(coalesce(p_code, ''));

  -- Once per user, EVER (the UNIQUE(code,user_id) gate — a reverted attempt
  -- still counts). Checked BEFORE the availability collapse so the caller who
  -- already redeemed sees the truthful reason even after the code exhausts or
  -- expires (on a max_uses=1 code their own redemption IS the exhaustion).
  -- 'already_used' necessarily confirms the code exists, but only to a caller
  -- who has already redeemed it.
  if v_code.code is not null and exists (
    select 1 from public.redemptions
    where code = v_code.code and user_id = auth.uid()
  ) then
    return jsonb_build_object('valid', false, 'kind', null, 'reason', 'already_used');
  end if;

  -- ONE collapsed reason for unknown / deactivated / expired / exhausted: a
  -- distinguishable "expired" or "exhausted" would confirm to an enumerator
  -- that a code EXISTS. This is a UX echo; the authoritative gate is
  -- reserve_redemption at checkout-create time.
  if v_code.code is null
     or not v_code.active
     or (v_code.expires_at is not null and v_code.expires_at <= now())
     or v_code.uses_count >= v_code.max_uses then
    return jsonb_build_object('valid', false, 'kind', null, 'reason', 'invalid_code');
  end if;

  -- kind lets the client phrase the confirmation ("one month free" vs "bonus
  -- credits"). The coupon id and amounts NEVER leave the server.
  return jsonb_build_object('valid', true, 'kind', v_code.kind, 'reason', null);
end;

bind_redemption_session(p_redemption_id:
declare
  caller_role text;
  v_id uuid;
begin
  caller_role := coalesce(current_setting('request.jwt.claim.role', true), auth.role());
  if caller_role <> 'service_role' then
    raise exception 'bind_redemption_session is service-role only (got: %)', caller_role;
  end if;

  if coalesce(btrim(p_session_id), '') = '' then
    return jsonb_build_object('ok', false, 'reason', 'session_id_required');
  end if;

  -- Write-once: a reserved row binds to exactly one checkout session (a retry
  -- with the SAME id is an idempotent success; a different id is refused so a
  -- second session can never hijack the seat).
  update public.redemptions
     set stripe_session_id = p_session_id
   where id = p_redemption_id
     and status = 'reserved'
     and (stripe_session_id is null or stripe_session_id = p_session_id)
   returning id into v_id;

  if v_id is null then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  return jsonb_build_object('ok', true);
end;

apply_redemption(p_session_id text):
declare
  caller_role text;
  v_id     uuid;
  v_code   text;
  v_user   uuid;
  v_kind   text;
  v_credit integer;
begin
  caller_role := coalesce(current_setting('request.jwt.claim.role', true), auth.role());
  if caller_role <> 'service_role' then
    raise exception 'apply_redemption is service-role only (got: %)', caller_role;
  end if;

  if coalesce(btrim(p_session_id), '') = '' then
    return jsonb_build_object('ok', false, 'reason', 'session_id_required');
  end if;

  -- ATOMIC CLAIM: reserved → applied exactly once per session; a redelivered
  -- checkout.session.completed finds no reserved row and no-ops.
  update public.redemptions
     set status = 'applied',
         applied_at = now()
   where stripe_session_id = p_session_id
     and status = 'reserved'
   returning id, code, user_id into v_id, v_code, v_user;

  if v_id is null then
    return jsonb_build_object('ok', false, 'reason', 'no_reserved_redemption');
  end if;

  -- Joined so the webhook can grant credit-kind codes (via system_grant_credits)
  -- without a second round trip. free_month codes need no further DB action —
  -- the coupon already rode the checkout session.
  select kind, credit_amount into v_kind, v_credit
    from public.redeem_codes
    where code = v_code;

  return jsonb_build_object(
    'ok', true,
    'redemption_id', v_id,
    'code', v_code,
    'user_id', v_user,
    'kind', v_kind,
    'credit_amount', v_credit
  );
end;

revert_redemption(p_session_id text):
declare
  caller_role text;
  v_id   uuid;
  v_code text;
begin
  caller_role := coalesce(current_setting('request.jwt.claim.role', true), auth.role());
  if caller_role <> 'service_role' then
    raise exception 'revert_redemption is service-role only (got: %)', caller_role;
  end if;

  if coalesce(btrim(p_session_id), '') = '' then
    return jsonb_build_object('ok', false, 'reason', 'session_id_required');
  end if;

  -- ATOMIC CLAIM: only a reserved row flips, so a redelivered expiry event (or
  -- an expiry racing the completion) finds no row and no-ops — the seat is
  -- handed back at most once, and an APPLIED redemption is never reverted.
  update public.redemptions
     set status = 'reverted'
   where stripe_session_id = p_session_id
     and status = 'reserved'
   returning id, code into v_id, v_code;

  if v_id is null then
    return jsonb_build_object('ok', false, 'reason', 'no_reserved_redemption');
  end if;

  -- Hand the seat back. Guarded — never below zero (check constraint backstop).
  update public.redeem_codes
     set uses_count = greatest(uses_count - 1, 0)
   where code = v_code;

  return jsonb_build_object('ok', true, 'redemption_id', v_id);
end;

grant_dossier_entitlement(p_user uuid, p:
declare
  caller_role text;
  v_source    text;
  v_owner     uuid;
  v_id        uuid;
  v_existing  uuid;
begin
  -- In-body service-role assertion (024's system_grant_credits idiom): the GRANT
  -- posture below already restricts execution; this makes a future grant-posture
  -- regression fail loudly instead of minting a right.
  caller_role := coalesce(current_setting('request.jwt.claim.role', true), auth.role());
  if caller_role <> 'service_role' then
    raise exception 'grant_dossier_entitlement is service-role only (got: %)', caller_role;
  end if;

  if p_user is null then
    return jsonb_build_object('ok', false, 'reason', 'user_required');
  end if;
  if coalesce(btrim(p_session_id), '') = '' then
    -- The session id is the idempotency + clawback key — refuse a grant without one.
    return jsonb_build_object('ok', false, 'reason', 'session_id_required');
  end if;
  -- Default to 'purchase'; only the two known sources are accepted.
  v_source := coalesce(p_source, 'purchase');
  if v_source not in ('purchase', 'claim') then
    return jsonb_build_object('ok', false, 'reason', 'invalid_source');
  end if;

  -- "Save it first": the settlement must EXIST and belong to p_user. A missing or
  -- foreign save is refused before any row is written — the durable right can
  -- only attach to the buyer's own saved dossier.
  select user_id into v_owner from public.settlements where id = p_save_id;
  if v_owner is null or v_owner <> p_user then
    return jsonb_build_object('ok', false, 'reason', 'save_not_found');
  end if;

  -- IDEMPOTENT on stripe_session_id: a webhook redelivery of the same paid
  -- session finds the existing row and reports already_existed WITHOUT minting a
  -- second right. Checked first so a replay is a clean success, not a conflict.
  select id into v_existing
    from public.dossier_entitlements
    where stripe_session_id = btrim(p_session_id);
  if v_existing is not null then
    return jsonb_build_object('ok', true, 'already_existed', true, 'entitlement_id', v_existing);
  end if;

  -- Mint the durable right. The UNIQUE(user_id, save_id) catches an already-held
  -- settlement (a different session for a save the user is already entitled to);
  -- the UNIQUE(stripe_session_id) is the concurrent-replay backstop.
  insert into public.dossier_entitlements (user_id, save_id, stripe_session_id, source)
    values (p_user, p_save_id, btrim(p_session_id), v_source)
    returning id into v_id;

  return jsonb_build_object('ok', true, 'already_existed', false, 'entitlement_id', v_id);
exception
  when unique_violation then
    -- Distinguish the two unique constraints so the caller gets a truthful reason.
    -- A (user, save) collision means the user already holds a right on this
    -- settlement (via a DIFFERENT session); a session collision is a concurrent
    -- replay of THIS session that raced past the pre-check.
    if exists (
      select 1 from public.dossier_entitlements
      where user_id = p_user and save_id = p_save_id
    ) and not exists (
      select 1 from public.dossier_entitlements
      where stripe_session_id = btrim(p_session_id)
    ) then
      return jsonb_build_object('ok', false, 'reason', 'already_entitled');
    end if;
    -- Concurrent same-session replay: resolve to the existing row, report success.
    select id into v_existing
      from public.dossier_entitlements
      where stripe_session_id = btrim(p_session_id);
    return jsonb_build_object('ok', true, 'already_existed', true, 'entitlement_id', v_existing);
end;

clawback_dossier_entitlement(p_session_i:
declare
  caller_role text;
  v_id     uuid;
  v_user   uuid;
begin
  caller_role := coalesce(current_setting('request.jwt.claim.role', true), auth.role());
  if caller_role <> 'service_role' then
    raise exception 'clawback_dossier_entitlement is service-role only (got: %)', caller_role;
  end if;

  if coalesce(btrim(p_session_id), '') = '' then
    return jsonb_build_object('ok', false, 'reason', 'session_id_required');
  end if;

  -- Poison the voucher FIRST and UNCONDITIONALLY: a refunded purchase can never
  -- be claimed, whether or not a durable right was ever minted (the anonymous-
  -- refund case, where the buyer never signed up so no entitlement exists). This
  -- closes the refund→claim race permanently — a claim after this point finds a
  -- 'refunded' row and is denied. Idempotent: a redelivered refund re-writes the
  -- same terminal status.
  update public.single_dossier_purchases
     set status = 'refunded'
   where stripe_session_id = btrim(p_session_id)
     and status <> 'refunded';

  -- ATOMIC CLAIM (the 024 idiom): exactly one caller flips active → clawed_back.
  -- A redelivered refund event — or a concurrent duplicate — finds status <>
  -- 'active', claims no row, and no-ops.
  update public.dossier_entitlements
     set status = 'clawed_back',
         clawed_back_at = now()
   where stripe_session_id = btrim(p_session_id)
     and status = 'active'
   returning id, user_id into v_id, v_user;

  if v_id is null then
    -- No active entitlement to reverse. The purchase row (if any) is already
    -- flipped to 'refunded' above, so the anonymous-refund case is fully handled
    -- — report success with a null entitlement id so the webhook does not retry.
    return jsonb_build_object('ok', true, 'entitlement_id', null);
  end if;

  return jsonb_build_object('ok', true, 'entitlement_id', v_id, 'user_id', v_user);
end;

has_dossier_entitlement(p_save_id uuid):
declare
  v_caller uuid;
begin
  v_caller := auth.uid();
  if v_caller is null then
    return false;
  end if;
  return exists (
    select 1 from public.dossier_entitlements
    where user_id = v_caller
      and save_id = p_save_id
      and status = 'active'
  );
end;

claim_dossier_purchase_by_session(p_sess:
declare
  caller_role text;
  v_purchase  public.single_dossier_purchases%rowtype;
  v_owner     uuid;
  v_claimed   text;
  v_id        uuid;
begin
  caller_role := coalesce(current_setting('request.jwt.claim.role', true), auth.role());
  if caller_role <> 'service_role' then
    raise exception 'claim_dossier_purchase_by_session is service-role only (got: %)', caller_role;
  end if;

  if p_user is null then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  if coalesce(btrim(p_session_id), '') = '' then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;

  select * into v_purchase
    from public.single_dossier_purchases
    where stripe_session_id = btrim(p_session_id);
  if v_purchase.stripe_session_id is null then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;

  if v_purchase.status = 'refunded' then
    return jsonb_build_object('ok', false, 'reason', 'refunded');
  end if;
  if v_purchase.status = 'claimed' then
    return jsonb_build_object('ok', false, 'reason', 'already_claimed');
  end if;

  -- "Save it first": the voucher binds only to a settlement p_user owns.
  select user_id into v_owner from public.settlements where id = p_save_id;
  if v_owner is null or v_owner <> p_user then
    return jsonb_build_object('ok', false, 'reason', 'save_not_found');
  end if;

  -- GUARD 1 (check-before-consume): if the save already carries a durable right for this
  -- user, the voucher can mint nothing (the (user_id, save_id) unique index), so do NOT
  -- burn it — leave it 'unclaimed' so it stays spendable on another settlement.
  if exists (
    select 1 from public.dossier_entitlements
    where user_id = p_user and save_id = p_save_id
  ) then
    return jsonb_build_object('ok', false, 'reason', 'already_entitled');
  end if;

  -- ATOMIC CLAIM #1: flip unclaimed → claimed exactly once.
  update public.single_dossier_purchases
     set status = 'claimed',
         claimed_by = p_user,
         claimed_at = now()
   where stripe_session_id = v_purchase.stripe_session_id
     and status = 'unclaimed'
   returning stripe_session_id into v_claimed;

  if v_claimed is null then
    return jsonb_build_object('ok', false, 'reason', 'already_claimed');
  end if;

  -- ATOMIC CLAIM #2 (same transaction): mint the durable right.
  begin
    insert into public.dossier_entitlements (user_id, save_id, stripe_session_id, source)
      values (p_user, p_save_id, v_purchase.stripe_session_id, 'claim')
      returning id into v_id;
  exception
    when unique_violation then
      if exists (
        select 1 from public.dossier_entitlements
        where user_id = p_user and save_id = p_save_id
      ) and not exists (
        select 1 from public.dossier_entitlements
        where stripe_session_id = v_purchase.stripe_session_id
      ) then
        -- GUARD 2 (restore-in-race): a concurrent claim minted the (user, save) right
        -- between GUARD 1 and here, so CLAIM #1 burned THIS voucher for nothing. Restore
        -- it to 'unclaimed' (this txn owns the just-set 'claimed' row, so no one else can
        -- see it yet) so the paid voucher stays spendable on another settlement.
        update public.single_dossier_purchases
           set status = 'unclaimed', claimed_by = null, claimed_at = null
         where stripe_session_id = v_purchase.stripe_session_id
           and status = 'claimed'
           and claimed_by = p_user;
        return jsonb_build_object('ok', false, 'reason', 'already_entitled');
      end if;
      return jsonb_build_object('ok', false, 'reason', 'already_claimed');
  end;

  return jsonb_build_object('ok', true, 'entitlement_id', v_id);
end;

reserve_redemption(p_code text, p_user u:
declare
  caller_role  text;
  v_code       text;
  v_coupon     text;
  v_kind       text;
  v_credit     integer;
  v_applies    text;
  v_redemption uuid;
begin
  caller_role := coalesce(current_setting('request.jwt.claim.role', true), auth.role());
  if caller_role <> 'service_role' then
    raise exception 'reserve_redemption is service-role only (got: %)', caller_role;
  end if;

  if p_user is null then
    return jsonb_build_object('ok', false, 'reason', 'user_required');
  end if;

  -- GUARDED ATOMIC INCREMENT: one statement takes the code's row lock, and the
  -- WHERE is re-evaluated after the lock clears — so of two concurrent reserves on
  -- the last seat (uses_count = max_uses - 1), exactly one gets a row and the loser
  -- falls through to 'invalid_code'.
  update public.redeem_codes
     set uses_count = uses_count + 1
   where code = btrim(coalesce(p_code, ''))
     and active
     and (expires_at is null or expires_at > now())
     and uses_count < max_uses
   returning code, stripe_coupon_id, kind, credit_amount, applies_to
    into v_code, v_coupon, v_kind, v_credit, v_applies;

  if v_code is null then
    return jsonb_build_object('ok', false, 'reason', 'invalid_code');
  end if;

  -- MODE GATE (112): reject a code that cannot ride this checkout mode BEFORE the
  -- once-per-user row is created, so a wrong-modal attempt never burns the redemption.
  -- Mirrors create-checkout's redeemAppliesToMode exactly: 'subscription' rides only
  -- subscription mode, 'one_time' only payment mode, 'any'/null rides both. A null
  -- p_mode skips the gate (mode-blind back-compat). Hand the just-claimed seat back.
  if p_mode is not null and (
       (v_applies = 'subscription' and p_mode <> 'subscription')
    or (v_applies = 'one_time'     and p_mode <> 'payment')
  ) then
    update public.redeem_codes
       set uses_count = greatest(uses_count - 1, 0)
     where code = v_code;
    return jsonb_build_object('ok', false, 'reason', 'mode_mismatch', 'applies_to', v_applies);
  end if;

  insert into public.redemptions (code, user_id, status)
    values (v_code, p_user, 'reserved')
    on conflict (code, user_id) do nothing
    returning id into v_redemption;

  if v_redemption is null then
    -- Once-per-user gate hit: hand the seat straight back (same transaction).
    update public.redeem_codes
       set uses_count = greatest(uses_count - 1, 0)
     where code = v_code;
    return jsonb_build_object('ok', false, 'reason', 'already_used');
  end if;

  return jsonb_build_object(
    'ok', true,
    'stripe_coupon_id', v_coupon,
    'kind', v_kind,
    'credit_amount', v_credit,
    'applies_to', v_applies,
    'redemption_id', v_redemption
  );
end;

get_ai_pricing():
declare
  costs_cfg   jsonb;
  price_cfg   jsonb;
  is_elevated boolean;
  caller_role text;
  profile_key text;
  fallback    jsonb;
  credit_out  jsonb := '{}'::jsonb;
  models_out  jsonb := '{}'::jsonb;
  usd_out     jsonb := '{}'::jsonb;
  cost_val    integer;
  tokens      integer;
  est_run     jsonb;
  in_price    numeric;
  out_price   numeric;
  updated_at  text;
  -- The 8 profile keys paired with their tier defaults (180: standard 5/4/6, fast 2/3/4).
  -- This literal table IS the always-complete fallback schedule.
  defaults    jsonb := jsonb_build_object(
    'anthropic_claude_opus_4_8',   jsonb_build_object('narrative', 5, 'dailyLife', 4, 'progression', 6),
    'anthropic_claude_sonnet_4_6', jsonb_build_object('narrative', 5, 'dailyLife', 4, 'progression', 6),
    'anthropic_claude_haiku_4_5',  jsonb_build_object('narrative', 2, 'dailyLife', 3, 'progression', 4),
    'openai_gpt_5_2',              jsonb_build_object('narrative', 5, 'dailyLife', 4, 'progression', 6),
    'openai_gpt_5_mini',           jsonb_build_object('narrative', 2, 'dailyLife', 3, 'progression', 4),
    'openai_gpt_5_nano',           jsonb_build_object('narrative', 2, 'dailyLife', 3, 'progression', 4),
    'openai_gpt_4_1',              jsonb_build_object('narrative', 5, 'dailyLife', 4, 'progression', 6),
    'openai_gpt_4_1_mini',         jsonb_build_object('narrative', 2, 'dailyLife', 3, 'progression', 4)
  );
  feat        text;
begin
  select value into costs_cfg from public.system_config where key = 'ai_credit_costs';
  select value into price_cfg from public.system_config where key = 'ai_price_book';

  -- Elevated = the privileged-email/role helper OR an explicit developer/admin role
  -- (mirrors how 057/024 detect elevation). Only elevation reveals the USD block.
  select role into caller_role from public.profiles where id = auth.uid();
  is_elevated := public.current_user_is_privileged()
                 or coalesce(caller_role, '') in ('developer', 'admin');

  -- Resolve credit costs profile-by-profile. Each feature is validated (integer 1..12);
  -- any miss/malformation falls back to that profile's tier default.
  for profile_key in select jsonb_object_keys(defaults)
  loop
    fallback := defaults -> profile_key;
    declare
      resolved jsonb := fallback;
    begin
      foreach feat in array array['narrative', 'dailyLife', 'progression']
      loop
        cost_val := null;
        begin
          cost_val := (costs_cfg -> 'profiles' -> profile_key ->> feat)::integer;
        exception when others then
          cost_val := null;
        end;
        if cost_val is null or cost_val < 1 or cost_val > 12 then
          resolved := jsonb_set(resolved, array[feat], fallback -> feat);
        else
          resolved := jsonb_set(resolved, array[feat], to_jsonb(cost_val));
        end if;
      end loop;
      credit_out := jsonb_set(credit_out, array[profile_key], resolved);
    end;

    -- Per-model est-run token shape (input+output rounded), null when absent.
    est_run := price_cfg -> 'models' -> profile_key -> 'estRun';
    tokens := null;
    if est_run is not null and jsonb_typeof(est_run) = 'object' then
      begin
        tokens := round(
          coalesce((est_run ->> 'inputTokens')::numeric, 0)
          + coalesce((est_run ->> 'outputTokens')::numeric, 0)
        )::integer;
      exception when others then
        tokens := null;
      end;
    end if;
    models_out := jsonb_set(models_out, array[profile_key],
      jsonb_build_object('estRunTokens', case when tokens is null then null else to_jsonb(tokens) end));

    -- USD block (elevated only): per-model input/output price + est run cost.
    if is_elevated then
      begin
        in_price  := (price_cfg -> 'models' -> profile_key ->> 'inputPerMtok')::numeric;
        out_price := (price_cfg -> 'models' -> profile_key ->> 'outputPerMtok')::numeric;
      exception when others then
        in_price := null; out_price := null;
      end;
      usd_out := jsonb_set(usd_out, array[profile_key], jsonb_build_object(
        'inputPerMtok', case when in_price is null then null else to_jsonb(in_price) end,
        'outputPerMtok', case when out_price is null then null else to_jsonb(out_price) end,
        'estRunUsd', case
          when tokens is null or in_price is null or out_price is null then null
          else to_jsonb(round(
            coalesce((est_run ->> 'inputTokens')::numeric, 0) / 1000000.0 * in_price
            + coalesce((est_run ->> 'outputTokens')::numeric, 0) / 1000000.0 * out_price, 6))
        end
      ));
    end if;
  end loop;

  updated_at := coalesce(costs_cfg ->> 'updatedAt', price_cfg ->> 'updatedAt');

  return jsonb_build_object(
    'updatedAt', case when updated_at is null then null else to_jsonb(updated_at) end,
    'creditCosts', credit_out,
    'chronicle', 2,
    'models', models_out
  ) || case when is_elevated then jsonb_build_object('usd', usd_out) else '{}'::jsonb end;
end;

_pricing_cron_should_dispatch(cfg jsonb,:
declare
  tz         text;
  local_now  timestamp;
  local_today text;
  cfg_url    text;
  cfg_secret text;
begin
  -- 1. missing / malformed config → not_configured
  if cfg is null or jsonb_typeof(cfg) <> 'object' then
    return 'not_configured';
  end if;
  -- 2. enabled must be exactly true (the kill switch)
  if coalesce((cfg ->> 'enabled')::boolean, false) is not true then
    return 'disabled';
  end if;
  -- 3. url + secret must both be present + non-empty
  cfg_url    := nullif(cfg ->> 'url', '');
  cfg_secret := nullif(cfg ->> 'secret', '');
  if cfg_url is null or cfg_secret is null then
    return 'not_configured';
  end if;
  -- 4. THE DST-PROOF GUARD: only the local-midnight firing proceeds. The job fires
  --    hourly UTC; convert to the configured zone and require wall-clock hour = 0.
  tz := coalesce(nullif(cfg ->> 'timezone', ''), 'America/New_York');
  local_now := at_ts at time zone tz;
  if extract(hour from local_now) <> 0 then
    return 'skipped_hour';
  end if;
  -- 5. at-most-once-per-local-day dedupe
  local_today := to_char(local_now, 'YYYY-MM-DD');
  if (cfg ->> 'lastDispatchedOn') = local_today then
    return 'skipped_already';
  end if;
  return 'ok';
exception
  -- A bad IANA zone string (or any coercion failure) must never throw out of the
  -- cron job — treat it as not_configured so the operator fixes the config, no dispatch.
  when others then
    return 'not_configured';
end;

run_pricing_resync_nightly():
declare
  cfg        jsonb;
  verdict    text;
  cfg_url    text;
  cfg_secret text;
  tz         text;
  local_today text;
  req_id     bigint;
begin
  select value into cfg from public.system_config where key = 'pricing_resync_cron';

  -- The guard owns the config/enabled/hour/dedupe decision (shared with the tests).
  verdict := public._pricing_cron_should_dispatch(cfg, now());
  if verdict <> 'ok' then
    return verdict;
  end if;

  cfg_url    := cfg ->> 'url';
  cfg_secret := cfg ->> 'secret';
  tz         := coalesce(nullif(cfg ->> 'timezone', ''), 'America/New_York');
  local_today := to_char(now() at time zone tz, 'YYYY-MM-DD');

  -- Mark dispatched FIRST: if pg_net then errors we still won't re-dispatch this
  -- local day (the edge function is the source of truth for the run outcome; a
  -- failed POST is recoverable tomorrow, a double-charge from a double-run is not).
  update public.system_config
     set value = jsonb_set(value, '{lastDispatchedOn}', to_jsonb(local_today))
   where key = 'pricing_resync_cron';

  -- Fire the POST. net.http_post is only present when pg_net is installed; wrap the
  -- call so a missing extension is a soft 'pg_net_unavailable', never a throw.
  begin
    select net.http_post(
      url     := cfg_url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'x-cron-secret', cfg_secret
      ),
      body    := '{}'::jsonb
    ) into req_id;
  exception
    when undefined_function or undefined_table or invalid_schema_name then
      raise notice 'pg_net unavailable; pricing-resync-cron not dispatched (install pg_net or schedule the POST manually)';
      return 'pg_net_unavailable';
  end;

  return 'dispatched:' || coalesce(req_id::text, 'unknown');
end;

claim_free_narrative(p_user uuid):
declare
  claimed boolean;
begin
  update public.profiles
    set free_narrative_claimed_at = now()
    where id = p_user
      and free_narrative_claimed_at is null;
  -- FOUND is true iff the UPDATE flipped a row (i.e. THIS call won the claim). A row
  -- that was already claimed matches the id but fails the NULL guard, so FOUND is
  -- false and the caller falls through to the normal precheck + spend path.
  claimed := found;
  return claimed;
end;

free_narrative_available(target_user uui:
declare
  available boolean;
begin
  if target_user is null then
    return false;
  end if;
  -- IDOR guard (mirrors 110's get_credit_balance): a non-NULL auth.uid() may read only
  -- its OWN row unless elevated. service_role / pg_cron / migrations reach here with a
  -- NULL auth.uid() and are trusted to read any target.
  if auth.uid() is not null
     and target_user is distinct from auth.uid()
     and not public.current_user_is_privileged()
  then
    raise exception 'free_narrative_available: not authorized to read another user''s claim'
      using errcode = '42501';  -- insufficient_privilege
  end if;

  select free_narrative_claimed_at is null
    into available
    from public.profiles
    where id = target_user;

  -- No such profile ⇒ nothing to offer.
  return coalesce(available, false);
end;

claim_ai_request(p_user uuid, p_key text:
declare
  v_ttl        integer;
  v_inserted   integer := 0;
  v_spend_id   uuid;
begin
  if p_user is null or p_key is null or length(p_key) = 0 then
    -- A malformed claim never deduplicates (fail OPEN toward the normal flow):
    -- report not-a-duplicate so the caller charges as it would today. The edge
    -- also validates the key before calling, so this is defence-in-depth.
    return jsonb_build_object('duplicate', false);
  end if;

  -- Clamp a negative/null TTL to 0 (every prior row is stale) rather than error.
  v_ttl := greatest(coalesce(p_ttl_seconds, 180), 0);

  -- Prune a STALE claim for this exact key so an expired key is a fresh request.
  -- Only this (user, key) is touched — never another request's live claim.
  delete from public.ai_request_claims
    where user_id = p_user
      and request_key = p_key
      and created_at < now() - make_interval(secs => v_ttl);

  -- Atomic dedup: exactly one of two concurrent identical claims inserts a row.
  insert into public.ai_request_claims (user_id, request_key)
    values (p_user, p_key)
    on conflict (user_id, request_key) do nothing;
  get diagnostics v_inserted = row_count;

  if v_inserted > 0 then
    -- We won the claim: a genuinely-new (or post-TTL) logical request.
    return jsonb_build_object('duplicate', false);
  end if;

  -- A live row already exists (a retry within the TTL): report the prior spend_id
  -- so the caller can target the real charge without re-spending. May be NULL if
  -- the first attempt was free/elevated or hasn't attached yet — that's expected.
  select spend_id into v_spend_id
    from public.ai_request_claims
    where user_id = p_user and request_key = p_key;

  return jsonb_build_object('duplicate', true, 'spend_id', v_spend_id);
end;

attach_ai_spend_to_claim(p_user uuid, p_:
begin
  if p_user is null or p_key is null then
    return;
  end if;
  update public.ai_request_claims
    set spend_id = p_spend_id
    where user_id = p_user
      and request_key = p_key;
  -- No-op when the row is gone (pruned/expired) — nothing to attach to, and the
  -- charge already stands on its own ledger row regardless.
end;

purge_dossier_purchases(p_retention_seco:
declare
  v_deleted integer := 0;
begin
  if p_retention_seconds is null or p_retention_seconds < 1 then
    p_retention_seconds := 2592000;
  end if;
  delete from public.dossier_purchases
    where created_at < now() - make_interval(secs => p_retention_seconds);
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;

_consume_action_rate_limit(p_uid uuid, p:
declare
  v_window timestamptz;
  v_count  integer;
begin
  if p_window_seconds is null or p_window_seconds < 1 then
    p_window_seconds := 3600;
  end if;

  v_window := to_timestamp(
    floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds
  );

  insert into public.user_action_rate_limits as ual (user_key, action, window_start, count)
  values (p_uid, p_action, v_window, 1)
  on conflict (user_key, action, window_start)
    do update set count = ual.count + 1
  returning ual.count into v_count;

  return v_count;
end;

cleanup_user_action_rate_limits(p_retent:
declare
  v_deleted integer := 0;
begin
  if p_retention_seconds is null or p_retention_seconds < 1 then
    p_retention_seconds := 86400;
  end if;
  delete from public.user_action_rate_limits
    where window_start < now() - make_interval(secs => p_retention_seconds);
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;

is_allowed_email_category(p_category tex:
select p_category is not null and p_category in (
  'product_updates',
  'referral',
  'lifecycle'
);

get_my_email_preferences():
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  return query
    select
      coalesce(ep.product_updates and ep.product_updates_decided_at is not null, false),
      coalesce(ep.referral, true),
      coalesce(ep.lifecycle, true)
    from (select v_uid as user_id) base
    left join public.email_preferences ep on ep.user_id = base.user_id;
end;

unsubscribe_via_token(p_token uuid, p_ca:
declare
  v_uid uuid;
begin
  if p_token is null then return false; end if;
  if p_category <> 'all' and not public.is_allowed_email_category(p_category) then
    return false;
  end if;

  select ep.user_id into v_uid
    from public.email_preferences ep
   where ep.unsubscribe_token = p_token
   limit 1;
  if v_uid is null then return false; end if;

  if p_category = 'all' then
    update public.email_preferences
       set product_updates = false,
           product_updates_decided_at = now(),
           referral = false,
           lifecycle = false,
           updated_at = now()
     where user_id = v_uid;
  elsif p_category = 'product_updates' then
    update public.email_preferences
       set product_updates = false,
           product_updates_decided_at = now(),
           updated_at = now()
     where user_id = v_uid;
  else
    execute format(
      'update public.email_preferences set %I = false, updated_at = now() where user_id = $1',
      p_category
    ) using v_uid;
  end if;
  return true;
end;

can_email_user(p_user_id uuid, p_categor:
declare
  v_enabled boolean;
begin
  if p_user_id is null or not public.is_allowed_email_category(p_category) then
    return false;
  end if;
  if p_category = 'product_updates' then
    select ep.product_updates and ep.product_updates_decided_at is not null
      into v_enabled
      from public.email_preferences ep
     where ep.user_id = p_user_id;
    return coalesce(v_enabled, false);
  end if;
  execute format('select %I from public.email_preferences where user_id = $1', p_category)
    into v_enabled using p_user_id;
  return coalesce(v_enabled, true);
end;

get_or_mint_unsubscribe_token(p_user_id:
declare
  v_token uuid;
begin
  if p_user_id is null then
    raise exception 'user id is required';
  end if;

  insert into public.email_preferences (user_id)
  values (p_user_id)
  on conflict (user_id) do nothing;

  select ep.unsubscribe_token into v_token
  from public.email_preferences ep
  where ep.user_id = p_user_id
  limit 1;

  return v_token;
end;

set_founder_display_optin(p_display_name:
declare
  v_seat   smallint;
  v_name   text;
  v_slug   text;
begin
  if auth.uid() is null then
    raise exception 'sign-in required';
  end if;
  v_name := nullif(btrim(coalesce(p_display_name, '')), '');
  v_slug := nullif(btrim(coalesce(p_gallery_slug, '')), '');

  update public.founder_seats
     set display_name_optin  = v_name,
         gallery_author_slug  = v_slug,
         -- any new/changed opt-in re-enters moderation; clearing it resets to pending.
         display_name_status  = 'pending',
         updated_at           = now()
   where holder_user_id = auth.uid()
  returning seat_id into v_seat;

  if v_seat is null then
    raise exception 'caller holds no founder seat';
  end if;

  return jsonb_build_object('seat_id', v_seat, 'display_name', v_name, 'status', 'pending');
end;

claim_next_founder_seat(p_user uuid):
declare
  v_role text;
  v_seat smallint;
begin
  v_role := coalesce(current_setting('request.jwt.claim.role', true), auth.role());
  if v_role <> 'service_role' then
    raise exception 'claim_next_founder_seat is service-role only (got: %)', v_role;
  end if;
  if p_user is null then
    raise exception 'a user is required';
  end if;

  -- Already a holder? Return the existing seat (idempotent — never mints a second).
  select seat_id into v_seat from public.founder_seats where holder_user_id = p_user;
  if v_seat is not null then
    return jsonb_build_object('seat_id', v_seat, 'assigned', false);
  end if;

  -- Claim the lowest unclaimed seat atomically (row lock; skip locked so concurrent
  -- purchases take distinct seats). NULL ⇒ sold out (all 30 held). The transfer
  -- lifecycle stamps (§6.1) are set here at the ORIGINAL purchase: original_purchase_at
  -- anchors the 12-month hold + chargeback invariant (LAW 8), and transfer_eligible_at
  -- = held_since + 12 months is the earliest this holder may initiate a transfer.
  update public.founder_seats
     set holder_user_id       = p_user,
         held_since           = now(),
         claimed_at           = now(),
         original_purchase_at = now(),
         acquired_via         = 'purchase',
         transfer_eligible_at = now() + interval '12 months',
         updated_at           = now()
   where seat_id = (
     select seat_id from public.founder_seats
      where holder_user_id is null
        -- ESCHEAT seats (§6.8/M-10) return to the pool but are NEVER auto-resold
        -- (Q1) — only an owner decision releases them. A 'normal' unclaimed seat is
        -- the only auto-assignable one.
        and security_status = 'normal'
      order by seat_id
      for update skip locked
      limit 1
   )
  returning seat_id into v_seat;

  if v_seat is null then
    raise exception 'all 30 founder seats are claimed';
  end if;

  return jsonb_build_object('seat_id', v_seat, 'assigned', true);
end;

release_founder_seat_on_clawback(p_user:
declare
  v_role text;
  v_seat smallint;
  v_from_name text;
begin
  v_role := coalesce(current_setting('request.jwt.claim.role', true), auth.role());
  if v_role <> 'service_role' then
    raise exception 'release_founder_seat_on_clawback is service-role only (got: %)', v_role;
  end if;
  if p_user is null then
    raise exception 'a user is required';
  end if;

  -- Snapshot the outgoing holder's opted+approved display name BEFORE clearing, so
  -- the lineage keeps what they chose to show as a Founder (NULL if never opted in).
  select case when display_name_status = 'approved'
              then nullif(btrim(coalesce(display_name_optin, '')), '') end
    into v_from_name
  from public.founder_seats
  where holder_user_id = p_user;

  -- Claim-once: clear the holder and reset the seat to a fresh unclaimed state. A
  -- redelivered refund finds no matching holder and no-ops.
  update public.founder_seats
     set holder_user_id       = null,
         display_name_optin   = null,
         display_name_status  = 'pending',
         gallery_author_slug  = null,
         held_since           = null,
         claimed_at           = null,
         original_purchase_at = null,
         acquired_via         = 'purchase',
         transfer_eligible_at = null,
         last_transfer_at     = null,
         cooldown_until       = null,
         security_status      = 'normal',
         updated_at           = now()
   where holder_user_id = p_user
  returning seat_id into v_seat;

  if v_seat is null then
    return jsonb_build_object('released', false);
  end if;

  insert into public.founder_seat_transfers (seat_id, from_holder, to_holder, from_display_name, note)
    values (v_seat, p_user, null, v_from_name, 'clawback');

  return jsonb_build_object('released', true, 'seat_id', v_seat);
end;

has_surveyor_entitlement():
declare v_caller uuid;
begin
  v_caller := auth.uid();
  if v_caller is null then return false; end if;
  -- 1. Staff (developer/admin), checked first (201, unchanged).
  if public.current_user_is_privileged() then return true; end if;
  -- 2. An active premium tier: Cartographer and above, Founders as lifetime premium.
  if public.current_user_has_premium_access() then return true; end if;
  -- 3. A staff grant (the admin concierge path), honoured; a purchased row is not access.
  return exists (
    select 1 from public.surveyor_entitlements
    where user_id = v_caller and status = 'active' and source = 'grant'
  );
end;

_surveyor_byok_secret():
declare v text;
begin
  v := nullif(btrim(coalesce(current_setting('app.settings.byok_secret', true), '')), '');
  if v is null then
    raise exception 'BYOK is not configured (app.settings.byok_secret unset)';
  end if;
  return v;
end;

surveyor_byok_set(p_provider text, p_key:
declare v_uid uuid; v_provider text;
begin
  v_uid := auth.uid();
  if v_uid is null then raise exception 'not authenticated'; end if;
  if p_key is null or btrim(p_key) = '' then raise exception 'key is required'; end if;
  -- RIDER (159, audit 1.3): BYOK is a Surveyor-tier capability. Refuse unless the
  -- caller holds an active entitlement or is a founder. Raises BEFORE any pgcrypto
  -- call, so an unentitled caller never reaches the vault.
  if not (public.has_surveyor_entitlement()
          or exists (select 1 from public.profiles where id = v_uid and is_founder)) then
    raise exception 'a Surveyor entitlement is required to set a provider key';
  end if;
  v_provider := coalesce(nullif(btrim(p_provider), ''), 'anthropic');
  insert into public.surveyor_byok_keys (
    user_id, provider, ciphertext, created_at, rotated_at,
    health, last_verified_at, last_checked_at, last_error_class,
    probe_tier, probe_checked_at, probe_model, probe_version, probe_profile
  )
  values (
    v_uid, v_provider, pgp_sym_encrypt(p_key, public._surveyor_byok_secret()), now(), now(),
    'unverified', null, null, null,
    null, null, null, null, null
  )
  on conflict (user_id, provider)
  do update set
    ciphertext       = excluded.ciphertext,
    rotated_at       = now(),
    health           = 'unverified',   -- 143: a rotated key must re-prove itself
    last_verified_at = null,
    last_checked_at  = null,
    last_error_class = null,
    probe_tier       = null,           -- 191: and must re-EARN its tier
    probe_checked_at = null,
    probe_model      = null,
    -- L-7a: the exam receipt clears WITH the tier. A profile outliving the tier that
    -- summarised it would coach the next key about a previous key's mistakes, which is
    -- the same class of lie 143's health reset exists to prevent.
    probe_version    = null,
    probe_profile    = null;
  return true;
end;

surveyor_byok_clear(p_provider text):
declare v_uid uuid;
begin
  v_uid := auth.uid();
  if v_uid is null then raise exception 'not authenticated'; end if;
  delete from public.surveyor_byok_keys
  where user_id = v_uid and provider = coalesce(nullif(btrim(p_provider), ''), 'anthropic');
  return true;
end;

surveyor_byok_set_health(p_user uuid, p_:
declare v_provider text; v_updated integer := 0;
begin
  if p_user is null then return false; end if;
  if p_health is null or p_health not in ('unverified','healthy','out_of_credit','invalid','rate_limited','down') then
    raise exception 'invalid byok health class: %', p_health;
  end if;
  v_provider := coalesce(nullif(btrim(p_provider), ''), 'anthropic');
  update public.surveyor_byok_keys
     set health           = p_health,
         last_checked_at  = now(),
         last_verified_at = case when p_health = 'healthy' or p_verified then now() else last_verified_at end,
         last_error_class = case when p_health = 'healthy' then null else coalesce(nullif(btrim(p_error_class), ''), p_health) end
   where user_id = p_user and provider = v_provider;
  get diagnostics v_updated = row_count;
  return v_updated > 0;
end;

write_ai_operation_log(p_user uuid, p_fe:
declare v_id uuid;
begin
  if p_feature is null or btrim(p_feature) = '' then
    raise exception 'ai operation feature is required';
  end if;
  if p_prompt_hash is null or btrim(p_prompt_hash) = '' then
    raise exception 'ai operation prompt_hash is required';
  end if;
  insert into public.ai_operation_log (
    user_id, feature, audience, prompt_hash, answer_hash,
    retrieval_slice_ids, retrieval_sources, model, model_version, provider,
    byok, citation_coverage, claim_count, refused, spend_id,
    meta_probe, canary, refusal_class
  ) values (
    p_user, p_feature, coalesce(nullif(btrim(p_audience), ''), 'player'), p_prompt_hash, p_answer_hash,
    coalesce(p_retrieval_slice_ids, '{}'), coalesce(p_retrieval_sources, '{}'),
    p_model, p_model_version, p_provider,
    coalesce(p_byok, false), p_citation_coverage, p_claim_count,
    coalesce(p_refused, false), p_spend_id,
    coalesce(p_meta_probe, false), p_canary, nullif(btrim(p_refusal_class), '')
  )
  returning id into v_id;
  return v_id;
end;

