surveyor_settings_set(p_patch jsonb):
declare
  v_uid uuid;
  v_row public.surveyor_user_settings;
  v_has boolean;
begin
  v_uid := auth.uid();
  if v_uid is null then raise exception 'not authenticated'; end if;
  if not public.account_is_active(v_uid) then raise exception 'account is not active'; end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then
    raise exception 'settings patch must be a json object';
  end if;

  -- Seed from the existing row (or defaults) then apply the patch key-by-key.
  select * into v_row from public.surveyor_user_settings where user_id = v_uid;
  v_has := found;
  if not v_has then
    v_row.user_id := v_uid; v_row.provider := 'anthropic';
    v_row.model_prefs := '{}'::jsonb; v_row.per_task_caps := '{}'::jsonb;
    v_row.warn_pct := 80; v_row.paused := false;
  end if;

  if p_patch ? 'provider' then
    v_row.provider := coalesce(nullif(btrim(p_patch ->> 'provider'), ''), 'anthropic');
  end if;
  if p_patch ? 'model_prefs' and jsonb_typeof(p_patch -> 'model_prefs') = 'object' then
    v_row.model_prefs := p_patch -> 'model_prefs';
  end if;
  if p_patch ? 'per_task_caps' and jsonb_typeof(p_patch -> 'per_task_caps') = 'object' then
    v_row.per_task_caps := p_patch -> 'per_task_caps';
  end if;
  if p_patch ? 'daily_token_cap' then
    v_row.daily_token_cap := nullif(greatest((p_patch ->> 'daily_token_cap')::bigint, 0), 0);
  end if;
  if p_patch ? 'weekly_token_cap' then
    v_row.weekly_token_cap := nullif(greatest((p_patch ->> 'weekly_token_cap')::bigint, 0), 0);
  end if;
  if p_patch ? 'daily_usd_cap' then
    v_row.daily_usd_cap := nullif(greatest((p_patch ->> 'daily_usd_cap')::numeric, 0), 0);
  end if;
  if p_patch ? 'weekly_usd_cap' then
    v_row.weekly_usd_cap := nullif(greatest((p_patch ->> 'weekly_usd_cap')::numeric, 0), 0);
  end if;
  if p_patch ? 'warn_pct' then
    v_row.warn_pct := least(greatest((p_patch ->> 'warn_pct')::integer, 1), 100);
  end if;
  if p_patch ? 'paused' then
    v_row.paused := (p_patch ->> 'paused')::boolean;
  end if;
  v_row.updated_at := now();

  insert into public.surveyor_user_settings as s
    (user_id, provider, model_prefs, daily_token_cap, weekly_token_cap, daily_usd_cap, weekly_usd_cap, per_task_caps, warn_pct, paused, updated_at)
  values
    (v_uid, v_row.provider, v_row.model_prefs, v_row.daily_token_cap, v_row.weekly_token_cap, v_row.daily_usd_cap, v_row.weekly_usd_cap, v_row.per_task_caps, v_row.warn_pct, v_row.paused, v_row.updated_at)
  on conflict (user_id) do update set
    provider = excluded.provider, model_prefs = excluded.model_prefs,
    daily_token_cap = excluded.daily_token_cap, weekly_token_cap = excluded.weekly_token_cap,
    daily_usd_cap = excluded.daily_usd_cap, weekly_usd_cap = excluded.weekly_usd_cap,
    per_task_caps = excluded.per_task_caps, warn_pct = excluded.warn_pct,
    paused = excluded.paused, updated_at = excluded.updated_at
  returning * into v_row;
  return v_row;
end;

surveyor_usage_precheck(p_user uuid, p_p:
declare
  v_s            public.surveyor_user_settings;
  v_prices       jsonb;
  v_pp           jsonb;   -- provider price map
  v_day_start    timestamptz;
  v_week_start   timestamptz;
  v_dtok bigint; v_wtok bigint; v_dusd numeric; v_wusd numeric;
  v_task_dtok bigint; v_task_wtok bigint;
  v_task_caps    jsonb;
  v_allowed boolean := true;
  v_reason text := 'none';
  v_breached text := null;
  v_warn boolean := false;
  v_paused boolean := false;
begin
  if p_user is null then
    return jsonb_build_object('allowed', true, 'paused', false, 'warn', false, 'reason_class', 'none');
  end if;
  set local time zone 'UTC';
  v_day_start  := date_trunc('day', now());
  v_week_start := now() - interval '7 days';

  select * into v_s from public.surveyor_user_settings where user_id = p_user;
  if not found then
    -- No governors configured ⇒ allow (the global operator cap still applies).
    return jsonb_build_object('allowed', true, 'paused', false, 'warn', false, 'reason_class', 'none',
      'daily_tokens', 0, 'weekly_tokens', 0, 'daily_usd', 0, 'weekly_usd', 0);
  end if;
  v_paused := v_s.paused;

  -- Price map for the provider ($/Mtok), with a 'default' fallback bucket.
  select value into v_prices from public.system_config where key = 'surveyor_price_estimates';
  v_pp := coalesce(v_prices -> coalesce(nullif(btrim(p_provider), ''), 'anthropic'), '{}'::jsonb);

  -- Windowed token sums (global).
  select coalesce(sum(input_tokens + output_tokens), 0) into v_dtok
    from public.ai_usage_events where user_id = p_user and created_at >= v_day_start;
  select coalesce(sum(input_tokens + output_tokens), 0) into v_wtok
    from public.ai_usage_events where user_id = p_user and created_at >= v_week_start;

  -- Windowed estimated-$ sums (tokens × the maintained price table).
  select coalesce(sum(
      (input_tokens::numeric  / 1000000) * coalesce((v_pp -> model ->> 'in')::numeric,  (v_pp -> 'default' ->> 'in')::numeric,  0)
    + (output_tokens::numeric / 1000000) * coalesce((v_pp -> model ->> 'out')::numeric, (v_pp -> 'default' ->> 'out')::numeric, 0)
    ), 0) into v_dusd
    from public.ai_usage_events where user_id = p_user and created_at >= v_day_start;
  select coalesce(sum(
      (input_tokens::numeric  / 1000000) * coalesce((v_pp -> model ->> 'in')::numeric,  (v_pp -> 'default' ->> 'in')::numeric,  0)
    + (output_tokens::numeric / 1000000) * coalesce((v_pp -> model ->> 'out')::numeric, (v_pp -> 'default' ->> 'out')::numeric, 0)
    ), 0) into v_wusd
    from public.ai_usage_events where user_id = p_user and created_at >= v_week_start;

  -- Per-task token sums (only needed when a per-task cap exists for this feature).
  v_task_caps := v_s.per_task_caps -> coalesce(p_feature, '');
  if v_task_caps is not null and jsonb_typeof(v_task_caps) = 'object' then
    select coalesce(sum(input_tokens + output_tokens), 0) into v_task_dtok
      from public.ai_usage_events where user_id = p_user and feature = p_feature and created_at >= v_day_start;
    select coalesce(sum(input_tokens + output_tokens), 0) into v_task_wtok
      from public.ai_usage_events where user_id = p_user and feature = p_feature and created_at >= v_week_start;
  end if;

  -- Evaluate breaches (paused wins; else the first breached window sets reason).
  if v_paused then
    v_allowed := false; v_reason := 'paused'; v_breached := 'paused';
  else
    if v_s.daily_token_cap is not null and v_dtok >= v_s.daily_token_cap then
      v_allowed := false; v_breached := 'daily_tokens';
    elsif v_s.weekly_token_cap is not null and v_wtok >= v_s.weekly_token_cap then
      v_allowed := false; v_breached := 'weekly_tokens';
    elsif v_s.daily_usd_cap is not null and v_dusd >= v_s.daily_usd_cap then
      v_allowed := false; v_breached := 'daily_usd';
    elsif v_s.weekly_usd_cap is not null and v_wusd >= v_s.weekly_usd_cap then
      v_allowed := false; v_breached := 'weekly_usd';
    elsif v_task_caps is not null and (v_task_caps ->> 'daily_tokens') is not null
          and v_task_dtok >= (v_task_caps ->> 'daily_tokens')::bigint then
      v_allowed := false; v_breached := 'task_daily_tokens';
    elsif v_task_caps is not null and (v_task_caps ->> 'weekly_tokens') is not null
          and v_task_wtok >= (v_task_caps ->> 'weekly_tokens')::bigint then
      v_allowed := false; v_breached := 'task_weekly_tokens';
    end if;
    if not v_allowed then v_reason := 'cap'; end if;
  end if;

  -- Warn: any capped window at/above warn_pct% of its cap (only meaningful when allowed).
  if v_allowed then
    v_warn :=
      (v_s.daily_token_cap  is not null and v_dtok * 100 >= v_s.daily_token_cap  * v_s.warn_pct) or
      (v_s.weekly_token_cap is not null and v_wtok * 100 >= v_s.weekly_token_cap * v_s.warn_pct) or
      (v_s.daily_usd_cap    is not null and v_dusd * 100 >= v_s.daily_usd_cap    * v_s.warn_pct) or
      (v_s.weekly_usd_cap   is not null and v_wusd * 100 >= v_s.weekly_usd_cap   * v_s.warn_pct);
  end if;

  return jsonb_build_object(
    'allowed', v_allowed, 'paused', v_paused, 'warn', v_warn,
    'reason_class', v_reason, 'breached', v_breached,
    'daily_tokens', v_dtok, 'weekly_tokens', v_wtok,
    'daily_usd', round(v_dusd, 4), 'weekly_usd', round(v_wusd, 4),
    -- the user's per-task model preference (the edge honours it for a BYOK call,
    -- validated against the adapter-supported set; falls back to the server default).
    'model_prefs', v_s.model_prefs,
    'caps', jsonb_build_object(
      'daily_token_cap', v_s.daily_token_cap, 'weekly_token_cap', v_s.weekly_token_cap,
      'daily_usd_cap', v_s.daily_usd_cap, 'weekly_usd_cap', v_s.weekly_usd_cap,
      'warn_pct', v_s.warn_pct)
  );
end;

toggle_gallery_reaction(target_settlemen:
begin
  if auth.uid() is null then
    raise exception 'Sign in to react';
  end if;
  if not public.account_is_active(auth.uid()) then
    raise exception 'account is not active';
  end if;
  -- The bounded vocabulary — MUST stay identical to the table CHECK above and
  -- to src/data/galleryReactionVocab.js (pinned by the vocab parity test).
  if reaction not in (
    'worth_walking', 'finely_wrought', 'steeped_history',
    'run_campaign', 'map_speaks', 'true_to_life'
  ) then
    raise exception 'Unknown reaction';
  end if;

  -- Velocity guard (125 infra): at most 120 accepted toggles/hour/user. Six
  -- distinct chips make a higher legitimate rate than the single vote button
  -- (60/h); wire-speed toggling is still bot behaviour.
  if public._consume_action_rate_limit(auth.uid(), 'gallery_reaction', 3600) > 120 then
    raise exception 'You are reacting too quickly — please slow down and try again shortly.';
  end if;

  perform 1 from public.settlements
    where id = target_settlement_id and is_public = true;
  if not found then
    raise exception 'Settlement is not public';
  end if;

  if exists (
    select 1 from public.gallery_reactions gr
    where gr.settlement_id = target_settlement_id
      and gr.user_id = auth.uid()
      and gr.reaction_key = reaction
  ) then
    delete from public.gallery_reactions gr
      where gr.settlement_id = target_settlement_id
        and gr.user_id = auth.uid()
        and gr.reaction_key = reaction;
  else
    insert into public.gallery_reactions(settlement_id, user_id, reaction_key)
      values (target_settlement_id, auth.uid(), reaction)
      on conflict do nothing;
  end if;

  -- Return the settlement's FULL post-toggle reaction state (nonzero keys only;
  -- the client fills zeros from its frozen vocabulary) so one round-trip
  -- refreshes every chip.
  return query
    select gr.reaction_key,
           count(*)::integer as reaction_count,
           bool_or(gr.user_id = auth.uid()) as mine
    from public.gallery_reactions gr
    where gr.settlement_id = target_settlement_id
    group by gr.reaction_key;
end;

surveyor_stage_enabled(p_stage text):
declare
  v_map  jsonb;
  v_flag jsonb;
  v_key  text;
begin
  v_key := nullif(btrim(coalesce(p_stage, '')), '');
  if v_key is null then return false; end if;   -- no stage named ⇒ nothing to enable
  select value into v_map from public.system_config where key = 'surveyor_stage_switches';
  if v_map is null then
    -- The config row is missing entirely (pre-seed / wiped). Launch-whole default-on:
    -- an unconfigured switch does not itself pause a stage (the edge's own
    -- entitlement + kill-switch-error handling still bound access).
    return true;
  end if;
  v_flag := v_map -> v_key;
  if v_flag is null then
    return true;   -- ABSENT stage key ⇒ a newly added stage ships enabled
  end if;
  -- Present: honour the stored boolean (anything non-boolean reads as NOT enabled).
  return jsonb_typeof(v_flag) = 'boolean' and (v_flag)::boolean;
end;

consume_token_bucket(p_key text, p_capac:
declare
  v_now       timestamptz := now();
  v_key       text;
  v_capacity  double precision;
  v_refill    double precision;
  v_cost      double precision;
  v_tokens    double precision;
  v_updated   timestamptz;
  v_allowed   boolean;
begin
  -- Clamp params to safe defaults (fail toward protection, never toward "no cap").
  v_capacity := greatest(coalesce(p_capacity, 60), 1);
  v_refill   := greatest(coalesce(p_refill_per_sec, v_capacity / 3600.0), 0);
  v_cost     := least(greatest(coalesce(p_cost, 1), 0), v_capacity);
  v_key      := coalesce(nullif(btrim(p_key), ''), 'anon');

  -- Ensure the bucket exists as a FULL bucket, idempotently. A concurrent first
  -- hit either inserts or no-ops — either way the row exists afterward, and the
  -- FOR UPDATE below serializes the actual refill+consume so neither races past
  -- the cap. Seeding a full bucket means the very first request refills by ~0s
  -- and simply consumes its cost (a fresh caller starts with a full allowance).
  insert into public.token_buckets (bucket_key, tokens, updated_at)
    values (v_key, v_capacity, v_now)
  on conflict (bucket_key) do nothing;

  -- Lock the (now-guaranteed) row so concurrent callers on the same key serialize.
  select tokens, updated_at into v_tokens, v_updated
    from public.token_buckets
   where bucket_key = v_key
   for update;

  -- Refill by elapsed time (capped at capacity), then consume if affordable.
  v_tokens := least(v_capacity, v_tokens + extract(epoch from (v_now - v_updated)) * v_refill);
  if v_tokens >= v_cost then
    v_allowed := true;
    v_tokens  := v_tokens - v_cost;
  else
    v_allowed := false;
  end if;

  update public.token_buckets
     set tokens = v_tokens, updated_at = v_now
   where bucket_key = v_key;

  return jsonb_build_object('allowed', v_allowed, 'tokens', round(v_tokens::numeric, 4), 'capacity', v_capacity);
end;

cleanup_token_buckets(p_retention_second:
declare
  v_deleted integer := 0;
begin
  if p_retention_seconds is null or p_retention_seconds < 1 then
    p_retention_seconds := 172800;
  end if;
  delete from public.token_buckets
    where updated_at < now() - make_interval(secs => p_retention_seconds);
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;

set_auto_reload_settings(p_enabled boole:
declare v_uid uuid;
begin
  v_uid := auth.uid();
  if v_uid is null then raise exception 'not authenticated'; end if;
  -- Validate the ranges here too (the table CHECKs are the backstop) so a bad
  -- input raises a clear error rather than a constraint-name leak.
  if p_threshold is null or p_threshold < 1 or p_threshold > 500 then
    raise exception 'threshold_credits must be between 1 and 500';
  end if;
  if p_target is null or p_target < 2 or p_target > 1000 then
    raise exception 'target_credits must be between 2 and 1000';
  end if;
  if p_target <= p_threshold then
    raise exception 'target_credits must exceed threshold_credits';
  end if;
  if p_cap is null or p_cap < 500 or p_cap > 20000 then
    raise exception 'monthly_cap_cents must be between 500 and 20000';
  end if;
  insert into public.credit_auto_reload_settings
    (user_id, enabled, threshold_credits, target_credits, monthly_cap_cents, updated_at)
    values (v_uid, coalesce(p_enabled, false), p_threshold, p_target, p_cap, now())
  on conflict (user_id) do update set
    enabled = excluded.enabled,
    threshold_credits = excluded.threshold_credits,
    target_credits = excluded.target_credits,
    monthly_cap_cents = excluded.monthly_cap_cents,
    updated_at = now();
  return true;
end;

claim_auto_reload_attempt(p_user uuid, p:
declare
  caller_role text;
  v_settings public.credit_auto_reload_settings%rowtype;
  v_balance int;
  v_delta int;
  v_rate numeric;
  v_amount int;
  v_bucket text;
  v_spent int;
  v_id uuid;
begin
  caller_role := coalesce(current_setting('request.jwt.claim.role', true), auth.role());
  if caller_role <> 'service_role' then
    raise exception 'claim_auto_reload_attempt is service-role only (got: %)', caller_role;
  end if;

  -- Serialize against the deletion processor's profile-flag UPDATE. If deletion
  -- commits first the predicate below fails; if this lock wins, the claim
  -- legitimately commits before deletion and the processor waits.
  perform 1
    from public.profiles
   where id = p_user
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'account_inactive');
  end if;

  -- Missing profile is inactive by definition (057). This check precedes settings,
  -- balance, cap, and INSERT work, so no auto-reload attempt can be claimed after
  -- deletion/disable even if application state was checked just before the race.
  if not public.account_is_active(p_user) then
    return jsonb_build_object('ok', false, 'reason', 'account_inactive');
  end if;

  select * into v_settings
    from public.credit_auto_reload_settings
   where user_id = p_user
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no_settings');
  end if;

  v_balance := public.get_credit_balance(p_user);

  if not v_settings.enabled then
    return jsonb_build_object(
      'ok', false,
      'reason', 'disabled',
      'below_threshold', (v_balance < v_settings.threshold_credits)
    );
  end if;

  if v_balance >= v_settings.threshold_credits then
    return jsonb_build_object('ok', false, 'reason', 'above_threshold');
  end if;

  v_delta := v_settings.target_credits - v_balance;
  if v_delta <= 0 then
    return jsonb_build_object('ok', false, 'reason', 'no_delta');
  end if;

  if p_credits_per_unit is null or p_credits_per_unit <= 0
     or p_unit_amount_cents is null or p_unit_amount_cents <= 0 then
    return jsonb_build_object('ok', false, 'reason', 'bad_rate');
  end if;
  v_rate := p_unit_amount_cents::numeric / p_credits_per_unit::numeric;
  v_amount := round(v_delta * v_rate)::int;
  if v_amount <= 0 then
    return jsonb_build_object('ok', false, 'reason', 'no_amount');
  end if;

  v_bucket := to_char((now() at time zone 'utc'), 'YYYY-MM');

  if exists (
    select 1
      from public.credit_auto_reload_attempts
     where user_id = p_user
       and resolved_at is not null
       and resolved_at > now() - interval '10 minutes'
  ) then
    return jsonb_build_object('ok', false, 'reason', 'cooldown');
  end if;

  select coalesce(sum(amount_cents), 0)
    into v_spent
    from public.credit_auto_reload_attempts
   where user_id = p_user
     and month_bucket = v_bucket
     and state in ('succeeded', 'pending', 'requires_action');
  if v_spent + v_amount > v_settings.monthly_cap_cents then
    return jsonb_build_object(
      'ok', false,
      'reason', 'cap',
      'below_threshold', true
    );
  end if;

  begin
    insert into public.credit_auto_reload_attempts (
      user_id, state, credits_delta, amount_cents, month_bucket
    ) values (
      p_user, 'pending', v_delta, v_amount, v_bucket
    )
    returning id into v_id;
  exception when unique_violation then
    return jsonb_build_object('ok', false, 'reason', 'open_attempt');
  end;

  return jsonb_build_object(
    'ok', true,
    'attempt_id', v_id,
    'credits_delta', v_delta,
    'amount_cents', v_amount
  );
end;

cancel_stale_auto_reload_attempts():
declare
  caller_role text;
  v_count int;
begin
  caller_role := coalesce(current_setting('request.jwt.claim.role', true), auth.role());
  if caller_role <> 'service_role' then
    raise exception 'cancel_stale_auto_reload_attempts is service-role only (got: %)', caller_role;
  end if;
  update public.credit_auto_reload_attempts
    set state = 'canceled', failure_reason = 'expired', resolved_at = now()
    where state in ('pending', 'requires_action')
      and created_at < now() - interval '72 hours';
  get diagnostics v_count = row_count;
  return v_count;
end;

mark_low_balance_notified(p_user uuid, p:
declare
  caller_role text;
  v_updated int;
begin
  caller_role := coalesce(current_setting('request.jwt.claim.role', true), auth.role());
  if caller_role <> 'service_role' then
    raise exception 'mark_low_balance_notified is service-role only (got: %)', caller_role;
  end if;
  update public.credit_auto_reload_settings
    set notified_at = now(), notified_bucket = p_bucket
    where user_id = p_user
      and (notified_bucket is distinct from p_bucket);
