  insert into public.surveyor_entitlements (
    user_id,
    status,
    source,
    granted_at,
    revoked_at,
    stripe_subscription_id,
    stripe_customer_id
  ) values (
    p_user,
    'active',
    coalesce(nullif(btrim(p_source), ''), 'subscription'),
    now(),
    null,
    p_subscription_id,
    p_customer_id
  )
  on conflict (user_id) do update set
    status = 'active',
    source = coalesce(
      nullif(btrim(p_source), ''),
      public.surveyor_entitlements.source
    ),
    granted_at = now(),
    revoked_at = null,
    stripe_subscription_id = coalesce(
      p_subscription_id,
      public.surveyor_entitlements.stripe_subscription_id
    ),
    stripe_customer_id = coalesce(
      p_customer_id,
      public.surveyor_entitlements.stripe_customer_id
    );

  return true;
end;

revoke_surveyor_entitlement(p_user uuid,:
