        -- FP-3: hold the payout until the original $99 dispute window has closed.
        and (original_purchase_at is null
             or original_purchase_at + make_interval(days => v_hold_days) <= now())
      order by created_at
      limit 1
      for update skip locked
    )
    returning * into v_bb;
  if not found then return jsonb_build_object('ok', false, 'reason', 'none_due'); end if;
  return jsonb_build_object('ok', true, 'buyback_id', v_bb.id, 'from_user', v_bb.user_id,
