sweep_seat_dormancy_nudges():
declare caller_role text; v_nudge int; v_renudge int; r record;
begin
  caller_role := coalesce(current_setting('request.jwt.claim.role', true), auth.role());
  if caller_role <> 'service_role' then
    raise exception 'sweep_seat_dormancy_nudges is service-role only (got: %)', caller_role;
  end if;
  v_nudge := public._seat_stewardship_dial('dormancy_nudge_months', 18);
  v_renudge := public._seat_stewardship_dial('dormancy_renudge_months', 12);
  for r in
    update public.founder_seats fs
      set last_dormancy_nudge_at = now(), updated_at = now()
      where fs.holder_user_id is not null
        and fs.security_status = 'normal'
        and public._seat_holder_last_active(fs.holder_user_id) is not null
        and public._seat_holder_last_active(fs.holder_user_id) < now() - make_interval(months => v_nudge)
        and (fs.last_dormancy_nudge_at is null
             or fs.last_dormancy_nudge_at < now() - make_interval(months => v_renudge))
      returning fs.seat_id, fs.holder_user_id
  loop
    seat_id := r.seat_id; user_id := r.holder_user_id; return next;
  end loop;
  return;
end;

_retention_warning_cron_should_dispatch(:
declare
  tz         text;
  local_now  timestamp;
  local_today text;
  cfg_url    text;
  cfg_secret text;
begin
  -- 1. missing / malformed config → not_configured
  if cfg is null or jsonb_typeof(cfg) <> 'object' then
    return 'not_configured';
  end if;
  -- 2. enabled must be exactly true (the kill switch)
  if coalesce((cfg ->> 'enabled')::boolean, false) is not true then
    return 'disabled';
  end if;
  -- 3. url + secret must both be present + non-empty
  cfg_url    := nullif(cfg ->> 'url', '');
  cfg_secret := nullif(cfg ->> 'secret', '');
  if cfg_url is null or cfg_secret is null then
    return 'not_configured';
  end if;
  -- 4. THE DST-PROOF GUARD: only the local-midnight firing proceeds. The job fires
  --    hourly UTC; convert to the configured zone and require wall-clock hour = 0.
  tz := coalesce(nullif(cfg ->> 'timezone', ''), 'America/New_York');
  local_now := at_ts at time zone tz;
  if extract(hour from local_now) <> 0 then
    return 'skipped_hour';
  end if;
  -- 5. at-most-once-per-local-day dedupe
  local_today := to_char(local_now, 'YYYY-MM-DD');
  if (cfg ->> 'lastDispatchedOn') = local_today then
    return 'skipped_already';
  end if;
  return 'ok';
exception
  -- A bad IANA zone string (or any coercion failure) must never throw out of the
  -- cron job — treat it as not_configured so the operator fixes the config, no dispatch.
  when others then
    return 'not_configured';
end;

run_retention_warning_nightly():
declare
  cfg        jsonb;
  verdict    text;
  cfg_url    text;
  cfg_secret text;
  tz         text;
  local_today text;
  req_id     bigint;
begin
  select value into cfg from public.system_config where key = 'retention_warning_cron';

  -- The guard owns the config/enabled/hour/dedupe decision (shared with the tests).
  verdict := public._retention_warning_cron_should_dispatch(cfg, now());
  if verdict <> 'ok' then
    return verdict;
  end if;

  cfg_url    := cfg ->> 'url';
  cfg_secret := cfg ->> 'secret';
  tz         := coalesce(nullif(cfg ->> 'timezone', ''), 'America/New_York');
  local_today := to_char(now() at time zone tz, 'YYYY-MM-DD');

  -- Mark dispatched FIRST: if pg_net then errors we still won't re-dispatch this
  -- local day (the edge function is the source of truth for which accounts were
  -- warned, via its own dedup ledger; a failed POST is recoverable tomorrow).
  update public.system_config
     set value = jsonb_set(value, '{lastDispatchedOn}', to_jsonb(local_today))
   where key = 'retention_warning_cron';

  -- Fire the POST. net.http_post is only present when pg_net is installed; wrap the
  -- call so a missing extension is a soft 'pg_net_unavailable', never a throw.
  begin
    select net.http_post(
      url     := cfg_url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'x-cron-secret', cfg_secret
      ),
      body    := '{}'::jsonb
    ) into req_id;
  exception
    when undefined_function or undefined_table or invalid_schema_name then
      raise notice 'pg_net unavailable; retention-warning-cron not dispatched (install pg_net or schedule the POST manually)';
      return 'pg_net_unavailable';
  end;

  return 'dispatched:' || coalesce(req_id::text, 'unknown');
end;

set_featured(target_id uuid, featured bo:
declare
  caller_role text;
  before_state jsonb;
begin
  select role into caller_role from public.profiles where id = auth.uid();
  if caller_role not in ('developer', 'admin') then
    raise exception 'Only admins can change featured status';
  end if;

  select jsonb_build_object('is_featured', is_featured, 'featured_order', featured_order, 'name', name)
    into before_state from public.settlements where id = target_id;
  if before_state is null then raise exception 'Settlement not found'; end if;

  if featured then
    update public.settlements set is_featured = true, featured_order = sort_order
      where id = target_id and is_public = true;
    if not found then raise exception 'Cannot feature a non-public settlement. Publish it first.'; end if;
  else
    update public.settlements set is_featured = false, featured_order = null where id = target_id;
  end if;

  perform public._audit_action(
    auth.uid(), null,
    case when featured then 'gallery_feature' else 'gallery_unfeature' end,
    before_state || jsonb_build_object('settlement_id', target_id),
    jsonb_build_object('settlement_id', target_id, 'is_featured', featured, 'featured_order', sort_order),
    null
  );
end;

