_account_deletion_cron_should_dispatch(c:
begin
  if cfg is null or jsonb_typeof(cfg) <> 'object' then
    return 'not_configured';
  end if;
  if coalesce((cfg ->> 'enabled')::boolean, false) is not true then
    return 'disabled';
  end if;
  if nullif(btrim(cfg ->> 'url'), '') is null
     or nullif(btrim(cfg ->> 'secret'), '') is null then
    return 'not_configured';
  end if;
  return 'ok';
exception when others then
  return 'not_configured';
end;

run_account_deletion_cleanup():
declare
  cfg jsonb;
  verdict text;
  req_id bigint;
begin
  select value into cfg
    from public.system_config
   where key = 'account_deletion_cron';
  verdict := public._account_deletion_cron_should_dispatch(cfg);
  if verdict <> 'ok' then
    return verdict;
  end if;

  begin
    select net.http_post(
      url := cfg ->> 'url',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'x-cron-secret', cfg ->> 'secret'
      ),
      body := '{}'::jsonb
    ) into req_id;
  exception
    when undefined_function or undefined_table or invalid_schema_name then
      raise notice 'pg_net unavailable; account-deletion-worker not dispatched';
      return 'pg_net_unavailable';
  end;
  return 'dispatched:' || coalesce(req_id::text, 'unknown');
end;

claim_auto_reload_payment_intent(p_attem:
declare
  caller_role text;
  v_state text;
begin
  caller_role := coalesce(current_setting('request.jwt.claim.role', true), auth.role());
  if caller_role <> 'service_role' then
    raise exception 'claim_auto_reload_payment_intent is service-role only (got: %)', caller_role;
  end if;

  if p_attempt is null or p_user is null
     or p_payment_intent is null or btrim(p_payment_intent) = ''
     or p_amount_cents is null or p_amount_cents <= 0
     or p_credits_delta is null or p_credits_delta <= 0 then
    return jsonb_build_object('ok', false, 'reason', 'invalid_input');
  end if;

  update public.credit_auto_reload_attempts
    set stripe_payment_intent_id = p_payment_intent
    where id = p_attempt
      and user_id = p_user
      and amount_cents = p_amount_cents
      and credits_delta = p_credits_delta
      and (
        (
          state in ('pending', 'requires_action', 'failed', 'canceled')
          and (
            stripe_payment_intent_id is null
            or stripe_payment_intent_id = p_payment_intent
          )
        )
        or (
          -- The trigger resumes after confirm=true; the webhook can finish first.
          -- Let that continuation recognize the SAME completed PI idempotently,
          -- but never bind a null/different PI on an already-succeeded attempt.
          state = 'succeeded'
          and stripe_payment_intent_id = p_payment_intent
        )
      )
    returning state into v_state;

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_claimed');
  end if;

  return jsonb_build_object('ok', true, 'state', v_state);
end;

guard_inactive_profile_billing():
declare
  v_inactive boolean;
begin
  v_inactive := new.deleted_at is not null
    or new.disabled_at is not null
    or new.banned_at is not null;

  if not v_inactive then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.stripe_subscription_id is not null
       or new.stripe_customer_id is not null
       or new.tier = 'premium'
       or new.is_founder is true then
      raise exception 'inactive_profile_billing_upgrade_forbidden';
    end if;
    return new;
  end if;

  -- Existing linkage/entitlement may remain long enough for the cleanup worker
  -- to inspect it. Clearing/downgrading is allowed; acquisition or replacement is
  -- not. This also permits the deletion processor to set lock flags atomically
  -- while preserving the IDs that the worker must cancel.
  if (
    new.stripe_subscription_id is not null
    and new.stripe_subscription_id is distinct from old.stripe_subscription_id
  ) or (
    new.stripe_customer_id is not null
    and new.stripe_customer_id is distinct from old.stripe_customer_id
  ) or (
    new.tier = 'premium'
    and old.tier is distinct from 'premium'
  ) or (
    new.is_founder is true
    and old.is_founder is distinct from true
  ) then
    raise exception 'inactive_profile_billing_upgrade_forbidden';
  end if;

  return new;
end;

guard_inactive_surveyor_entitlement():
begin
  -- Serialize every Surveyor write against deletion's profile-flag update. A
  -- plain predicate check would race because the two transactions otherwise
  -- mutate different tables.
  perform 1
    from public.profiles
   where id = new.user_id
   for update;
  if found and public.account_is_active(new.user_id) then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.status = 'active'
       or new.stripe_subscription_id is not null
       or new.stripe_customer_id is not null then
      raise exception 'inactive_surveyor_entitlement_forbidden';
    end if;
    return new;
  end if;

  -- Revocation and nulling IDs are cleanup. Reactivation or assigning a fresh
  -- non-null billing identity to an inactive owner is forbidden.
  if new.status = 'active' or (
    new.stripe_subscription_id is not null
    and new.stripe_subscription_id is distinct from old.stripe_subscription_id
  ) or (
    new.stripe_customer_id is not null
    and new.stripe_customer_id is distinct from old.stripe_customer_id
  ) then
    raise exception 'inactive_surveyor_entitlement_forbidden';
  end if;

  return new;
end;

requeue_account_deletion_cleanup_for_lat:
declare
  v_caller_role text;
  v_subscription_id text;
  v_customer_id text;
  v_job public.account_deletion_cleanup_jobs%rowtype;
begin
  v_caller_role := coalesce(
    nullif(current_setting('request.jwt.claim.role', true), ''),
    auth.role()
  );
  if v_caller_role <> 'service_role' then
    raise exception
      'requeue_account_deletion_cleanup_for_late_billing is service-role only (got: %)',
      coalesce(v_caller_role, 'none');
  end if;

  if p_user is null then
    raise exception 'p_user is required';
  end if;
  v_subscription_id := nullif(btrim(p_subscription_id), '');
  v_customer_id := nullif(btrim(p_customer_id), '');
  if p_subscription_id is not null and v_subscription_id is null then
    raise exception 'p_subscription_id cannot be blank';
  end if;
  if p_customer_id is not null and v_customer_id is null then
    raise exception 'p_customer_id cannot be blank';
  end if;
  if v_subscription_id is null and v_customer_id is null then
    raise exception 'subscription_id or customer_id is required';
  end if;

  -- A still-active account belongs to normal billing flow, not deletion cleanup.
  if public.account_is_active(p_user) then
    return jsonb_build_object('ok', false, 'reason', 'account_active');
  end if;

  select j.*
    into v_job
    from public.account_deletion_cleanup_jobs j
    join public.deletion_requests dr on dr.id = j.deletion_request_id
   where j.user_id = p_user
     and dr.status <> 'cancelled'
   order by j.created_at desc, j.id desc
   limit 1
   for update of j;

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'cleanup_job_not_found');
  end if;

  update public.account_deletion_cleanup_jobs
     set late_stripe_subscription_ids = case
           when v_subscription_id is null
             or v_subscription_id = any(late_stripe_subscription_ids)
             then late_stripe_subscription_ids
           else array_append(late_stripe_subscription_ids, v_subscription_id)
         end,
         late_stripe_customer_ids = case
           when v_customer_id is null
             or v_customer_id = any(late_stripe_customer_ids)
             then late_stripe_customer_ids
           else array_append(late_stripe_customer_ids, v_customer_id)
         end,
         known_stripe_subscription_ids = case
           when v_subscription_id is null
             or v_subscription_id = any(known_stripe_subscription_ids)
             then known_stripe_subscription_ids
           else array_append(known_stripe_subscription_ids, v_subscription_id)
         end,
         known_stripe_customer_ids = case
           when v_customer_id is null
             or v_customer_id = any(known_stripe_customer_ids)
             then known_stripe_customer_ids
           else array_append(known_stripe_customer_ids, v_customer_id)
         end,
         late_billing_revision = late_billing_revision + 1,
         late_billing_recorded_at = now(),
         status = 'retry',
         next_attempt_at = now(),
         locked_at = null,
         lease_token = null,
         stripe_cleaned_at = null,
         completed_at = null,
         last_error = left(
           coalesce(
             nullif(btrim(p_reason), ''),
             'late Stripe billing observed after account deletion'
           ),
           1000
         ),
         updated_at = now()
   where id = v_job.id
   returning * into v_job;

  -- A previously completed request is no longer externally clean. Reopen the
  -- durable parent without rewriting its final audit history.
  update public.deletion_requests
     set status = 'processing',
         email = null
   where id = v_job.deletion_request_id
     and status <> 'cancelled';

  return jsonb_build_object(
    'ok', true,
    'job_id', v_job.id,
    'status', v_job.status,
    'late_billing_revision', v_job.late_billing_revision,
    'late_stripe_subscription_ids', v_job.late_stripe_subscription_ids,
    'late_stripe_customer_ids', v_job.late_stripe_customer_ids,
    'known_stripe_subscription_ids', v_job.known_stripe_subscription_ids,
    'known_stripe_customer_ids', v_job.known_stripe_customer_ids
  );
end;

checkpoint_account_deletion_billing_iden:
declare
  v_caller_role text;
  v_subscription_id text;
  v_customer_id text;
  v_job public.account_deletion_cleanup_jobs%rowtype;
  v_late_set_grows boolean;
begin
  v_caller_role := coalesce(
    nullif(current_setting('request.jwt.claim.role', true), ''),
    auth.role()
  );
  if v_caller_role <> 'service_role' then
    raise exception
      'checkpoint_account_deletion_billing_identity is service-role only (got: %)',
      coalesce(v_caller_role, 'none');
  end if;

  v_subscription_id := nullif(btrim(p_subscription_id), '');
  v_customer_id := nullif(btrim(p_customer_id), '');
  if p_subscription_id is not null and v_subscription_id is null then
    raise exception 'p_subscription_id cannot be blank';
  end if;
  if p_customer_id is not null and v_customer_id is null then
    raise exception 'p_customer_id cannot be blank';
  end if;
  if v_subscription_id is null and v_customer_id is null then
    raise exception 'subscription_id or customer_id is required';
  end if;

  select *
    into v_job
    from public.account_deletion_cleanup_jobs
   where id = p_job_id
     and status = 'processing'
     and lease_token = p_lease_token
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'lease_lost');
  end if;

  v_late_set_grows := (
    v_subscription_id is not null
    and not (v_subscription_id = any(v_job.late_stripe_subscription_ids))
  ) or (
    v_customer_id is not null
    and not (v_customer_id = any(v_job.late_stripe_customer_ids))
  );

  update public.account_deletion_cleanup_jobs
     set late_stripe_subscription_ids = case
           when v_subscription_id is null
             or v_subscription_id = any(late_stripe_subscription_ids)
             then late_stripe_subscription_ids
           else array_append(late_stripe_subscription_ids, v_subscription_id)
         end,
         late_stripe_customer_ids = case
           when v_customer_id is null
             or v_customer_id = any(late_stripe_customer_ids)
             then late_stripe_customer_ids
           else array_append(late_stripe_customer_ids, v_customer_id)
         end,
         known_stripe_subscription_ids = case
           when v_subscription_id is null
             or v_subscription_id = any(known_stripe_subscription_ids)
             then known_stripe_subscription_ids
           else array_append(known_stripe_subscription_ids, v_subscription_id)
         end,
         known_stripe_customer_ids = case
           when v_customer_id is null
             or v_customer_id = any(known_stripe_customer_ids)
             then known_stripe_customer_ids
           else array_append(known_stripe_customer_ids, v_customer_id)
         end,
         late_billing_revision = late_billing_revision
           + case when v_late_set_grows then 1 else 0 end,
         late_billing_recorded_at = case
           when v_late_set_grows then now()
           else late_billing_recorded_at
         end,
         updated_at = now()
   where id = v_job.id
   returning * into v_job;

  return jsonb_build_object(
    'ok', true,
    'job_id', v_job.id,
    'lease_token', v_job.lease_token,
    'late_billing_revision', v_job.late_billing_revision,
    'late_stripe_subscription_ids', v_job.late_stripe_subscription_ids,
    'late_stripe_customer_ids', v_job.late_stripe_customer_ids
  );
end;

resolve_account_deletion_user_by_stripe_:
declare
  v_caller_role text;
  v_subscription_id text;
  v_customer_id text;
  v_user_count int;
  v_user_id uuid;
  v_job_id uuid;
begin
  v_caller_role := coalesce(
    nullif(current_setting('request.jwt.claim.role', true), ''),
    auth.role()
  );
  if v_caller_role <> 'service_role' then
    raise exception
      'resolve_account_deletion_user_by_stripe_billing is service-role only (got: %)',
      coalesce(v_caller_role, 'none');
  end if;

  v_subscription_id := nullif(btrim(p_subscription_id), '');
  v_customer_id := nullif(btrim(p_customer_id), '');
  if p_subscription_id is not null and v_subscription_id is null then
    raise exception 'p_subscription_id cannot be blank';
  end if;
  if p_customer_id is not null and v_customer_id is null then
    raise exception 'p_customer_id cannot be blank';
  end if;
  if v_subscription_id is null and v_customer_id is null then
    raise exception 'subscription_id or customer_id is required';
  end if;

  select count(distinct j.user_id)::int
    into v_user_count
    from public.account_deletion_cleanup_jobs j
   where (
     v_subscription_id is null
     or v_subscription_id = any(j.known_stripe_subscription_ids)
     or v_subscription_id = any(j.late_stripe_subscription_ids)
   )
     and (
       v_customer_id is null
       or v_customer_id = any(j.known_stripe_customer_ids)
       or v_customer_id = any(j.late_stripe_customer_ids)
     );

  if v_user_count = 0 then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  if v_user_count > 1 then
    return jsonb_build_object('ok', false, 'reason', 'ambiguous');
  end if;

  select j.user_id, j.id
    into v_user_id, v_job_id
    from public.account_deletion_cleanup_jobs j
   where (
     v_subscription_id is null
     or v_subscription_id = any(j.known_stripe_subscription_ids)
     or v_subscription_id = any(j.late_stripe_subscription_ids)
   )
     and (
       v_customer_id is null
       or v_customer_id = any(j.known_stripe_customer_ids)
       or v_customer_id = any(j.late_stripe_customer_ids)
     )
   order by j.created_at desc, j.id desc
   limit 1;

  return jsonb_build_object(
    'ok', true,
    'user_id', v_user_id,
    'job_id', v_job_id
  );
end;

complete_account_deletion_cleanup_job(p_:
declare
  v_caller_role text;
  j record;
  v_subscription_id text;
  v_customer_id text;
  v_surveyor_subscription_id text;
  v_surveyor_customer_id text;
  v_expected_late_subscription_ids text[] :=
    coalesce(p_expected_late_subscription_ids, '{}'::text[]);
  v_expected_late_customer_ids text[] :=
    coalesce(p_expected_late_customer_ids, '{}'::text[]);
begin
  v_caller_role := coalesce(
    nullif(current_setting('request.jwt.claim.role', true), ''),
    auth.role()
  );
  if v_caller_role <> 'service_role' then
    raise exception
      'complete_account_deletion_cleanup_job is service-role only (got: %)',
      coalesce(v_caller_role, 'none');
  end if;

  select *
    into j
    from public.account_deletion_cleanup_jobs
   where id = p_job_id
     and status = 'processing'
     and lease_token = p_lease_token
   for update;

  if not found or j.auth_revoked_at is null then
    return false;
  end if;

  -- Old workers (which omit the new arguments) remain safe only for jobs with no
  -- late identities. Any non-empty late set requires an explicit generation CAS.
  if j.late_stripe_subscription_ids
       is distinct from v_expected_late_subscription_ids
     or j.late_stripe_customer_ids
       is distinct from v_expected_late_customer_ids
     or (
       (
         cardinality(j.late_stripe_subscription_ids) > 0
         or cardinality(j.late_stripe_customer_ids) > 0
       )
       and p_expected_late_billing_revision is null
     )
     or (
       p_expected_late_billing_revision is not null
       and j.late_billing_revision <> p_expected_late_billing_revision
     ) then
    return false;
  end if;

  select stripe_subscription_id, stripe_customer_id
    into v_subscription_id, v_customer_id
    from public.profiles
   where id = j.user_id
   for update;
  if not found then
    return false;
  end if;

  if v_subscription_id is distinct from p_expected_subscription_id
     or v_customer_id is distinct from p_expected_customer_id then
    return false;
  end if;

  select stripe_subscription_id, stripe_customer_id
    into v_surveyor_subscription_id, v_surveyor_customer_id
    from public.surveyor_entitlements
   where user_id = j.user_id
   for update;
  if not found then
    v_surveyor_subscription_id := null;
    v_surveyor_customer_id := null;
  end if;
  if v_surveyor_subscription_id
       is distinct from p_expected_surveyor_subscription_id
     or v_surveyor_customer_id
       is distinct from p_expected_surveyor_customer_id then
    return false;
  end if;

  update public.profiles
     set stripe_subscription_id = null,
         stripe_customer_id = null,
         updated_at = now()
   where id = j.user_id;

  update public.surveyor_entitlements
     set status = 'revoked',
         revoked_at = coalesce(revoked_at, now()),
         stripe_subscription_id = null,
         stripe_customer_id = null
   where user_id = j.user_id;

  delete from public.surveyor_byok_keys
   where user_id = j.user_id;

  update public.account_deletion_cleanup_jobs
     set status = 'done',
         stripe_cleaned_at = now(),
         completed_at = now(),
         next_attempt_at = now(),
         locked_at = null,
         lease_token = null,
         last_error = null,
         known_stripe_subscription_ids = (
           select coalesce(array_agg(distinct x order by x), '{}'::text[])
             from unnest(
               j.known_stripe_subscription_ids
               || j.late_stripe_subscription_ids
               || array_remove(
                 array[
                   p_expected_subscription_id,
                   p_expected_surveyor_subscription_id
                 ],
                 null
               )
             ) as ids(x)
            where btrim(x) <> ''
         ),
         known_stripe_customer_ids = (
           select coalesce(array_agg(distinct x order by x), '{}'::text[])
             from unnest(
               j.known_stripe_customer_ids
               || j.late_stripe_customer_ids
               || array_remove(
                 array[
                   p_expected_customer_id,
                   p_expected_surveyor_customer_id
                 ],
                 null
               )
             ) as ids(x)
            where btrim(x) <> ''
         ),
         late_stripe_subscription_ids = '{}'::text[],
         late_stripe_customer_ids = '{}'::text[],
         late_billing_revision = j.late_billing_revision + 1,
         updated_at = now()
   where id = j.id;

  update public.deletion_requests
     set status = 'done',
         processed_at = now(),
         email = null
   where id = j.deletion_request_id;

  if j.audit_required and j.audit_written_at is null then
    perform public.write_audit(
      p_action          => 'process_deletion',
      p_target_user_id  => j.user_id,
      p_target_type     => 'deletion_request',
      p_target_id       => j.deletion_request_id::text,
      p_reason          =>
        'soft-delete and external cleanup completed after grace window',
      p_before          =>
        coalesce(j.audit_before, jsonb_build_object('backfilled', true)),
      p_after           => jsonb_build_object(
        'anonymized', true,
        'status', 'done',
        'locked', true,
        'auth_revoked', true,
        'billing_canceled', true
      ),
      p_was_destructive => true,
      p_was_reversible  => false,
      p_user_notified   => true,
      p_actor_id        => j.audit_actor_id
    );
    update public.account_deletion_cleanup_jobs
       set audit_written_at = now()
     where id = j.id;
  elsif not j.audit_required and j.audit_written_at is null then
    perform public.write_audit(
      p_action          => 'complete_deletion_external_cleanup',
      p_target_user_id  => j.user_id,
      p_target_type     => 'deletion_request',
      p_target_id       => j.deletion_request_id::text,
      p_reason          => 'backfilled GoTrue and Stripe cleanup completed',
      p_before          => jsonb_build_object('backfilled', true),
      p_after           => jsonb_build_object(
        'status', 'done',
        'auth_revoked', true,
        'billing_canceled', true
      ),
      p_was_destructive => true,
      p_was_reversible  => false,
      p_user_notified   => true,
      p_actor_id        => j.audit_actor_id
    );
    update public.account_deletion_cleanup_jobs
       set audit_written_at = now()
     where id = j.id;
  end if;

  return true;
end;

enforce_active_credit_spend_insert():
declare
  acting uuid := auth.uid();
begin
  if new.kind <> 'spend'
     or acting is null
     or coalesce(
          nullif(current_setting('request.jwt.claim.role', true), ''),
          auth.role()
        ) = 'service_role' then
    return new;
  end if;

  if new.user_id <> acting then
    raise exception 'credit spend owner does not match authenticated user'
      using errcode = 'check_violation';
  end if;
  perform 1
  from public.profiles p
  where p.id = acting
    and p.banned_at is null
    and p.disabled_at is null
    and p.deleted_at is null
  for update;
  if not found then
    raise exception 'account is not active'
      using errcode = 'check_violation';
  end if;
  return new;
end;

mutate_settlement_batch(p_expected_user:
declare
  item jsonb;
  target_id uuid;
  affected integer := 0;
  deleted_count integer := 0;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if p_expected_user is null or auth.uid() <> p_expected_user then
    raise exception 'auth session changed before settlement batch mutation';
  end if;

  -- Serialize the full mutation against account deletion/moderation. Deletion
  -- first => this finds no active row and fails closed. Mutation first => the
  -- profile lock is held until all writes commit, then deletion may proceed.
  perform 1
  from public.profiles p
  where p.id = auth.uid()
    and p.banned_at is null
    and p.disabled_at is null
    and p.deleted_at is null
  for update;
  if not found then
    raise exception 'account is not active';
  end if;

  if jsonb_typeof(coalesce(updates, '[]'::jsonb)) <> 'array' then
    raise exception 'updates must be an array';
  end if;
  if jsonb_typeof(coalesce(creates, '[]'::jsonb)) <> 'array' then
    raise exception 'creates must be an array';
  end if;

  for item in
    select value
    from jsonb_array_elements(coalesce(updates, '[]'::jsonb))
  loop
    target_id := (item->>'id')::uuid;
    if not exists (
      select 1
      from public.settlements
      where id = target_id
        and user_id = auth.uid()
        and access_state = 'active'
      for update
    ) then
      raise exception
        'settlement % is not active or not owned by caller',
        target_id;
    end if;
  end loop;

  -- Lock every requested deletion target. Unlike updates, privacy deletion is
  -- valid for active, inactive_plan, and pending_delete rows.
  if exists (
    select 1
    from unnest(coalesce(delete_ids, '{}'::uuid[])) requested(id)
    left join public.settlements s
      on s.id = requested.id
     and s.user_id = auth.uid()
    where s.id is null
  ) then
    raise exception 'one or more deleted settlements are not owned by caller';
  end if;
  perform 1
  from public.settlements s
  where s.id = any(coalesce(delete_ids, '{}'::uuid[]))
    and s.user_id = auth.uid()
  for update;

  for item in
    select value
    from jsonb_array_elements(coalesce(creates, '[]'::jsonb))
  loop
    insert into public.settlements (
      id, user_id, name, tier, data, config, toggles, seed,
      neighbour_links, ai_data, campaign_state, version_history
    ) values (
      (item->>'id')::uuid,
      auth.uid(),
      item->>'name',
      item->>'tier',
      item->'data',
      item->'config',
      item->'toggles',
      item->>'seed',
      item->'neighbour_links',
      coalesce(item->'ai_data', '{}'::jsonb),
      item->'campaign_state',
      item->'version_history'
    );
    affected := affected + 1;
  end loop;

  for item in
    select value
    from jsonb_array_elements(coalesce(updates, '[]'::jsonb))
  loop
    target_id := (item->>'id')::uuid;
    update public.settlements
    set
      name = case when item ? 'name' then item->>'name' else name end,
      tier = case when item ? 'tier' then item->>'tier' else tier end,
      data = case when item ? 'data' then item->'data' else data end,
      config = case when item ? 'config' then item->'config' else config end,
      toggles = case when item ? 'toggles' then item->'toggles' else toggles end,
      seed = case when item ? 'seed' then item->>'seed' else seed end,
      neighbour_links = case
        when item ? 'neighbour_links' then item->'neighbour_links'
        else neighbour_links
      end,
      ai_data = case
        when item ? 'ai_data' then item->'ai_data'
        else ai_data
      end,
      campaign_state = case
        when item ? 'campaign_state' then item->'campaign_state'
        else campaign_state
      end,
      version_history = case
        when item ? 'version_history' then item->'version_history'
        else version_history
      end
    where id = target_id
      and user_id = auth.uid();
    affected := affected + 1;
  end loop;

  delete from public.settlements
  where id = any(coalesce(delete_ids, '{}'::uuid[]))
    and user_id = auth.uid();
  get diagnostics deleted_count = row_count;
  if deleted_count <> coalesce(cardinality(delete_ids), 0) then
    -- Duplicate ids or an unexpected short delete cannot be reported as exact
    -- success. Raising rolls the entire SECURITY DEFINER transaction back.
    raise exception 'settlement batch delete did not confirm every requested row';
  end if;
  affected := affected + deleted_count;
  return affected;
end;

release_payment_refund_obligation_lease(:
declare
  v_caller_role text;
  v_updated text;
  v_retry_seconds integer :=
    greatest(30, least(coalesce(p_retry_seconds, 300), 86400));
  v_error text := nullif(left(btrim(coalesce(p_error, '')), 1000), '');
begin
  v_caller_role := coalesce(
    nullif(current_setting('request.jwt.claim.role', true), ''),
    auth.role()
  );
  if v_caller_role <> 'service_role' then
    raise exception 'release_payment_refund_obligation_lease is service-role only (got: %)',
      coalesce(v_caller_role, 'none');
  end if;

  update public.payment_refund_obligations obligation
     set recovery_lease_token = null,
         recovery_lease_expires_at = null,
         recovery_next_attempt_at = case
           when obligation.status in ('pending', 'requires_action')
             then now() + make_interval(secs => v_retry_seconds)
           else null
         end,
         recovery_last_error = case
           when obligation.status in ('succeeded', 'failed', 'canceled')
             then null
           else v_error
         end,
         recovery_last_reconciled_at = case
           when v_error is null then now()
           else obligation.recovery_last_reconciled_at
         end,
         updated_at = now()
   where obligation.payment_intent_id = btrim(coalesce(p_payment_intent_id, ''))
     and obligation.recovery_lease_token = p_lease_token
  returning obligation.payment_intent_id into v_updated;

  return v_updated is not null;
end;

_payment_refund_recovery_cron_should_dis:
begin
  if cfg is null or jsonb_typeof(cfg) <> 'object' then
    return 'not_configured';
  end if;
  if coalesce((cfg ->> 'enabled')::boolean, false) is not true then
    return 'disabled';
  end if;
  if nullif(btrim(cfg ->> 'url'), '') is null
     or nullif(btrim(cfg ->> 'secret'), '') is null then
    return 'not_configured';
  end if;
  return 'ok';
exception when others then
  return 'not_configured';
end;

run_payment_refund_recovery():
declare
  cfg jsonb;
  verdict text;
  req_id bigint;
begin
  select value into cfg
    from public.system_config
   where key = 'payment_refund_recovery_cron';
  verdict := public._payment_refund_recovery_cron_should_dispatch(cfg);
  if verdict <> 'ok' then
    return verdict;
  end if;

  begin
    select net.http_post(
      url := cfg ->> 'url',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'x-cron-secret', cfg ->> 'secret'
      ),
      body := '{}'::jsonb
    ) into req_id;
  exception
    when undefined_function or undefined_table or invalid_schema_name then
      raise notice 'pg_net unavailable; payment-refund-worker not dispatched';
      return 'pg_net_unavailable';
  end;
  return 'dispatched:' || coalesce(req_id::text, 'unknown');
end;

claim_stripe_webhook_event(p_event_id te:
declare
  v_caller_role text;
  v_event_id text := nullif(btrim(p_event_id), '');
  v_event_type text := nullif(btrim(p_event_type), '');
  v_stale interval := make_interval(
    secs => greatest(30, least(coalesce(p_stale_after_seconds, 300), 3600))
  );
  v_lease uuid := gen_random_uuid();
  v_row public.processed_webhook_events%rowtype;
begin
  v_caller_role := coalesce(
    nullif(current_setting('request.jwt.claim.role', true), ''),
    auth.role()
  );
  if v_caller_role <> 'service_role' then
    raise exception 'claim_stripe_webhook_event is service-role only';
  end if;
  if v_event_id is null then
    raise exception 'event id is required';
  end if;

  insert into public.processed_webhook_events (
    event_id,
    event_type,
    status,
    lease_token,
    locked_at,
    completed_at,
    first_claimed_at,
    attempts
  ) values (
    v_event_id,
    v_event_type,
    'processing',
    v_lease,
    now(),
    null,
    now(),
    1
  )
  on conflict (event_id) do nothing
  returning * into v_row;

  if found then
    return jsonb_build_object(
      'claimed', true,
      'lease_token', v_row.lease_token,
      'attempts', v_row.attempts
    );
  end if;

  select *
    into v_row
    from public.processed_webhook_events
   where event_id = v_event_id
   for update;

  if v_row.status = 'done' then
    return jsonb_build_object('claimed', false, 'reason', 'done');
  end if;
  if v_row.status = 'processing'
     and v_row.locked_at > now() - v_stale then
    return jsonb_build_object(
      'claimed', false,
      'reason', 'in_progress',
      'retry_after_seconds',
      greatest(
        1,
        ceil(extract(epoch from (v_row.locked_at + v_stale - now())))::int
      )
    );
  end if;

  update public.processed_webhook_events
     set event_type = coalesce(v_event_type, event_type),
         status = 'processing',
         lease_token = v_lease,
         locked_at = now(),
         completed_at = null,
         attempts = attempts + 1
   where event_id = v_event_id
   returning * into v_row;

  return jsonb_build_object(
    'claimed', true,
    'lease_token', v_row.lease_token,
    'attempts', v_row.attempts,
    'reclaimed', true
  );
end;

complete_stripe_webhook_event(p_event_id:
declare
