report_operational_obligation_health(p_s:
declare
  v_stale interval := make_interval(
    mins => greatest(5, least(coalesce(p_stale_minutes, 30), 1440))
  );
  v_deletion_warning_age constant interval := interval '1 hour';
  v_deletion_critical_age constant interval := interval '24 hours';
  v_refund_warning_age constant interval := interval '15 minutes';
  v_refund_critical_age constant interval := interval '60 minutes';
  v_webhook_warning_age constant interval := interval '15 minutes';
  v_webhook_critical_age constant interval := interval '60 minutes';
  v_deletion jsonb;
  v_refund jsonb;
  v_webhook jsonb;
  v_workers jsonb;
  v_acks jsonb;
  v_critical integer;
  v_warning integer;
  v_severity text;
begin
  perform public._require_operational_service_role();

  select jsonb_build_object(
    'open', count(*) filter (where j.status <> 'done'),
    'due', count(*) filter (
      where j.status in ('pending', 'retry')
        and j.next_attempt_at <= now()
    ),
    'retrying', count(*) filter (where j.status = 'retry'),
    'processing', count(*) filter (where j.status = 'processing'),
    'staleLeases', count(*) filter (
      where j.status = 'processing'
        and (j.locked_at is null or j.locked_at <= now() - v_stale)
    ),
    'highAttempt', count(*) filter (
      where j.status <> 'done' and j.attempts >= 10
    ),
    'warningAgeBreaches', count(*) filter (
      where j.status <> 'done'
        and j.created_at <= now() - v_deletion_warning_age
        and j.created_at > now() - v_deletion_critical_age
    ),
    'criticalAgeBreaches', count(*) filter (
      where j.status <> 'done'
        and j.created_at <= now() - v_deletion_critical_age
    ),
    'maxAttempts', coalesce(max(j.attempts) filter (where j.status <> 'done'), 0),
    'oldestOpenSeconds', coalesce(
      floor(extract(epoch from now() - min(j.created_at)
        filter (where j.status <> 'done')))::bigint,
      0
    )
  ) into v_deletion
  from public.account_deletion_cleanup_jobs j;

  select jsonb_build_object(
    'open', count(*) filter (
      where r.status in ('pending', 'requires_action')
    ),
    'due', count(*) filter (
      where r.status in ('pending', 'requires_action')
        and coalesce(r.recovery_next_attempt_at, r.created_at) <= now()
        and (
          r.recovery_lease_token is null
          or r.recovery_lease_expires_at <= now()
        )
    ),
    'requiresAction', count(*) filter (where r.status = 'requires_action'),
    'terminalFailed', count(*) filter (where r.status in ('failed', 'canceled')),
    'leased', count(*) filter (
      where r.status in ('pending', 'requires_action')
        and r.recovery_lease_token is not null
        and r.recovery_lease_expires_at > now()
    ),
    'staleLeases', count(*) filter (
      where r.status in ('pending', 'requires_action')
        and r.recovery_lease_token is not null
        and r.recovery_lease_expires_at <= now()
    ),
    'highAttempt', count(*) filter (
      where r.status in ('pending', 'requires_action')
        and r.recovery_attempts >= 10
    ),
    'warningAgeBreaches', count(*) filter (
      where r.status in ('pending', 'requires_action')
        and r.created_at <= now() - v_refund_warning_age
        and r.created_at > now() - v_refund_critical_age
    ),
    'criticalAgeBreaches', count(*) filter (
      where r.status in ('pending', 'requires_action')
        and r.created_at <= now() - v_refund_critical_age
    ),
    'maxAttempts', coalesce(max(r.recovery_attempts)
      filter (where r.status in ('pending', 'requires_action')), 0),
    'oldestOpenSeconds', coalesce(
      floor(extract(epoch from now() - min(r.created_at)
        filter (where r.status in ('pending', 'requires_action'))))::bigint,
      0
    )
  ) into v_refund
  from public.payment_refund_obligations r;

  select jsonb_build_object(
    'open', count(*),
    'processing', count(*) filter (where w.status = 'processing'),
    'retrying', count(*) filter (where w.status = 'retry'),
    'staleLeases', count(*) filter (
      where w.status = 'processing'
        and (w.locked_at is null or w.locked_at <= now() - v_stale)
    ),
    'highAttempt', count(*) filter (
      where w.attempts >= 5
    ),
    'warningAgeBreaches', count(*) filter (
      where w.first_claimed_at <= now() - v_webhook_warning_age
        and w.first_claimed_at > now() - v_webhook_critical_age
    ),
    'criticalAgeBreaches', count(*) filter (
      where w.first_claimed_at <= now() - v_webhook_critical_age
    ),
    'maxAttempts', coalesce(max(w.attempts), 0),
    'oldestOpenSeconds', coalesce(
      floor(extract(epoch from now() - min(w.first_claimed_at)))::bigint,
      0
    ),
    'oldestProcessingSeconds', coalesce(
      floor(extract(epoch from now() - min(w.first_claimed_at)
        filter (where w.status = 'processing')))::bigint,
      0
    )
  ) into v_webhook
  from public.processed_webhook_events w
  where w.status in ('processing', 'retry');

  select jsonb_build_object(
    'accountDeletion', coalesce(
      (select value from public.system_config
        where key = 'account_deletion_last_run'),
      '{"ok":false,"reason":"never_run"}'::jsonb
    ),
    'paymentRefund', coalesce(
      (select value from public.system_config
        where key = 'payment_refund_recovery_last_run'),
      '{"ok":false,"reason":"never_run"}'::jsonb
    )
  ) into v_workers;

  select coalesce(
    jsonb_object_agg(source, active_count),
    '{}'::jsonb
  ) into v_acks
  from (
    select source, count(*)::integer as active_count
      from public.operational_obligation_acknowledgements
     where cleared_at is null
     group by source
  ) counts;

  v_critical :=
      coalesce((v_deletion ->> 'highAttempt')::integer, 0)
    + coalesce((v_deletion ->> 'criticalAgeBreaches')::integer, 0)
    + coalesce((v_refund ->> 'requiresAction')::integer, 0)
    + coalesce((v_refund ->> 'terminalFailed')::integer, 0)
    + coalesce((v_refund ->> 'highAttempt')::integer, 0)
    + coalesce((v_refund ->> 'criticalAgeBreaches')::integer, 0)
    + coalesce((v_webhook ->> 'criticalAgeBreaches')::integer, 0);
  v_warning :=
      coalesce((v_deletion ->> 'due')::integer, 0)
    + coalesce((v_deletion ->> 'retrying')::integer, 0)
    + coalesce((v_deletion ->> 'staleLeases')::integer, 0)
    + coalesce((v_deletion ->> 'warningAgeBreaches')::integer, 0)
    + coalesce((v_refund ->> 'due')::integer, 0)
    + coalesce((v_refund ->> 'staleLeases')::integer, 0)
    + coalesce((v_refund ->> 'warningAgeBreaches')::integer, 0)
    + coalesce((v_webhook ->> 'retrying')::integer, 0)
    + coalesce((v_webhook ->> 'staleLeases')::integer, 0)
    + coalesce((v_webhook ->> 'highAttempt')::integer, 0)
    + coalesce((v_webhook ->> 'warningAgeBreaches')::integer, 0);
  v_severity := case
    when v_critical > 0 then 'critical'
    when v_warning > 0 then 'warning'
    else 'healthy'
  end;

  return jsonb_build_object(
    'schemaVersion', 1,
    'generatedAt', now(),
    'staleAfterSeconds', floor(extract(epoch from v_stale))::integer,
    'severity', v_severity,
    'healthy', v_severity = 'healthy',
    'accountDeletion', v_deletion,
    'paymentRefund', v_refund,
    'stripeWebhook', v_webhook,
    'workerHeartbeats', v_workers,
    'activeAcknowledgements', v_acks
  );
end;

acknowledge_operational_obligation(p_sou:
declare
  v_source text := btrim(coalesce(p_source, ''));
  v_key text := btrim(coalesce(p_obligation_key, ''));
  v_note text := nullif(left(btrim(coalesce(p_note, '')), 1000), '');
  v_exists boolean := false;
begin
  perform public._require_operational_service_role();
  if not public.has_role(p_actor, array['admin', 'developer']) then
    raise exception 'not authorized: operational acknowledgement requires admin or developer';
  end if;
  if v_source not in (
    'account_deletion',
    'payment_refund',
    'stripe_webhook'
  ) or v_key = '' then
    raise exception 'invalid operational obligation identity';
  end if;

  if v_source = 'account_deletion' then
    select exists(
      select 1 from public.account_deletion_cleanup_jobs
       where id::text = v_key and status <> 'done'
    ) into v_exists;
  elsif v_source = 'payment_refund' then
    select exists(
      select 1 from public.payment_refund_obligations
       where payment_intent_id = v_key
         and status in ('pending', 'requires_action', 'failed', 'canceled')
    ) into v_exists;
  else
    select exists(
      select 1 from public.processed_webhook_events
       where event_id = v_key and status in ('processing', 'retry')
    ) into v_exists;
  end if;
  if not v_exists then
    return false;
  end if;

  insert into public.operational_obligation_acknowledgements (
    source,
    obligation_key,
    acknowledged_by,
    acknowledged_at,
    note,
    cleared_at,
    updated_at
  ) values (
    v_source,
    v_key,
    p_actor,
    now(),
    v_note,
    case when p_clear then now() else null end,
    now()
  )
  on conflict (source, obligation_key) do update
     set acknowledged_by = excluded.acknowledged_by,
         acknowledged_at = excluded.acknowledged_at,
         note = excluded.note,
         cleared_at = excluded.cleared_at,
         updated_at = excluded.updated_at;

  perform public.write_audit(
    p_action            => case
      when p_clear then 'clear_operational_acknowledgement'
      else 'acknowledge_operational_obligation'
    end,
    p_target_user_id    => null,
    p_target_type       => 'operational_obligation',
    p_target_id         => v_source || ':' || v_key,
    p_reason            => v_note,
    p_before            => null,
    p_after             => jsonb_build_object(
      'source', v_source,
      'acknowledged', not p_clear
    ),
    p_was_destructive   => false,
    p_was_reversible    => true,
    p_user_notified     => false,
    p_actor_id          => p_actor
  );
  return true;
end;

claim_application_command(p_owner_id uui:
declare
  v_inserted integer := 0;
  v_row public.application_command_journal%rowtype;
begin
  if p_owner_id is null
    or nullif(btrim(p_command_id), '') is null
    or p_command_id !~ '^.{1,240}$'
    or p_fingerprint !~ '^[0-9a-f]{64}$'
    or p_kind !~ '^[a-z][a-z0-9.-]{0,159}$'
  then
    raise exception 'invalid application command claim'
      using errcode = '22023';
  end if;

  insert into public.application_command_journal (
    owner_id,
    command_id,
    fingerprint,
    kind,
    target_id,
    expected_revision
  ) values (
    p_owner_id,
    p_command_id,
    p_fingerprint,
    p_kind,
    p_target_id,
    p_expected_revision
  )
  on conflict (owner_id, command_id) do nothing;
  get diagnostics v_inserted = row_count;

  select * into strict v_row
    from public.application_command_journal
   where owner_id = p_owner_id
     and command_id = p_command_id
   for update;

  if v_row.fingerprint <> p_fingerprint then
    return jsonb_build_object(
      'status', 'conflict',
      'reason', 'command_id_conflict',
      'replayed', true,
      'fingerprint', v_row.fingerprint
    );
  end if;

  return jsonb_build_object(
    'status', v_row.status,
    'phase', v_row.phase,
    'replayed', v_inserted = 0,
    'fingerprint', v_row.fingerprint,
    'receipt', v_row.receipt,
    'reason', v_row.failure_code
  );
end;

finalize_application_command(p_owner_id:
declare
  v_updated integer;
begin
  if p_status not in ('applied', 'stale', 'failed') then
    raise exception 'invalid final application command status'
      using errcode = '22023';
  end if;

  update public.application_command_journal
     set phase = 'finalized',
         status = p_status,
         receipt = p_receipt,
         failure_code = p_failure_code,
         finalized_at = coalesce(finalized_at, now()),
         updated_at = now()
   where owner_id = p_owner_id
     and command_id = p_command_id
     and fingerprint = p_fingerprint
     and (
       status = 'claimed'
       or (
         phase = 'finalized'
         and status = p_status
         and receipt is not distinct from p_receipt
       )
     );
  get diagnostics v_updated = row_count;
  return v_updated = 1;
end;

mark_application_command_reconcile(p_own:
declare
  v_updated integer;
begin
  update public.application_command_journal
     set phase = 'reconcile',
         status = 'reconcile-required',
         failure_code = coalesce(nullif(btrim(p_reason), ''), 'ambiguous_result'),
         updated_at = now()
   where owner_id = p_owner_id
     and command_id = p_command_id
     and fingerprint = p_fingerprint
     and status in ('claimed', 'reconcile-required');
  get diagnostics v_updated = row_count;
  return v_updated = 1;
end;

apply_cut_trade_route_command(p_expected:
declare
  v_uid uuid := auth.uid();
  v_fingerprint text;
  v_claim jsonb;
  v_row public.settlements%rowtype;
  v_receipt jsonb;
  v_reason text;
  v_expected_log_length integer;
  v_next_log_length integer;
  v_expected_route_length integer;
  v_next_route_length integer;
  v_last_log_entry jsonb;
  v_last_route jsonb;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if p_expected_owner is null or p_expected_owner <> v_uid then
    raise exception 'application command owner changed'
      using errcode = '42501';
  end if;
  if not public.account_is_active(v_uid) then
    raise exception 'account is not active'
      using errcode = '42501';
  end if;
  if p_save_id is null or p_expected_revision is null then
    raise exception 'save id and expected revision are required'
      using errcode = '22023';
  end if;
  if jsonb_typeof(p_event) <> 'object'
    or p_event ->> 'type' <> 'CUT_TRADE_ROUTE'
    or nullif(btrim(p_event ->> 'id'), '') is null
  then
    raise exception 'only CUT_TRADE_ROUTE is server-authoritative in this RPC'
      using errcode = '22023';
  end if;
  if jsonb_typeof(p_expected_data) <> 'object'
    or jsonb_typeof(p_expected_campaign_state) <> 'object'
    or jsonb_typeof(p_next_data) <> 'object'
    or jsonb_typeof(p_next_campaign_state) <> 'object'
    or coalesce(p_next_campaign_state ->> 'phase', '') <> 'canon'
  then
    raise exception 'prepared canon-event projection is invalid'
      using errcode = '22023';
  end if;
  if jsonb_typeof(p_expected_campaign_state -> 'eventLog') is distinct from 'array'
    or jsonb_typeof(p_next_campaign_state -> 'eventLog') is distinct from 'array'
  then
    raise exception 'canon-event log projections must be arrays'
      using errcode = '22023';
  end if;
  if p_next_ai_data is not null and jsonb_typeof(p_next_ai_data) <> 'object' then
    raise exception 'p_next_ai_data must be an object or null'
      using errcode = '22023';
  end if;

  -- Constrain the client-prepared projection before accepting it. The server
  -- proves the prior log/route prefixes are intact, one matching entry is
  -- appended to each, and fields outside CUT_TRADE_ROUTE's known mutation
  -- surface are unchanged. It deliberately does NOT claim to recompute or
  -- semantically prove the contents of allowed fields (active conditions,
  -- reconciliation, derived SystemState, and optional narrative snapshot).
  -- The receipt names that boundary so an audit cannot mistake this transitional
  -- client-prepared envelope for future server-side event preparation.
  if (
    p_next_data
      - 'config'
      - '_config'
      - 'activeConditions'
      - 'reconciliationLog'
  ) is distinct from (
    p_expected_data
      - 'config'
      - '_config'
      - 'activeConditions'
      - 'reconciliationLog'
  ) then
    raise exception 'CUT_TRADE_ROUTE changed an unrelated settlement field'
      using errcode = '22023';
  end if;
  if (
    coalesce(p_next_data -> 'config', '{}'::jsonb)
      - '_cutRoutes'
      - 'eventConditions'
  ) is distinct from (
    coalesce(p_expected_data -> 'config', '{}'::jsonb)
      - '_cutRoutes'
      - 'eventConditions'
  ) then
    raise exception 'CUT_TRADE_ROUTE changed an unrelated config field'
      using errcode = '22023';
  end if;
  if (
    coalesce(p_next_data -> '_config', '{}'::jsonb)
      - '_cutRoutes'
      - 'eventConditions'
  ) is distinct from (
    coalesce(p_expected_data -> '_config', '{}'::jsonb)
      - '_cutRoutes'
      - 'eventConditions'
  ) then
    raise exception 'CUT_TRADE_ROUTE changed an unrelated raw-config field'
      using errcode = '22023';
  end if;
  if (
    p_next_campaign_state
      - 'eventLog'
      - 'systemState'
      - 'editedAt'
      - 'narrativeDrift'
      - 'exportState'
  ) is distinct from (
    p_expected_campaign_state
      - 'eventLog'
      - 'systemState'
      - 'editedAt'
      - 'narrativeDrift'
      - 'exportState'
  ) then
    raise exception 'CUT_TRADE_ROUTE changed an unrelated campaign-state field'
      using errcode = '22023';
  end if;

  v_expected_log_length := jsonb_array_length(
    p_expected_campaign_state -> 'eventLog'
  );
  v_next_log_length := jsonb_array_length(p_next_campaign_state -> 'eventLog');
  if v_next_log_length <> v_expected_log_length + 1 then
    raise exception 'CUT_TRADE_ROUTE must append exactly one event-log entry'
      using errcode = '22023';
  end if;
  if (
    (p_next_campaign_state -> 'eventLog') - v_expected_log_length
  ) is distinct from (
    p_expected_campaign_state -> 'eventLog'
  ) then
    raise exception 'CUT_TRADE_ROUTE must preserve the existing event-log prefix'
      using errcode = '22023';
  end if;
  v_last_log_entry := p_next_campaign_state
    -> 'eventLog'
    -> v_expected_log_length;
  if v_last_log_entry #>> '{event,type}' is distinct from 'CUT_TRADE_ROUTE'
    or v_last_log_entry #>> '{event,id}' is distinct from p_event ->> 'id'
  then
    raise exception 'event-log append does not match the command event'
      using errcode = '22023';
  end if;

  if p_expected_data #> '{config,_cutRoutes}' is null then
    v_expected_route_length := 0;
  elsif jsonb_typeof(p_expected_data #> '{config,_cutRoutes}') = 'array' then
    v_expected_route_length := jsonb_array_length(
      p_expected_data #> '{config,_cutRoutes}'
    );
  else
    raise exception 'base _cutRoutes must be an array when present'
      using errcode = '22023';
  end if;
  if jsonb_typeof(p_next_data #> '{config,_cutRoutes}') is distinct from 'array' then
    raise exception 'CUT_TRADE_ROUTE must append a route annotation'
      using errcode = '22023';
  end if;
  v_next_route_length := jsonb_array_length(
    p_next_data #> '{config,_cutRoutes}'
  );
  if v_next_route_length <> v_expected_route_length + 1 then
    raise exception 'CUT_TRADE_ROUTE must append exactly one route annotation'
      using errcode = '22023';
  end if;
  if (
    (p_next_data #> '{config,_cutRoutes}') - v_expected_route_length
  ) is distinct from coalesce(
    p_expected_data #> '{config,_cutRoutes}',
    '[]'::jsonb
  ) then
    raise exception 'CUT_TRADE_ROUTE must preserve existing route annotations'
      using errcode = '22023';
  end if;
  v_last_route := p_next_data
    #> '{config,_cutRoutes}'
    -> v_expected_route_length;
  if v_last_route ->> 'atEventId' is distinct from p_event ->> 'id'
    or v_last_route ->> 'name'
      is distinct from coalesce(nullif(p_event ->> 'targetId', ''), 'primary')
  then
    raise exception 'route annotation does not match the command event'
      using errcode = '22023';
  end if;

  -- The server fingerprints every mutation-bearing input. No raw settlement,
  -- event prose, or campaign JSON is retained in the journal.
  v_fingerprint := encode(sha256(convert_to(
    jsonb_build_object(
      'kind', 'settlement.canon-event.apply',
      'saveId', p_save_id,
      'expectedRevision', p_expected_revision,
      'event', p_event,
      'expectedData', p_expected_data,
      'expectedCampaignState', p_expected_campaign_state,
      'expectedAiData', p_expected_ai_data,
      'nextData', p_next_data,
      'nextCampaignState', p_next_campaign_state,
      'nextAiData', p_next_ai_data
    )::text,
    'UTF8'
  )), 'hex');

  v_claim := public.claim_application_command(
    v_uid,
    p_command_id,
    v_fingerprint,
    'settlement.canon-event.apply',
    p_save_id,
    p_expected_revision
  );

  if v_claim ->> 'status' = 'conflict' then
    return v_claim;
  end if;

  -- A completed duplicate returns the authoritative current row. The receipt is
  -- historical identity; the projection may include legitimate later commands.
  if coalesce((v_claim ->> 'replayed')::boolean, false)
    and v_claim ->> 'status' <> 'claimed'
  then
    select * into v_row
      from public.settlements
     where id = p_save_id
       and user_id = v_uid;
    return jsonb_build_object(
      'status', v_claim ->> 'status',
      'reason', v_claim ->> 'reason',
      'replayed', true,
      'fingerprint', v_fingerprint,
      'revisionKind', 'base-projection-v1',
      'receipt', v_claim -> 'receipt',
      'settlement', v_row.data,
      'campaignState', v_row.campaign_state,
      'aiData', v_row.ai_data,
      'updatedAt', v_row.updated_at
    );
  end if;

  -- A separately committed claim has no safe automatic interpretation. The
  -- command-specific path normally claims and applies in this same transaction,
  -- so this state means an operator/service workflow intervened.
  if coalesce((v_claim ->> 'replayed')::boolean, false)
    and v_claim ->> 'status' = 'claimed'
  then
    perform public.mark_application_command_reconcile(
      v_uid,
      p_command_id,
      v_fingerprint,
      'abandoned_claim'
    );
    return jsonb_build_object(
      'status', 'reconcile-required',
      'reason', 'abandoned_claim',
      'replayed', true,
      'fingerprint', v_fingerprint,
      'revisionKind', 'base-projection-v1'
    );
  end if;

  -- The row comparison and replacement are one statement. JSONB equality is
  -- structural (object-key order is irrelevant). ai_data participates only
  -- when this command will replace it with a narrative-history snapshot; an
  -- unrelated AI write otherwise remains independent.
  update public.settlements
     set data = p_next_data,
         campaign_state = p_next_campaign_state,
         ai_data = case
           when p_next_ai_data is null then ai_data
           else p_next_ai_data
         end,
         neighbour_links = p_next_data -> 'neighbourNetwork',
         updated_at = clock_timestamp()
   where id = p_save_id
     and user_id = v_uid
     and access_state = 'active'
     and data = p_expected_data
     and campaign_state is not distinct from p_expected_campaign_state
     and (
       p_next_ai_data is null
       or ai_data is not distinct from p_expected_ai_data
     )
   returning * into v_row;

  if not found then
    if exists (
      select 1
        from public.settlements
       where id = p_save_id
         and user_id = v_uid
         and access_state = 'active'
    ) then
      v_reason := 'base_projection_changed';
    else
      v_reason := 'save_unavailable';
    end if;
    v_receipt := jsonb_build_object(
      'saveId', p_save_id,
      'eventType', 'CUT_TRADE_ROUTE',
      'reason', v_reason
    );
    perform public.finalize_application_command(
      v_uid,
      p_command_id,
      v_fingerprint,
      'stale',
      v_receipt,
      v_reason
    );
    return jsonb_build_object(
      'status', 'stale',
      'reason', v_reason,
      'replayed', false,
      'fingerprint', v_fingerprint,
      'revisionKind', 'base-projection-v1',
      'receipt', v_receipt
    );
  end if;

  v_receipt := jsonb_build_object(
    'saveId', p_save_id,
    'eventId', coalesce(p_event ->> 'id', p_command_id),
    'eventType', 'CUT_TRADE_ROUTE',
    'projectionValidation', 'client-prepared-constrained-envelope-v1',
    'revisionKind', 'base-projection-v1',
    'updatedAt', v_row.updated_at
  );
  if not public.finalize_application_command(
    v_uid,
    p_command_id,
    v_fingerprint,
    'applied',
    v_receipt,
    null
  ) then
    raise exception 'application command finalization failed'
      using errcode = '40001';
  end if;

  return jsonb_build_object(
    'status', 'applied',
    'replayed', false,
    'fingerprint', v_fingerprint,
    'revisionKind', 'base-projection-v1',
    'receipt', v_receipt,
    'settlement', v_row.data,
    'campaignState', v_row.campaign_state,
    'aiData', v_row.ai_data,
    'updatedAt', v_row.updated_at
  );
end;

_import_campaign_shape(p_map_data jsonb):
declare
  v_version_text text;
begin
  if jsonb_typeof(p_map_data) is distinct from 'object' then
    return 'invalid';
  end if;

  if p_map_data ->> 'kind' = 'settlementforge_campaign' then
    v_version_text := p_map_data ->> 'version';
    if jsonb_typeof(p_map_data -> 'campaign') is distinct from 'object'
      or v_version_text is null
      or v_version_text !~ '^[0-9]+$'
      or v_version_text::integer not between 1 and 2
    then
      return 'invalid';
    end if;
    return 'nested';
  end if;

  if p_map_data ? 'campaign' then
    if p_map_data ->> 'kind' is not null
      or jsonb_typeof(p_map_data -> 'campaign') is distinct from 'object'
    then
      return 'invalid';
    end if;
    return 'nested';
  end if;

  if p_map_data ? 'settlementIds'
    or p_map_data ? 'mapState'
    or p_map_data ? 'regionalGraph'
    or p_map_data ? 'wizardNews'
    or p_map_data ? 'worldState'
  then
    if p_map_data ? 'settlementIds'
      and jsonb_typeof(p_map_data -> 'settlementIds') is distinct from 'array'
    then
      return 'invalid';
    end if;
    return 'unwrapped';
  end if;

  return 'not-campaign';
end;

_import_campaign_members(p_map_data json:
declare
  v_shape text := public._import_campaign_shape(p_map_data);
  v_members jsonb;
begin
  if v_shape = 'nested' then
    v_members := p_map_data #> '{campaign,settlementIds}';
  elsif v_shape = 'unwrapped' then
    v_members := p_map_data -> 'settlementIds';
  else
    return null;
  end if;

  if v_members is null then
    return '[]'::jsonb;
  end if;
  if jsonb_typeof(v_members) is distinct from 'array' then
    return null;
  end if;
  return v_members;
end;

_import_patch_campaign_members(p_map_dat:
declare
  v_shape text := public._import_campaign_shape(p_map_data);
  v_campaign jsonb;
  v_members jsonb;
  v_pending jsonb;
begin
  if v_shape = 'nested' then
    v_campaign := p_map_data -> 'campaign';
  elsif v_shape = 'unwrapped' then
    v_campaign := p_map_data;
  else
    raise exception 'campaign envelope cannot be patched'
      using errcode = '22023';
  end if;

  v_members := coalesce(v_campaign -> 'settlementIds', '[]'::jsonb);
  if jsonb_typeof(v_members) is distinct from 'array' then
    raise exception 'campaign membership is not an array'
      using errcode = '22023';
  end if;

  select coalesce(jsonb_agg(value order by ordinal), '[]'::jsonb)
    into v_members
    from jsonb_array_elements(v_members) with ordinality as member(value, ordinal)
   where member.value #>> '{}' <> p_save_id::text;

  if p_include then
    v_members := v_members || jsonb_build_array(p_save_id::text);
  end if;

  v_campaign := jsonb_set(v_campaign, '{settlementIds}', v_members, true);
  v_campaign := jsonb_set(
    v_campaign,
    '{updatedAt}',
    to_jsonb(p_changed_at::text),
    true
  );

  -- Leaving a campaign is a deliberate moment: queued intentions for the
  -- departing settlement must be pruned exactly as campaignSlice.addToCampaign
  -- does. The target retains its queue.
  if not p_include
    and jsonb_typeof(v_campaign #> '{worldState,pendingEvents}') = 'array'
  then
    select coalesce(jsonb_agg(value order by ordinal), '[]'::jsonb)
      into v_pending
      from jsonb_array_elements(
        v_campaign #> '{worldState,pendingEvents}'
      ) with ordinality as event(value, ordinal)
     where event.value ->> 'saveId' is distinct from p_save_id::text;
    v_campaign := jsonb_set(
      v_campaign,
      '{worldState,pendingEvents}',
      v_pending,
      false
    );
  end if;

  if v_shape = 'nested' then
    return jsonb_set(p_map_data, '{campaign}', v_campaign, false);
  end if;
  return v_campaign;
end;

apply_import_reconciliation_command(p_ex:
declare
  v_uid uuid := auth.uid();
  v_fingerprint text;
  v_claim jsonb;
  v_now timestamptz := clock_timestamp();
  v_map public.saved_maps%rowtype;
  v_shape text;
  v_members jsonb;
  v_expected_ids jsonb;
  v_actual_ids jsonb := '[]'::jsonb;
  v_target_found boolean := false;
  v_save_exists boolean := false;
  v_affected_ids jsonb := '[]'::jsonb;
  v_receipt jsonb;
  v_save_row jsonb;
  v_campaign_rows jsonb := '[]'::jsonb;
  v_reason text;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if p_expected_owner is null or p_expected_owner <> v_uid then
    raise exception 'application command owner changed'
      using errcode = '42501';
  end if;
  if not public.account_is_active(v_uid)
    or not public.current_user_has_premium_access()
  then
    raise exception 'active premium account required'
      using errcode = '42501';
  end if;
  if p_kind not in (
    'import.settlement.create-and-attach',
    'import.campaign.attach-existing'
  )
    or p_campaign_id is null
    or p_save_id is null
    or nullif(btrim(p_source_checksum), '') is null
    or char_length(p_source_checksum) > 240
    or nullif(btrim(p_import_session_id), '') is null
    or char_length(p_import_session_id) > 240
    or jsonb_typeof(p_expected_membership_campaign_ids) is distinct from 'array'
    or exists (
      select 1
        from jsonb_array_elements(p_expected_membership_campaign_ids) as item
       where jsonb_typeof(item) <> 'string'
          or (item #>> '{}') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    )
  then
    raise exception 'invalid import reconciliation command'
      using errcode = '22023';
  end if;

  select coalesce(jsonb_agg(value order by value), '[]'::jsonb)
    into v_expected_ids
    from (
      select distinct item #>> '{}' as value
        from jsonb_array_elements(p_expected_membership_campaign_ids) as item
    ) expected;
  if jsonb_array_length(v_expected_ids)
    <> jsonb_array_length(p_expected_membership_campaign_ids)
  then
    raise exception 'expected campaign membership contains duplicates'
      using errcode = '22023';
  end if;

  if p_kind = 'import.settlement.create-and-attach' then
    if jsonb_typeof(p_entry) is distinct from 'object'
      or pg_column_size(p_entry) > 2 * 1024 * 1024
      or nullif(btrim(p_entry ->> 'name'), '') is null
      or char_length(p_entry ->> 'name') > 240
      or nullif(btrim(p_entry ->> 'tier'), '') is null
      or jsonb_typeof(p_entry -> 'settlement') is distinct from 'object'
      or jsonb_typeof(p_entry -> 'aiData') is distinct from 'object'
      or p_entry -> 'config' is distinct from 'null'::jsonb
      or p_entry -> 'seed' is distinct from 'null'::jsonb
      or p_entry #>> '{campaignState,phase}' is distinct from 'draft'
      or p_entry #> '{campaignState,eventLog}' is distinct from '[]'::jsonb
      or p_entry -> 'versionHistory' is distinct from '[]'::jsonb
      or p_entry #>> '{settlement,importedFrom,source}'
        is distinct from 'account-export'
      or p_entry #>> '{settlement,importedFrom,sourceChecksum}'
        is distinct from p_source_checksum
      or coalesce(p_entry #> '{settlement,neighbourNetwork}', '[]'::jsonb)
        is distinct from '[]'::jsonb
      or coalesce(
        p_entry #> '{settlement,interSettlementRelationships}',
        '[]'::jsonb
      ) is distinct from '[]'::jsonb
      or (
        p_entry #> '{settlement,neighborRelationship}' is not null
        and p_entry #> '{settlement,neighborRelationship}' <> 'null'::jsonb
      )
    then
      raise exception 'import settlement entry violates the dormant-copy contract'
        using errcode = '22023';
    end if;
  elsif p_entry is not null then
    raise exception 'attach-existing must not carry settlement content'
      using errcode = '22023';
  end if;

  v_fingerprint := encode(sha256(convert_to(
    jsonb_build_object(
      'kind', p_kind,
      'campaignId', p_campaign_id,
      'saveId', p_save_id,
      'sourceChecksum', p_source_checksum,
      'importSessionId', p_import_session_id,
      'expectedMembershipCampaignIds', v_expected_ids,
      'entry', p_entry
    )::text,
    'UTF8'
  )), 'hex');

  v_claim := public.claim_application_command(
    v_uid,
    p_command_id,
    v_fingerprint,
    p_kind,
    p_save_id,
    null
  );

  if v_claim ->> 'status' = 'conflict' then
    return v_claim;
  end if;

  if coalesce((v_claim ->> 'replayed')::boolean, false)
    and v_claim ->> 'status' <> 'claimed'
  then
    v_receipt := v_claim -> 'receipt';
    select to_jsonb(s) into v_save_row
      from public.settlements s
     where s.id = p_save_id
       and s.user_id = v_uid;
    select coalesce(jsonb_agg(to_jsonb(sm) order by sm.id), '[]'::jsonb)
      into v_campaign_rows
      from public.saved_maps sm
     where sm.user_id = v_uid
       and sm.id::text in (
         select item #>> '{}'
           from jsonb_array_elements(
             coalesce(v_receipt -> 'affectedCampaignIds', '[]'::jsonb)
           ) as item
       );
    return jsonb_build_object(
      'status', v_claim ->> 'status',
      'reason', v_claim ->> 'reason',
      'replayed', true,
      'fingerprint', v_fingerprint,
      'receipt', v_receipt,
      'saveRow', v_save_row,
      'campaignRows', v_campaign_rows
    );
  end if;

  if coalesce((v_claim ->> 'replayed')::boolean, false)
    and v_claim ->> 'status' = 'claimed'
  then
    perform public.mark_application_command_reconcile(
      v_uid,
      p_command_id,
      v_fingerprint,
      'abandoned_claim'
    );
    return jsonb_build_object(
      'status', 'reconcile-required',
      'reason', 'abandoned_claim',
      'replayed', true,
      'fingerprint', v_fingerprint
    );
  end if;

  -- Lock every active campaign in stable order. The first pass validates all
  -- campaign-shaped rows and captures the exact pre-command topology.
  for v_map in
    select *
      from public.saved_maps
     where user_id = v_uid
       and access_state = 'active'
     order by id
     for update
  loop
    v_shape := public._import_campaign_shape(v_map.map_data);
    if v_shape = 'invalid' then
      v_reason := 'campaign_shape_unsupported';
      exit;
    end if;
    if v_map.id = p_campaign_id then
      if v_shape not in ('nested', 'unwrapped') then
        v_reason := 'target_campaign_shape_unsupported';
        exit;
      end if;
      v_target_found := true;
    end if;
    if v_shape in ('nested', 'unwrapped') then
      v_members := public._import_campaign_members(v_map.map_data);
      if v_members is null then
        v_reason := 'campaign_membership_invalid';
        exit;
      end if;
      -- Historical campaign envelopes are admitted, but malformed or
      -- duplicate membership ids are not. Silently normalizing either would
      -- make the reviewed topology differ from the topology mutated here.
      if exists (
        select 1
          from jsonb_array_elements(v_members) as member
         where jsonb_typeof(member) <> 'string'
            or (member #>> '{}') !~*
              '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      ) or (
        select count(*)
          from jsonb_array_elements(v_members)
      ) <> (
        select count(distinct member #>> '{}')
          from jsonb_array_elements(v_members) as member
      ) then
        v_reason := 'campaign_membership_invalid';
        exit;
      end if;
      if exists (
        select 1
          from jsonb_array_elements(v_members) as member
         where member #>> '{}' = p_save_id::text
      ) then
        v_actual_ids := v_actual_ids || jsonb_build_array(v_map.id::text);
      end if;
    end if;
  end loop;

  if v_reason is null and not v_target_found then
    v_reason := 'target_campaign_unavailable';
  end if;

  if v_reason is null then
    select coalesce(jsonb_agg(value order by value), '[]'::jsonb)
      into v_actual_ids
      from (
        select distinct item #>> '{}' as value
          from jsonb_array_elements(v_actual_ids) as item
      ) actual;
    if v_actual_ids is distinct from v_expected_ids then
      v_reason := 'membership_topology_changed';
    end if;
  end if;

  if p_kind = 'import.campaign.attach-existing' and v_reason is null then
    select true into v_save_exists
      from public.settlements
     where id = p_save_id
       and user_id = v_uid
       and access_state = 'active'
     for update;
    if not coalesce(v_save_exists, false) then
      v_reason := 'save_unavailable';
    end if;
  elsif p_kind = 'import.settlement.create-and-attach' and v_reason is null then
    if exists (select 1 from public.settlements where id = p_save_id) then
      v_reason := 'save_id_unavailable';
    end if;
  end if;

  if v_reason is not null then
    v_receipt := jsonb_build_object(
      'importSessionId', p_import_session_id,
      'sourceChecksum', p_source_checksum,
      'campaignId', p_campaign_id,
      'saveId', p_save_id,
      'reason', v_reason
    );
    perform public.finalize_application_command(
      v_uid,
      p_command_id,
      v_fingerprint,
      'stale',
      v_receipt,
      v_reason
    );
    return jsonb_build_object(
      'status', 'stale',
      'reason', v_reason,
      'replayed', false,
      'fingerprint', v_fingerprint,
      'receipt', v_receipt
    );
  end if;

  if p_kind = 'import.settlement.create-and-attach' then
    insert into public.settlements (
      id,
      user_id,
      name,
      tier,
      data,
      config,
      toggles,
      seed,
      neighbour_links,
      ai_data,
      campaign_state,
      version_history
    ) values (
      p_save_id,
      v_uid,
      p_entry ->> 'name',
      p_entry ->> 'tier',
      p_entry -> 'settlement',
      null,
      null,
      null,
      '[]'::jsonb,
      p_entry -> 'aiData',
      p_entry -> 'campaignState',
      p_entry -> 'versionHistory'
    );
  end if;

  -- Patch only membership, campaign.updatedAt, and departed queued intentions.
  -- All other map/campaign fields remain the row's locked server value.
  for v_map in
    select *
      from public.saved_maps
     where user_id = v_uid
       and access_state = 'active'
       and (
         id = p_campaign_id
         or id::text in (
           select item #>> '{}'
             from jsonb_array_elements(v_actual_ids) as item
         )
       )
     order by id
     for update
  loop
    update public.saved_maps
       set map_data = public._import_patch_campaign_members(
             v_map.map_data,
             p_save_id,
             v_map.id = p_campaign_id,
             v_now
           ),
           updated_at = v_now
     where id = v_map.id
       and user_id = v_uid;
    v_affected_ids := v_affected_ids || jsonb_build_array(v_map.id::text);
  end loop;

  select coalesce(jsonb_agg(value order by value), '[]'::jsonb)
    into v_affected_ids
    from (
      select distinct item #>> '{}' as value
        from jsonb_array_elements(v_affected_ids) as item
    ) affected;

  v_receipt := jsonb_build_object(
    'importSessionId', p_import_session_id,
    'sourceChecksum', p_source_checksum,
    'kind', p_kind,
    'campaignId', p_campaign_id,
    'saveId', p_save_id,
    'membershipPolicy', 'exclusive-rehome',
    'previousCampaignIds', v_actual_ids,
    'affectedCampaignIds', v_affected_ids,
    'created', p_kind = 'import.settlement.create-and-attach',
    'appliedAt', v_now
  );
  if not public.finalize_application_command(
    v_uid,
    p_command_id,
    v_fingerprint,
    'applied',
    v_receipt,
    null
  ) then
    raise exception 'application command finalization failed'
      using errcode = '40001';
  end if;

  select to_jsonb(s) into v_save_row
    from public.settlements s
   where s.id = p_save_id
     and s.user_id = v_uid;
  select coalesce(jsonb_agg(to_jsonb(sm) order by sm.id), '[]'::jsonb)
    into v_campaign_rows
    from public.saved_maps sm
   where sm.user_id = v_uid
     and sm.id::text in (
       select item #>> '{}'
         from jsonb_array_elements(v_affected_ids) as item
     );

  return jsonb_build_object(
    'status', 'applied',
    'replayed', false,
    'fingerprint', v_fingerprint,
    'receipt', v_receipt,
    'saveRow', v_save_row,
    'campaignRows', v_campaign_rows
  );
end;

report_application_command_health(p_stal:
declare
  v_role text := coalesce(
    current_setting('request.jwt.claim.role', true),
    auth.role()
  );
  v_stale_minutes integer := greatest(1, least(coalesce(p_stale_minutes, 30), 1440));
  v_claimed integer;
  v_stale_claimed integer;
  v_reconcile integer;
  v_import_reconcile integer;
begin
  if v_role is distinct from 'service_role' then
    raise exception 'service-role only' using errcode = '42501';
  end if;

  select
    count(*) filter (where status = 'claimed'),
    count(*) filter (
      where status = 'claimed'
        and updated_at <= now() - make_interval(mins => v_stale_minutes)
    ),
    count(*) filter (where status = 'reconcile-required'),
    count(*) filter (
      where status = 'reconcile-required'
        and kind in (
          'import.settlement.create-and-attach',
          'import.campaign.attach-existing'
        )
    )
  into v_claimed, v_stale_claimed, v_reconcile, v_import_reconcile
  from public.application_command_journal;

  return jsonb_build_object(
    'schemaVersion', 1,
    'healthy', v_stale_claimed = 0 and v_reconcile = 0,
    'severity', case
      when v_reconcile > 0 then 'critical'
      when v_stale_claimed > 0 then 'warning'
      else 'healthy'
    end,
    'staleMinutes', v_stale_minutes,
    'claimed', v_claimed,
    'staleClaimed', v_stale_claimed,
    'reconcileRequired', v_reconcile,
    'importReconcileRequired', v_import_reconcile,
    'observedAt', now()
  );
end;

_content_canonical_json(p_value jsonb):
declare
  v_type text := jsonb_typeof(p_value);
  v_result text;
begin
  if v_type = 'object' then
    select '{' || coalesce(string_agg(
      to_jsonb(entry.key)::text
        || ':'
        || public._content_canonical_json(entry.value),
      ',' order by entry.key collate "C"
    ), '') || '}'
      into v_result
      from jsonb_each(p_value) as entry;
    return v_result;
  elsif v_type = 'array' then
    select '[' || coalesce(string_agg(
      public._content_canonical_json(entry.value),
      ',' order by entry.ordinal
    ), '') || ']'
      into v_result
      from jsonb_array_elements(p_value)
        with ordinality as entry(value, ordinal);
    return v_result;
  end if;
  return p_value::text;
end;

