  v_category jsonb;
  v_key text;
  v_value jsonb;
  v_rule jsonb;
  v_type text;
  v_text text;
begin
  if jsonb_typeof(p_data) is distinct from 'object'
    or octet_length(p_data::text) > 262144
  then
    return false;
  end if;
  v_category := v_manifest -> p_category;
  if v_category is null then return false; end if;

  for v_key, v_rule in select * from jsonb_each(v_category) loop
    if coalesce((v_rule ->> 'r')::integer, 0) = 1
      and (
        not (p_data ? v_key)
        or jsonb_typeof(p_data -> v_key) <> 'string'
        or nullif(btrim(p_data ->> v_key), '') is null
      )
    then
      return false;
    end if;
  end loop;

  for v_key, v_value in select * from jsonb_each(p_data) loop
    if v_key = 'localUid' then
      if jsonb_typeof(v_value) <> 'string'
        or nullif(btrim(v_value #>> '{}'), '') is null
        or char_length(v_value #>> '{}') > 240
        or v_value #>> '{}' <> btrim(v_value #>> '{}')
      then return false; end if;
      continue;
    end if;
    v_rule := v_category -> v_key;
    if v_rule is null then return false; end if;
    v_type := v_rule ->> 't';
    if v_type = 'boolean' then
      if jsonb_typeof(v_value) <> 'boolean' then return false; end if;
    elsif v_type in ('string', 'enum') then
      if jsonb_typeof(v_value) <> 'string' then return false; end if;
      v_text := v_value #>> '{}';
      if v_rule ? 'n' and char_length(btrim(v_text)) < (v_rule ->> 'n')::integer
        then return false; end if;
      if v_rule ? 'x' and char_length(v_text) > (v_rule ->> 'x')::integer
        then return false; end if;
      if v_rule ? 'v'
        and not ((v_rule -> 'v') @> jsonb_build_array(v_text))
        then return false; end if;
    elsif v_type = 'string-or-string-list' then
      if jsonb_typeof(v_value) = 'string' then
        v_text := v_value #>> '{}';
        if v_rule ? 'i' and char_length(v_text) > (v_rule ->> 'i')::integer
          then return false; end if;
        if v_rule ? 'v'
          and not ((v_rule -> 'v') @> jsonb_build_array(v_text))
          then return false; end if;
      elsif jsonb_typeof(v_value) = 'array' then
        if v_rule ? 'm'
          and jsonb_array_length(v_value) > (v_rule ->> 'm')::integer
          then return false; end if;
        if exists (
          select 1
            from jsonb_array_elements(v_value) as item(value)
           where jsonb_typeof(item.value) <> 'string'
              or (
                v_rule ? 'i'
                and char_length(item.value #>> '{}')
                  > (v_rule ->> 'i')::integer
              )
              or (
                v_rule ? 'v'
                and not ((v_rule -> 'v') @> jsonb_build_array(
                  item.value #>> '{}'
                ))
              )
        ) then return false; end if;
      else
        return false;
      end if;
    else
      return false;
    end if;
  end loop;
  return true;
exception when others then
  return false;
end;

_custom_content_head_valid():
begin
  if new.head_revision_id is not null and not exists (
    select 1
      from public.custom_content_revisions revision
     where revision.id = new.head_revision_id
       and revision.owner_id = new.owner_id
       and revision.definition_id = new.id
  ) then
    raise exception 'definition head must reference its own revision'
      using errcode = '23503';
  end if;
  return new;
end;

_content_pack_active_valid():
begin
  if new.active_pack_version is null then return new; end if;
  if not exists (
    select 1
      from public.content_pack_versions version
     where version.owner_id = new.owner_id
       and version.pack_id = new.pack_id
       and version.pack_version = new.active_pack_version
       and version.manifest_hash = new.active_manifest_hash
  ) then
    raise exception 'active pack pointer must reference its exact manifest'
      using errcode = '23503';
  end if;
  return new;
end;

_content_environment_valid(p_environment:
declare
  v_core jsonb;
  v_tunables jsonb;
  v_key text;
  v_value jsonb;
begin
  if jsonb_typeof(p_environment) is distinct from 'object'
    or not (
      p_environment ?& array[
        'schemaVersion','environmentId','environmentRevisionId',
        'revisionNumber','source','packVersions','directDefinitions',
        'tunables','visualSelection','environmentHash','createdAt'
      ]
    )
    or (
      p_environment - array[
        'schemaVersion','environmentId','environmentRevisionId',
        'revisionNumber','source','packVersions','directDefinitions',
        'tunables','visualSelection','environmentHash','createdAt'
      ]
    ) <> '{}'::jsonb
    or jsonb_typeof(p_environment -> 'schemaVersion') <> 'number'
    or p_environment ->> 'schemaVersion' is distinct from '1'
    or nullif(btrim(p_environment ->> 'environmentId'), '') is null
    or char_length(p_environment ->> 'environmentId') > 240
    or p_environment ->> 'environmentId'
      <> btrim(p_environment ->> 'environmentId')
    or nullif(btrim(p_environment ->> 'environmentRevisionId'), '') is null
    or char_length(p_environment ->> 'environmentRevisionId') > 240
    or p_environment ->> 'environmentRevisionId'
      <> btrim(p_environment ->> 'environmentRevisionId')
    or jsonb_typeof(p_environment -> 'revisionNumber') <> 'number'
    or coalesce(p_environment ->> 'revisionNumber', '') !~ '^[1-9][0-9]*$'
    or jsonb_typeof(p_environment -> 'source') <> 'string'
    or nullif(btrim(p_environment ->> 'source'), '') is null
    or char_length(p_environment ->> 'source') > 240
    or p_environment ->> 'source' <> btrim(p_environment ->> 'source')
    or jsonb_typeof(p_environment -> 'packVersions') is distinct from 'array'
    or jsonb_array_length(p_environment -> 'packVersions') > 64
    or jsonb_typeof(p_environment -> 'directDefinitions') is distinct from 'array'
    or jsonb_array_length(p_environment -> 'directDefinitions') > 2000
    or jsonb_typeof(p_environment -> 'tunables') is distinct from 'object'
    or jsonb_typeof(p_environment -> 'visualSelection') is distinct from 'object'
    -- No environment-wide visual selection has a renderer consumer yet. The
    -- client registry is deliberately empty; SQL mirrors that fail-closed
    -- contract until a registered ASCII key/value is implemented end to end.
    or p_environment -> 'visualSelection' <> '{}'::jsonb
    or coalesce(p_environment ->> 'environmentHash', '')
      !~ '^[0-9a-f]{64}$'
    or not (
      jsonb_typeof(p_environment -> 'createdAt') = 'null'
      or (
        jsonb_typeof(p_environment -> 'createdAt') = 'string'
        and nullif(btrim(p_environment ->> 'createdAt'), '') is not null
        and char_length(p_environment ->> 'createdAt') <= 100
      )
    )
  then
    return false;
  end if;

  if exists (
    select 1
      from jsonb_array_elements(p_environment -> 'packVersions')
        with ordinality as item(value, ordinal)
     where jsonb_typeof(item.value) <> 'object'
        or not (
          item.value ?& array[
            'packId','packVersionId','manifestHash','order'
          ]
        )
        or (
          item.value - array[
            'packId','packVersionId','manifestHash','order'
          ]
        ) <> '{}'::jsonb
        or nullif(btrim(item.value ->> 'packId'), '') is null
        or char_length(item.value ->> 'packId') > 240
        or item.value ->> 'packId' <> btrim(item.value ->> 'packId')
        or nullif(btrim(item.value ->> 'packVersionId'), '') is null
        or char_length(item.value ->> 'packVersionId') > 240
        or item.value ->> 'packVersionId'
          <> btrim(item.value ->> 'packVersionId')
        or coalesce(item.value ->> 'manifestHash', '')
          !~ '^[0-9a-f]{64}$'
        or jsonb_typeof(item.value -> 'order') <> 'number'
        or coalesce(item.value ->> 'order', '') !~ '^[0-9]+$'
        or (item.value ->> 'order')::integer <> item.ordinal - 1
  ) then return false; end if;

  if (
    select count(distinct item.value ->> 'packId')
      from jsonb_array_elements(p_environment -> 'packVersions')
        as item(value)
  ) <> jsonb_array_length(p_environment -> 'packVersions')
  then return false; end if;

  if exists (
    select 1
      from jsonb_array_elements(p_environment -> 'directDefinitions')
        as item(value)
     where jsonb_typeof(item.value) <> 'object'
        or not (
          item.value ?& array[
            'definitionId','revisionId','contentHash','category'
          ]
        )
        or (
          item.value - array[
            'definitionId','revisionId','contentHash','category'
          ]
        ) <> '{}'::jsonb
        or nullif(btrim(item.value ->> 'definitionId'), '') is null
        or char_length(item.value ->> 'definitionId') > 240
        or item.value ->> 'definitionId'
          <> btrim(item.value ->> 'definitionId')
        or nullif(btrim(item.value ->> 'revisionId'), '') is null
        or char_length(item.value ->> 'revisionId') > 240
        or item.value ->> 'revisionId'
          <> btrim(item.value ->> 'revisionId')
        or coalesce(item.value ->> 'contentHash', '')
          !~ '^[0-9a-f]{64}$'
        or item.value ->> 'category' not in (
          'institutions','services','resources','stressors',
          'tradeGoods','factions','deities','traditions','supplyChains'
        )
  ) then return false; end if;

  if (
    select count(distinct item.value ->> 'definitionId')
      from jsonb_array_elements(p_environment -> 'directDefinitions')
        as item(value)
  ) <> jsonb_array_length(p_environment -> 'directDefinitions')
  then return false; end if;

  if not public._reviewed_supply_chain_text_valid(
       p_environment -> 'environmentId', 240, false
     )
    or not public._reviewed_supply_chain_text_valid(
      p_environment -> 'environmentRevisionId', 240, false
    )
    or not public._reviewed_supply_chain_text_valid(
      p_environment -> 'source', 240, false
    )
    or not public._reviewed_supply_chain_text_valid(
      p_environment -> 'createdAt', 100, true
    )
    or (p_environment ->> 'revisionNumber')::numeric > 2147483647
    or jsonb_typeof(p_environment -> 'environmentHash')
      is distinct from 'string'
    or exists (
      select 1
        from jsonb_array_elements(p_environment -> 'packVersions') item(value)
       where not public._reviewed_supply_chain_text_valid(
               item.value -> 'packId', 240, false
             )
          or not public._reviewed_supply_chain_text_valid(
               item.value -> 'packVersionId', 240, false
             )
          or jsonb_typeof(item.value -> 'manifestHash')
            is distinct from 'string'
    )
    or exists (
      select 1
        from jsonb_array_elements(
          p_environment -> 'directDefinitions'
        ) item(value)
       where not public._reviewed_supply_chain_text_valid(
               item.value -> 'definitionId', 240, false
             )
          or not public._reviewed_supply_chain_text_valid(
               item.value -> 'revisionId', 240, false
             )
          or jsonb_typeof(item.value -> 'contentHash')
            is distinct from 'string'
    )
  then
    return false;
  end if;
  v_tunables := p_environment -> 'tunables';
  for v_key, v_value in select * from jsonb_each(v_tunables) loop
    if v_key = 'magicExists' then
      if jsonb_typeof(v_value) <> 'boolean' then return false; end if;
    elsif v_key in (
      'priorityEconomy','priorityMilitary','priorityMagic',
      'priorityReligion','priorityCriminal'
    ) then
      if jsonb_typeof(v_value) <> 'number'
        or (v_value #>> '{}') !~ '^(0|[1-9][0-9]?|100)$'
      then return false; end if;
    else
      return false;
    end if;
  end loop;

  v_core := jsonb_build_object(
    'schemaVersion', 1,
    'environmentId', p_environment -> 'environmentId',
    'environmentRevisionId', p_environment -> 'environmentRevisionId',
    'revisionNumber', p_environment -> 'revisionNumber',
    'source', p_environment -> 'source',
    'packVersions', p_environment -> 'packVersions',
    'directDefinitions', p_environment -> 'directDefinitions',
    'tunables', p_environment -> 'tunables',
    'visualSelection', p_environment -> 'visualSelection'
  );
  return public._content_sha256(v_core)
    = p_environment ->> 'environmentHash';
exception when others then
  return false;
end;

_content_uuid(p_value text):
begin
  if p_value is null
    or p_value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  then
    return null;
  end if;
  return p_value::uuid;
end;

_content_pack_manifest_valid(p_manifest:
declare
  v_bucket text;
  v_entry jsonb;
  v_authored jsonb;
  v_count integer := 0;
  v_top_keys text[] := array[
    'format','formatVersion','packId','packVersion','contentSchemaVersion',
    'name','description','authorship','license','source','compatibility',
    'dependencies','tunables','visualSelection','exportedAt','content',
    'manifestHash'
  ];
  v_buckets text[] := array[
    'institutions','services','resources','stressors',
    'tradeGoods','factions','deities','traditions'
  ];
  v_transport_keys text[] := array[
    'id','definitionId','revisionId','revisionNumber','contentHash',
    'createdAt','updatedAt','archivedAt','isCustom','_schemaVersion',
    'packEntryId','sourceDefinitionId','sourceRevisionId','commandReceipt'
  ];
begin
  if jsonb_typeof(p_manifest) is distinct from 'object'
    or not (p_manifest ?& v_top_keys)
    or (p_manifest - v_top_keys) <> '{}'::jsonb
    or p_manifest ->> 'format'
      is distinct from 'settlementforge.content-pack'
    or p_manifest ->> 'formatVersion' is distinct from '2'
    or p_manifest ->> 'contentSchemaVersion' is distinct from '1'
    or p_manifest ->> 'packId' is distinct from p_pack_id
    or p_manifest ->> 'packVersion' is distinct from p_pack_version
    or p_manifest ->> 'manifestHash' is distinct from p_manifest_hash
    or nullif(btrim(p_manifest ->> 'name'), '') is null
    or char_length(p_manifest ->> 'name') > 160
    or jsonb_typeof(p_manifest -> 'compatibility') is distinct from 'object'
    or (
      (p_manifest -> 'compatibility') - array[
        'minAppVersion','maxAppVersion',
        'minSimulationVersion','maxSimulationVersion'
      ]
    ) <> '{}'::jsonb
    or not (
      (p_manifest -> 'compatibility') ?& array[
        'minAppVersion','maxAppVersion',
        'minSimulationVersion','maxSimulationVersion'
      ]
    )
    or jsonb_typeof(p_manifest -> 'dependencies') is distinct from 'array'
    or jsonb_array_length(p_manifest -> 'dependencies') <> 0
    or jsonb_typeof(p_manifest -> 'tunables') is distinct from 'object'
    or jsonb_typeof(p_manifest -> 'visualSelection') is distinct from 'object'
    or coalesce(p_manifest ->> 'exportedAt', '')
      !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'
    or jsonb_typeof(p_manifest -> 'content') is distinct from 'object'
    or not ((p_manifest -> 'content') ?& v_buckets)
    or ((p_manifest -> 'content') - v_buckets) <> '{}'::jsonb
    or public._content_sha256(
      p_manifest - array['exportedAt','manifestHash']
    ) <> p_manifest_hash
  then
    return false;
  end if;

  foreach v_bucket in array v_buckets loop
    if jsonb_typeof(p_manifest #> array['content', v_bucket])
      is distinct from 'array'
    then
      return false;
    end if;
    for v_entry in
      select value
        from jsonb_array_elements(
          p_manifest #> array['content', v_bucket]
        )
    loop
      v_count := v_count + 1;
      if v_count > 1000
        or jsonb_typeof(v_entry) is distinct from 'object'
        or nullif(btrim(v_entry ->> 'packEntryId'), '') is null
        or char_length(v_entry ->> 'packEntryId') > 240
        or nullif(btrim(v_entry ->> 'sourceDefinitionId'), '') is null
        or char_length(v_entry ->> 'sourceDefinitionId') > 240
        or nullif(btrim(v_entry ->> 'sourceRevisionId'), '') is null
        or char_length(v_entry ->> 'sourceRevisionId') > 240
        or coalesce(v_entry ->> 'contentHash', '')
          !~ '^[0-9a-f]{64}$'
      then
        return false;
      end if;
      v_authored := v_entry - v_transport_keys;
      if not public._custom_content_record_valid(v_bucket, v_authored)
        or public._content_sha256(jsonb_build_object(
          'schemaVersion', 1,
          'category', v_bucket,
          'data', v_authored
        )) <> v_entry ->> 'contentHash'
      then
        return false;
      end if;
    end loop;
  end loop;

  if v_count = 0
    or (
      select count(distinct entry.value ->> 'packEntryId')
        from jsonb_each(p_manifest -> 'content') bucket
        cross join lateral jsonb_array_elements(bucket.value) entry(value)
    ) <> v_count
    or (
      select count(distinct entry.value ->> 'localUid')
        from jsonb_each(p_manifest -> 'content') bucket
        cross join lateral jsonb_array_elements(bucket.value) entry(value)
       where entry.value ->> 'localUid' is not null
    ) <> (
      select count(*)
        from jsonb_each(p_manifest -> 'content') bucket
        cross join lateral jsonb_array_elements(bucket.value) entry(value)
       where entry.value ->> 'localUid' is not null
    )
  then
    return false;
  end if;
  return true;
exception when others then
  return false;
end;

_content_pack_import_data(p_manifest jso:
declare
  v_entry jsonb;
  v_data jsonb;
  v_field text;
  v_value jsonb;
  v_ref text;
  v_source_entry_id text;
  v_destination_ref text;
  v_rewritten jsonb;
  v_transport_keys text[] := array[
    'id','definitionId','revisionId','revisionNumber','contentHash',
    'createdAt','updatedAt','archivedAt','isCustom','_schemaVersion',
    'packEntryId','sourceDefinitionId','sourceRevisionId','commandReceipt'
  ];
  v_dependency_fields text[] := array[
    'produces','requires','subsumes','providedBy','yields','enables',
    'disablesInstitutions','disablesGoods','requiredInstitution',
    'requiredResources','controls','rivals'
  ];
begin
  select entry.value
    into v_entry
    from jsonb_each(p_manifest -> 'content') bucket
    cross join lateral jsonb_array_elements(bucket.value) entry(value)
   where entry.value ->> 'packEntryId' = p_pack_entry_id;
  if not found then return null; end if;

  v_data := v_entry - v_transport_keys;
  v_data := jsonb_set(
    v_data,
    '{localUid}',
    to_jsonb(
      'lu_pack_' || substring(public._content_sha256(
        jsonb_build_object(
          'packId', p_manifest ->> 'packId',
          'packEntryId', p_pack_entry_id
        )
      ) from 1 for 24)
    ),
    true
  );

  foreach v_field in array v_dependency_fields loop
    if not (v_data ? v_field) then continue; end if;
    v_value := v_data -> v_field;
    if jsonb_typeof(v_value) = 'string' then
      v_ref := v_data ->> v_field;
      if left(v_ref, 7) = 'custom:' then
        select entry.value ->> 'packEntryId'
          into v_source_entry_id
          from jsonb_each(p_manifest -> 'content') bucket
          cross join lateral jsonb_array_elements(bucket.value) entry(value)
         where entry.value ->> 'localUid' = substring(v_ref from 8);
        if not found then return null; end if;
        v_destination_ref := 'custom:lu_pack_' || substring(
          public._content_sha256(jsonb_build_object(
            'packId', p_manifest ->> 'packId',
            'packEntryId', v_source_entry_id
          )) from 1 for 24
        );
        v_data := jsonb_set(
          v_data, array[v_field], to_jsonb(v_destination_ref), false
        );
      end if;
    elsif jsonb_typeof(v_value) = 'array' then
      select coalesce(jsonb_agg(
        case
          when jsonb_typeof(item.value) = 'string'
            and left(item.value #>> '{}', 7) = 'custom:'
          then (
            select case
              when source_entry.value is null then null
              else to_jsonb(
                'custom:lu_pack_' || substring(
                  public._content_sha256(jsonb_build_object(
                    'packId', p_manifest ->> 'packId',
                    'packEntryId',
                    source_entry.value ->> 'packEntryId'
                  )) from 1 for 24
                )
              )
            end
              from (
                select entry.value
                  from jsonb_each(p_manifest -> 'content') bucket
                  cross join lateral jsonb_array_elements(
                    bucket.value
                  ) entry(value)
                 where entry.value ->> 'localUid'
                   = substring(item.value #>> '{}' from 8)
              ) source_entry
          )
          else item.value
        end
        order by item.ordinal
      ), '[]'::jsonb)
        into v_rewritten
        from jsonb_array_elements(v_value)
          with ordinality item(value, ordinal);
      if exists (
        select 1
          from jsonb_array_elements(v_rewritten) item(value)
         where item.value = 'null'::jsonb
      ) then
        return null;
      end if;
      v_data := jsonb_set(v_data, array[v_field], v_rewritten, false);
    end if;
  end loop;
  return v_data;
exception when others then
  return null;
end;

_apply_custom_content_command_authorable:
declare
  v_uid uuid := auth.uid();
  v_kind text;
  v_fingerprint text;
  v_claim jsonb;
  v_now timestamptz := clock_timestamp();
  v_entry jsonb;
  v_ordinal integer;
  v_definition_id uuid;
  v_expected_revision_id uuid;
  v_revision_id uuid;
  v_parent_revision_id uuid;
  v_revision_no integer;
  v_local_uid text;
  v_data jsonb;
  v_content_hash text;
  v_definition public.custom_content_definitions%rowtype;
  v_revision public.custom_content_revisions%rowtype;
  v_existing boolean;
  v_reason text := null;
  v_failure_status text := 'failed';
  v_items jsonb := '[]'::jsonb;
  v_archived_items jsonb := '[]'::jsonb;
  v_per_entry jsonb := '[]'::jsonb;
  v_result jsonb;
  v_response jsonb;
  v_pack jsonb;
  v_pack_manifest jsonb;
  v_pack_id text;
  v_pack_version text;
  v_pack_hash text;
  v_pack_import_hash text;
  v_pack_existing_hash text;
  v_pack_existing_import_hash text;
  v_expected_pack_version text;
  v_expected_pack_hash text;
  v_active_pack_version text;
  v_active_pack_hash text;
  v_pack_entry_count integer;
  v_prior_pack_revision_id uuid;
  v_environment jsonb;
  v_environment_id text;
  v_environment_revision_id text;
  v_environment_hash text;
  v_expected_environment_revision_id text;
  v_active_environment_revision_id text;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if p_expected_owner is null or p_expected_owner <> v_uid then
    raise exception 'custom-content owner changed' using errcode = '42501';
  end if;
  if not public.account_is_active(v_uid)
    or not public.current_user_has_premium_access()
  then
    raise exception 'active premium account required' using errcode = '42501';
  end if;
  if nullif(btrim(p_command_id), '') is null
    or char_length(p_command_id) > 240
    or coalesce(p_preview_fingerprint, '') !~ '^[0-9a-f]{64}$'
    or jsonb_typeof(p_plan) is distinct from 'object'
    or octet_length(p_plan::text) > 4194304
  then
    raise exception 'invalid custom-content command envelope'
      using errcode = '22023';
  end if;

  v_kind := p_plan ->> 'kind';
  if not (
      p_plan ?& array[
        'schemaVersion','kind','definitionId','expectedHeadRevisionId',
        'expectedActiveEnvironmentRevisionId','pack','environment','entries'
      ]
    )
    or (
      p_plan - array[
        'schemaVersion','kind','definitionId','expectedHeadRevisionId',
        'expectedActiveEnvironmentRevisionId','pack','environment','entries'
      ]
    ) <> '{}'::jsonb
    or jsonb_typeof(p_plan -> 'schemaVersion') <> 'number'
    or p_plan ->> 'schemaVersion' is distinct from '1'
    or jsonb_typeof(p_plan -> 'kind') <> 'string'
    or jsonb_typeof(p_plan -> 'definitionId') not in ('null', 'string')
    or jsonb_typeof(p_plan -> 'expectedHeadRevisionId')
      not in ('null', 'string')
    or jsonb_typeof(p_plan -> 'expectedActiveEnvironmentRevisionId')
      not in ('null', 'string')
    or jsonb_typeof(p_plan -> 'pack') not in ('null', 'object')
    or jsonb_typeof(p_plan -> 'environment') not in ('null', 'object')
    or v_kind not in (
      'content.definition.create-revision',
      'content.definition.archive',
      'content.definition.restore',
      'content.pack.import',
      'content.environment.migrate',
      'content.definition.mass-update'
    )
    or jsonb_typeof(coalesce(p_plan -> 'entries', '[]'::jsonb))
      is distinct from 'array'
    or jsonb_array_length(coalesce(p_plan -> 'entries', '[]'::jsonb)) > 1000
  then
    raise exception 'unsupported custom-content command plan'
      using errcode = '22023';
  end if;

  if v_kind in (
    'content.definition.create-revision',
    'content.definition.mass-update',
    'content.pack.import'
  ) and jsonb_array_length(p_plan -> 'entries') = 0 then
    raise exception 'custom-content command requires entries'
      using errcode = '22023';
  end if;

  if (
      v_kind not in (
        'content.definition.archive',
        'content.definition.restore'
      )
      and (
        p_plan ->> 'definitionId' is not null
        or p_plan ->> 'expectedHeadRevisionId' is not null
      )
    )
    or (
      v_kind <> 'content.environment.migrate'
      and (
        p_plan ->> 'expectedActiveEnvironmentRevisionId' is not null
        or p_plan ->> 'environment' is not null
      )
    )
    or (
      v_kind <> 'content.pack.import'
      and p_plan ->> 'pack' is not null
    )
    or (
      v_kind not in (
        'content.definition.create-revision',
        'content.definition.mass-update',
        'content.pack.import'
      )
      and jsonb_array_length(p_plan -> 'entries') <> 0
    )
  then
    raise exception 'custom-content command carries fields its kind does not consume'
      using errcode = '22023';
  end if;

  for v_entry in
    select value from jsonb_array_elements(p_plan -> 'entries')
  loop
    if jsonb_typeof(v_entry) is distinct from 'object'
      or not (
        v_entry ?& array[
          'definitionId','expectedHeadRevisionId','packEntryId',
          'category','data'
        ]
      )
      or (
        v_entry - array[
          'definitionId','expectedHeadRevisionId','packEntryId',
          'category','data'
        ]
      ) <> '{}'::jsonb
      or jsonb_typeof(v_entry -> 'definitionId') not in ('null', 'string')
      or jsonb_typeof(v_entry -> 'expectedHeadRevisionId')
        not in ('null', 'string')
      or jsonb_typeof(v_entry -> 'packEntryId') not in ('null', 'string')
      or jsonb_typeof(v_entry -> 'category') <> 'string'
      or not public._custom_content_record_valid(
        v_entry ->> 'category',
        v_entry -> 'data'
      )
      or (
        v_entry ->> 'definitionId' is not null
        and public._content_uuid(v_entry ->> 'definitionId') is null
      )
      or (
        v_entry ->> 'expectedHeadRevisionId' is not null
        and public._content_uuid(
          v_entry ->> 'expectedHeadRevisionId'
        ) is null
      )
      or (
        v_kind = 'content.pack.import'
        and (
          nullif(btrim(v_entry ->> 'packEntryId'), '') is null
          or char_length(v_entry ->> 'packEntryId') > 240
          or v_entry ->> 'packEntryId' <> btrim(v_entry ->> 'packEntryId')
        )
      )
      or (
        v_kind <> 'content.pack.import'
        and v_entry ->> 'packEntryId' is not null
      )
      or (
        v_kind in (
          'content.definition.create-revision',
          'content.definition.mass-update'
        )
        and public._content_uuid(v_entry ->> 'definitionId') is null
      )
    then
      raise exception 'custom-content entry failed manifest admission'
        using errcode = '22023';
    end if;
  end loop;

  if (
    select count(*)
      from jsonb_array_elements(p_plan -> 'entries') as item(value)
     where item.value ->> 'definitionId' is not null
  ) <> (
    select count(distinct item.value ->> 'definitionId')
      from jsonb_array_elements(p_plan -> 'entries') as item(value)
     where item.value ->> 'definitionId' is not null
  ) then
    raise exception 'definition ids must be unique inside one command'
      using errcode = '22023';
  end if;

  if (
    select count(*)
      from jsonb_array_elements(p_plan -> 'entries') as item(value)
     where item.value #>> '{data,localUid}' is not null
  ) <> (
    select count(distinct item.value #>> '{data,localUid}')
      from jsonb_array_elements(p_plan -> 'entries') as item(value)
     where item.value #>> '{data,localUid}' is not null
  ) then
    raise exception 'local content references must be unique inside one command'
      using errcode = '22023';
  end if;

  if v_kind in (
    'content.definition.archive',
    'content.definition.restore'
  ) then
    v_definition_id := public._content_uuid(p_plan ->> 'definitionId');
    v_expected_revision_id := public._content_uuid(
      p_plan ->> 'expectedHeadRevisionId'
    );
    if v_definition_id is null or v_expected_revision_id is null then
      raise exception 'lifecycle command requires definition and expected head'
        using errcode = '22023';
    end if;
  end if;

  if v_kind = 'content.pack.import' then
    v_pack := p_plan -> 'pack';
    v_pack_id := v_pack ->> 'packId';
    v_pack_version := v_pack ->> 'packVersion';
    v_pack_hash := v_pack ->> 'manifestHash';
    v_pack_manifest := v_pack -> 'manifest';
    v_pack_import_hash := v_pack ->> 'importPlanHash';
    v_expected_pack_version := v_pack ->> 'expectedActivePackVersion';
    v_expected_pack_hash := v_pack ->> 'expectedActiveManifestHash';
    if jsonb_typeof(v_pack) is distinct from 'object'
      or not (
        v_pack ?& array[
          'packId','packVersion','name','manifestHash',
          'expectedActivePackVersion','expectedActiveManifestHash',
          'importPlanHash','manifest'
        ]
      )
      or (
        v_pack - array[
          'packId','packVersion','name','manifestHash',
          'expectedActivePackVersion','expectedActiveManifestHash',
          'importPlanHash','manifest'
        ]
      ) <> '{}'::jsonb
      or jsonb_typeof(v_pack -> 'packId') <> 'string'
      or jsonb_typeof(v_pack -> 'packVersion') <> 'string'
      or jsonb_typeof(v_pack -> 'name') <> 'string'
      or jsonb_typeof(v_pack -> 'manifestHash') <> 'string'
      or jsonb_typeof(v_pack -> 'manifest') <> 'object'
      or jsonb_typeof(v_pack -> 'expectedActivePackVersion')
        not in ('null', 'string')
      or jsonb_typeof(v_pack -> 'expectedActiveManifestHash')
        not in ('null', 'string')
      or jsonb_typeof(v_pack -> 'importPlanHash') <> 'string'
      or nullif(btrim(v_pack_id), '') is null
      or char_length(v_pack_id) > 240
      or v_pack_id <> btrim(v_pack_id)
      or nullif(btrim(v_pack_version), '') is null
      or char_length(v_pack_version) > 120
      or v_pack_version <> btrim(v_pack_version)
      or coalesce(v_pack_hash, '') !~ '^[0-9a-f]{64}$'
      or nullif(btrim(v_pack ->> 'name'), '') is null
      or char_length(v_pack ->> 'name') > 240
      or v_pack ->> 'name' <> btrim(v_pack ->> 'name')
      or not public._content_pack_manifest_valid(
        v_pack_manifest,
        v_pack_id,
        v_pack_version,
        v_pack_hash
      )
    then
      raise exception 'pack command requires a valid immutable version'
        using errcode = '22023';
    end if;
    if (
      (v_expected_pack_version is null) <> (v_expected_pack_hash is null)
      or (
        v_expected_pack_hash is not null
        and v_expected_pack_hash !~ '^[0-9a-f]{64}$'
      )
      or (
        v_expected_pack_version is not null
        and v_expected_pack_version <> btrim(v_expected_pack_version)
      )
    ) then
      raise exception 'pack command expected-active identity is invalid'
        using errcode = '22023';
    end if;
    if (
      coalesce(v_pack_import_hash, '') !~ '^[0-9a-f]{64}$'
      or v_pack_import_hash <> public._content_sha256(
        jsonb_build_object(
          'schemaVersion', 1,
          'packId', v_pack_id,
          'packVersion', v_pack_version,
          'entries', (
            select coalesce(jsonb_agg(
              jsonb_build_object(
                'packEntryId', item.value -> 'packEntryId',
                'category', item.value -> 'category',
                'data', item.value -> 'data'
              )
              order by item.ordinal
            ), '[]'::jsonb)
              from jsonb_array_elements(p_plan -> 'entries')
                with ordinality as item(value, ordinal)
          )
        )
      )
    ) then
      raise exception 'pack normalized import plan hash is invalid'
        using errcode = '22023';
    end if;
    if (
      select count(distinct value ->> 'packEntryId')
        from jsonb_array_elements(p_plan -> 'entries')
    ) <> jsonb_array_length(p_plan -> 'entries') then
      raise exception 'pack entry ids must be unique'
        using errcode = '22023';
    end if;
    if exists (
      select 1
        from jsonb_array_elements(p_plan -> 'entries') item(value)
       where public._content_pack_import_data(
           v_pack_manifest,
           item.value ->> 'packEntryId'
         ) is distinct from item.value -> 'data'
          or not exists (
            select 1
              from jsonb_each(v_pack_manifest -> 'content') bucket
              cross join lateral jsonb_array_elements(
                bucket.value
              ) manifest_entry(value)
             where manifest_entry.value ->> 'packEntryId'
               = item.value ->> 'packEntryId'
               and bucket.key = item.value ->> 'category'
          )
    ) or (
      select count(*)
        from jsonb_each(v_pack_manifest -> 'content') bucket
        cross join lateral jsonb_array_elements(bucket.value) entry(value)
    ) <> jsonb_array_length(p_plan -> 'entries')
    then
      raise exception 'pack manifest does not match normalized import entries'
        using errcode = '22023';
    end if;
  end if;

  if v_kind = 'content.environment.migrate' then
    v_environment := p_plan -> 'environment';
    v_expected_environment_revision_id :=
      p_plan ->> 'expectedActiveEnvironmentRevisionId';
    if not public._content_environment_valid(v_environment) then
      raise exception 'content environment failed admission'
        using errcode = '22023';
    elsif nullif(btrim(v_expected_environment_revision_id), '') is null
      or char_length(v_expected_environment_revision_id) > 240
      or v_expected_environment_revision_id
        <> btrim(v_expected_environment_revision_id)
    then
      raise exception 'content environment requires an expected active revision'
        using errcode = '22023';
    end if;
    v_environment_id := v_environment ->> 'environmentId';
    v_environment_revision_id :=
      v_environment ->> 'environmentRevisionId';
    v_environment_hash := v_environment ->> 'environmentHash';
  end if;

  v_fingerprint := public._content_sha256(p_plan);
  if v_fingerprint <> p_preview_fingerprint then
    raise exception 'custom-content preview fingerprint mismatch'
      using errcode = '22023';
  end if;

  -- One account has one custom-content constitution. Take this lock before the
  -- caller-selected command row so generic, reviewed, and archive writers share
  -- one global order. The narrower locks below still document each CAS scope.
  perform pg_advisory_xact_lock(
    hashtext('custom-content-owner'),
    hashtext(v_uid::text)
  );

  v_claim := public.claim_application_command(
    v_uid,
    p_command_id,
    v_fingerprint,
    v_kind,
    case
      when v_kind in (
        'content.definition.archive',
        'content.definition.restore'
      ) then v_definition_id
      else null
    end,
    null
  );

  if v_claim ->> 'status' = 'conflict' then
    return v_claim;
  end if;
  if v_claim ->> 'phase' = 'finalized'
    and v_claim -> 'receipt' is not null
  then
    return (v_claim -> 'receipt') || jsonb_build_object('replayed', true);
  end if;
  if v_claim ->> 'status' = 'reconcile-required' then
    return jsonb_build_object(
      'status', 'reconcile-required',
      'reason', coalesce(v_claim ->> 'reason', 'command_requires_reconciliation'),
      'replayed', true,
      'fingerprint', v_fingerprint
    );
  end if;

  -- Immutable pack version identity is checked before any definition write.
  if v_kind = 'content.pack.import' then
    perform pg_advisory_xact_lock(
      hashtext(
        'custom-content-pack:' || v_uid::text || ':' || coalesce(v_pack_id, '')
      )
    );
    select pack.active_pack_version, pack.active_manifest_hash
      into v_active_pack_version, v_active_pack_hash
      from public.content_packs pack
     where pack.owner_id = v_uid
       and pack.pack_id = v_pack_id
     for update;
    if (
      v_active_pack_version is distinct from v_expected_pack_version
      or v_active_pack_hash is distinct from v_expected_pack_hash
    ) then
      v_reason := 'pack_preview_stale';
      v_failure_status := 'stale';
    end if;

    -- Lock every already-mapped definition before validating reviewed heads.
    -- This also protects the same-version early-return path: a concurrent manual
    -- edit cannot advance a head after validation and before the response is
    -- projected.
    if v_reason is null then
      perform definition.id
        from jsonb_array_elements(p_plan -> 'entries') as requested(value)
        join public.content_pack_entry_definitions mapping
          on mapping.owner_id = v_uid
         and mapping.pack_id = v_pack_id
         and mapping.pack_entry_id = requested.value ->> 'packEntryId'
        join public.custom_content_definitions definition
          on definition.owner_id = mapping.owner_id
         and definition.id = mapping.definition_id
       order by definition.id
       for update of definition;
    end if;

    -- Pack-entry identity is stable across releases. The reviewed definition id
    -- must describe the mapping the RPC will actually mutate; a new entry must
    -- explicitly carry null rather than smuggling an unrelated definition id.
    if v_reason is null and exists (
      select 1
        from jsonb_array_elements(p_plan -> 'entries') as requested(value)
        left join public.content_pack_entry_definitions mapping
          on mapping.owner_id = v_uid
         and mapping.pack_id = v_pack_id
         and mapping.pack_entry_id = requested.value ->> 'packEntryId'
       where public._content_uuid(
           requested.value ->> 'definitionId'
         ) is distinct from mapping.definition_id
    ) then
      v_reason := 'pack_mapping_definition_changed';
      v_failure_status := 'stale';
    end if;

    -- Even a same-version no-op must not return a head the owner did not review.
    if v_reason is null and exists (
      select 1
        from jsonb_array_elements(p_plan -> 'entries') as requested(value)
        join public.content_pack_entry_definitions mapping
          on mapping.owner_id = v_uid
         and mapping.pack_id = v_pack_id
         and mapping.pack_entry_id = requested.value ->> 'packEntryId'
        join public.custom_content_definitions definition
          on definition.owner_id = mapping.owner_id
         and definition.id = mapping.definition_id
       where public._content_uuid(
           requested.value ->> 'expectedHeadRevisionId'
         ) is distinct from definition.head_revision_id
    ) then
      v_reason := 'definition_head_changed';
      v_failure_status := 'stale';
    end if;

    select version.manifest_hash, version.import_plan_hash
      into v_pack_existing_hash, v_pack_existing_import_hash
      from public.content_pack_versions version
     where version.owner_id = v_uid
       and version.pack_id = v_pack_id
       and version.pack_version = v_pack_version
     for update;
    if v_reason is null and found and (
      v_pack_existing_hash <> v_pack_hash
      or v_pack_existing_import_hash <> v_pack_import_hash
    ) then
      v_reason := 'pack_version_immutable';
    elsif v_reason is null
      and found
      and v_active_pack_version is distinct from v_pack_version
    then
      v_reason := 'pack_version_already_installed';
      v_failure_status := 'stale';
    elsif v_reason is null
      and found
    then
      select count(*)
        into v_pack_entry_count
        from public.content_pack_version_entries entry
       where entry.owner_id = v_uid
         and entry.pack_id = v_pack_id
         and entry.pack_version = v_pack_version;
      -- Only a complete active installation is a no-op. An incomplete version
      -- cannot be manufactured through a separate publication command.
      if v_pack_entry_count = jsonb_array_length(p_plan -> 'entries') then
        select
          coalesce(jsonb_agg(
            public._custom_content_projection(definition, current_revision)
            order by entry.ordinal
          ), '[]'::jsonb),
          coalesce(jsonb_agg(jsonb_build_object(
            'definitionId', entry.definition_id,
            'revisionId', definition.head_revision_id,
            'status', 'unchanged',
            'category', entry.category,
            'packEntryId', entry.pack_entry_id
          ) order by entry.ordinal), '[]'::jsonb)
          into v_items, v_per_entry
          from public.content_pack_version_entries entry
          join public.custom_content_definitions definition
            on definition.owner_id = entry.owner_id
           and definition.id = entry.definition_id
          join public.custom_content_revisions current_revision
            on current_revision.id = definition.head_revision_id
         where entry.owner_id = v_uid
           and entry.pack_id = v_pack_id
           and entry.pack_version = v_pack_version;
        v_result := jsonb_build_object(
          'items', v_items,
          'archivedItems', '[]'::jsonb,
          'pack', v_pack,
          'environment', null,
          'perEntry', v_per_entry
        );
        v_response := jsonb_build_object(
          'ok', true,
          'status', 'applied',
          'commandId', p_command_id,
          'replayed', false,
          'fingerprint', v_fingerprint,
          'result', v_result,
          'perEntry', v_per_entry
        );
        if not public.finalize_application_command(
          v_uid, p_command_id, v_fingerprint, 'applied', v_response, null
        ) then
          raise exception 'custom-content command did not finalize'
            using errcode = '40001';
        end if;
        return v_response;
      else
        v_reason := 'pack_version_incomplete';
      end if;
    end if;
  end if;

  if v_kind = 'content.environment.migrate' then
    -- Different environment commands have different journal ids, so the
    -- application-command claim alone cannot serialize their expected-current
    -- checks. The owner-scoped advisory lock closes the absent-activation-row
    -- race as well as the ordinary update race.
    perform pg_advisory_xact_lock(
      hashtext('custom-content-environment:' || v_uid::text)
    );
    select activation.environment_revision_id
      into v_active_environment_revision_id
      from public.content_environment_activations activation
     where activation.owner_id = v_uid
     for update;
    if coalesce(
      v_active_environment_revision_id,
      'system:vanilla:v1'
    ) <> v_expected_environment_revision_id then
      v_reason := 'content_environment_preview_stale';
      v_failure_status := 'stale';
    end if;

    if v_reason is null and exists (
      select 1
        from jsonb_array_elements(v_environment -> 'packVersions')
          as requested(value)
       where not exists (
         select 1
           from public.content_pack_versions version
          where version.owner_id = v_uid
            and version.pack_id = requested.value ->> 'packId'
            and version.pack_version =
              requested.value ->> 'packVersionId'
            and version.manifest_hash =
              requested.value ->> 'manifestHash'
       )
    ) then
      v_reason := 'content_environment_pack_reference_unavailable';
      v_failure_status := 'stale';
    end if;

    -- A pack binding is semantic input, not decorative provenance. Every entry
    -- published by the exact immutable pack version must be represented by the
    -- same definition/revision/category tuple in the environment's canonical
    -- direct-definition set. A published pack version is never empty; accepting
    -- an empty closure would make its manifest decorative provenance again.
    -- Additional direct definitions remain valid.
    if v_reason is null and exists (
      select 1
        from jsonb_array_elements(v_environment -> 'packVersions')
          as requested_pack(value)
       where not exists (
         select 1
           from public.content_pack_version_entries pack_entry
          where pack_entry.owner_id = v_uid
            and pack_entry.pack_id =
              requested_pack.value ->> 'packId'
            and pack_entry.pack_version =
              requested_pack.value ->> 'packVersionId'
       )
    ) then
      v_reason := 'content_environment_pack_closure_mismatch';
      v_failure_status := 'stale';
    end if;

    if v_reason is null and exists (
      select 1
        from jsonb_array_elements(v_environment -> 'packVersions')
          as requested_pack(value)
        join public.content_pack_version_entries pack_entry
          on pack_entry.owner_id = v_uid
         and pack_entry.pack_id =
           requested_pack.value ->> 'packId'
         and pack_entry.pack_version =
           requested_pack.value ->> 'packVersionId'
       where not exists (
         select 1
           from jsonb_array_elements(
             v_environment -> 'directDefinitions'
           ) as requested_definition(value)
          where public._content_uuid(
              requested_definition.value ->> 'definitionId'
            ) = pack_entry.definition_id
            and public._content_uuid(
              requested_definition.value ->> 'revisionId'
            ) = pack_entry.revision_id
            and requested_definition.value ->> 'category' =
              pack_entry.category
       )
    ) then
      v_reason := 'content_environment_pack_closure_mismatch';
      v_failure_status := 'stale';
    end if;

    if v_reason is null and exists (
      select 1
        from jsonb_array_elements(v_environment -> 'directDefinitions')
          as requested(value)
       where public._content_uuid(
           requested.value ->> 'definitionId'
         ) is null
          or public._content_uuid(
            requested.value ->> 'revisionId'
          ) is null
          or not exists (
            select 1
              from public.custom_content_definitions definition
              join public.custom_content_revisions revision
                on revision.owner_id = definition.owner_id
               and revision.definition_id = definition.id
               and revision.id = public._content_uuid(
                 requested.value ->> 'revisionId'
               )
             where definition.owner_id = v_uid
               and definition.id = public._content_uuid(
                 requested.value ->> 'definitionId'
               )
               and definition.category =
                 requested.value ->> 'category'
               and revision.content_hash =
                 requested.value ->> 'contentHash'
          )
    ) then
      v_reason := 'content_environment_definition_reference_unavailable';
      v_failure_status := 'stale';
    end if;

    select revision.environment_hash
      into v_pack_existing_hash
      from public.content_environment_revisions revision
     where revision.owner_id = v_uid
       and revision.environment_revision_id = v_environment_revision_id
     for update;
    if v_reason is null
      and found
      and v_pack_existing_hash <> v_environment_hash
    then
      v_reason := 'environment_revision_immutable';
    elsif v_reason is null and exists (
      select 1
        from public.content_environment_revisions revision
       where revision.owner_id = v_uid
         and revision.environment_id = v_environment_id
         and revision.revision_no =
           (v_environment ->> 'revisionNumber')::integer
         and revision.environment_revision_id <> v_environment_revision_id
    ) then
      v_reason := 'environment_revision_number_conflict';
    end if;
  end if;

  -- Lock and compare every affected head before appending any revision.
  if v_reason is null and v_kind in (
    'content.definition.create-revision',
    'content.definition.mass-update',
    'content.pack.import'
  ) then
    for v_entry in
      -- Every command acquires multi-definition locks in the same codepoint
      -- order. Response/application order still follows the reviewed array
      -- below, but reversed mass-update previews cannot deadlock each other.
      select item.value
        from jsonb_array_elements(p_plan -> 'entries') as item(value)
       order by case
         when v_kind = 'content.pack.import'
           then item.value ->> 'packEntryId'
         else item.value ->> 'definitionId'
       end collate "C"
    loop
      if v_kind = 'content.pack.import' then
        select mapping.definition_id
          into v_definition_id
          from public.content_pack_entry_definitions mapping
         where mapping.owner_id = v_uid
           and mapping.pack_id = v_pack_id
           and mapping.pack_entry_id = v_entry ->> 'packEntryId'
         for update;
        if v_definition_id is not null then
          -- A release may omit an older entry and a later release may restore
          -- it. Compare against the latest pack-authored revision, not only the
          -- active release, so that omission is not mistaken for lost lineage.
          select version_entry.revision_id
            into v_prior_pack_revision_id
            from public.content_pack_version_entries version_entry
            join public.content_pack_versions version
              on version.owner_id = version_entry.owner_id
             and version.pack_id = version_entry.pack_id
             and version.pack_version = version_entry.pack_version
           where version_entry.owner_id = v_uid
             and version_entry.pack_id = v_pack_id
             and version_entry.pack_entry_id = v_entry ->> 'packEntryId'
           order by version.created_at desc,
                    version.pack_version collate "C" desc
           limit 1;
        else
          v_prior_pack_revision_id := null;
        end if;
      else
        v_definition_id := public._content_uuid(
          v_entry ->> 'definitionId'
        );
        if v_definition_id is null then
          raise exception 'definition id is required for direct revision writes'
            using errcode = '22023';
        end if;
        -- A row lock cannot serialize two concurrent creations of the same
        -- not-yet-existent definition. The stable advisory key closes that gap;
        -- once the first transaction commits, the second observes its new head
        -- and returns the ordinary stale-preview result.
        perform pg_advisory_xact_lock(hashtext(
          'custom-content-definition:'
            || v_uid::text || ':' || v_definition_id::text
        ));
      end if;

      v_existing := false;
      if v_definition_id is not null then
        select *
          into v_definition
          from public.custom_content_definitions definition
         where definition.owner_id = v_uid
           and definition.id = v_definition_id
         for update;
        v_existing := found;
      end if;

      if v_existing
        and v_definition.category is distinct from v_entry ->> 'category'
      then
        v_reason := 'definition_category_immutable';
        exit;
      elsif v_existing
        and v_entry #>> '{data,localUid}' is not null
        and v_definition.local_uid is distinct from
          v_entry #>> '{data,localUid}'
      then
        v_reason := 'definition_local_uid_immutable';
        exit;
      elsif v_existing and v_definition.archived_at is not null then
        v_reason := 'definition_archived';
        exit;
      elsif not v_existing
        and v_entry #>> '{data,localUid}' is not null
        and exists (
          select 1
            from public.custom_content_definitions other_definition
           where other_definition.owner_id = v_uid
             and other_definition.local_uid =
               v_entry #>> '{data,localUid}'
        )
      then
        v_reason := 'local_uid_unavailable';
        v_failure_status := 'stale';
        exit;
      elsif v_kind = 'content.pack.import'
        and v_existing
        and v_prior_pack_revision_id is null
      then
        v_reason := 'pack_mapping_revision_unavailable';
        v_failure_status := 'stale';
        exit;
      elsif v_kind = 'content.pack.import'
        and v_existing
        and public._content_uuid(
          v_entry ->> 'expectedHeadRevisionId'
        ) is null
      then
        v_reason := 'pack_preview_expected_head_required';
        v_failure_status := 'stale';
        exit;
      elsif v_kind = 'content.pack.import'
        and v_existing
        and v_definition.head_revision_id is distinct from
          v_prior_pack_revision_id
      then
        v_reason := 'pack_definition_head_changed';
        v_failure_status := 'stale';
        exit;
      elsif v_kind = 'content.pack.import'
        and v_existing
        and v_definition.head_revision_id is distinct from
          public._content_uuid(v_entry ->> 'expectedHeadRevisionId')
      then
        v_reason := 'definition_head_changed';
        v_failure_status := 'stale';
        exit;
      elsif v_kind <> 'content.pack.import' and v_existing
        and v_definition.head_revision_id is distinct from
          public._content_uuid(v_entry ->> 'expectedHeadRevisionId')
      then
        v_reason := 'definition_head_changed';
        v_failure_status := 'stale';
        exit;
      elsif v_kind <> 'content.pack.import' and not v_existing
        and v_entry ->> 'expectedHeadRevisionId' is not null
      then
        v_reason := 'definition_unavailable';
        v_failure_status := 'stale';
        exit;
      end if;
    end loop;
  end if;

  if v_reason is null and v_kind in (
    'content.definition.archive',
    'content.definition.restore'
  ) then
    select *
      into v_definition
      from public.custom_content_definitions definition
     where definition.owner_id = v_uid
       and definition.id = v_definition_id
     for update;
    if not found then
      v_reason := 'definition_unavailable';
      v_failure_status := 'stale';
    elsif v_definition.head_revision_id is distinct from v_expected_revision_id
    then
      v_reason := 'definition_head_changed';
      v_failure_status := 'stale';
    end if;
  end if;

  if v_reason is not null then
    v_result := jsonb_build_object(
      'items', '[]'::jsonb,
      'archivedItems', '[]'::jsonb,
      'pack', v_pack,
      'environment', v_environment,
      'perEntry', '[]'::jsonb
    );
    v_response := jsonb_build_object(
      'ok', false,
      'status', v_failure_status,
      'commandId', p_command_id,
      'reason', v_reason,
      'replayed', false,
      'fingerprint', v_fingerprint,
      'result', v_result,
      'perEntry', '[]'::jsonb
    );
    if not public.finalize_application_command(
      v_uid, p_command_id, v_fingerprint,
      v_failure_status, v_response, v_reason
    ) then
      raise exception 'custom-content command did not finalize'
        using errcode = '40001';
    end if;
    return v_response;
  end if;

  if v_kind = 'content.pack.import' then
    insert into public.content_packs (
      owner_id, pack_id, name, updated_at
    ) values (
      v_uid, v_pack_id, v_pack ->> 'name', v_now
    )
    on conflict (owner_id, pack_id) do update
      set name = excluded.name,
          updated_at = excluded.updated_at;
    insert into public.content_pack_versions (
      owner_id, pack_id, pack_version, manifest_hash, import_plan_hash,
      manifest, command_id, created_at
    ) values (
      v_uid, v_pack_id, v_pack_version, v_pack_hash, v_pack_import_hash,
      v_pack_manifest,
      p_command_id, v_now
    )
    on conflict (owner_id, pack_id, pack_version) do nothing;
  end if;

  if v_kind in (
    'content.definition.create-revision',
    'content.definition.mass-update',
    'content.pack.import'
  ) then
    for v_entry, v_ordinal in
      select value, (ordinal - 1)::integer
        from jsonb_array_elements(p_plan -> 'entries')
          with ordinality as item(value, ordinal)
    loop
      v_definition_id := null;
      if v_kind = 'content.pack.import' then
        select mapping.definition_id
          into v_definition_id
          from public.content_pack_entry_definitions mapping
         where mapping.owner_id = v_uid
           and mapping.pack_id = v_pack_id
           and mapping.pack_entry_id = v_entry ->> 'packEntryId'
         for update;
      else
        v_definition_id := public._content_uuid(
          v_entry ->> 'definitionId'
        );
      end if;

      v_existing := false;
      if v_definition_id is not null then
        select *
          into v_definition
          from public.custom_content_definitions definition
         where definition.owner_id = v_uid
           and definition.id = v_definition_id
         for update;
        v_existing := found;
      end if;

      if not v_existing then
        v_definition_id := coalesce(v_definition_id, gen_random_uuid());
        v_local_uid := coalesce(
          nullif(v_entry #>> '{data,localUid}', ''),
          'lu_' || replace(gen_random_uuid()::text, '-', '')
        );
        insert into public.custom_content_definitions (
          id, owner_id, category, local_uid, created_at, updated_at
        ) values (
          v_definition_id, v_uid, v_entry ->> 'category',
          v_local_uid, v_now, v_now
        );
        select *
          into strict v_definition
          from public.custom_content_definitions definition
         where definition.owner_id = v_uid
           and definition.id = v_definition_id;
        if v_kind = 'content.pack.import' then
          insert into public.content_pack_entry_definitions (
            owner_id, pack_id, pack_entry_id, definition_id, created_at
          ) values (
            v_uid, v_pack_id, v_entry ->> 'packEntryId',
            v_definition_id, v_now
          );
        end if;
      else
        v_local_uid := v_definition.local_uid;
      end if;

      v_data := jsonb_set(
        v_entry -> 'data',
        '{localUid}',
        to_jsonb(v_local_uid),
        true
      );
      v_content_hash := public._content_sha256(jsonb_build_object(
        'schemaVersion', 1,
        'category', v_entry ->> 'category',
        'data', v_data
      ));

      if v_definition.head_revision_id is not null then
        select *
          into strict v_revision
          from public.custom_content_revisions revision
         where revision.id = v_definition.head_revision_id;
      else
        v_revision.id := null;
      end if;

      if v_revision.id is not null
        and v_revision.content_hash = v_content_hash
      then
        v_revision_id := v_revision.id;
        v_revision_no := v_revision.revision_no;
        v_per_entry := v_per_entry || jsonb_build_array(
          jsonb_build_object(
            'definitionId', v_definition_id,
            'revisionId', v_revision_id,
            'status', 'unchanged',
            'category', v_entry ->> 'category',
            'packEntryId', v_entry ->> 'packEntryId'
          )
        );
      else
        v_parent_revision_id := v_definition.head_revision_id;
        v_revision_no := coalesce(v_revision.revision_no, 0) + 1;
        v_revision_id := gen_random_uuid();
        insert into public.custom_content_revisions (
          id, owner_id, definition_id, revision_no,
          parent_revision_id, schema_version, content_hash,
          data, command_id, created_at
        ) values (
          v_revision_id, v_uid, v_definition_id, v_revision_no,
          v_parent_revision_id, 1, v_content_hash,
          v_data, p_command_id, v_now
        );
        update public.custom_content_definitions
           set head_revision_id = v_revision_id,
               updated_at = v_now
         where owner_id = v_uid
           and id = v_definition_id;
        select *
          into strict v_definition
          from public.custom_content_definitions definition
         where definition.owner_id = v_uid
           and definition.id = v_definition_id;
        select *
          into strict v_revision
          from public.custom_content_revisions revision
         where revision.id = v_revision_id;
        v_per_entry := v_per_entry || jsonb_build_array(
          jsonb_build_object(
            'definitionId', v_definition_id,
            'revisionId', v_revision_id,
            'status', case when v_parent_revision_id is null
              then 'created' else 'updated' end,
            'category', v_entry ->> 'category',
            'packEntryId', v_entry ->> 'packEntryId'
          )
        );
      end if;

      v_items := v_items || jsonb_build_array(
        public._custom_content_projection(v_definition, v_revision)
      );
      if v_kind = 'content.pack.import' then
        insert into public.content_pack_version_entries (
          owner_id, pack_id, pack_version, pack_entry_id,
          definition_id, revision_id, category, ordinal
        ) values (
          v_uid, v_pack_id, v_pack_version, v_entry ->> 'packEntryId',
          v_definition_id, v_revision_id, v_entry ->> 'category', v_ordinal
        );
      end if;
    end loop;
  elsif v_kind in (
    'content.definition.archive',
    'content.definition.restore'
  ) then
    update public.custom_content_definitions
       set archived_at = case
             when v_kind = 'content.definition.archive'
               then coalesce(archived_at, v_now)
             else null
           end,
           updated_at = v_now
     where owner_id = v_uid
       and id = v_definition_id
     returning * into strict v_definition;
    select *
      into strict v_revision
      from public.custom_content_revisions revision
     where revision.id = v_definition.head_revision_id;
    if v_kind = 'content.definition.archive' then
      v_archived_items := jsonb_build_array(
        public._custom_content_projection(v_definition, v_revision)
      );
    else
      v_items := jsonb_build_array(
        public._custom_content_projection(v_definition, v_revision)
      );
    end if;
    v_per_entry := jsonb_build_array(jsonb_build_object(
      'definitionId', v_definition.id,
      'revisionId', v_revision.id,
      'status', case when v_kind = 'content.definition.archive'
        then 'archived' else 'restored' end,
      'category', v_definition.category,
      'packEntryId', null
    ));
  elsif v_kind = 'content.environment.migrate' then
    insert into public.content_environments (
      owner_id, environment_id, created_at, updated_at
    ) values (
      v_uid, v_environment_id, v_now, v_now
    )
    on conflict (owner_id, environment_id) do update
      set updated_at = excluded.updated_at;
    insert into public.content_environment_revisions (
      owner_id, environment_id, environment_revision_id,
      revision_no, environment_hash, revision, command_id, created_at
    ) values (
      v_uid, v_environment_id, v_environment_revision_id,
      (v_environment ->> 'revisionNumber')::integer,
      v_environment_hash, v_environment, p_command_id, v_now
    )
    on conflict (owner_id, environment_revision_id) do nothing;
    insert into public.content_environment_activations (
      owner_id, environment_revision_id, activated_at
    ) values (
      v_uid, v_environment_revision_id, v_now
    )
    on conflict (owner_id) do update
      set environment_revision_id = excluded.environment_revision_id,
          activated_at = excluded.activated_at;
  end if;

  if v_kind = 'content.pack.import' then
    update public.content_packs
       set active_pack_version = v_pack_version,
           active_manifest_hash = v_pack_hash,
           updated_at = v_now
     where owner_id = v_uid
       and pack_id = v_pack_id;
  end if;

  v_result := jsonb_build_object(
    'items', v_items,
    'archivedItems', v_archived_items,
    'pack', v_pack,
    'environment', v_environment,
    'perEntry', v_per_entry
  );
  v_response := jsonb_build_object(
    'ok', true,
    'status', 'applied',
    'commandId', p_command_id,
    'reason', null,
    'replayed', false,
    'fingerprint', v_fingerprint,
    'result', v_result,
    'perEntry', v_per_entry
  );
  if not public.finalize_application_command(
    v_uid, p_command_id, v_fingerprint, 'applied', v_response, null
  ) then
    raise exception 'custom-content command did not finalize'
      using errcode = '40001';
  end if;
  return v_response;
end;

_campaign_content_binding_history_valid(:
begin
  if jsonb_typeof(p_history) is distinct from 'array'
    or jsonb_array_length(p_history) > 64
    or octet_length(public._content_canonical_json(p_history))
      > 2 * 1024 * 1024
    or exists (
      select 1
        from jsonb_array_elements(p_history) as binding(value)
       where not public._campaign_content_binding_valid(binding.value)
    )
    or exists (
      select 1
        from jsonb_array_elements(p_history) as binding(value)
       group by binding.value ->> 'bindingHash'
      having count(*) > 1
    )
  then
    return false;
  end if;
  return true;
exception
  when others then
    return false;
end;

_campaign_patch_content_binding(p_map_da:
declare
  v_campaign jsonb;
begin
  if jsonb_typeof(p_map_data) is distinct from 'object' then
    return null;
  end if;
  if jsonb_typeof(p_map_data -> 'campaign') = 'object' then
    v_campaign := p_map_data -> 'campaign';
    v_campaign := jsonb_set(v_campaign, '{contentBinding}', p_binding, true);
    v_campaign := jsonb_set(
      v_campaign,
      '{contentBindingHistory}',
      p_history,
      true
    );
    v_campaign := jsonb_set(
      v_campaign,
      '{contentBindingStatus}',
      to_jsonb('pinned'::text),
      true
    );
    v_campaign := jsonb_set(
      v_campaign,
      '{updatedAt}',
      to_jsonb(p_now),
      true
    );
    return jsonb_set(p_map_data, '{campaign}', v_campaign, false);
  end if;
  if p_map_data ? 'settlementIds'
    or p_map_data ? 'mapState'
    or p_map_data ? 'regionalGraph'
    or p_map_data ? 'worldState'
  then
    v_campaign := jsonb_set(
      p_map_data,
      '{contentBinding}',
      p_binding,
      true
    );
    v_campaign := jsonb_set(
      v_campaign,
      '{contentBindingHistory}',
      p_history,
      true
    );
    v_campaign := jsonb_set(
      v_campaign,
      '{contentBindingStatus}',
      to_jsonb('pinned'::text),
      true
    );
    return jsonb_set(v_campaign, '{updatedAt}', to_jsonb(p_now), true);
  end if;
  return null;
end;

enforce_campaign_content_binding_cas():
declare
  v_old_binding jsonb;
  v_new_binding jsonb;
  v_old_history jsonb;
  v_new_history jsonb;
  v_command_fingerprint text;
begin
  v_new_binding := public._campaign_content_binding_from_map(new.map_data);
  v_new_history :=
    public._campaign_content_binding_history_from_map(new.map_data);
  if not public._campaign_content_binding_history_valid(v_new_history)
    or not public._campaign_reviewed_supply_chain_history_references_valid(
      new.user_id,
      v_new_history
    )
    or (
      v_new_binding is not null
      and (
        not public._campaign_content_binding_valid(v_new_binding)
        or not public._campaign_reviewed_supply_chain_references_valid(
          new.user_id,
          v_new_binding
        )
      )
    )
  then
    raise exception 'invalid campaign content binding envelope'
      using errcode = '22023';
  end if;

  if tg_op = 'INSERT' then
    return new;
  end if;

  v_old_binding := public._campaign_content_binding_from_map(old.map_data);
  v_old_history :=
    public._campaign_content_binding_history_from_map(old.map_data);
  if v_old_binding is not distinct from v_new_binding
    and v_old_history is not distinct from v_new_history
  then
    return new;
  end if;

  -- Authorization is the unfinalized command claim created by the CAS RPC in
  -- this transaction. A custom GUC is not a capability: any database role can
  -- set an arbitrary custom setting. The journal row cannot be forged by the
  -- authenticated client, is visible to its own transaction, and is finalized
  -- before commit.
  if v_old_binding is not null and v_new_binding is not null then
    v_command_fingerprint := public._content_sha256(jsonb_build_object(
      'schemaVersion', 1,
      'kind', 'campaign.content-binding.cas',
      'campaignId', new.id::text,
      'expectedBindingHash', v_old_binding ->> 'bindingHash',
      'targetBinding', v_new_binding,
      'contentBindingHistory', v_new_history
    ));
  end if;
  if v_command_fingerprint is not null and exists (
    select 1
      from public.application_command_journal as command
     where command.owner_id = new.user_id
       and command.target_id = new.id
       and command.kind = 'campaign.content-binding.cas'
       and command.fingerprint = v_command_fingerprint
       and command.phase = 'claimed'
       and command.status = 'claimed'
  ) then
    return new;
  end if;

  -- One migration-compatible bootstrap for rows created before bindings
  -- existed. History is empty because no earlier portable cutoff was stored.
  if v_old_binding is null
    and v_new_binding is not null
    and v_new_history = '[]'::jsonb
  then
    return new;
  end if;

  raise exception 'campaign content binding requires compare-and-swap'
    using errcode = '40001';
end;

compare_and_swap_campaign_content_bindin:
declare
  v_uid uuid := auth.uid();
  v_core jsonb;
  v_claim jsonb;
  v_map_data jsonb;
  v_next_map_data jsonb;
  v_actual_binding jsonb;
  v_actual_history jsonb;
  v_actual_hash text;
  v_target_hash text := p_target_binding ->> 'bindingHash';
  v_now timestamptz := clock_timestamp();
  v_receipt jsonb;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if p_expected_owner is null or p_expected_owner <> v_uid then
    raise exception 'campaign content command owner changed'
      using errcode = '42501';
  end if;
  if not public.account_is_active(v_uid)
    or not public.current_user_has_premium_access()
  then
    raise exception 'active premium account required'
      using errcode = '42501';
  end if;
  if p_campaign_id is null
    or p_expected_binding_hash !~ '^[0-9a-f]{64}$'
    or not public._campaign_content_binding_valid(p_target_binding)
    or not public._campaign_content_binding_history_valid(
      p_content_binding_history
    )
    or not public._campaign_reviewed_supply_chain_references_valid(
      v_uid,
      p_target_binding
    )
    or not public._campaign_reviewed_supply_chain_history_references_valid(
      v_uid,
      p_content_binding_history
    )
    or not exists (
      select 1
        from jsonb_array_elements(p_content_binding_history) as binding(value)
       where binding.value ->> 'bindingHash' = v_target_hash
    )
    or not exists (
      select 1
        from jsonb_array_elements(p_content_binding_history) as binding(value)
       where binding.value ->> 'bindingHash' = p_expected_binding_hash
    )
  then
    raise exception 'invalid campaign content binding command'
      using errcode = '22023';
  end if;

  v_core := jsonb_build_object(
    'schemaVersion', 1,
    'kind', 'campaign.content-binding.cas',
    'campaignId', p_campaign_id::text,
    'expectedBindingHash', p_expected_binding_hash,
    'targetBinding', p_target_binding,
    'contentBindingHistory', p_content_binding_history
  );
  if p_fingerprint !~ '^[0-9a-f]{64}$'
    or public._content_sha256(v_core) <> p_fingerprint
    or nullif(btrim(p_command_id), '') is null
    or char_length(p_command_id) > 240
  then
    raise exception 'campaign content command fingerprint mismatch'
      using errcode = '22023';
  end if;

  v_claim := public.claim_application_command(
    v_uid,
    p_command_id,
    p_fingerprint,
    'campaign.content-binding.cas',
    p_campaign_id,
    null
  );
  if v_claim ->> 'status' = 'conflict' then
    return jsonb_build_object(
      'schemaVersion', 1,
      'status', 'failed',
      'reason', 'command_id_conflict',
      'replayed', true,
      'commandId', p_command_id,
      'fingerprint', p_fingerprint,
      'campaignId', p_campaign_id
    );
  end if;
  if coalesce((v_claim ->> 'replayed')::boolean, false)
    and v_claim ->> 'phase' = 'finalized'
    and jsonb_typeof(v_claim -> 'receipt') = 'object'
  then
    -- Applied and failed receipts are immutable facts. A stale receipt is also
    -- permanently non-mutating, but its remote projection is an observation:
    -- another device may have advanced again before this retry. Refresh those
    -- fields instead of sending the browser an older winning binding.
    if v_claim #>> '{receipt,status}' = 'stale' then
      select map_data
        into v_map_data
        from public.saved_maps
       where id = p_campaign_id
         and user_id = v_uid
         and access_state = 'active';
      if found then
        v_actual_binding :=
          public._campaign_content_binding_from_map(v_map_data);
        v_actual_history :=
          public._campaign_content_binding_history_from_map(v_map_data);
        v_actual_hash := v_actual_binding ->> 'bindingHash';
      else
        v_actual_binding := null;
        v_actual_history := '[]'::jsonb;
        v_actual_hash := null;
      end if;
      return (v_claim -> 'receipt') || jsonb_build_object(
        'replayed', true,
        'actualBindingHash', v_actual_hash,
        'remoteBinding', v_actual_binding,
        'remoteBindingHistory', v_actual_history,
        'observedAt', v_now
      );
    end if;
    return (v_claim -> 'receipt')
      || jsonb_build_object('replayed', true);
  end if;
  if v_claim ->> 'phase' = 'reconcile' then
    return jsonb_build_object(
      'schemaVersion', 1,
      'status', 'reconcile-required',
      'reason', coalesce(v_claim ->> 'reason', 'ambiguous_result'),
      'replayed', true,
      'commandId', p_command_id,
      'fingerprint', p_fingerprint,
      'campaignId', p_campaign_id
    );
  end if;

  select map_data
    into v_map_data
    from public.saved_maps
   where id = p_campaign_id
     and user_id = v_uid
     and access_state = 'active'
   for update;
  if not found then
    v_receipt := jsonb_build_object(
      'schemaVersion', 1,
      'status', 'failed',
      'reason', 'campaign_content_campaign_unavailable',
      'replayed', false,
      'commandId', p_command_id,
      'fingerprint', p_fingerprint,
      'campaignId', p_campaign_id
    );
    if not public.finalize_application_command(
      v_uid,
      p_command_id,
      p_fingerprint,
      'failed',
      v_receipt,
      'campaign_content_campaign_unavailable'
    ) then
      raise exception 'campaign content command did not finalize'
        using errcode = '40001';
    end if;
    return v_receipt;
  end if;

  v_actual_binding :=
    public._campaign_content_binding_from_map(v_map_data);
  v_actual_history :=
    public._campaign_content_binding_history_from_map(v_map_data);
  v_actual_hash := v_actual_binding ->> 'bindingHash';

  if not public._campaign_content_binding_history_valid(v_actual_history)
    or (
      v_actual_binding is not null
      and not public._campaign_reviewed_supply_chain_references_valid(
        v_uid,
        v_actual_binding
      )
    )
    or not public._campaign_reviewed_supply_chain_history_references_valid(
      v_uid,
      v_actual_history
    )
  then
    raise exception 'stored campaign content history failed admission'
      using errcode = '22023';
  end if;

  if v_actual_hash is distinct from p_expected_binding_hash
    and v_actual_hash is distinct from v_target_hash
  then
    v_receipt := jsonb_build_object(
      'schemaVersion', 1,
      'status', 'stale',
      'reason', 'campaign_content_binding_conflict',
      'replayed', false,
      'commandId', p_command_id,
      'fingerprint', p_fingerprint,
      'campaignId', p_campaign_id,
      'expectedBindingHash', p_expected_binding_hash,
      'actualBindingHash', v_actual_hash,
      'remoteBinding', v_actual_binding,
      'remoteBindingHistory', v_actual_history,
      'observedAt', v_now
    );
    if not public.finalize_application_command(
      v_uid,
      p_command_id,
      p_fingerprint,
      'stale',
      v_receipt,
      'campaign_content_binding_conflict'
    ) then
      raise exception 'campaign content command did not finalize'
        using errcode = '40001';
    end if;
    return v_receipt;
  end if;

  -- Binding-hash CAS alone has an ABA hole: another device can advance
  -- B -> C -> B while an older B-based review remains open. The current hash
  -- matches, but accepting the older history would erase C. Existing history
  -- must remain an exact prefix, and the only legal suffix entries are the
  -- current and target snapshots that the domain append operation can add.
  if jsonb_array_length(p_content_binding_history)
      < jsonb_array_length(v_actual_history)
    or exists (
      select 1
        from jsonb_array_elements(v_actual_history)
          with ordinality as prior(value, ordinal)
       where (
         p_content_binding_history
           -> ((prior.ordinal - 1)::integer)
       ) is distinct from prior.value
    )
    or exists (
      select 1
        from jsonb_array_elements(p_content_binding_history)
          with ordinality as proposed(value, ordinal)
       where proposed.ordinal > jsonb_array_length(v_actual_history)
         and proposed.value ->> 'bindingHash'
           not in (v_actual_hash, v_target_hash)
    )
  then
    v_receipt := jsonb_build_object(
      'schemaVersion', 1,
      'status', 'stale',
      'reason', 'campaign_content_binding_history_conflict',
      'replayed', false,
      'commandId', p_command_id,
      'fingerprint', p_fingerprint,
      'campaignId', p_campaign_id,
      'expectedBindingHash', p_expected_binding_hash,
      'actualBindingHash', v_actual_hash,
      'remoteBinding', v_actual_binding,
      'remoteBindingHistory', v_actual_history,
      'observedAt', v_now
    );
    if not public.finalize_application_command(
      v_uid,
      p_command_id,
      p_fingerprint,
      'stale',
      v_receipt,
      'campaign_content_binding_history_conflict'
    ) then
      raise exception 'campaign content command did not finalize'
        using errcode = '40001';
    end if;
    return v_receipt;
  end if;

  if v_actual_hash = v_target_hash then
    v_receipt := jsonb_build_object(
      'schemaVersion', 1,
      'status', 'applied',
      'replayed', false,
      'commandId', p_command_id,
      'fingerprint', p_fingerprint,
      'campaignId', p_campaign_id,
      'previousBindingHash', p_expected_binding_hash,
      'bindingHash', v_target_hash,
      'appliedAt', v_now
    );
    if not public.finalize_application_command(
      v_uid,
      p_command_id,
      p_fingerprint,
      'applied',
      v_receipt,
      null
    ) then
      raise exception 'campaign content command did not finalize'
        using errcode = '40001';
    end if;
    return v_receipt;
  end if;

  v_next_map_data := public._campaign_patch_content_binding(
    v_map_data,
    p_target_binding,
    p_content_binding_history,
    v_now
  );
  if v_next_map_data is null then
    v_receipt := jsonb_build_object(
      'schemaVersion', 1,
      'status', 'failed',
      'reason', 'campaign_content_envelope_unsupported',
      'replayed', false,
      'commandId', p_command_id,
      'fingerprint', p_fingerprint,
      'campaignId', p_campaign_id
    );
    if not public.finalize_application_command(
      v_uid,
      p_command_id,
      p_fingerprint,
      'failed',
      v_receipt,
      'campaign_content_envelope_unsupported'
    ) then
      raise exception 'campaign content command did not finalize'
        using errcode = '40001';
    end if;
    return v_receipt;
  end if;

  update public.saved_maps
     set map_data = v_next_map_data,
         updated_at = v_now
   where id = p_campaign_id
     and user_id = v_uid;

  v_receipt := jsonb_build_object(
    'schemaVersion', 1,
    'status', 'applied',
    'replayed', false,
    'commandId', p_command_id,
    'fingerprint', p_fingerprint,
    'campaignId', p_campaign_id,
    'previousBindingHash', p_expected_binding_hash,
    'bindingHash', v_target_hash,
    'appliedAt', v_now
  );
  if not public.finalize_application_command(
    v_uid,
    p_command_id,
    p_fingerprint,
    'applied',
    v_receipt,
    null
  ) then
    raise exception 'campaign content command did not finalize'
      using errcode = '40001';
  end if;
  return v_receipt;
end;

_custom_content_archive_timestamp_valid(:
declare
  v_text text;
  v_timestamp timestamptz;
begin
  if jsonb_typeof(p_value) = 'null' then return true; end if;
  if jsonb_typeof(p_value) is distinct from 'string' then return false; end if;
  v_text := p_value #>> '{}';
  if v_text !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'
  then
    return false;
  end if;
  v_timestamp := v_text::timestamptz;
  return to_char(
    v_timestamp at time zone 'UTC',
    'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
  ) = v_text;
exception when others then
  return false;
end;

_custom_content_archive_ledger_valid(p_l:
declare
  v_expected_keys text[] := case when p_require_receipts then
    array[
      'schemaVersion','definitions','revisions','packs','packVersions',
      'packEntryDefinitions','packVersionEntries','environments',
      'activeEnvironmentRevisionId','commandReceipts'
    ]
  else
    array[
      'schemaVersion','definitions','revisions','packs','packVersions',
      'packEntryDefinitions','packVersionEntries','environments',
      'activeEnvironmentRevisionId'
    ]
  end;
begin
  if jsonb_typeof(p_ledger) is distinct from 'object'
    or p_ledger ->> 'schemaVersion' is distinct from '1'
    or (p_ledger - v_expected_keys) <> '{}'::jsonb
    or not (p_ledger ?& v_expected_keys)
    or jsonb_typeof(p_ledger -> 'definitions') is distinct from 'array'
    or jsonb_array_length(p_ledger -> 'definitions') > 2000
    or jsonb_typeof(p_ledger -> 'revisions') is distinct from 'array'
    or jsonb_array_length(p_ledger -> 'revisions') > 20000
    or jsonb_typeof(p_ledger -> 'packs') is distinct from 'array'
    or jsonb_array_length(p_ledger -> 'packs') > 128
    or jsonb_typeof(p_ledger -> 'packVersions') is distinct from 'array'
    or jsonb_array_length(p_ledger -> 'packVersions') > 1024
    or jsonb_typeof(p_ledger -> 'packEntryDefinitions')
      is distinct from 'array'
    or jsonb_array_length(p_ledger -> 'packEntryDefinitions') > 20000
    or jsonb_typeof(p_ledger -> 'packVersionEntries')
      is distinct from 'array'
    or jsonb_array_length(p_ledger -> 'packVersionEntries') > 20000
    or jsonb_typeof(p_ledger -> 'environments') is distinct from 'array'
    or jsonb_array_length(p_ledger -> 'environments') > 2000
    or (
      p_require_receipts
      and (
        jsonb_typeof(p_ledger -> 'commandReceipts')
          is distinct from 'array'
        or jsonb_array_length(p_ledger -> 'commandReceipts') > 10000
      )
    )
  then
    return false;
  end if;

  if exists (
    select 1
      from jsonb_array_elements(p_ledger -> 'definitions') definition(value)
     where jsonb_typeof(definition.value) is distinct from 'object'
        or not (
          definition.value ?& array[
            'id','category','localUid','headRevisionId','archivedAt',
            'createdAt','updatedAt','legacyContentId'
          ]
        )
        or (
          definition.value - array[
            'id','category','localUid','headRevisionId','archivedAt',
            'createdAt','updatedAt','legacyContentId'
          ]
        ) <> '{}'::jsonb
        or nullif(btrim(definition.value ->> 'id'), '') is null
        or char_length(definition.value ->> 'id') > 240
        or definition.value ->> 'category' not in (
          'institutions','services','resources','stressors',
          'tradeGoods','factions','deities','traditions','supplyChains'
        )
        or nullif(btrim(definition.value ->> 'localUid'), '') is null
        or char_length(definition.value ->> 'localUid') > 240
        or definition.value ->> 'localUid'
          <> btrim(definition.value ->> 'localUid')
        or nullif(btrim(definition.value ->> 'headRevisionId'), '') is null
        or char_length(definition.value ->> 'headRevisionId') > 240
        or not public._custom_content_archive_timestamp_valid(
          definition.value -> 'archivedAt'
        )
        or not public._custom_content_archive_timestamp_valid(
          definition.value -> 'createdAt'
        )
        or not public._custom_content_archive_timestamp_valid(
          definition.value -> 'updatedAt'
        )
        or jsonb_typeof(definition.value -> 'legacyContentId')
          not in ('null', 'string')
        or (
          definition.value ->> 'legacyContentId' is not null
          and (
            nullif(btrim(definition.value ->> 'legacyContentId'), '') is null
            or char_length(definition.value ->> 'legacyContentId') > 240
          )
        )
        or (
          p_require_uuid
          and (
            public._content_uuid(definition.value ->> 'id') is null
            or public._content_uuid(
              definition.value ->> 'headRevisionId'
            ) is null
          )
        )
  ) or (
    select count(distinct definition.value ->> 'id')
      from jsonb_array_elements(p_ledger -> 'definitions') definition(value)
  ) <> jsonb_array_length(p_ledger -> 'definitions')
  or (
    select count(distinct definition.value ->> 'localUid')
      from jsonb_array_elements(p_ledger -> 'definitions') definition(value)
  ) <> jsonb_array_length(p_ledger -> 'definitions')
  then
    return false;
  end if;

  if exists (
    select 1
      from jsonb_array_elements(p_ledger -> 'revisions') revision(value)
     where jsonb_typeof(revision.value) is distinct from 'object'
        or not (
          revision.value ?& array[
            'schemaVersion','id','definitionId','category','revisionNumber',
            'parentRevisionId','contentHash','data','createdAt'
          ]
        )
        or (
          revision.value - array[
            'schemaVersion','id','definitionId','category','revisionNumber',
            'parentRevisionId','contentHash','data','createdAt'
          ]
        ) <> '{}'::jsonb
        or revision.value ->> 'schemaVersion' is distinct from '1'
        or nullif(btrim(revision.value ->> 'id'), '') is null
        or char_length(revision.value ->> 'id') > 240
        or nullif(btrim(revision.value ->> 'definitionId'), '') is null
        or char_length(revision.value ->> 'definitionId') > 240
        or coalesce(revision.value ->> 'revisionNumber', '')
          !~ '^[1-9][0-9]*$'
        or jsonb_typeof(revision.value -> 'parentRevisionId')
          not in ('null', 'string')
        or coalesce(revision.value ->> 'contentHash', '')
          !~ '^[0-9a-f]{64}$'
        or not public._custom_content_archive_timestamp_valid(
          revision.value -> 'createdAt'
        )
        or (
          case
            when revision.value ->> 'category' = 'supplyChains'
              then not public._reviewed_supply_chain_record_valid(
                revision.value -> 'data'
              )
            else not public._custom_content_record_valid(
              revision.value ->> 'category',
              revision.value -> 'data'
            )
          end
        )
        or public._content_sha256(jsonb_build_object(
          'schemaVersion', 1,
          'category', revision.value ->> 'category',
          'data', revision.value -> 'data'
        )) <> revision.value ->> 'contentHash'
        or (
          p_require_uuid
          and (
            public._content_uuid(revision.value ->> 'id') is null
            or public._content_uuid(
              revision.value ->> 'definitionId'
            ) is null
            or (
              revision.value ->> 'parentRevisionId' is not null
              and public._content_uuid(
                revision.value ->> 'parentRevisionId'
              ) is null
            )
          )
        )
        or not exists (
          select 1
            from jsonb_array_elements(
              p_ledger -> 'definitions'
            ) definition(value)
           where definition.value ->> 'id'
             = revision.value ->> 'definitionId'
             and definition.value ->> 'category'
             = revision.value ->> 'category'
             and (
               revision.value ->> 'category' = 'supplyChains'
               or definition.value ->> 'localUid'
                 = revision.value #>> '{data,localUid}'
             )
        )
  ) or (
    select count(distinct revision.value ->> 'id')
      from jsonb_array_elements(p_ledger -> 'revisions') revision(value)
  ) <> jsonb_array_length(p_ledger -> 'revisions')
  or exists (
    select 1
      from jsonb_array_elements(p_ledger -> 'revisions') revision(value)
     group by
       revision.value ->> 'definitionId',
       revision.value ->> 'revisionNumber'
    having count(*) > 1
  ) or exists (
    select 1
      from jsonb_array_elements(p_ledger -> 'definitions') definition(value)
     where not exists (
       select 1
         from jsonb_array_elements(p_ledger -> 'revisions') revision(value)
        where revision.value ->> 'id'
          = definition.value ->> 'headRevisionId'
          and revision.value ->> 'definitionId'
          = definition.value ->> 'id'
     )
  ) or exists (
    select 1
      from jsonb_array_elements(p_ledger -> 'revisions') child(value)
     where child.value ->> 'parentRevisionId' is not null
       and not exists (
         select 1
           from jsonb_array_elements(p_ledger -> 'revisions') parent(value)
          where parent.value ->> 'id'
            = child.value ->> 'parentRevisionId'
            and parent.value ->> 'definitionId'
            = child.value ->> 'definitionId'
            and (parent.value ->> 'revisionNumber')::integer
              < (child.value ->> 'revisionNumber')::integer
       )
  ) or exists (
    select 1
      from jsonb_array_elements(p_ledger -> 'definitions') definition(value)
     where (
       select count(*)
         from jsonb_array_elements(p_ledger -> 'revisions') revision(value)
        where revision.value ->> 'definitionId'
          = definition.value ->> 'id'
     ) <> (
       select max((revision.value ->> 'revisionNumber')::integer)
         from jsonb_array_elements(p_ledger -> 'revisions') revision(value)
        where revision.value ->> 'definitionId'
          = definition.value ->> 'id'
     )
       or not exists (
         select 1
           from jsonb_array_elements(p_ledger -> 'revisions') head(value)
          where head.value ->> 'id'
            = definition.value ->> 'headRevisionId'
            and (head.value ->> 'revisionNumber')::integer = (
              select max((revision.value ->> 'revisionNumber')::integer)
                from jsonb_array_elements(
                  p_ledger -> 'revisions'
                ) revision(value)
               where revision.value ->> 'definitionId'
                 = definition.value ->> 'id'
            )
       )
  ) or exists (
    select 1
      from jsonb_array_elements(p_ledger -> 'revisions') child(value)
     where (
       (child.value ->> 'revisionNumber')::integer = 1
       and child.value ->> 'parentRevisionId' is not null
     ) or (
       (child.value ->> 'revisionNumber')::integer > 1
       and not exists (
         select 1
           from jsonb_array_elements(p_ledger -> 'revisions') parent(value)
          where parent.value ->> 'id'
            = child.value ->> 'parentRevisionId'
            and parent.value ->> 'definitionId'
              = child.value ->> 'definitionId'
            and (parent.value ->> 'revisionNumber')::integer
              = (child.value ->> 'revisionNumber')::integer - 1
       )
     )
  ) then
    return false;
  end if;

  if exists (
    select 1
      from jsonb_array_elements(p_ledger -> 'packs') pack(value)
     where jsonb_typeof(pack.value) is distinct from 'object'
        or not (
          pack.value ?& array[
            'packId','name','activePackVersion','activeManifestHash',
            'createdAt','updatedAt'
          ]
        )
        or (
          pack.value - array[
            'packId','name','activePackVersion','activeManifestHash',
            'createdAt','updatedAt'
          ]
        ) <> '{}'::jsonb
        or nullif(btrim(pack.value ->> 'packId'), '') is null
        or char_length(pack.value ->> 'packId') > 240
        or nullif(btrim(pack.value ->> 'name'), '') is null
        or char_length(pack.value ->> 'name') > 240
        or (
          (pack.value ->> 'activePackVersion' is null)
          <> (pack.value ->> 'activeManifestHash' is null)
        )
        or (
          pack.value ->> 'activeManifestHash' is not null
          and pack.value ->> 'activeManifestHash'
            !~ '^[0-9a-f]{64}$'
        )
        or not public._custom_content_archive_timestamp_valid(
          pack.value -> 'createdAt'
        )
        or not public._custom_content_archive_timestamp_valid(
          pack.value -> 'updatedAt'
        )
  ) or (
    select count(distinct pack.value ->> 'packId')
      from jsonb_array_elements(p_ledger -> 'packs') pack(value)
  ) <> jsonb_array_length(p_ledger -> 'packs')
  then
    return false;
  end if;

  if exists (
    select 1
      from jsonb_array_elements(p_ledger -> 'packVersions') version(value)
     where jsonb_typeof(version.value) is distinct from 'object'
        or not (
          version.value ?& array[
            'packId','packVersion','manifestHash','importPlanHash',
            'manifest','createdAt'
          ]
        )
        or (
          version.value - array[
            'packId','packVersion','manifestHash','importPlanHash',
            'manifest','createdAt'
          ]
        ) <> '{}'::jsonb
        or nullif(btrim(version.value ->> 'packVersion'), '') is null
        or char_length(version.value ->> 'packVersion') > 120
        or version.value ->> 'manifestHash' !~ '^[0-9a-f]{64}$'
        or version.value ->> 'importPlanHash' !~ '^[0-9a-f]{64}$'
        or jsonb_typeof(version.value -> 'manifest')
          is distinct from 'object'
        or not public._custom_content_archive_timestamp_valid(
          version.value -> 'createdAt'
        )
        or not public._content_pack_manifest_valid(
          version.value -> 'manifest',
          version.value ->> 'packId',
          version.value ->> 'packVersion',
          version.value ->> 'manifestHash'
        )
        or not exists (
          select 1
            from jsonb_array_elements(p_ledger -> 'packs') pack(value)
           where pack.value ->> 'packId' = version.value ->> 'packId'
        )
        or not exists (
          select 1
            from jsonb_array_elements(
              p_ledger -> 'packVersionEntries'
            ) entry(value)
           where entry.value ->> 'packId' = version.value ->> 'packId'
             and entry.value ->> 'packVersion'
               = version.value ->> 'packVersion'
        )
        or version.value ->> 'importPlanHash'
          <> public._content_sha256(jsonb_build_object(
            'schemaVersion', 1,
            'packId', version.value ->> 'packId',
            'packVersion', version.value ->> 'packVersion',
            'entries', (
              select coalesce(jsonb_agg(
                jsonb_build_object(
                  'packEntryId', entry.value -> 'packEntryId',
                  'category', entry.value -> 'category',
                  'data', revision.value -> 'data'
                )
                order by (entry.value ->> 'ordinal')::integer
              ), '[]'::jsonb)
                from jsonb_array_elements(
                  p_ledger -> 'packVersionEntries'
                ) entry(value)
                join jsonb_array_elements(
                  p_ledger -> 'revisions'
                ) revision(value)
                  on revision.value ->> 'id'
                    = entry.value ->> 'revisionId'
               where entry.value ->> 'packId'
                 = version.value ->> 'packId'
                 and entry.value ->> 'packVersion'
                   = version.value ->> 'packVersion'
            )
          ))
        or exists (
          select 1
            from jsonb_array_elements(
              p_ledger -> 'packVersionEntries'
            ) entry(value)
            join jsonb_array_elements(
              p_ledger -> 'revisions'
            ) revision(value)
              on revision.value ->> 'id'
                = entry.value ->> 'revisionId'
           where entry.value ->> 'packId'
             = version.value ->> 'packId'
             and entry.value ->> 'packVersion'
               = version.value ->> 'packVersion'
             and not exists (
               select 1
                 from jsonb_each(
                   version.value #> '{manifest,content}'
                 ) bucket(key, value)
                 cross join lateral jsonb_array_elements(
                   bucket.value
                 ) manifest_entry(value)
                where bucket.key = entry.value ->> 'category'
                  and manifest_entry.value ->> 'packEntryId'
                    = entry.value ->> 'packEntryId'
                  and manifest_entry.value ->> 'sourceDefinitionId'
                    = entry.value ->> 'definitionId'
                  and manifest_entry.value ->> 'sourceRevisionId'
                    = entry.value ->> 'revisionId'
                  and manifest_entry.value ->> 'contentHash'
                    = revision.value ->> 'contentHash'
                  and (
                    manifest_entry.value - array[
                      'id','definitionId','revisionId','revisionNumber',
                      'contentHash','createdAt','updatedAt','archivedAt',
                      'isCustom','_schemaVersion','packEntryId',
                      'sourceDefinitionId','sourceRevisionId',
                      'commandReceipt'
                    ]
                  ) = revision.value -> 'data'
             )
        )
        or (
          select count(*)
            from jsonb_each(
              version.value #> '{manifest,content}'
            ) bucket(key, value)
            cross join lateral jsonb_array_elements(bucket.value) entry(value)
        ) <> (
          select count(*)
            from jsonb_array_elements(
              p_ledger -> 'packVersionEntries'
            ) entry(value)
           where entry.value ->> 'packId'
             = version.value ->> 'packId'
             and entry.value ->> 'packVersion'
               = version.value ->> 'packVersion'
        )
  ) or exists (
    select 1
      from jsonb_array_elements(p_ledger -> 'packVersions') version(value)
     group by
       version.value ->> 'packId',
       version.value ->> 'packVersion'
    having count(*) > 1
  ) then
    return false;
  end if;

  if exists (
    select 1
      from jsonb_array_elements(
        p_ledger -> 'packEntryDefinitions'
      ) mapping(value)
     where jsonb_typeof(mapping.value) is distinct from 'object'
        or not (
          mapping.value ?& array[
            'packId','packEntryId','definitionId'
          ]
        )
        or (
          mapping.value - array[
            'packId','packEntryId','definitionId'
          ]
        ) <> '{}'::jsonb
        or nullif(btrim(mapping.value ->> 'packEntryId'), '') is null
        or char_length(mapping.value ->> 'packEntryId') > 240
        or not exists (
          select 1
            from jsonb_array_elements(p_ledger -> 'packs') pack(value)
           where pack.value ->> 'packId' = mapping.value ->> 'packId'
        )
        or not exists (
          select 1
            from jsonb_array_elements(
              p_ledger -> 'definitions'
            ) definition(value)
           where definition.value ->> 'id'
             = mapping.value ->> 'definitionId'
             and definition.value ->> 'category' <> 'supplyChains'
        )
        or (
          p_require_uuid
          and public._content_uuid(mapping.value ->> 'definitionId') is null
        )
  ) or exists (
    select 1
      from jsonb_array_elements(
        p_ledger -> 'packEntryDefinitions'
      ) mapping(value)
     group by
       mapping.value ->> 'packId',
       mapping.value ->> 'packEntryId'
    having count(*) > 1
  ) then
    return false;
  end if;

  if exists (
    select 1
      from jsonb_array_elements(
        p_ledger -> 'packVersionEntries'
      ) entry(value)
     where jsonb_typeof(entry.value) is distinct from 'object'
        or not (
          entry.value ?& array[
            'packId','packVersion','packEntryId','definitionId',
            'revisionId','category','ordinal'
          ]
        )
        or (
          entry.value - array[
            'packId','packVersion','packEntryId','definitionId',
            'revisionId','category','ordinal'
          ]
        ) <> '{}'::jsonb
        or entry.value ->> 'category' = 'supplyChains'
        or coalesce(entry.value ->> 'ordinal', '') !~ '^[0-9]+$'
        or not exists (
          select 1
            from jsonb_array_elements(
              p_ledger -> 'packVersions'
            ) version(value)
           where version.value ->> 'packId' = entry.value ->> 'packId'
             and version.value ->> 'packVersion'
               = entry.value ->> 'packVersion'
        )
        or not exists (
          select 1
            from jsonb_array_elements(
              p_ledger -> 'packEntryDefinitions'
            ) mapping(value)
           where mapping.value ->> 'packId' = entry.value ->> 'packId'
             and mapping.value ->> 'packEntryId'
               = entry.value ->> 'packEntryId'
             and mapping.value ->> 'definitionId'
               = entry.value ->> 'definitionId'
        )
        or not exists (
          select 1
            from jsonb_array_elements(p_ledger -> 'revisions') revision(value)
           where revision.value ->> 'id' = entry.value ->> 'revisionId'
             and revision.value ->> 'definitionId'
               = entry.value ->> 'definitionId'
             and revision.value ->> 'category'
               = entry.value ->> 'category'
        )
        or (
          p_require_uuid
          and (
            public._content_uuid(entry.value ->> 'definitionId') is null
            or public._content_uuid(entry.value ->> 'revisionId') is null
          )
        )
  ) or exists (
    select 1
      from jsonb_array_elements(
        p_ledger -> 'packVersionEntries'
      ) entry(value)
     group by
       entry.value ->> 'packId',
       entry.value ->> 'packVersion',
       entry.value ->> 'packEntryId'
    having count(*) > 1
  ) or exists (
    select 1
      from jsonb_array_elements(
        p_ledger -> 'packVersionEntries'
      ) entry(value)
     group by entry.value ->> 'packId', entry.value ->> 'packVersion'
    having min((entry.value ->> 'ordinal')::integer) <> 0
        or max((entry.value ->> 'ordinal')::integer) <> count(*) - 1
        or count(distinct (entry.value ->> 'ordinal')::integer) <> count(*)
  ) or exists (
    select 1
      from jsonb_array_elements(p_ledger -> 'packs') pack(value)
     where pack.value ->> 'activePackVersion' is not null
       and not exists (
         select 1
           from jsonb_array_elements(
             p_ledger -> 'packVersions'
           ) version(value)
          where version.value ->> 'packId' = pack.value ->> 'packId'
            and version.value ->> 'packVersion'
              = pack.value ->> 'activePackVersion'
            and version.value ->> 'manifestHash'
              = pack.value ->> 'activeManifestHash'
       )
  ) then
    return false;
  end if;

  if exists (
    select 1
     from jsonb_array_elements(p_ledger -> 'environments') environment(value)
     where not public._content_environment_valid(environment.value)
        or not public._custom_content_archive_timestamp_valid(
          environment.value -> 'createdAt'
        )
        or not exists (
          select 1
          where not exists (
            select 1
              from jsonb_array_elements(
                environment.value -> 'directDefinitions'
              ) direct(value)
             where not exists (
               select 1
                 from jsonb_array_elements(
                   p_ledger -> 'revisions'
                 ) revision(value)
                where revision.value ->> 'id'
                  = direct.value ->> 'revisionId'
                  and revision.value ->> 'definitionId'
                    = direct.value ->> 'definitionId'
                  and revision.value ->> 'category'
                    = direct.value ->> 'category'
                  and revision.value ->> 'contentHash'
                    = direct.value ->> 'contentHash'
             )
          )
        )
        or exists (
          select 1
            from jsonb_array_elements(
              environment.value -> 'packVersions'
            ) binding(value)
           where not exists (
             select 1
               from jsonb_array_elements(
                 p_ledger -> 'packVersions'
               ) version(value)
              where version.value ->> 'packId'
                = binding.value ->> 'packId'
                and version.value ->> 'packVersion'
                  = binding.value ->> 'packVersionId'
                and version.value ->> 'manifestHash'
                  = binding.value ->> 'manifestHash'
                and exists (
                  select 1
                    from jsonb_array_elements(
                      p_ledger -> 'packVersionEntries'
                    ) entry(value)
                   where entry.value ->> 'packId'
                     = binding.value ->> 'packId'
                     and entry.value ->> 'packVersion'
                       = binding.value ->> 'packVersionId'
                )
             )
        )
        or exists (
          select 1
            from jsonb_array_elements(
              environment.value -> 'packVersions'
            ) binding(value)
            join jsonb_array_elements(
              p_ledger -> 'packVersionEntries'
            ) entry(value)
              on entry.value ->> 'packId' = binding.value ->> 'packId'
             and entry.value ->> 'packVersion'
               = binding.value ->> 'packVersionId'
           where not exists (
             select 1
               from jsonb_array_elements(
                 environment.value -> 'directDefinitions'
               ) direct(value)
              where direct.value ->> 'definitionId'
                = entry.value ->> 'definitionId'
                and direct.value ->> 'revisionId'
                  = entry.value ->> 'revisionId'
                and direct.value ->> 'category'
                  = entry.value ->> 'category'
           )
        )
  ) or exists (
    select 1
      from jsonb_array_elements(p_ledger -> 'environments') environment(value)
     group by environment.value ->> 'environmentRevisionId'
    having count(*) > 1
  ) or exists (
    select 1
      from jsonb_array_elements(p_ledger -> 'environments') environment(value)
     group by environment.value ->> 'environmentId'
    having count(*) <> max(
      (environment.value ->> 'revisionNumber')::integer
    )
       or min((environment.value ->> 'revisionNumber')::integer) <> 1
  ) or (
    p_ledger ->> 'activeEnvironmentRevisionId' is not null
    and not exists (
      select 1
        from jsonb_array_elements(
          p_ledger -> 'environments'
        ) environment(value)
       where environment.value ->> 'environmentRevisionId'
         = p_ledger ->> 'activeEnvironmentRevisionId'
    )
  ) then
    return false;
  end if;

  if p_require_receipts and exists (
    select 1
      from jsonb_array_elements(
        p_ledger -> 'commandReceipts'
      ) receipt(value)
     where jsonb_typeof(receipt.value) is distinct from 'object'
        or not (
          receipt.value ?& array[
            'commandId','fingerprint','receipt'
          ]
        )
        or (
          receipt.value - array[
            'commandId','fingerprint','receipt'
          ]
        ) <> '{}'::jsonb
        or nullif(btrim(receipt.value ->> 'commandId'), '') is null
        or char_length(receipt.value ->> 'commandId') > 240
        or receipt.value ->> 'fingerprint' !~ '^[0-9a-f]{64}$'
        or jsonb_typeof(receipt.value -> 'receipt') is distinct from 'object'
  ) or p_require_receipts and exists (
    select 1
      from jsonb_array_elements(
        p_ledger -> 'commandReceipts'
      ) receipt(value)
     group by receipt.value ->> 'commandId'
    having count(*) > 1
  ) then
    return false;
  end if;
  if not public._reviewed_supply_chain_archive_graph_valid(p_ledger) then
    return false;
  end if;
  return true;
exception
  when others then
    return false;
end;

_custom_content_archive_destination_uuid:
declare
  v_hash text := public._custom_content_archive_destination_hash(
    p_owner, p_source_key, p_kind, p_source_id
  );
  v_variant text;
begin
  v_variant := case substring(v_hash from 17 for 1)
    when '0' then '8' when '4' then '8'
    when '8' then '8' when 'c' then '8'
    when '1' then '9' when '5' then '9'
    when '9' then '9' when 'd' then '9'
    when '2' then 'a' when '6' then 'a'
    when 'a' then 'a' when 'e' then 'a'
    else 'b'
  end;
  return (
    substring(v_hash from 1 for 8) || '-'
    || substring(v_hash from 9 for 4) || '-5'
    || substring(v_hash from 14 for 3) || '-'
    || v_variant || substring(v_hash from 18 for 3) || '-'
    || substring(v_hash from 21 for 12)
  )::uuid;
end;

_custom_content_archive_destination_text:
select p_prefix || ':' || substring(
  public._custom_content_archive_destination_hash(
    p_owner, p_source_key, p_prefix, p_source_id
  ) from 1 for 48
)

_custom_content_archive_remap_data(p_dat:
declare
  v_result jsonb := p_data;
  v_local_uid text;
  v_field text;
  v_value jsonb;
  v_rewritten jsonb;
  v_dependency_fields text[] := array[
    'produces','requires','subsumes','providedBy','yields','enables',
    'disablesInstitutions','disablesGoods','requiredInstitution',
    'requiredResources','controls','rivals'
  ];
begin
  select mapping.value ->> 'destinationId'
    into v_local_uid
    from jsonb_array_elements(p_local_uid_map) mapping(value)
   where mapping.value ->> 'sourceId' = p_data ->> 'localUid';
  if not found then return null; end if;
  v_result := jsonb_set(v_result, '{localUid}', to_jsonb(v_local_uid), false);

  foreach v_field in array v_dependency_fields loop
    if not (v_result ? v_field) then continue; end if;
    v_value := v_result -> v_field;
    if jsonb_typeof(v_value) = 'string' then
      if left(v_result ->> v_field, 7) = 'custom:' then
        select mapping.value ->> 'destinationId'
          into v_local_uid
          from jsonb_array_elements(p_local_uid_map) mapping(value)
         where mapping.value ->> 'sourceId'
           = substring(v_result ->> v_field from 8);
        if found then
          v_result := jsonb_set(
            v_result,
            array[v_field],
            to_jsonb('custom:' || v_local_uid),
            false
          );
        end if;
      end if;
    elsif jsonb_typeof(v_value) = 'array' then
      select jsonb_agg(
        case
          when jsonb_typeof(item.value) = 'string'
            and left(item.value #>> '{}', 7) = 'custom:'
            and mapped.destination_id is not null
          then to_jsonb('custom:' || mapped.destination_id)
          else item.value
        end
        order by item.ordinal
      )
        into v_rewritten
        from jsonb_array_elements(v_value)
          with ordinality item(value, ordinal)
        left join lateral (
          select mapping.value ->> 'destinationId' as destination_id
            from jsonb_array_elements(p_local_uid_map) mapping(value)
           where mapping.value ->> 'sourceId'
             = substring(item.value #>> '{}' from 8)
        ) mapped on true;
      v_result := jsonb_set(v_result, array[v_field], v_rewritten, false);
    end if;
  end loop;
  return v_result;
exception when others then
  return null;
end;

import_custom_content_archive(p_expected:
declare
  v_uid uuid := auth.uid();
  v_claim jsonb;
  v_archive jsonb := p_bundle -> 'sourceArchive';
  v_transfer jsonb := p_bundle -> 'transfer';
  v_identity_map jsonb := p_bundle -> 'identityMap';
  v_activation_policy text := p_bundle ->> 'activationPolicy';
  v_archive_core jsonb;
  v_archive_fingerprint text;
  v_source_key text;
  v_source_ledger_fingerprint text;
  v_provenance_fingerprint text;
  v_now timestamptz := clock_timestamp();
  v_receipt jsonb;
  v_failure_reason text;
  v_destination_pristine boolean;
  v_activation_adopted boolean := false;
  v_definition_outcomes jsonb := '{}'::jsonb;
  v_exported_archive jsonb;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if p_expected_owner is null or p_expected_owner <> v_uid then
    raise exception 'custom-content archive owner changed'
      using errcode = '42501';
  end if;
  if not public.account_is_active(v_uid)
    or not public.current_user_has_premium_access()
  then
    raise exception 'active premium account required'
      using errcode = '42501';
  end if;
  if nullif(btrim(p_command_id), '') is null
    or char_length(p_command_id) > 240
    or p_fingerprint !~ '^[0-9a-f]{64}$'
    or jsonb_typeof(p_bundle) is distinct from 'object'
    or octet_length(p_bundle::text) > 32 * 1024 * 1024
    or (p_bundle - array[
      'schemaVersion','activationPolicy',
      'sourceArchive','transfer','identityMap'
    ]) <> '{}'::jsonb
    or not (p_bundle ?& array[
      'schemaVersion','activationPolicy',
      'sourceArchive','transfer','identityMap'
    ])
    or p_bundle ->> 'schemaVersion' is distinct from '1'
    or v_activation_policy not in ('preserve', 'adopt-if-empty')
    or public._content_sha256(p_bundle) <> p_fingerprint
  then
    raise exception 'invalid custom-content archive command'
      using errcode = '22023';
  end if;

  v_archive_fingerprint := v_archive ->> 'archiveFingerprint';
  v_source_key := v_archive #>> '{source,key}';
  v_source_ledger_fingerprint :=
    v_archive #>> '{source,ledgerFingerprint}';
  v_provenance_fingerprint := public._content_sha256(jsonb_build_object(
    'schemaVersion', 1,
    'commandReceipts', v_archive #> '{ledger,commandReceipts}',
    'auditProvenance', v_archive -> 'auditProvenance'
  ));
  v_archive_core := v_archive - 'archiveFingerprint';
  if jsonb_typeof(v_archive) is distinct from 'object'
    or not (v_archive ?& array[
      'format','formatVersion','source','ledger',
      'auditProvenance','archiveFingerprint'
    ])
    or (
      v_archive - array[
        'format','formatVersion','source','ledger',
        'auditProvenance','archiveFingerprint'
      ]
    ) <> '{}'::jsonb
    or v_archive ->> 'format'
      is distinct from 'settlementforge.custom-content-ledger'
    or v_archive ->> 'formatVersion' is distinct from '1'
    or v_archive_fingerprint !~ '^[0-9a-f]{64}$'
    or public._content_sha256(v_archive_core) <> v_archive_fingerprint
    or v_source_ledger_fingerprint !~ '^[0-9a-f]{64}$'
    or not public._custom_content_archive_source_valid(
      v_archive -> 'source'
    )
    or public._content_sha256(v_archive -> 'ledger')
      <> v_source_ledger_fingerprint
    or nullif(btrim(v_source_key), '') is null
    or char_length(v_source_key) > 240
    or jsonb_typeof(v_archive -> 'auditProvenance')
      is distinct from 'array'
    or not public._custom_content_archive_ledger_valid(
      v_archive -> 'ledger',
      false,
      true
    )
    or not public._custom_content_archive_ledger_valid(
      v_transfer,
      true,
      false
    )
  then
    raise exception 'custom-content archive graph failed admission'
      using errcode = '22023';
  end if;

  if exists (
    with recursive provenance(value) as (
      select item.value
        from jsonb_array_elements(
          v_archive -> 'auditProvenance'
        ) item(value)
      union all
      select child.value
        from provenance parent
        cross join lateral jsonb_array_elements(
          case
            when jsonb_typeof(parent.value -> 'auditProvenance') = 'array'
            then parent.value -> 'auditProvenance'
            else '[]'::jsonb
          end
        ) child(value)
    )
    select 1
      from provenance
     where jsonb_typeof(provenance.value) is distinct from 'object'
        or not (
          provenance.value ?& array[
            'archiveFingerprint','source',
            'commandReceipts','auditProvenance'
          ]
        )
        or (
          provenance.value - array[
            'archiveFingerprint','source',
            'commandReceipts','auditProvenance'
          ]
        ) <> '{}'::jsonb
        or provenance.value ->> 'archiveFingerprint'
          !~ '^[0-9a-f]{64}$'
        or not public._custom_content_archive_source_valid(
          provenance.value -> 'source'
        )
        or jsonb_typeof(provenance.value -> 'commandReceipts')
          is distinct from 'array'
        or jsonb_array_length(
          provenance.value -> 'commandReceipts'
        ) > 10000
        or exists (
          select 1
            from jsonb_array_elements(
              provenance.value -> 'commandReceipts'
            ) receipt(value)
           where jsonb_typeof(receipt.value) is distinct from 'object'
              or not (
                receipt.value ?& array[
                  'commandId','fingerprint','receipt'
                ]
              )
              or (
                receipt.value - array[
                  'commandId','fingerprint','receipt'
                ]
              ) <> '{}'::jsonb
              or nullif(btrim(receipt.value ->> 'commandId'), '') is null
              or char_length(receipt.value ->> 'commandId') > 240
              or receipt.value ->> 'fingerprint' !~ '^[0-9a-f]{64}$'
              or jsonb_typeof(receipt.value -> 'receipt')
                is distinct from 'object'
        )
        or exists (
          select 1
            from jsonb_array_elements(
              provenance.value -> 'commandReceipts'
            ) receipt(value)
           group by receipt.value ->> 'commandId'
          having count(*) > 1
        )
        or jsonb_typeof(provenance.value -> 'auditProvenance')
          is distinct from 'array'
  ) or (
    with recursive provenance(value) as (
      select item.value
        from jsonb_array_elements(
          v_archive -> 'auditProvenance'
        ) item(value)
      union all
      select child.value
        from provenance parent
        cross join lateral jsonb_array_elements(
          case
            when jsonb_typeof(parent.value -> 'auditProvenance') = 'array'
            then parent.value -> 'auditProvenance'
            else '[]'::jsonb
          end
        ) child(value)
    )
    select count(distinct value ->> 'archiveFingerprint') > 128
        or count(distinct value) <>
          count(distinct value ->> 'archiveFingerprint')
      from provenance
  ) then
    raise exception 'custom-content archive provenance failed admission'
      using errcode = '22023';
  end if;

  if jsonb_typeof(v_identity_map) is distinct from 'object'
    or (v_identity_map - array[
      'definitionIds','revisionIds','localUids','packIds',
      'environmentIds','environmentRevisionIds'
    ]) <> '{}'::jsonb
    or not (v_identity_map ?& array[
      'definitionIds','revisionIds','localUids','packIds',
      'environmentIds','environmentRevisionIds'
    ])
    or exists (
      select 1
        from jsonb_each(v_identity_map) mapping_set(key, value)
       where jsonb_typeof(mapping_set.value) is distinct from 'array'
          or jsonb_array_length(mapping_set.value) > 20000
          or exists (
            select 1
              from jsonb_array_elements(mapping_set.value) mapping(value)
             where jsonb_typeof(mapping.value) is distinct from 'object'
                or (
                  mapping_set.key = 'revisionIds'
                  and (
                    not (
                      mapping.value ?& array[
                        'sourceId','destinationId','destinationContentHash'
                      ]
                    )
                    or (
                      mapping.value - array[
                        'sourceId','destinationId','destinationContentHash',
                        'destinationRevisionNumber'
                      ]
                    ) <> '{}'::jsonb
                    or mapping.value ->> 'destinationContentHash'
                      !~ '^[0-9a-f]{64}$'
                    or (
                      mapping.value ? 'destinationRevisionNumber'
                      and (
                        jsonb_typeof(
                          mapping.value -> 'destinationRevisionNumber'
                        ) is distinct from 'number'
                        or coalesce(
                          mapping.value ->> 'destinationRevisionNumber',
                          ''
                        ) !~ '^[1-9][0-9]*$'
                        or (
                          mapping.value ->> 'destinationRevisionNumber'
                        )::numeric > 2147483647
                      )
                    )
                  )
                )
                or (
                  mapping_set.key = 'environmentRevisionIds'
                  and (
                    not (
                      mapping.value ?& array[
                        'sourceId','destinationId',
                        'destinationEnvironmentHash'
                      ]
                    )
                    or (
                      mapping.value - array[
                        'sourceId','destinationId',
                        'destinationEnvironmentHash'
                      ]
                    ) <> '{}'::jsonb
                    or mapping.value ->> 'destinationEnvironmentHash'
                      !~ '^[0-9a-f]{64}$'
                  )
                )
                or (
                  mapping_set.key not in (
                    'revisionIds','environmentRevisionIds'
                  )
                  and (
                    not (
                      mapping.value ?& array[
                        'sourceId','destinationId'
                      ]
                    )
                    or (
                      mapping.value - array[
                        'sourceId','destinationId'
                      ]
                    ) <> '{}'::jsonb
                  )
                )
                or nullif(btrim(mapping.value ->> 'sourceId'), '') is null
                or nullif(btrim(mapping.value ->> 'destinationId'), '') is null
                or char_length(mapping.value ->> 'sourceId') > 240
                or char_length(mapping.value ->> 'destinationId') > 240
          )
          or (
            select count(distinct mapping.value ->> 'sourceId')
              from jsonb_array_elements(mapping_set.value) mapping(value)
          ) <> jsonb_array_length(mapping_set.value)
          or (
            select count(distinct mapping.value ->> 'destinationId')
              from jsonb_array_elements(mapping_set.value) mapping(value)
          ) <> jsonb_array_length(mapping_set.value)
    )
  then
    raise exception 'custom-content archive identity map is invalid'
      using errcode = '22023';
  end if;

  if jsonb_array_length(v_identity_map -> 'definitionIds')
      <> jsonb_array_length(v_archive #> '{ledger,definitions}')
    or jsonb_array_length(v_identity_map -> 'definitionIds')
      <> jsonb_array_length(v_transfer -> 'definitions')
    or jsonb_array_length(v_identity_map -> 'revisionIds')
      <> jsonb_array_length(v_archive #> '{ledger,revisions}')
    or jsonb_array_length(v_identity_map -> 'revisionIds')
      <> jsonb_array_length(v_transfer -> 'revisions')
    or jsonb_array_length(v_identity_map -> 'localUids')
      <> jsonb_array_length(v_archive #> '{ledger,definitions}')
    or jsonb_array_length(v_identity_map -> 'localUids')
      <> jsonb_array_length(v_transfer -> 'definitions')
    or jsonb_array_length(v_identity_map -> 'packIds')
      <> jsonb_array_length(v_archive #> '{ledger,packs}')
    or jsonb_array_length(v_identity_map -> 'packIds')
      <> jsonb_array_length(v_transfer -> 'packs')
    or jsonb_array_length(v_identity_map -> 'environmentIds')
      <> (
        select count(distinct environment.value ->> 'environmentId')
          from jsonb_array_elements(
            v_archive #> '{ledger,environments}'
          ) environment(value)
      )
    or jsonb_array_length(v_identity_map -> 'environmentIds')
      <> (
        select count(distinct environment.value ->> 'environmentId')
          from jsonb_array_elements(
            v_transfer -> 'environments'
          ) environment(value)
      )
    or jsonb_array_length(v_identity_map -> 'environmentRevisionIds')
      <> jsonb_array_length(v_archive #> '{ledger,environments}')
    or jsonb_array_length(v_identity_map -> 'environmentRevisionIds')
      <> jsonb_array_length(v_transfer -> 'environments')
  then
    raise exception 'custom-content archive identity map is incomplete'
      using errcode = '22023';
  end if;

  -- The server proves the client projection rather than trusting a signed
  -- client fingerprint as authority.
  if exists (
    select 1
      from jsonb_array_elements(
        v_archive #> '{ledger,definitions}'
      ) source(value)
      left join jsonb_array_elements(
        v_identity_map -> 'definitionIds'
      ) mapping(value)
        on mapping.value ->> 'sourceId' = source.value ->> 'id'
     where mapping.value ->> 'destinationId' is distinct from
       public._custom_content_archive_destination_uuid(
         v_uid, v_source_key, 'definition', source.value ->> 'id'
       )::text
  ) or exists (
    select 1
      from jsonb_array_elements(
        v_archive #> '{ledger,definitions}'
      ) source(value)
      left join jsonb_array_elements(
        v_identity_map -> 'localUids'
      ) mapping(value)
        on mapping.value ->> 'sourceId' = source.value ->> 'localUid'
     where mapping.value ->> 'destinationId' is distinct from
       public._custom_content_archive_destination_text(
         'lu_import', v_uid, v_source_key, source.value ->> 'localUid'
       )
  ) or exists (
    select 1
      from jsonb_array_elements(
        v_archive #> '{ledger,revisions}'
      ) source(value)
      left join jsonb_array_elements(
        v_identity_map -> 'revisionIds'
      ) mapping(value)
        on mapping.value ->> 'sourceId' = source.value ->> 'id'
     where mapping.value ->> 'destinationId' is distinct from
       public._custom_content_archive_destination_uuid(
         v_uid, v_source_key, 'revision', source.value ->> 'id'
       )::text
  ) or exists (
    select 1
      from jsonb_array_elements(
        v_archive #> '{ledger,packs}'
      ) source(value)
      left join jsonb_array_elements(
        v_identity_map -> 'packIds'
      ) mapping(value)
        on mapping.value ->> 'sourceId' = source.value ->> 'packId'
     where mapping.value ->> 'destinationId' is distinct from
       public._custom_content_archive_destination_text(
         'imported-pack', v_uid, v_source_key, source.value ->> 'packId'
       )
  ) or exists (
    select 1
      from (
        select distinct environment.value ->> 'environmentId' as source_id
          from jsonb_array_elements(
            v_archive #> '{ledger,environments}'
          ) environment(value)
      ) source
      left join jsonb_array_elements(
        v_identity_map -> 'environmentIds'
      ) mapping(value)
        on mapping.value ->> 'sourceId' = source.source_id
     where mapping.value ->> 'destinationId' is distinct from
       public._custom_content_archive_destination_text(
         'imported-environment', v_uid, v_source_key, source.source_id
       )
  ) or exists (
    select 1
      from jsonb_array_elements(
        v_archive #> '{ledger,environments}'
      ) source(value)
      left join jsonb_array_elements(
        v_identity_map -> 'environmentRevisionIds'
      ) mapping(value)
        on mapping.value ->> 'sourceId'
          = source.value ->> 'environmentRevisionId'
     where mapping.value ->> 'destinationId' is distinct from
       public._custom_content_archive_destination_text(
         'imported-environment-revision',
         v_uid,
         v_source_key,
         source.value ->> 'environmentRevisionId'
       )
  ) then
    raise exception 'custom-content archive identity map is not deterministic'
      using errcode = '22023';
  end if;

  if exists (
    select 1
      from jsonb_array_elements(
        v_archive #> '{ledger,definitions}'
      ) source(value)
      join jsonb_array_elements(
        v_identity_map -> 'definitionIds'
      ) id_map(value)
        on id_map.value ->> 'sourceId' = source.value ->> 'id'
      join jsonb_array_elements(
        v_identity_map -> 'localUids'
      ) uid_map(value)
        on uid_map.value ->> 'sourceId' = source.value ->> 'localUid'
      join jsonb_array_elements(
        v_identity_map -> 'revisionIds'
      ) head_map(value)
        on head_map.value ->> 'sourceId'
          = source.value ->> 'headRevisionId'
      left join jsonb_array_elements(
        v_transfer -> 'definitions'
      ) destination(value)
        on destination.value ->> 'id'
          = id_map.value ->> 'destinationId'
     where destination.value is null
        or destination.value ->> 'category'
          is distinct from source.value ->> 'category'
        or destination.value ->> 'localUid'
          is distinct from uid_map.value ->> 'destinationId'
        or destination.value ->> 'headRevisionId'
          is distinct from head_map.value ->> 'destinationId'
        or destination.value -> 'archivedAt'
          is distinct from source.value -> 'archivedAt'
        or destination.value -> 'createdAt'
          is distinct from source.value -> 'createdAt'
        or destination.value -> 'updatedAt'
          is distinct from source.value -> 'updatedAt'
        or jsonb_typeof(destination.value -> 'legacyContentId')
          is distinct from 'null'
  ) or exists (
    select 1
      from jsonb_array_elements(
        v_archive #> '{ledger,revisions}'
      ) source(value)
      join jsonb_array_elements(
        v_identity_map -> 'revisionIds'
      ) revision_map(value)
        on revision_map.value ->> 'sourceId' = source.value ->> 'id'
      join jsonb_array_elements(
        v_identity_map -> 'definitionIds'
      ) definition_map(value)
        on definition_map.value ->> 'sourceId'
          = source.value ->> 'definitionId'
      left join jsonb_array_elements(
        v_identity_map -> 'revisionIds'
      ) parent_map(value)
        on parent_map.value ->> 'sourceId'
          = source.value ->> 'parentRevisionId'
      left join jsonb_array_elements(
        v_transfer -> 'revisions'
      ) destination(value)
        on destination.value ->> 'id'
          = revision_map.value ->> 'destinationId'
     where destination.value is null
        or destination.value ->> 'definitionId'
          is distinct from definition_map.value ->> 'destinationId'
        or destination.value ->> 'category'
          is distinct from source.value ->> 'category'
        or destination.value ->> 'revisionNumber' is distinct from
          case
            when source.value ->> 'category' = 'supplyChains'
              then revision_map.value ->> 'destinationRevisionNumber'
            else source.value ->> 'revisionNumber'
          end
        or destination.value ->> 'parentRevisionId'
          is distinct from parent_map.value ->> 'destinationId'
        or destination.value -> 'createdAt'
          is distinct from source.value -> 'createdAt'
        or destination.value -> 'data' is distinct from
          case
            when source.value ->> 'category' = 'supplyChains'
              then public._reviewed_supply_chain_archive_remap_data(
                source.value -> 'data',
                v_identity_map
              )
            else public._custom_content_archive_remap_data(
              source.value -> 'data',
              v_identity_map -> 'localUids'
            )
          end
        or destination.value ->> 'contentHash' is distinct from
          public._content_sha256(jsonb_build_object(
            'schemaVersion', 1,
            'category', source.value ->> 'category',
            'data', case
              when source.value ->> 'category' = 'supplyChains'
                then public._reviewed_supply_chain_archive_remap_data(
                  source.value -> 'data',
                  v_identity_map
                )
              else public._custom_content_archive_remap_data(
                source.value -> 'data',
                v_identity_map -> 'localUids'
              )
            end
          ))
        or revision_map.value ->> 'destinationContentHash'
          is distinct from destination.value ->> 'contentHash'
  ) then
    raise exception 'custom-content archive definition remap is invalid'
      using errcode = '22023';
  end if;

  if exists (
    select 1
      from jsonb_array_elements(
        v_archive #> '{ledger,packs}'
      ) source(value)
      join jsonb_array_elements(
        v_identity_map -> 'packIds'
      ) pack_map(value)
        on pack_map.value ->> 'sourceId' = source.value ->> 'packId'
      left join jsonb_array_elements(
        v_transfer -> 'packs'
      ) destination(value)
        on destination.value ->> 'packId'
          = pack_map.value ->> 'destinationId'
      left join jsonb_array_elements(
        v_transfer -> 'packVersions'
      ) active_version(value)
        on active_version.value ->> 'packId'
          = pack_map.value ->> 'destinationId'
       and active_version.value ->> 'packVersion'
          = source.value ->> 'activePackVersion'
     where destination.value is null
        or destination.value ->> 'name'
          is distinct from source.value ->> 'name'
        or destination.value ->> 'activePackVersion'
          is distinct from source.value ->> 'activePackVersion'
        or destination.value ->> 'activeManifestHash'
          is distinct from active_version.value ->> 'manifestHash'
        or destination.value -> 'createdAt'
          is distinct from source.value -> 'createdAt'
        or destination.value -> 'updatedAt'
          is distinct from source.value -> 'updatedAt'
  ) or exists (
    select 1
      from jsonb_array_elements(
        v_archive #> '{ledger,packVersions}'
      ) source(value)
      join jsonb_array_elements(
        v_identity_map -> 'packIds'
      ) pack_map(value)
        on pack_map.value ->> 'sourceId' = source.value ->> 'packId'
      left join jsonb_array_elements(
        v_transfer -> 'packVersions'
      ) destination(value)
        on destination.value ->> 'packId'
          = pack_map.value ->> 'destinationId'
       and destination.value ->> 'packVersion'
          = source.value ->> 'packVersion'
     where destination.value is null
        or destination.value -> 'createdAt'
          is distinct from source.value -> 'createdAt'
        or (
          (destination.value -> 'manifest')
          - array['packId','content','manifestHash']
        ) is distinct from (
          (source.value -> 'manifest')
          - array['packId','content','manifestHash']
        )
  ) or exists (
    select 1
      from jsonb_array_elements(
        v_archive #> '{ledger,packEntryDefinitions}'
      ) source(value)
      join jsonb_array_elements(
        v_identity_map -> 'packIds'
      ) pack_map(value)
        on pack_map.value ->> 'sourceId' = source.value ->> 'packId'
      join jsonb_array_elements(
        v_identity_map -> 'definitionIds'
      ) definition_map(value)
        on definition_map.value ->> 'sourceId'
          = source.value ->> 'definitionId'
      left join jsonb_array_elements(
        v_transfer -> 'packEntryDefinitions'
      ) destination(value)
        on destination.value ->> 'packId'
          = pack_map.value ->> 'destinationId'
       and destination.value ->> 'packEntryId'
          = source.value ->> 'packEntryId'
     where destination.value is null
        or destination.value ->> 'definitionId'
          is distinct from definition_map.value ->> 'destinationId'
  ) or exists (
    select 1
      from jsonb_array_elements(
        v_archive #> '{ledger,packVersionEntries}'
      ) source(value)
      join jsonb_array_elements(
        v_identity_map -> 'packIds'
      ) pack_map(value)
        on pack_map.value ->> 'sourceId' = source.value ->> 'packId'
      join jsonb_array_elements(
        v_identity_map -> 'definitionIds'
      ) definition_map(value)
        on definition_map.value ->> 'sourceId'
          = source.value ->> 'definitionId'
      join jsonb_array_elements(
        v_identity_map -> 'revisionIds'
      ) revision_map(value)
        on revision_map.value ->> 'sourceId'
          = source.value ->> 'revisionId'
      left join jsonb_array_elements(
        v_transfer -> 'packVersionEntries'
      ) destination(value)
        on destination.value ->> 'packId'
          = pack_map.value ->> 'destinationId'
       and destination.value ->> 'packVersion'
          = source.value ->> 'packVersion'
       and destination.value ->> 'packEntryId'
          = source.value ->> 'packEntryId'
     where destination.value is null
        or destination.value ->> 'definitionId'
          is distinct from definition_map.value ->> 'destinationId'
        or destination.value ->> 'revisionId'
          is distinct from revision_map.value ->> 'destinationId'
        or destination.value ->> 'category'
          is distinct from source.value ->> 'category'
        or destination.value ->> 'ordinal'
          is distinct from source.value ->> 'ordinal'
  ) then
    raise exception 'custom-content archive pack remap is invalid'
      using errcode = '22023';
  end if;

  if exists (
    select 1
      from jsonb_array_elements(
        v_archive #> '{ledger,environments}'
      ) source(value)
      join jsonb_array_elements(
        v_identity_map -> 'environmentIds'
      ) environment_map(value)
        on environment_map.value ->> 'sourceId'
          = source.value ->> 'environmentId'
      join jsonb_array_elements(
        v_identity_map -> 'environmentRevisionIds'
      ) revision_map(value)
        on revision_map.value ->> 'sourceId'
          = source.value ->> 'environmentRevisionId'
      left join jsonb_array_elements(
        v_transfer -> 'environments'
      ) destination(value)
        on destination.value ->> 'environmentRevisionId'
          = revision_map.value ->> 'destinationId'
     where destination.value is null
        or destination.value ->> 'environmentId'
          is distinct from environment_map.value ->> 'destinationId'
        or destination.value ->> 'revisionNumber' is distinct from
          case
            when source.value ->> 'category' = 'supplyChains'
              then revision_map.value ->> 'destinationRevisionNumber'
            else source.value ->> 'revisionNumber'
          end
        or destination.value ->> 'source'
          is distinct from source.value ->> 'source'
        or destination.value -> 'tunables'
          is distinct from source.value -> 'tunables'
        or destination.value -> 'visualSelection'
          is distinct from source.value -> 'visualSelection'
        or destination.value -> 'createdAt'
          is distinct from source.value -> 'createdAt'
        or revision_map.value ->> 'destinationEnvironmentHash'
          is distinct from destination.value ->> 'environmentHash'
        or jsonb_array_length(destination.value -> 'directDefinitions')
          <> jsonb_array_length(source.value -> 'directDefinitions')
        or jsonb_array_length(destination.value -> 'packVersions')
          <> jsonb_array_length(source.value -> 'packVersions')
        or exists (
          select 1
            from jsonb_array_elements(
              source.value -> 'directDefinitions'
            ) source_direct(value)
            join jsonb_array_elements(
              v_identity_map -> 'definitionIds'
            ) definition_map(value)
              on definition_map.value ->> 'sourceId'
                = source_direct.value ->> 'definitionId'
            join jsonb_array_elements(
              v_identity_map -> 'revisionIds'
            ) direct_revision_map(value)
              on direct_revision_map.value ->> 'sourceId'
                = source_direct.value ->> 'revisionId'
           where not exists (
             select 1
               from jsonb_array_elements(
                 destination.value -> 'directDefinitions'
               ) destination_direct(value)
              where destination_direct.value ->> 'definitionId'
                = definition_map.value ->> 'destinationId'
                and destination_direct.value ->> 'revisionId'
                  = direct_revision_map.value ->> 'destinationId'
                and destination_direct.value ->> 'contentHash'
                  = direct_revision_map.value ->> 'destinationContentHash'
                and destination_direct.value ->> 'category'
                  = source_direct.value ->> 'category'
           )
        )
        or exists (
          select 1
            from jsonb_array_elements(
              source.value -> 'packVersions'
            ) source_binding(value)
            join jsonb_array_elements(
              v_identity_map -> 'packIds'
            ) binding_pack_map(value)
              on binding_pack_map.value ->> 'sourceId'
                = source_binding.value ->> 'packId'
            join jsonb_array_elements(
              v_transfer -> 'packVersions'
            ) destination_version(value)
              on destination_version.value ->> 'packId'
                = binding_pack_map.value ->> 'destinationId'
             and destination_version.value ->> 'packVersion'
                = source_binding.value ->> 'packVersionId'
           where not exists (
             select 1
               from jsonb_array_elements(
                 destination.value -> 'packVersions'
               ) destination_binding(value)
              where destination_binding.value ->> 'packId'
                = binding_pack_map.value ->> 'destinationId'
                and destination_binding.value ->> 'packVersionId'
                  = source_binding.value ->> 'packVersionId'
                and destination_binding.value ->> 'manifestHash'
                  = destination_version.value ->> 'manifestHash'
                and destination_binding.value ->> 'order'
                  = source_binding.value ->> 'order'
           )
        )
  ) or (
    v_archive #>> '{ledger,activeEnvironmentRevisionId}' is null
    and v_transfer ->> 'activeEnvironmentRevisionId' is not null
  ) or (
    v_archive #>> '{ledger,activeEnvironmentRevisionId}' is not null
    and not exists (
      select 1
        from jsonb_array_elements(
          v_identity_map -> 'environmentRevisionIds'
        ) mapping(value)
       where mapping.value ->> 'sourceId'
         = v_archive #>> '{ledger,activeEnvironmentRevisionId}'
         and mapping.value ->> 'destinationId'
           = v_transfer ->> 'activeEnvironmentRevisionId'
    )
  ) then
    raise exception 'custom-content archive environment remap is invalid'
      using errcode = '22023';
  end if;

  -- `exportedAt` and the outer archive fingerprint are transport facts. Once
  -- this exact source ledger and provenance graph has been admitted, another
  -- envelope carrying the same semantic artifact must not consume a journal
  -- row or another unit of the 10k receipt budget.
  perform pg_advisory_xact_lock(
    hashtext('custom-content-owner'),
    hashtext(v_uid::text)
  );
  v_transfer :=
    public._custom_content_archive_normalize_transfer_timestamps(
      v_uid,
      v_transfer
    );
  select jsonb_build_object(
    'ok', true,
    'status', 'applied',
    'reason', null,
    'replayed', true,
    'semanticReplay', true,
    'commandId', p_command_id,
    'fingerprint', p_fingerprint,
    'archiveFingerprint', imported.archive_fingerprint,
    'activationPolicy', v_activation_policy,
    'activationAdopted', false,
    'identityMap', imported.identity_map,
    'counts', jsonb_build_object(
      'definitions', jsonb_array_length(v_transfer -> 'definitions'),
      'revisions', jsonb_array_length(v_transfer -> 'revisions'),
      'packs', jsonb_array_length(v_transfer -> 'packs'),
      'packVersions', jsonb_array_length(v_transfer -> 'packVersions'),
      'packEntries', jsonb_array_length(v_transfer -> 'packVersionEntries'),
      'environments', jsonb_array_length(v_transfer -> 'environments')
    ),
    'importedAt', public._custom_content_archive_timestamp(
      imported.imported_at
    )
  )
    into v_receipt
    from public.custom_content_archive_imports imported
   where imported.owner_id = v_uid
     and imported.source_key = v_source_key
     and imported.source_ledger_fingerprint = v_source_ledger_fingerprint
     and imported.provenance_fingerprint = v_provenance_fingerprint
   order by imported.imported_at
   limit 1;
  if found then return v_receipt; end if;

  v_claim := public.claim_application_command(
    v_uid,
    p_command_id,
    p_fingerprint,
    'content.archive.import',
    null,
    null
  );
  if v_claim ->> 'status' = 'conflict' then
    return jsonb_build_object(
      'ok', false,
      'status', 'failed',
      'reason', 'command_id_conflict',
      'replayed', true,
      'commandId', p_command_id
    );
  end if;
  if coalesce((v_claim ->> 'replayed')::boolean, false)
    and v_claim ->> 'phase' = 'finalized'
    and jsonb_typeof(v_claim -> 'receipt') = 'object'
  then
    return (v_claim -> 'receipt') || jsonb_build_object('replayed', true);
  end if;
  if coalesce((v_claim ->> 'replayed')::boolean, false)
    and v_claim ->> 'phase' = 'finalized'
    and v_claim ->> 'status' = 'failed'
    and jsonb_typeof(v_claim -> 'receipt') is distinct from 'object'
  then
    return jsonb_build_object(
      'ok', false,
      'status', 'failed',
      'reason', coalesce(
        v_claim ->> 'reason',
        'custom_content_archive_limit_exceeded'
      ),
      'replayed', true,
      'commandId', p_command_id,
      'fingerprint', p_fingerprint,
      'archiveFingerprint', v_archive_fingerprint,
      'activationPolicy', v_activation_policy,
      'activationAdopted', false
    );
  end if;

  perform set_config(
    'settlementforge.reviewed_chain_command',
    p_command_id,
    true
  );
  update public.application_command_journal command
     set authority_transaction_id = txid_current()
   where command.owner_id = v_uid
     and command.command_id = p_command_id
     and command.fingerprint = p_fingerprint
     and command.phase = 'claimed'
     and command.status = 'claimed';
  if not found then
    raise exception 'archive import authority was not claimed'
      using errcode = '40001';
  end if;

  -- Different archive envelopes use different command ids, but all mutate one
  -- account constitution. The owner lock closes absent-row races and makes the
  -- pristine activation decision stable through the final write.
  perform pg_advisory_xact_lock(
    hashtext('custom-content-owner'),
    hashtext(v_uid::text)
  );
  perform pg_advisory_xact_lock(hashtext(
    'reviewed-supply-chain-identity:' || v_uid::text || ':'
      || identity.chain_id
  ))
    from (
      select head.value #>> '{data,chainId}' as chain_id
        from jsonb_array_elements(v_transfer -> 'definitions')
          definition(value)
        join jsonb_array_elements(v_transfer -> 'revisions') head(value)
          on head.value ->> 'id'
            = definition.value ->> 'headRevisionId'
       where definition.value ->> 'category' = 'supplyChains'
       order by head.value #>> '{data,chainId}' collate "C"
    ) identity;
  if exists (
    select 1
      from jsonb_array_elements(v_transfer -> 'definitions')
        incoming_definition(value)
      join jsonb_array_elements(v_transfer -> 'revisions')
        incoming_head(value)
        on incoming_head.value ->> 'id'
          = incoming_definition.value ->> 'headRevisionId'
      join public.custom_content_definitions existing_definition
        on existing_definition.owner_id = v_uid
       and existing_definition.category = 'supplyChains'
       and existing_definition.id <> public._content_uuid(
         incoming_definition.value ->> 'id'
       )
      join public.custom_content_revisions existing_head
        on existing_head.owner_id = existing_definition.owner_id
       and existing_head.definition_id = existing_definition.id
       and existing_head.id = existing_definition.head_revision_id
       and existing_head.data ->> 'chainId'
         = incoming_head.value #>> '{data,chainId}'
     where incoming_definition.value ->> 'category' = 'supplyChains'
  ) then
    raise exception 'reviewed supply-chain archive identity exists'
      using errcode = '23505';
  end if;
  select not (
    exists (
      select 1 from public.custom_content_definitions
       where owner_id = v_uid
    )
    or exists (
      select 1 from public.content_packs where owner_id = v_uid
    )
    or exists (
      select 1 from public.content_environments where owner_id = v_uid
    )
    or exists (
      select 1 from public.content_environment_activations
       where owner_id = v_uid
    )
  ) into v_destination_pristine;
  v_activation_adopted :=
    v_activation_policy = 'adopt-if-empty'
    and v_destination_pristine;

  -- Deterministic identities may already exist after an earlier generation of
  -- the same source archive. Existing immutable rows are admitted only when
  -- they are exactly the same graph facts.
  if exists (
    select 1
      from jsonb_array_elements(v_transfer -> 'definitions') item(value)
      join public.custom_content_definitions definition
        on definition.id = public._content_uuid(item.value ->> 'id')
     where definition.owner_id <> v_uid
        or definition.category is distinct from item.value ->> 'category'
        or definition.local_uid is distinct from item.value ->> 'localUid'
        or definition.legacy_content_id is distinct from
          public._content_uuid(item.value ->> 'legacyContentId')
        or definition.created_at is distinct from
          nullif(item.value ->> 'createdAt', '')::timestamptz
  ) or exists (
    select 1
      from jsonb_array_elements(v_transfer -> 'definitions') item(value)
      join public.custom_content_definitions definition
        on definition.owner_id = v_uid
       and definition.local_uid = item.value ->> 'localUid'
     where definition.id <> public._content_uuid(item.value ->> 'id')
  ) or exists (
    select 1
      from jsonb_array_elements(v_transfer -> 'revisions') item(value)
      join public.custom_content_revisions revision
        on revision.id = public._content_uuid(item.value ->> 'id')
        or (
          revision.owner_id = v_uid
          and revision.definition_id =
            public._content_uuid(item.value ->> 'definitionId')
          and revision.revision_no =
            (item.value ->> 'revisionNumber')::integer
        )
     where revision.id <> public._content_uuid(item.value ->> 'id')
        or revision.owner_id <> v_uid
        or revision.definition_id is distinct from
          public._content_uuid(item.value ->> 'definitionId')
        or revision.revision_no is distinct from
          (item.value ->> 'revisionNumber')::integer
        or revision.parent_revision_id is distinct from
          public._content_uuid(item.value ->> 'parentRevisionId')
        or revision.schema_version <> 1
        or revision.content_hash is distinct from item.value ->> 'contentHash'
        or revision.data is distinct from item.value -> 'data'
        or revision.created_at is distinct from
          nullif(item.value ->> 'createdAt', '')::timestamptz
  ) or exists (
    select 1
      from jsonb_array_elements(v_transfer -> 'definitions') item(value)
      join public.custom_content_definitions definition
        on definition.owner_id = v_uid
       and definition.id = public._content_uuid(item.value ->> 'id')
      join public.custom_content_revisions current_head
        on current_head.owner_id = definition.owner_id
       and current_head.definition_id = definition.id
       and current_head.id = definition.head_revision_id
      join jsonb_array_elements(
        v_transfer -> 'revisions'
      ) incoming_head(value)
        on incoming_head.value ->> 'definitionId' = item.value ->> 'id'
       and incoming_head.value ->> 'id' = item.value ->> 'headRevisionId'
     where (
       current_head.revision_no =
         (incoming_head.value ->> 'revisionNumber')::integer
       and current_head.id <>
         public._content_uuid(incoming_head.value ->> 'id')
     ) or (
       current_head.revision_no >
         (incoming_head.value ->> 'revisionNumber')::integer
       and not exists (
         select 1
           from public.custom_content_archive_imports prior_import
          where prior_import.owner_id = v_uid
            and prior_import.source_key = v_source_key
            and prior_import.command_id = current_head.command_id
       )
     ) or (
       current_head.id =
         public._content_uuid(incoming_head.value ->> 'id')
       and definition.updated_at =
         nullif(item.value ->> 'updatedAt', '')::timestamptz
       and definition.archived_at is distinct from
         nullif(item.value ->> 'archivedAt', '')::timestamptz
     ) or (
       (
         current_head.revision_no <
           (incoming_head.value ->> 'revisionNumber')::integer
         or (
           current_head.id =
             public._content_uuid(incoming_head.value ->> 'id')
           and definition.updated_at <
             nullif(item.value ->> 'updatedAt', '')::timestamptz
         )
       )
       and not exists (
         select 1
           from (
             select lifecycle.value
               from public.custom_content_archive_imports prior_import
               cross join lateral jsonb_each(
                 prior_import.destination_definition_lifecycles
               ) lifecycle(key, value)
              where prior_import.owner_id = v_uid
                and prior_import.source_key = v_source_key
                and lifecycle.key = definition.id::text
              order by prior_import.imported_at desc
              limit 1
           ) last_imported
          where definition.updated_at =
              nullif(
                last_imported.value ->> 'updatedAt',
                ''
              )::timestamptz
            and definition.archived_at is not distinct from
              nullif(
                last_imported.value ->> 'archivedAt',
                ''
              )::timestamptz
       )
     )
  ) or exists (
    select 1
      from jsonb_array_elements(v_transfer -> 'packs') item(value)
      join public.content_packs pack
        on pack.owner_id = v_uid
       and pack.pack_id = item.value ->> 'packId'
     where pack.created_at is distinct from
          nullif(item.value ->> 'createdAt', '')::timestamptz
        or (
          pack.updated_at =
            nullif(item.value ->> 'updatedAt', '')::timestamptz
          and pack.name is distinct from item.value ->> 'name'
        )
  ) or exists (
    select 1
      from jsonb_array_elements(v_transfer -> 'packVersions') item(value)
      join public.content_pack_versions version
        on version.owner_id = v_uid
       and version.pack_id = item.value ->> 'packId'
       and version.pack_version = item.value ->> 'packVersion'
     where version.manifest_hash is distinct from
          item.value ->> 'manifestHash'
        or version.import_plan_hash is distinct from
          item.value ->> 'importPlanHash'
        or version.manifest is distinct from item.value -> 'manifest'
        or version.created_at is distinct from
          nullif(item.value ->> 'createdAt', '')::timestamptz
  ) or exists (
    select 1
      from jsonb_array_elements(
        v_transfer -> 'packEntryDefinitions'
      ) item(value)
      join public.content_pack_entry_definitions mapping
        on mapping.owner_id = v_uid
       and mapping.pack_id = item.value ->> 'packId'
       and mapping.pack_entry_id = item.value ->> 'packEntryId'
     where mapping.definition_id is distinct from
          public._content_uuid(item.value ->> 'definitionId')
  ) or exists (
    select 1
      from jsonb_array_elements(
        v_transfer -> 'packVersionEntries'
      ) item(value)
      join public.content_pack_version_entries entry
        on entry.owner_id = v_uid
       and entry.pack_id = item.value ->> 'packId'
       and entry.pack_version = item.value ->> 'packVersion'
       and (
         entry.pack_entry_id = item.value ->> 'packEntryId'
         or entry.ordinal = (item.value ->> 'ordinal')::integer
       )
     where entry.pack_entry_id is distinct from
          item.value ->> 'packEntryId'
        or entry.definition_id is distinct from
          public._content_uuid(item.value ->> 'definitionId')
        or entry.revision_id is distinct from
          public._content_uuid(item.value ->> 'revisionId')
        or entry.category is distinct from item.value ->> 'category'
        or entry.ordinal is distinct from
          (item.value ->> 'ordinal')::integer
  ) or exists (
    select 1
      from jsonb_array_elements(v_transfer -> 'environments') item(value)
      join public.content_environment_revisions environment
        on environment.owner_id = v_uid
       and (
         environment.environment_revision_id
           = item.value ->> 'environmentRevisionId'
         or (
           environment.environment_id = item.value ->> 'environmentId'
           and environment.revision_no
             = (item.value ->> 'revisionNumber')::integer
         )
       )
     where environment.environment_revision_id is distinct from
          item.value ->> 'environmentRevisionId'
        or environment.environment_id is distinct from
          item.value ->> 'environmentId'
        or environment.revision_no is distinct from
          (item.value ->> 'revisionNumber')::integer
        or environment.environment_hash is distinct from
          item.value ->> 'environmentHash'
        or environment.revision is distinct from item.value
        or (
          jsonb_typeof(item.value -> 'createdAt') <> 'null'
          and environment.created_at is distinct from
            nullif(item.value ->> 'createdAt', '')::timestamptz
        )
  ) then
    v_failure_reason := 'custom_content_archive_identity_conflict';
  end if;

  -- Bounds apply to the prospective account graph, not merely to the incoming
  -- payload. This prevents individually valid archives from accumulating into
  -- a destination that can no longer be exported by the same contract.
  if v_failure_reason is null and (
    (
      select count(*) from public.custom_content_definitions definition
       where definition.owner_id = v_uid
         and definition.category in (
           'institutions','services','resources','stressors',
           'tradeGoods','factions','deities','traditions','supplyChains'
         )
    ) + (
      select count(*)
        from jsonb_array_elements(v_transfer -> 'definitions') item(value)
       where not exists (
         select 1 from public.custom_content_definitions definition
          where definition.id = public._content_uuid(item.value ->> 'id')
       )
    ) > 2000
    or (
      select count(*)
        from public.custom_content_revisions revision
        join public.custom_content_definitions definition
          on definition.owner_id = revision.owner_id
         and definition.id = revision.definition_id
       where revision.owner_id = v_uid
         and definition.category in (
           'institutions','services','resources','stressors',
           'tradeGoods','factions','deities','traditions','supplyChains'
         )
    ) + (
      select count(*)
        from jsonb_array_elements(v_transfer -> 'revisions') item(value)
       where not exists (
         select 1 from public.custom_content_revisions revision
          where revision.id = public._content_uuid(item.value ->> 'id')
       )
    ) > 20000
    or (
      select count(*) from public.content_packs
       where owner_id = v_uid
    ) + (
      select count(*)
        from jsonb_array_elements(v_transfer -> 'packs') item(value)
       where not exists (
         select 1 from public.content_packs pack
          where pack.owner_id = v_uid
            and pack.pack_id = item.value ->> 'packId'
       )
    ) > 128
    or (
      select count(*) from public.content_pack_versions
       where owner_id = v_uid
    ) + (
      select count(*)
        from jsonb_array_elements(v_transfer -> 'packVersions') item(value)
       where not exists (
         select 1 from public.content_pack_versions version
          where version.owner_id = v_uid
            and version.pack_id = item.value ->> 'packId'
            and version.pack_version = item.value ->> 'packVersion'
       )
    ) > 1024
    or (
      select count(*) from public.content_pack_entry_definitions
       where owner_id = v_uid
    ) + (
      select count(*)
        from jsonb_array_elements(
          v_transfer -> 'packEntryDefinitions'
        ) item(value)
       where not exists (
         select 1 from public.content_pack_entry_definitions mapping
          where mapping.owner_id = v_uid
            and mapping.pack_id = item.value ->> 'packId'
            and mapping.pack_entry_id = item.value ->> 'packEntryId'
       )
    ) > 20000
    or (
      select count(*) from public.content_pack_version_entries
       where owner_id = v_uid
    ) + (
      select count(*)
        from jsonb_array_elements(
          v_transfer -> 'packVersionEntries'
        ) item(value)
       where not exists (
         select 1 from public.content_pack_version_entries entry
          where entry.owner_id = v_uid
            and entry.pack_id = item.value ->> 'packId'
            and entry.pack_version = item.value ->> 'packVersion'
            and entry.pack_entry_id = item.value ->> 'packEntryId'
       )
    ) > 20000
    or (
      select count(*) from public.content_environment_revisions
       where owner_id = v_uid
    ) + (
      select count(*)
        from jsonb_array_elements(v_transfer -> 'environments') item(value)
       where not exists (
         select 1 from public.content_environment_revisions environment
          where environment.owner_id = v_uid
            and environment.environment_revision_id =
              item.value ->> 'environmentRevisionId'
       )
    ) > 2000
    or (
      select count(*)
        from public.application_command_journal journal
       where journal.owner_id = v_uid
         and journal.kind like 'content.%'
         and jsonb_typeof(journal.receipt) = 'object'
    ) + 1 > 10000
  ) then
    v_failure_reason := 'custom_content_archive_limit_exceeded';
  end if;

  if v_failure_reason is null and exists (
    select 1
      from jsonb_array_elements(v_transfer -> 'definitions') item(value)
      join public.custom_content_definitions definition
        on definition.owner_id = v_uid
       and definition.id = public._content_uuid(item.value ->> 'id')
      join jsonb_array_elements(v_transfer -> 'revisions')
        incoming_head(value)
        on public._content_uuid(incoming_head.value ->> 'id') =
          public._content_uuid(item.value ->> 'headRevisionId')
      left join public.custom_content_revisions current_head
        on current_head.owner_id = definition.owner_id
       and current_head.definition_id = definition.id
       and current_head.id = definition.head_revision_id
     where definition.category = 'supplyChains'
       and definition.reviewed_lifecycle_version >= 2147483647
       and (
         current_head.revision_no
           < (incoming_head.value ->> 'revisionNumber')::integer
         or (
           definition.head_revision_id =
             public._content_uuid(incoming_head.value ->> 'id')
           and (
             definition.archived_at is distinct from
               nullif(item.value ->> 'archivedAt', '')::timestamptz
             or definition.updated_at <
               nullif(item.value ->> 'updatedAt', '')::timestamptz
           )
           and exists (
             select 1
               from public.custom_content_archive_imports imported
               cross join lateral jsonb_each(
                 imported.destination_definition_lifecycles
               ) lifecycle(key, value)
              where imported.owner_id = v_uid
                and imported.source_key = v_source_key
                and lifecycle.key = definition.id::text
                and nullif(
                  lifecycle.value ->> 'updatedAt',
                  ''
                )::timestamptz = definition.updated_at
                and nullif(
                  lifecycle.value ->> 'archivedAt',
                  ''
                )::timestamptz is not distinct from
                  definition.archived_at
           )
         )
       )
  ) then
    v_failure_reason := 'reviewed_supply_chain_lifecycle_exhausted';
  end if;

  if v_failure_reason is not null then
    v_receipt := jsonb_build_object(
      'ok', false,
      'status', 'failed',
      'reason', v_failure_reason,
      'replayed', false,
      'commandId', p_command_id,
      'fingerprint', p_fingerprint,
      'archiveFingerprint', v_archive_fingerprint,
      'activationPolicy', v_activation_policy,
      'activationAdopted', false
    );
    if not public.finalize_application_command(
      v_uid,
      p_command_id,
      p_fingerprint,
      'failed',
      null,
      v_failure_reason
    ) then
      raise exception 'custom-content archive failure did not finalize'
        using errcode = '40001';
    end if;
    return v_receipt;
  end if;

  select coalesce(jsonb_object_agg(
    item.value ->> 'id',
    case
      when definition.id is null then 'created'
      when definition.head_revision_id =
        public._content_uuid(item.value ->> 'headRevisionId')
        and definition.updated_at =
          nullif(item.value ->> 'updatedAt', '')::timestamptz
        and definition.archived_at is not distinct from
          nullif(item.value ->> 'archivedAt', '')::timestamptz
        then 'unchanged'
      when current_head.revision_no >
        (incoming_head.value ->> 'revisionNumber')::integer
        or (
          definition.head_revision_id =
            public._content_uuid(item.value ->> 'headRevisionId')
          and definition.updated_at >
            nullif(item.value ->> 'updatedAt', '')::timestamptz
        )
        then 'stale-preserved'
      else 'fast-forwarded'
    end
  ), '{}'::jsonb)
    into v_definition_outcomes
    from jsonb_array_elements(v_transfer -> 'definitions') item(value)
    left join public.custom_content_definitions definition
      on definition.owner_id = v_uid
     and definition.id = public._content_uuid(item.value ->> 'id')
    left join public.custom_content_revisions current_head
      on current_head.owner_id = definition.owner_id
     and current_head.definition_id = definition.id
     and current_head.id = definition.head_revision_id
    left join jsonb_array_elements(
      v_transfer -> 'revisions'
    ) incoming_head(value)
      on incoming_head.value ->> 'definitionId' = item.value ->> 'id'
     and incoming_head.value ->> 'id' = item.value ->> 'headRevisionId';

  -- A subtransaction makes the final exportability proof atomic with all graph
  -- writes. If the prospective account cannot be represented by this archive
  -- contract, every graph mutation rolls back while the outer command claim is
  -- still available to receive one durable failed receipt.
  begin
  insert into public.custom_content_definitions (
    id, owner_id, category, local_uid, legacy_content_id,
    head_revision_id, archived_at, created_at, updated_at
  )
  select
    public._content_uuid(item.value ->> 'id'),
    v_uid,
    item.value ->> 'category',
    item.value ->> 'localUid',
    public._content_uuid(item.value ->> 'legacyContentId'),
    null,
    nullif(item.value ->> 'archivedAt', '')::timestamptz,
    coalesce(
      nullif(item.value ->> 'createdAt', '')::timestamptz,
      timestamptz '1970-01-01 00:00:00+00'
    ),
    coalesce(
      nullif(item.value ->> 'updatedAt', '')::timestamptz,
      v_now
    )
  from jsonb_array_elements(v_transfer -> 'definitions') item(value)
  on conflict (id) do nothing;

  insert into public.custom_content_revisions (
    id, owner_id, definition_id, revision_no, parent_revision_id,
    schema_version, content_hash, data, command_id, created_at
  )
  select
    public._content_uuid(item.value ->> 'id'),
    v_uid,
    public._content_uuid(item.value ->> 'definitionId'),
    (item.value ->> 'revisionNumber')::integer,
    public._content_uuid(item.value ->> 'parentRevisionId'),
    1,
    item.value ->> 'contentHash',
    item.value -> 'data',
    p_command_id,
    coalesce(
      nullif(item.value ->> 'createdAt', '')::timestamptz,
      timestamptz '1970-01-01 00:00:00+00'
    )
  from jsonb_array_elements(v_transfer -> 'revisions') item(value)
  on conflict (id) do nothing;

  update public.custom_content_definitions definition
     set head_revision_id =
           public._content_uuid(item.value ->> 'headRevisionId'),
         archived_at = case
           when definition.head_revision_id is null
             or (
               definition.updated_at = prior_lifecycle.updated_at
               and definition.archived_at is not distinct from
                 prior_lifecycle.archived_at
             )
           then nullif(item.value ->> 'archivedAt', '')::timestamptz
           else definition.archived_at
         end,
         reviewed_lifecycle_version = case
           when definition.category = 'supplyChains'
             and definition.head_revision_id is not null
             and (
               definition.head_revision_id is distinct from incoming_head.id
               or (
                 definition.updated_at = prior_lifecycle.updated_at
                 and definition.archived_at is not distinct from
                   prior_lifecycle.archived_at
                 and (
                   definition.archived_at is distinct from
                     nullif(
                       item.value ->> 'archivedAt',
                       ''
                     )::timestamptz
                   or definition.updated_at <
                     nullif(
                       item.value ->> 'updatedAt',
                       ''
                     )::timestamptz
                 )
               )
             )
           then definition.reviewed_lifecycle_version + 1
           else definition.reviewed_lifecycle_version
         end,
         updated_at = case
           when definition.head_revision_id is null
             or (
               definition.updated_at = prior_lifecycle.updated_at
               and definition.archived_at is not distinct from
                 prior_lifecycle.archived_at
             )
           then coalesce(
             nullif(item.value ->> 'updatedAt', '')::timestamptz,
             v_now
           )
           else definition.updated_at
         end
    from jsonb_array_elements(v_transfer -> 'definitions') item(value)
    join public.custom_content_revisions incoming_head
      on incoming_head.owner_id = v_uid
     and incoming_head.id =
       public._content_uuid(item.value ->> 'headRevisionId')
    left join (
      select distinct on (lifecycle.key)
        lifecycle.key as destination_id,
        nullif(lifecycle.value ->> 'archivedAt', '')::timestamptz
          as archived_at,
        nullif(lifecycle.value ->> 'updatedAt', '')::timestamptz
          as updated_at
        from public.custom_content_archive_imports imported
        cross join lateral jsonb_each(
          imported.destination_definition_lifecycles
        ) lifecycle(key, value)
       where imported.owner_id = v_uid
         and imported.source_key = v_source_key
       order by lifecycle.key, imported.imported_at desc
    ) prior_lifecycle
      on prior_lifecycle.destination_id = item.value ->> 'id'
   where definition.owner_id = v_uid
     and definition.id = public._content_uuid(item.value ->> 'id')
     and (
       definition.head_revision_id is null
       or (
         select current_head.revision_no
           from public.custom_content_revisions current_head
          where current_head.owner_id = v_uid
            and current_head.id = definition.head_revision_id
       ) < incoming_head.revision_no
       or (
         definition.head_revision_id = incoming_head.id
         and definition.updated_at <
           nullif(item.value ->> 'updatedAt', '')::timestamptz
       )
     );

  insert into public.content_packs (
    owner_id, pack_id, name, created_at, updated_at
  )
  select
    v_uid,
    item.value ->> 'packId',
    item.value ->> 'name',
    coalesce(
      nullif(item.value ->> 'createdAt', '')::timestamptz,
      timestamptz '1970-01-01 00:00:00+00'
    ),
    coalesce(
      nullif(item.value ->> 'updatedAt', '')::timestamptz,
      v_now
    )
  from jsonb_array_elements(v_transfer -> 'packs') item(value)
  on conflict (owner_id, pack_id) do update
    set name = case
          when excluded.updated_at > content_packs.updated_at
            then excluded.name
          else content_packs.name
        end,
        updated_at = greatest(
          content_packs.updated_at,
          excluded.updated_at
        );

  insert into public.content_pack_versions (
    owner_id, pack_id, pack_version, manifest_hash, import_plan_hash,
    manifest, command_id, created_at
  )
  select
    v_uid,
    item.value ->> 'packId',
    item.value ->> 'packVersion',
    item.value ->> 'manifestHash',
    item.value ->> 'importPlanHash',
    item.value -> 'manifest',
    p_command_id,
    coalesce(
      nullif(item.value ->> 'createdAt', '')::timestamptz,
      timestamptz '1970-01-01 00:00:00+00'
    )
  from jsonb_array_elements(v_transfer -> 'packVersions') item(value)
  on conflict (owner_id, pack_id, pack_version) do nothing;

  insert into public.content_pack_entry_definitions (
    owner_id, pack_id, pack_entry_id, definition_id, created_at
  )
  select
    v_uid,
    item.value ->> 'packId',
    item.value ->> 'packEntryId',
    public._content_uuid(item.value ->> 'definitionId'),
    v_now
  from jsonb_array_elements(
    v_transfer -> 'packEntryDefinitions'
  ) item(value)
  on conflict (owner_id, pack_id, pack_entry_id) do nothing;

  insert into public.content_pack_version_entries (
    owner_id, pack_id, pack_version, pack_entry_id,
    definition_id, revision_id, category, ordinal
  )
  select
    v_uid,
    item.value ->> 'packId',
    item.value ->> 'packVersion',
    item.value ->> 'packEntryId',
    public._content_uuid(item.value ->> 'definitionId'),
    public._content_uuid(item.value ->> 'revisionId'),
    item.value ->> 'category',
    (item.value ->> 'ordinal')::integer
  from jsonb_array_elements(
    v_transfer -> 'packVersionEntries'
  ) item(value)
  on conflict (owner_id, pack_id, pack_version, pack_entry_id) do nothing;

  if v_activation_adopted then
    update public.content_packs pack
       set active_pack_version = item.value ->> 'activePackVersion',
           active_manifest_hash = item.value ->> 'activeManifestHash'
      from jsonb_array_elements(v_transfer -> 'packs') item(value)
     where pack.owner_id = v_uid
       and pack.pack_id = item.value ->> 'packId'
       and item.value ->> 'activePackVersion' is not null;
  end if;

  insert into public.content_environments (
    owner_id, environment_id, created_at, updated_at
  )
  select distinct on (item.value ->> 'environmentId')
    v_uid,
    item.value ->> 'environmentId',
    coalesce(
      nullif(item.value ->> 'createdAt', '')::timestamptz,
      timestamptz '1970-01-01 00:00:00+00'
    ),
    v_now
  from jsonb_array_elements(v_transfer -> 'environments') item(value)
  order by
    item.value ->> 'environmentId',
    (item.value ->> 'revisionNumber')::integer
  on conflict (owner_id, environment_id) do update
    set updated_at = excluded.updated_at;

  insert into public.content_environment_revisions (
    owner_id, environment_id, environment_revision_id,
    revision_no, environment_hash, revision, command_id, created_at
  )
  select
    v_uid,
    item.value ->> 'environmentId',
    item.value ->> 'environmentRevisionId',
    (item.value ->> 'revisionNumber')::integer,
    item.value ->> 'environmentHash',
    item.value,
    p_command_id,
    coalesce(
      nullif(item.value ->> 'createdAt', '')::timestamptz,
      timestamptz '1970-01-01 00:00:00+00'
    )
  from jsonb_array_elements(v_transfer -> 'environments') item(value)
  on conflict (owner_id, environment_revision_id) do nothing;

  if v_activation_adopted
    and v_transfer ->> 'activeEnvironmentRevisionId' is not null
  then
    insert into public.content_environment_activations (
      owner_id, environment_revision_id, activated_at
    ) values (
      v_uid,
      v_transfer ->> 'activeEnvironmentRevisionId',
      v_now
    )
    on conflict (owner_id) do update
      set environment_revision_id = excluded.environment_revision_id,
          activated_at = excluded.activated_at;
  end if;

  insert into public.custom_content_archive_imports (
    owner_id, archive_fingerprint, source_key,
    source_ledger_fingerprint, provenance_fingerprint, source_archive,
    identity_map, destination_definition_lifecycles,
    command_id, imported_at
  ) values (
    v_uid, v_archive_fingerprint, v_source_key,
    v_source_ledger_fingerprint,
    v_provenance_fingerprint,
    v_archive,
    v_identity_map,
    (
      select coalesce(jsonb_object_agg(
        definition.id::text,
        jsonb_build_object(
          'headRevisionId', definition.head_revision_id::text,
          'archivedAt', definition.archived_at,
          'updatedAt', definition.updated_at
        )
      ), '{}'::jsonb)
        from public.custom_content_definitions definition
        join jsonb_array_elements(v_transfer -> 'definitions') item(value)
          on definition.id = public._content_uuid(item.value ->> 'id')
       where definition.owner_id = v_uid
    ),
    p_command_id, v_now
  )
  on conflict (
    owner_id, source_key, source_ledger_fingerprint, provenance_fingerprint
  ) do nothing;

  v_receipt := jsonb_build_object(
    'ok', true,
    'status', 'applied',
    'reason', null,
    'replayed', false,
    'commandId', p_command_id,
    'fingerprint', p_fingerprint,
    'archiveFingerprint', v_archive_fingerprint,
    'activationPolicy', v_activation_policy,
    'activationAdopted', v_activation_adopted,
    'identityMap', v_identity_map,
    'definitionOutcomes', v_definition_outcomes,
    'counts', jsonb_build_object(
      'definitions', jsonb_array_length(v_transfer -> 'definitions'),
      'revisions', jsonb_array_length(v_transfer -> 'revisions'),
      'packs', jsonb_array_length(v_transfer -> 'packs'),
      'packVersions', jsonb_array_length(v_transfer -> 'packVersions'),
      'packEntries', jsonb_array_length(v_transfer -> 'packVersionEntries'),
      'environments', jsonb_array_length(v_transfer -> 'environments')
    ),
    'importedAt', public._custom_content_archive_timestamp(v_now)
  );
  if not public.finalize_application_command(
    v_uid,
    p_command_id,
    p_fingerprint,
    'applied',
    v_receipt,
    null
  ) then
    raise exception 'custom-content archive import did not finalize'
      using errcode = '40001';
  end if;

  v_exported_archive := public.export_custom_content_archive(v_uid);
  if octet_length(v_exported_archive::text) > 16 * 1024 * 1024
    or not public._custom_content_archive_source_valid(
      v_exported_archive -> 'source'
    )
    or not public._custom_content_archive_ledger_valid(
      v_exported_archive -> 'ledger',
      true,
      true
    )
    or (
      with recursive provenance(value) as (
        select item.value
          from jsonb_array_elements(
            v_exported_archive -> 'auditProvenance'
          ) item(value)
        union all
        select child.value
          from provenance parent
          cross join lateral jsonb_array_elements(
            parent.value -> 'auditProvenance'
          ) child(value)
      )
      select count(distinct value ->> 'archiveFingerprint') > 128
          or count(distinct value) <>
            count(distinct value ->> 'archiveFingerprint')
        from provenance
    )
  then
    raise exception 'prospective custom-content archive exceeds contract'
      using errcode = 'SF001';
  end if;
  exception when sqlstate 'SF001' then
    v_failure_reason := 'custom_content_archive_limit_exceeded';
  end;

  if v_failure_reason is not null then
    v_receipt := jsonb_build_object(
      'ok', false,
      'status', 'failed',
      'reason', v_failure_reason,
      'replayed', false,
      'commandId', p_command_id,
      'fingerprint', p_fingerprint,
      'archiveFingerprint', v_archive_fingerprint,
      'activationPolicy', v_activation_policy,
      'activationAdopted', false
    );
    if not public.finalize_application_command(
      v_uid,
      p_command_id,
      p_fingerprint,
      'failed',
      null,
      v_failure_reason
    ) then
      raise exception 'custom-content archive failure did not finalize'
        using errcode = '40001';
    end if;
    return v_receipt;
  end if;
  return v_receipt;
end;

_custom_content_archive_normalize_transf:
declare
  v_definitions jsonb;
  v_revisions jsonb;
  v_packs jsonb;
  v_pack_versions jsonb;
  v_environments jsonb;
begin
  select coalesce(jsonb_agg(
    item.value || jsonb_build_object(
      'createdAt',
      public._custom_content_archive_import_timestamp(
        item.value -> 'createdAt',
        definition.created_at
      ),
      'updatedAt',
      public._custom_content_archive_import_timestamp(
        item.value -> 'updatedAt',
        definition.updated_at
      )
    )
    order by item.ordinal
  ), '[]'::jsonb)
    into v_definitions
    from jsonb_array_elements(p_transfer -> 'definitions')
      with ordinality item(value, ordinal)
    left join public.custom_content_definitions definition
      on definition.owner_id = p_owner
     and definition.id = public._content_uuid(item.value ->> 'id');

  select coalesce(jsonb_agg(
    item.value || jsonb_build_object(
      'createdAt',
      public._custom_content_archive_import_timestamp(
        item.value -> 'createdAt',
        revision.created_at
      )
    )
    order by item.ordinal
  ), '[]'::jsonb)
    into v_revisions
    from jsonb_array_elements(p_transfer -> 'revisions')
      with ordinality item(value, ordinal)
    left join public.custom_content_revisions revision
      on revision.owner_id = p_owner
     and revision.id = public._content_uuid(item.value ->> 'id');

  select coalesce(jsonb_agg(
    item.value || jsonb_build_object(
      'createdAt',
      public._custom_content_archive_import_timestamp(
        item.value -> 'createdAt',
        pack.created_at
      ),
      'updatedAt',
      public._custom_content_archive_import_timestamp(
        item.value -> 'updatedAt',
        pack.updated_at
      )
    )
    order by item.ordinal
  ), '[]'::jsonb)
    into v_packs
    from jsonb_array_elements(p_transfer -> 'packs')
      with ordinality item(value, ordinal)
    left join public.content_packs pack
      on pack.owner_id = p_owner
     and pack.pack_id = item.value ->> 'packId';

  select coalesce(jsonb_agg(
    item.value || jsonb_build_object(
      'createdAt',
      public._custom_content_archive_import_timestamp(
        item.value -> 'createdAt',
        version.created_at
      )
    )
    order by item.ordinal
  ), '[]'::jsonb)
    into v_pack_versions
    from jsonb_array_elements(p_transfer -> 'packVersions')
      with ordinality item(value, ordinal)
    left join public.content_pack_versions version
      on version.owner_id = p_owner
     and version.pack_id = item.value ->> 'packId'
     and version.pack_version = item.value ->> 'packVersion';

  -- `createdAt` is deliberately excluded from the environment hash. It is
  -- transport metadata, so normalizing a legacy null does not rewrite the
  -- environment's semantic identity.
  select coalesce(jsonb_agg(
    item.value || jsonb_build_object(
      'createdAt',
      public._custom_content_archive_import_timestamp(
        item.value -> 'createdAt',
        environment.created_at
      )
    )
    order by item.ordinal
  ), '[]'::jsonb)
    into v_environments
    from jsonb_array_elements(p_transfer -> 'environments')
      with ordinality item(value, ordinal)
    left join public.content_environment_revisions environment
      on environment.owner_id = p_owner
     and environment.environment_revision_id =
       item.value ->> 'environmentRevisionId';

  return p_transfer || jsonb_build_object(
    'definitions', v_definitions,
    'revisions', v_revisions,
    'packs', v_packs,
    'packVersions', v_pack_versions,
    'environments', v_environments
  );
end;

_reviewed_supply_chain_text_array_valid(:
begin
  return jsonb_typeof(p_value) = 'array'
    and jsonb_array_length(p_value) <= p_max_entries
    and not exists (
      select 1
        from jsonb_array_elements(p_value) item(value)
       where not public._reviewed_supply_chain_text_valid(
         item.value, 240, false
       )
    );
exception when others then
  return false;
end;

_reviewed_supply_chain_id_for_nodes(p_no:
declare
  v_uids jsonb;
  v_readable text;
begin
  select jsonb_agg(to_jsonb(node.value ->> 'uid') order by node.ordinal),
         string_agg(node.value ->> 'uid', '-' order by node.ordinal)
    into v_uids, v_readable
    from jsonb_array_elements(p_nodes)
      with ordinality node(value, ordinal);
  -- `lower()` is locale/Unicode-table dependent and does not match
  -- JavaScript's case folding. The readable component admits ASCII only, so
  -- translate exactly A-Z and treat every non-ASCII code point as a delimiter.
  v_readable := regexp_replace(
    translate(
      coalesce(v_readable, ''),
      'ABCDEFGHIJKLMNOPQRSTUVWXYZ',
      'abcdefghijklmnopqrstuvwxyz'
    ),
    '[^a-z0-9]+',
    '-',
    'g'
  );
  v_readable := trim(both '-' from v_readable);
  if v_readable = '' then v_readable := 'chain'; end if;
  v_readable := regexp_replace(
    substring(v_readable from 1 for 120),
    '-+$',
    ''
  );
  if v_readable = '' then v_readable := 'chain'; end if;
  return 'discovered.' || v_readable || '.'
    || public._content_sha256(jsonb_build_object('nodeUids', v_uids));
exception when others then
  return null;
end;

_reviewed_supply_chain_projection(p_data:
declare
  v_nodes jsonb;
  v_edges jsonb;
  v_imports jsonb;
  v_exports jsonb;
begin
  select jsonb_agg(jsonb_build_object(
    'uid', node.value -> 'uid',
    'name', node.value -> 'name',
    'kind', node.value -> 'kind',
    'role', node.value -> 'role',
    'refId', node.value -> 'refId',
    'source', node.value -> 'source',
    'tierMin', node.value -> 'tierMin',
    'tierMax', node.value -> 'tierMax',
    'definitionId', node.value -> 'definitionId',
    'revisionId', node.value -> 'revisionId',
    'revisionNumber', node.value -> 'revisionNumber',
    'contentHash', node.value -> 'contentHash'
  ) order by node.ordinal)
    into v_nodes
    from jsonb_array_elements(p_data #> '{discovered,nodes}')
      with ordinality node(value, ordinal);

  select coalesce(jsonb_agg(jsonb_build_object(
    'from', edge.value -> 'from',
    'to', edge.value -> 'to',
    'commodity', edge.value -> 'commodity'
  ) order by edge.ordinal), '[]'::jsonb)
    into v_edges
    from jsonb_array_elements(p_data #> '{discovered,edges}')
      with ordinality edge(value, ordinal);

  select coalesce(jsonb_agg(jsonb_build_object(
    'label', endpoint.value -> 'label',
    'source', endpoint.value -> 'source',
    'counterpart', endpoint.value -> 'counterpart'
  ) order by endpoint.ordinal), '[]'::jsonb)
    into v_imports
    from jsonb_array_elements(
      p_data #> '{discovered,tradeEndpoints,imports}'
    ) with ordinality endpoint(value, ordinal);

  select coalesce(jsonb_agg(jsonb_build_object(
    'label', endpoint.value -> 'label',
    'source', endpoint.value -> 'source',
    'counterpart', endpoint.value -> 'counterpart'
  ) order by endpoint.ordinal), '[]'::jsonb)
    into v_exports
    from jsonb_array_elements(
      p_data #> '{discovered,tradeEndpoints,exports}'
    ) with ordinality endpoint(value, ordinal);

  return jsonb_build_object(
    'schemaVersion', 1,
    'chainId', p_data -> 'chainId',
    'nodes', v_nodes,
    'edges', v_edges,
    'tradeEndpoints', jsonb_build_object(
      'imports', v_imports,
      'exports', v_exports
    )
  );
exception when others then
  return null;
end;

_reviewed_supply_chain_record_valid(p_da:
declare
  v_nodes jsonb;
  v_edges jsonb;
  v_endpoints jsonb;
  v_verification jsonb;
  v_review jsonb;
begin
  if jsonb_typeof(p_data) is distinct from 'object'
    or not (p_data ?& array[
      'chainId','status','label','resource','resourceIcon',
      'resourceDepleted','processingInstitutions','outputs','services',
      'exportable','entrepot','upstreamMissing','upstreamNote',
      'needLabel','needIcon','needColor','discovered','verification'
    ])
    or (p_data - array[
      'chainId','status','label','resource','resourceIcon',
      'resourceDepleted','processingInstitutions','outputs','services',
      'exportable','entrepot','upstreamMissing','upstreamNote',
      'needLabel','needIcon','needColor','discovered','verification'
    ]) <> '{}'::jsonb
    or not public._reviewed_supply_chain_text_valid(
      p_data -> 'chainId', 240, false
    )
    or p_data ->> 'status' is distinct from 'confirmed'
    or not public._reviewed_supply_chain_text_valid(
      p_data -> 'label', 1000, false
    )
    or not public._reviewed_supply_chain_text_valid(
      p_data -> 'resource', 240, true
    )
    or jsonb_typeof(p_data -> 'resourceIcon') is distinct from 'string'
    or char_length(p_data ->> 'resourceIcon') > 240
    or jsonb_typeof(p_data -> 'resourceDepleted') is distinct from 'boolean'
    or not public._reviewed_supply_chain_text_array_valid(
      p_data -> 'processingInstitutions', 128
    )
    or not public._reviewed_supply_chain_text_array_valid(
      p_data -> 'outputs', 128
    )
    or not public._reviewed_supply_chain_text_array_valid(
      p_data -> 'services', 128
    )
    or jsonb_typeof(p_data -> 'exportable') is distinct from 'boolean'
    or jsonb_typeof(p_data -> 'entrepot') is distinct from 'boolean'
    or not public._reviewed_supply_chain_text_array_valid(
      p_data -> 'upstreamMissing', 128
    )
    or jsonb_typeof(p_data -> 'upstreamNote') is distinct from 'string'
    or char_length(p_data ->> 'upstreamNote') > 4000
    or not public._reviewed_supply_chain_text_valid(
      p_data -> 'needLabel', 240, false
    )
    or not public._reviewed_supply_chain_text_valid(
      p_data -> 'needIcon', 240, false
    )
    or not public._reviewed_supply_chain_text_valid(
      p_data -> 'needColor', 240, false
    )
  then
    return false;
  end if;

  if jsonb_typeof(p_data -> 'discovered') is distinct from 'object'
    or not ((p_data -> 'discovered') ?& array[
      'nodes','edges','tradeEndpoints'
    ])
    or ((p_data -> 'discovered') - array[
      'nodes','edges','tradeEndpoints'
    ]) <> '{}'::jsonb
  then
    return false;
  end if;
  v_nodes := p_data #> '{discovered,nodes}';
  v_edges := p_data #> '{discovered,edges}';
  v_endpoints := p_data #> '{discovered,tradeEndpoints}';
  if jsonb_typeof(v_nodes) is distinct from 'array'
    or jsonb_array_length(v_nodes) not between 2 and 64
    or jsonb_typeof(v_edges) is distinct from 'array'
    or jsonb_array_length(v_edges) > 256
    or jsonb_typeof(v_endpoints) is distinct from 'object'
    or not (v_endpoints ?& array['imports','exports'])
    or (v_endpoints - array['imports','exports']) <> '{}'::jsonb
    or jsonb_typeof(v_endpoints -> 'imports') is distinct from 'array'
    or jsonb_array_length(v_endpoints -> 'imports') > 128
    or jsonb_typeof(v_endpoints -> 'exports') is distinct from 'array'
    or jsonb_array_length(v_endpoints -> 'exports') > 128
  then
    return false;
  end if;

  if exists (
    select 1
      from jsonb_array_elements(v_nodes) node(value)
     where jsonb_typeof(node.value) is distinct from 'object'
        or not (node.value ?& array[
          'uid','name','kind','role','refId','source','tierMin','tierMax',
          'definitionId','revisionId','revisionNumber','contentHash'
        ])
        or (node.value - array[
          'uid','name','kind','role','refId','source','tierMin','tierMax',
          'definitionId','revisionId','revisionNumber','contentHash'
        ]) <> '{}'::jsonb
        or not public._reviewed_supply_chain_text_valid(
          node.value -> 'uid', 240, false
        )
        or not public._reviewed_supply_chain_text_valid(
          node.value -> 'name', 240, false
        )
        or jsonb_typeof(node.value -> 'kind') is distinct from 'string'
        or node.value ->> 'kind' not in (
          'institution','service','resource','good'
        )
        or jsonb_typeof(node.value -> 'role') is distinct from 'string'
        or node.value ->> 'role' not in ('source','processor','sink')
        or jsonb_typeof(node.value -> 'source') is distinct from 'string'
        or node.value ->> 'source' not in (
          'custom','prebuilt','reference'
        )
        or not public._reviewed_supply_chain_text_valid(
          node.value -> 'tierMin', 240, true
        )
        or not public._reviewed_supply_chain_text_valid(
          node.value -> 'tierMax', 240, true
        )
        or (
          node.value ->> 'tierMin' is not null
          and node.value ->> 'tierMin' not in (
            'thorp','hamlet','village','town','city','metropolis'
          )
        )
        or (
          node.value ->> 'tierMax' is not null
          and node.value ->> 'tierMax' not in (
            'thorp','hamlet','village','town','city','metropolis'
          )
        )
        or coalesce(array_position(
          array['thorp','hamlet','village','town','city','metropolis'],
          node.value ->> 'tierMin'
        ), 1) > coalesce(array_position(
          array['thorp','hamlet','village','town','city','metropolis'],
          node.value ->> 'tierMax'
        ), 6)
        or (
          node.value ->> 'source' = 'custom'
          and (
            not public._reviewed_supply_chain_text_valid(
              node.value -> 'refId', 240, false
            )
            or node.value ->> 'refId'
              is distinct from 'custom:' || (node.value ->> 'uid')
            or not public._reviewed_supply_chain_text_valid(
              node.value -> 'definitionId', 240, false
            )
            or not public._reviewed_supply_chain_text_valid(
              node.value -> 'revisionId', 240, false
            )
            or jsonb_typeof(node.value -> 'revisionNumber')
              is distinct from 'number'
            or coalesce(node.value ->> 'revisionNumber', '')
              !~ '^[1-9][0-9]*$'
            or (node.value ->> 'revisionNumber')::numeric > 2147483647
            or jsonb_typeof(node.value -> 'contentHash')
              is distinct from 'string'
            or coalesce(node.value ->> 'contentHash', '')
              !~ '^[0-9a-f]{64}$'
          )
        )
        or (
          node.value ->> 'source' = 'prebuilt'
          and (
            not public._reviewed_supply_chain_text_valid(
              node.value -> 'refId', 240, false
            )
            or left(node.value ->> 'refId', 9) <> 'prebuilt:'
            or jsonb_typeof(node.value -> 'definitionId') <> 'null'
            or jsonb_typeof(node.value -> 'revisionId') <> 'null'
            or jsonb_typeof(node.value -> 'revisionNumber') <> 'null'
            or jsonb_typeof(node.value -> 'contentHash') <> 'null'
          )
        )
        or (
          node.value ->> 'source' = 'reference'
          and (
            jsonb_typeof(node.value -> 'refId') <> 'null'
            or jsonb_typeof(node.value -> 'definitionId') <> 'null'
            or jsonb_typeof(node.value -> 'revisionId') <> 'null'
            or jsonb_typeof(node.value -> 'revisionNumber') <> 'null'
            or jsonb_typeof(node.value -> 'contentHash') <> 'null'
          )
        )
  ) or (
    select count(distinct node.value ->> 'uid')
      from jsonb_array_elements(v_nodes) node(value)
  ) <> jsonb_array_length(v_nodes)
  then
    return false;
  end if;

  if p_data ->> 'chainId'
    is distinct from public._reviewed_supply_chain_id_for_nodes(v_nodes)
  then
    return false;
  end if;

  if exists (
    select 1
      from jsonb_array_elements(v_edges) edge(value)
     where jsonb_typeof(edge.value) is distinct from 'object'
        or not (edge.value ?& array['from','to','commodity'])
        or (edge.value - array['from','to','commodity']) <> '{}'::jsonb
        or not public._reviewed_supply_chain_text_valid(
          edge.value -> 'from', 240, false
        )
        or not public._reviewed_supply_chain_text_valid(
          edge.value -> 'to', 240, false
        )
        or not public._reviewed_supply_chain_text_valid(
          edge.value -> 'commodity', 240, false
        )
        or edge.value ->> 'from' = edge.value ->> 'to'
        or not exists (
          select 1 from jsonb_array_elements(v_nodes) node(value)
           where node.value ->> 'uid' = edge.value ->> 'from'
        )
        or not exists (
          select 1 from jsonb_array_elements(v_nodes) node(value)
           where node.value ->> 'uid' = edge.value ->> 'to'
        )
  ) or exists (
    select 1
      from jsonb_array_elements(v_edges) edge(value)
     group by edge.value ->> 'from',
              edge.value ->> 'to',
              edge.value ->> 'commodity'
    having count(*) > 1
  ) then
    return false;
  end if;

  if exists (
    select 1
      from jsonb_array_elements(
        (v_endpoints -> 'imports') || (v_endpoints -> 'exports')
      ) endpoint(value)
     where jsonb_typeof(endpoint.value) is distinct from 'object'
        or not (endpoint.value ?& array['label','source','counterpart'])
        or (endpoint.value - array[
          'label','source','counterpart'
        ]) <> '{}'::jsonb
        or not public._reviewed_supply_chain_text_valid(
          endpoint.value -> 'label', 240, false
        )
        or not public._reviewed_supply_chain_text_valid(
          endpoint.value -> 'source', 240, true
        )
        or not public._reviewed_supply_chain_text_valid(
          endpoint.value -> 'counterpart', 240, true
        )
  ) then
    return false;
  end if;

  v_verification := p_data -> 'verification';
  if jsonb_typeof(v_verification) is distinct from 'object'
    or not (v_verification ?& array[
      'state','userName','corrections','review'
    ])
    or (v_verification - array[
      'state','userName','corrections','review'
    ]) <> '{}'::jsonb
    or v_verification ->> 'state' is distinct from 'confirmed'
    or not public._reviewed_supply_chain_text_valid(
      v_verification -> 'userName', 1000, true
    )
    or v_verification -> 'corrections' <> '{}'::jsonb
  then
    return false;
  end if;
  v_review := v_verification -> 'review';
  if jsonb_typeof(v_review) is distinct from 'object'
    or not (v_review ?& array[
      'schemaVersion','projectionFingerprint'
    ])
    or (v_review - array[
      'schemaVersion','projectionFingerprint'
    ]) <> '{}'::jsonb
    or jsonb_typeof(v_review -> 'schemaVersion') is distinct from 'number'
    or v_review -> 'schemaVersion' is distinct from '1'::jsonb
    or jsonb_typeof(v_review -> 'projectionFingerprint')
      is distinct from 'string'
    or coalesce(v_review ->> 'projectionFingerprint', '')
      !~ '^[0-9a-f]{64}$'
    or v_review ->> 'projectionFingerprint' is distinct from
      public._reviewed_supply_chain_projection_fingerprint(p_data)
  then
    return false;
  end if;
  return true;
exception when others then
  return false;
end;

_reviewed_supply_chain_archive_remap_dat:
declare
  v_result jsonb := p_data;
  v_nodes jsonb;
  v_edges jsonb;
  v_fingerprint text;
begin
  if not public._reviewed_supply_chain_record_valid(p_data)
    or jsonb_typeof(p_identity_map) is distinct from 'object'
  then
    return null;
  end if;

  select jsonb_agg(
    case
      when node.value ->> 'source' <> 'custom' then node.value
      else node.value || jsonb_build_object(
        'uid', uid_map.value ->> 'destinationId',
        'refId', 'custom:' || (uid_map.value ->> 'destinationId'),
        'definitionId', definition_map.value ->> 'destinationId',
        'revisionId', revision_map.value ->> 'destinationId',
        'revisionNumber',
          (revision_map.value ->> 'destinationRevisionNumber')::integer,
        'contentHash', revision_map.value ->> 'destinationContentHash'
      )
    end
    order by node.ordinal
  )
    into v_nodes
    from jsonb_array_elements(p_data #> '{discovered,nodes}')
      with ordinality node(value, ordinal)
    left join jsonb_array_elements(p_identity_map -> 'localUids')
      uid_map(value)
      on node.value ->> 'source' = 'custom'
     and uid_map.value ->> 'sourceId' = node.value ->> 'uid'
    left join jsonb_array_elements(p_identity_map -> 'definitionIds')
      definition_map(value)
      on node.value ->> 'source' = 'custom'
     and definition_map.value ->> 'sourceId'
       = node.value ->> 'definitionId'
    left join jsonb_array_elements(p_identity_map -> 'revisionIds')
      revision_map(value)
      on node.value ->> 'source' = 'custom'
     and revision_map.value ->> 'sourceId'
       = node.value ->> 'revisionId';

  if exists (
    select 1 from jsonb_array_elements(v_nodes) node(value)
     where node.value ->> 'source' = 'custom'
       and (
         nullif(node.value ->> 'uid', '') is null
         or nullif(node.value ->> 'definitionId', '') is null
         or nullif(node.value ->> 'revisionId', '') is null
         or jsonb_typeof(node.value -> 'revisionNumber') <> 'number'
         or (node.value ->> 'revisionNumber')::numeric <> trunc(
           (node.value ->> 'revisionNumber')::numeric
         )
         or (node.value ->> 'revisionNumber')::numeric not between 1
           and 2147483647
         or coalesce(node.value ->> 'contentHash', '')
           !~ '^[0-9a-f]{64}$'
       )
  ) then
    return null;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'from', coalesce(uid_map_from.value ->> 'destinationId',
                     edge.value ->> 'from'),
    'to', coalesce(uid_map_to.value ->> 'destinationId',
                   edge.value ->> 'to'),
    'commodity', edge.value -> 'commodity'
  ) order by edge.ordinal), '[]'::jsonb)
    into v_edges
    from jsonb_array_elements(p_data #> '{discovered,edges}')
      with ordinality edge(value, ordinal)
    left join jsonb_array_elements(p_identity_map -> 'localUids')
      uid_map_from(value)
      on uid_map_from.value ->> 'sourceId' = edge.value ->> 'from'
    left join jsonb_array_elements(p_identity_map -> 'localUids')
      uid_map_to(value)
      on uid_map_to.value ->> 'sourceId' = edge.value ->> 'to';

  v_result := jsonb_set(v_result, '{discovered,nodes}', v_nodes, false);
  v_result := jsonb_set(v_result, '{discovered,edges}', v_edges, false);
  v_result := jsonb_set(
    v_result,
    '{chainId}',
    to_jsonb(public._reviewed_supply_chain_id_for_nodes(v_nodes)),
    false
  );
  v_fingerprint :=
    public._reviewed_supply_chain_projection_fingerprint(v_result);
  v_result := jsonb_set(
    v_result,
    '{verification,review,projectionFingerprint}',
    to_jsonb(v_fingerprint),
    false
  );
  if not public._reviewed_supply_chain_record_valid(v_result) then
    return null;
  end if;
  return v_result;
exception when others then
  return null;
end;

apply_reviewed_supply_chain_command(p_ex:
declare
  v_uid uuid := auth.uid();
  v_kind text;
  v_artifact_id uuid;
  v_expected_head_id uuid;
  v_expected_lifecycle_version integer;
  v_chain jsonb;
  v_chain_id text;
  v_fingerprint text;
  v_claim jsonb;
  v_now timestamptz := clock_timestamp();
  v_definition public.custom_content_definitions%rowtype;
  v_revision public.custom_content_revisions%rowtype;
  v_evidence_definition public.custom_content_definitions%rowtype;
  v_evidence_revision public.custom_content_revisions%rowtype;
  v_node jsonb;
  v_existing boolean := false;
  v_conflict public.custom_content_definitions%rowtype;
  v_content_hash text;
  v_revision_id uuid;
  v_revision_no integer;
  v_parent_revision_id uuid;
  v_local_uid text;
  v_item jsonb := null;
  v_archived_item jsonb := null;
  v_entry_status text;
  v_was_archived boolean := false;
  v_reason text := null;
  v_failure_status text := 'failed';
  v_result jsonb;
  v_response jsonb;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if p_expected_owner is null or p_expected_owner <> v_uid then
    raise exception 'reviewed supply-chain owner changed'
      using errcode = '42501';
  end if;
  if not public.account_is_active(v_uid)
    or not public.current_user_has_premium_access()
  then
    raise exception 'active premium account required' using errcode = '42501';
  end if;
  if nullif(btrim(p_command_id), '') is null
    or char_length(p_command_id) > 240
    or coalesce(p_preview_fingerprint, '') !~ '^[0-9a-f]{64}$'
    or jsonb_typeof(p_plan) is distinct from 'object'
    or octet_length(p_plan::text) > 4194304
    or not (p_plan ?& array[
      'schemaVersion','kind','artifactId','expectedHeadRevisionId',
      'expectedLifecycleVersion','chain'
    ])
    or (p_plan - array[
      'schemaVersion','kind','artifactId','expectedHeadRevisionId',
      'expectedLifecycleVersion','chain'
    ]) <> '{}'::jsonb
    or jsonb_typeof(p_plan -> 'schemaVersion') is distinct from 'number'
    or p_plan -> 'schemaVersion' is distinct from '1'::jsonb
    or jsonb_typeof(p_plan -> 'kind') is distinct from 'string'
    or jsonb_typeof(p_plan -> 'artifactId') is distinct from 'string'
    or jsonb_typeof(p_plan -> 'expectedHeadRevisionId')
      not in ('null','string')
    or jsonb_typeof(p_plan -> 'expectedLifecycleVersion')
      not in ('null','number')
  then
    raise exception 'invalid reviewed supply-chain command envelope'
      using errcode = '22023';
  end if;

  v_kind := p_plan ->> 'kind';
  v_artifact_id := public._content_uuid(p_plan ->> 'artifactId');
  v_expected_head_id := public._content_uuid(
    p_plan ->> 'expectedHeadRevisionId'
  );
  if jsonb_typeof(p_plan -> 'expectedLifecycleVersion') = 'number' then
    if coalesce(p_plan ->> 'expectedLifecycleVersion', '')
        !~ '^[1-9][0-9]*$'
      or (p_plan ->> 'expectedLifecycleVersion')::numeric > 2147483647
    then
      raise exception 'invalid reviewed supply-chain lifecycle version'
        using errcode = '22023';
    end if;
    v_expected_lifecycle_version :=
      (p_plan ->> 'expectedLifecycleVersion')::integer;
  else
    v_expected_lifecycle_version := null;
  end if;
  if v_artifact_id is null
    or v_kind not in (
      'content.reviewed-supply-chain.confirm',
      'content.reviewed-supply-chain.remove'
    )
    or (
      p_plan ->> 'expectedHeadRevisionId' is not null
      and v_expected_head_id is null
    )
  then
    raise exception 'unsupported reviewed supply-chain command plan'
      using errcode = '22023';
  end if;

  if v_kind = 'content.reviewed-supply-chain.confirm' then
    v_chain := p_plan -> 'chain';
    if not public._reviewed_supply_chain_record_valid(v_chain) then
      raise exception 'reviewed supply-chain failed exact admission'
        using errcode = '22023';
    end if;
    v_chain_id := v_chain ->> 'chainId';
    v_content_hash :=
      public._reviewed_supply_chain_content_hash(v_chain);
  elsif jsonb_typeof(p_plan -> 'chain') <> 'null'
    or v_expected_head_id is null
    or v_expected_lifecycle_version is null
  then
    raise exception 'reviewed supply-chain removal is incomplete'
      using errcode = '22023';
  end if;

  v_fingerprint := public._content_sha256(p_plan);
  if v_fingerprint <> p_preview_fingerprint then
    raise exception 'reviewed supply-chain preview fingerprint mismatch'
      using errcode = '22023';
  end if;

  -- Every custom-content mutation lane takes the owner lock before it can
  -- claim a caller-selected journal identity. This single global order avoids
  -- an archive/reviewed deadlock on the same owner and command id.
  perform pg_advisory_xact_lock(
    hashtext('custom-content-owner'),
    hashtext(v_uid::text)
  );

  v_claim := public.claim_application_command(
    v_uid,
    p_command_id,
    v_fingerprint,
    v_kind,
    v_artifact_id,
    null
  );
  if v_claim ->> 'status' = 'conflict' then
    return jsonb_build_object(
      'ok', false,
      'status', 'failed',
      'reason', 'command_id_conflict',
      'replayed', true,
      'commandId', p_command_id,
      'fingerprint', v_fingerprint,
      'existingFingerprint', v_claim ->> 'fingerprint',
      'result', jsonb_build_object(
        'artifactId', v_artifact_id,
        'item', null,
        'archivedItem', null,
        'headRevisionId', null
      ),
      'perEntry', '[]'::jsonb
    );
  end if;
  if v_claim ->> 'phase' = 'finalized'
    and v_claim -> 'receipt' is not null
  then
    return (v_claim -> 'receipt') || jsonb_build_object('replayed', true);
  end if;
  if v_claim ->> 'status' = 'reconcile-required' then
    return jsonb_build_object(
      'ok', false,
      'status', 'reconcile-required',
      'commandId', p_command_id,
      'reason', coalesce(
        v_claim ->> 'reason',
        'command_requires_reconciliation'
      ),
      'replayed', true,
      'fingerprint', v_fingerprint,
      'result', jsonb_build_object(
        'artifactId', v_artifact_id,
        'item', null,
        'archivedItem', null,
        'headRevisionId', null
      ),
      'perEntry', '[]'::jsonb
    );
  end if;

  perform set_config(
    'settlementforge.reviewed_chain_command',
    p_command_id,
    true
  );
  update public.application_command_journal command
     set authority_transaction_id = txid_current()
   where command.owner_id = v_uid
     and command.command_id = p_command_id
     and command.fingerprint = v_fingerprint
     and command.phase = 'claimed'
     and command.status = 'claimed';
  if not found then
    raise exception 'reviewed supply-chain command authority was not claimed'
      using errcode = '40001';
  end if;
  perform pg_advisory_xact_lock(hashtext(
    'reviewed-supply-chain-artifact:'
      || v_uid::text || ':' || v_artifact_id::text
  ));
  if v_chain_id is not null then
    perform pg_advisory_xact_lock(hashtext(
      'reviewed-supply-chain-identity:'
        || v_uid::text || ':' || v_chain_id
    ));
  end if;

  select *
    into v_definition
    from public.custom_content_definitions definition
   where definition.owner_id = v_uid
     and definition.id = v_artifact_id
   for update;
  v_existing := found;
  v_was_archived := v_existing and v_definition.archived_at is not null;
  if v_existing and v_definition.category = 'supplyChains' then
    select *
      into strict v_revision
      from public.custom_content_revisions revision
     where revision.owner_id = v_uid
       and revision.definition_id = v_artifact_id
       and revision.id = v_definition.head_revision_id;
  end if;

  if v_existing and v_definition.category <> 'supplyChains' then
    v_reason := 'reviewed_artifact_category_immutable';
  elsif v_existing
    and (
      v_definition.reviewed_lifecycle_version is null
      or v_definition.reviewed_lifecycle_version < 1
    )
  then
    v_reason := 'reviewed_supply_chain_lifecycle_invalid';
  elsif v_existing
    and v_kind = 'content.reviewed-supply-chain.confirm'
    and v_revision.data ->> 'chainId' is distinct from v_chain_id
  then
    v_reason := 'reviewed_supply_chain_identity_immutable';
  elsif v_existing
    and v_definition.head_revision_id is distinct from v_expected_head_id
  then
    v_reason := 'reviewed_supply_chain_head_changed';
    v_failure_status := 'stale';
  elsif v_existing
    and v_definition.reviewed_lifecycle_version
      is distinct from v_expected_lifecycle_version
  then
    v_reason := 'reviewed_supply_chain_lifecycle_changed';
    v_failure_status := 'stale';
  elsif not v_existing
    and (
      v_expected_head_id is not null
      or v_expected_lifecycle_version is not null
    )
  then
    v_reason := 'reviewed_supply_chain_unavailable';
    v_failure_status := 'stale';
  elsif v_existing
    and v_definition.reviewed_lifecycle_version >= 2147483647
    and (
      (
        v_kind = 'content.reviewed-supply-chain.confirm'
        and (
          v_definition.archived_at is not null
          or v_revision.content_hash is distinct from v_content_hash
        )
      )
      or (
        v_kind = 'content.reviewed-supply-chain.remove'
        and v_definition.archived_at is null
      )
    )
  then
    v_reason := 'reviewed_supply_chain_lifecycle_exhausted';
  end if;

  if v_reason is null
    and v_kind = 'content.reviewed-supply-chain.confirm'
  then
    for v_node in
      select node.value
        from jsonb_array_elements(
          v_chain #> '{discovered,nodes}'
        ) node(value)
       where node.value ->> 'source' = 'custom'
       order by node.value ->> 'definitionId' collate "C"
    loop
      select *
        into v_evidence_definition
        from public.custom_content_definitions definition
       where definition.owner_id = v_uid
         and definition.id =
           public._content_uuid(v_node ->> 'definitionId')
       for update;
      if not found then
        v_reason := 'reviewed_supply_chain_node_evidence_mismatch';
        v_failure_status := 'stale';
        exit;
      end if;
      select *
        into v_evidence_revision
        from public.custom_content_revisions revision
       where revision.owner_id = v_uid
         and revision.definition_id = v_evidence_definition.id
         and revision.id = public._content_uuid(v_node ->> 'revisionId');
      if not found
        or v_evidence_definition.category is distinct from (
          case
            when v_node ->> 'kind' = 'institution' then 'institutions'
            when v_node ->> 'kind' = 'service' then 'services'
            when v_node ->> 'kind' = 'resource' then 'resources'
            when v_node ->> 'kind' = 'good' then 'tradeGoods'
            else null
          end
        )
        or v_evidence_definition.local_uid
          is distinct from v_node ->> 'uid'
        or v_evidence_definition.archived_at is not null
        or v_evidence_definition.head_revision_id
          is distinct from v_evidence_revision.id
        or v_evidence_revision.revision_no
          is distinct from (v_node ->> 'revisionNumber')::integer
        or v_evidence_revision.content_hash
          is distinct from v_node ->> 'contentHash'
        or v_evidence_revision.content_hash is distinct from
          public._content_sha256(jsonb_build_object(
            'schemaVersion', 1,
            'category', v_evidence_definition.category,
            'data', v_evidence_revision.data
          ))
      then
        v_reason := 'reviewed_supply_chain_node_evidence_mismatch';
        v_failure_status := 'stale';
        exit;
      end if;
    end loop;
  end if;

  if v_reason is null
    and v_kind = 'content.reviewed-supply-chain.confirm'
  then
    select definition.*
      into v_conflict
      from public.custom_content_definitions definition
      join public.custom_content_revisions revision
        on revision.owner_id = definition.owner_id
       and revision.definition_id = definition.id
       and revision.id = definition.head_revision_id
     where definition.owner_id = v_uid
       and definition.category = 'supplyChains'
       and definition.id <> v_artifact_id
       and revision.data ->> 'chainId' = v_chain_id
     order by definition.id
     limit 1
     for update of definition;
    if found then
      v_reason := 'reviewed_supply_chain_identity_exists';
      v_failure_status := 'stale';
    end if;
  end if;

  if v_reason is null
    and v_kind = 'content.reviewed-supply-chain.remove'
    and not v_existing
  then
    v_reason := 'reviewed_supply_chain_unavailable';
    v_failure_status := 'stale';
  end if;

  if v_reason is not null then
    v_result := jsonb_build_object(
      'artifactId', v_artifact_id,
      'item', null,
      'archivedItem', null,
      'headRevisionId', case
        when v_existing then v_definition.head_revision_id
        else null
      end,
      'conflictingArtifactId', case
        when v_conflict.id is not null then v_conflict.id
        else null
      end
    );
    v_response := jsonb_build_object(
      'ok', false,
      'status', v_failure_status,
      'commandId', p_command_id,
      'reason', v_reason,
      'replayed', false,
      'fingerprint', v_fingerprint,
      'result', v_result,
      'perEntry', '[]'::jsonb
    );
    if not public.finalize_application_command(
      v_uid, p_command_id, v_fingerprint,
      v_failure_status, v_response, v_reason
    ) then
      raise exception 'reviewed supply-chain command did not finalize'
        using errcode = '40001';
    end if;
    return v_response;
  end if;

  if v_kind = 'content.reviewed-supply-chain.confirm' then
    if v_existing and v_revision.content_hash = v_content_hash then
      if v_was_archived then
        update public.custom_content_definitions
           set archived_at = null,
               updated_at = v_now,
               reviewed_lifecycle_version =
                 reviewed_lifecycle_version + 1
         where owner_id = v_uid
           and id = v_artifact_id
         returning * into strict v_definition;
      end if;
      v_revision_id := v_revision.id;
      v_revision_no := v_revision.revision_no;
      v_entry_status := case
        when v_was_archived then 'restored'
        else 'unchanged'
      end;
    else
      v_parent_revision_id := case
        when v_existing then v_definition.head_revision_id
        else null
      end;
      v_revision_no := case
        when v_existing then v_revision.revision_no + 1
        else 1
      end;
      v_revision_id := gen_random_uuid();
      if not v_existing then
        v_local_uid := 'reviewed-chain:' || substring(
          public._content_sha256(to_jsonb(v_chain_id))
          from 1 for 32
        );
        insert into public.custom_content_definitions (
          id, owner_id, category, local_uid, head_revision_id,
          archived_at, created_at, updated_at,
          reviewed_lifecycle_version
        ) values (
          v_artifact_id, v_uid, 'supplyChains', v_local_uid, null,
          null, v_now, v_now, 1
        )
        returning * into strict v_definition;
      end if;
      insert into public.custom_content_revisions (
        id, owner_id, definition_id, revision_no, parent_revision_id,
        schema_version, content_hash, data, command_id, created_at
      ) values (
        v_revision_id, v_uid, v_artifact_id, v_revision_no,
        v_parent_revision_id, 1, v_content_hash, v_chain, p_command_id, v_now
      )
      returning * into strict v_revision;
      update public.custom_content_definitions
         set head_revision_id = v_revision_id,
             archived_at = null,
             updated_at = v_now,
             reviewed_lifecycle_version = case
               when v_existing then reviewed_lifecycle_version + 1
               else reviewed_lifecycle_version
             end
       where owner_id = v_uid
         and id = v_artifact_id
       returning * into strict v_definition;
      v_entry_status := case
        when not v_existing then 'created'
        when v_was_archived then 'restored'
        else 'updated'
      end;
    end if;
    v_item := public._custom_content_projection(v_definition, v_revision)
      || jsonb_build_object(
        'reviewedLifecycleVersion',
        v_definition.reviewed_lifecycle_version
      );
  else
    if v_definition.archived_at is null then
      update public.custom_content_definitions
         set archived_at = v_now,
             updated_at = v_now,
             reviewed_lifecycle_version =
               reviewed_lifecycle_version + 1
       where owner_id = v_uid
         and id = v_artifact_id
       returning * into strict v_definition;
    end if;
    select *
      into strict v_revision
      from public.custom_content_revisions revision
     where revision.owner_id = v_uid
       and revision.definition_id = v_artifact_id
       and revision.id = v_definition.head_revision_id;
    v_revision_id := v_revision.id;
    v_archived_item :=
      public._custom_content_projection(v_definition, v_revision)
      || jsonb_build_object(
        'reviewedLifecycleVersion',
        v_definition.reviewed_lifecycle_version
      );
    v_entry_status := 'archived';
  end if;

  v_result := jsonb_build_object(
    'artifactId', v_artifact_id,
    'item', v_item,
    'archivedItem', v_archived_item,
    'headRevisionId', v_revision_id
  );
  v_response := jsonb_build_object(
    'ok', true,
    'status', 'applied',
    'commandId', p_command_id,
    'reason', null,
    'replayed', false,
    'fingerprint', v_fingerprint,
    'result', v_result,
    'perEntry', jsonb_build_array(jsonb_build_object(
      'definitionId', v_artifact_id,
      'revisionId', v_revision_id,
      'category', 'supplyChains',
      'status', v_entry_status
    ))
  );
  if not public.finalize_application_command(
    v_uid, p_command_id, v_fingerprint,
    'applied', v_response, null
  ) then
    raise exception 'reviewed supply-chain command did not finalize'
      using errcode = '40001';
  end if;
  return v_response;
end;

apply_custom_content_command(p_expected_:
declare
  v_uid uuid := auth.uid();
  v_category text;
  v_definition_id uuid;
begin
  if p_plan ->> 'kind' in (
    'content.definition.archive',
    'content.definition.restore'
  ) then
    v_definition_id := public._content_uuid(p_plan ->> 'definitionId');
    select definition.category
      into v_category
      from public.custom_content_definitions definition
     where definition.owner_id = v_uid
       and definition.id = v_definition_id;
    if v_category is not null and v_category not in (
      'institutions','services','resources','stressors',
      'tradeGoods','factions','deities','traditions'
    ) then
      raise exception 'generic lifecycle category is not authorable'
        using errcode = '22023';
    end if;
  end if;
  return public._apply_custom_content_command_authorable(
    p_expected_owner,
    p_command_id,
    p_preview_fingerprint,
    p_plan
  );
end;

_campaign_reviewed_supply_chain_history_:
begin
  return public._campaign_content_binding_history_valid(p_history)
    and not exists (
      select 1
        from jsonb_array_elements(p_history) binding(value)
       where not public._campaign_reviewed_supply_chain_references_valid(
         p_owner,
         binding.value
       )
    );
exception
  when others then
    return false;
end;

_custom_content_reviewed_lifecycle_guard:
begin
  if tg_op = 'UPDATE' and new.category is distinct from old.category then
    raise exception 'custom-content definition category is immutable'
      using errcode = '22023';
  end if;
  if new.category = 'supplyChains' then
    -- The journal claim is the transaction-visible mutation capability. Both
    -- authorized lanes claim before touching definitions and finalize in the
    -- same transaction; authenticated/service roles cannot forge journal DML.
    -- This rejects accidental privileged/manual writes instead of silently
    -- minting generation one for an artifact that skipped graph review.
    if not exists (
      select 1
        from public.application_command_journal command
         where command.owner_id = new.owner_id
         and command.phase = 'claimed'
         and command.status = 'claimed'
         and command.command_id = current_setting(
           'settlementforge.reviewed_chain_command',
           true
         )
         and command.authority_transaction_id = txid_current()
         and (
           (
             command.kind in (
               'content.reviewed-supply-chain.confirm',
               'content.reviewed-supply-chain.remove'
             )
             and command.target_id = new.id
           )
           or command.kind = 'content.archive.import'
         )
    ) then
      raise exception 'reviewed supply-chain write lacks authority'
        using errcode = '42501';
    end if;
    new.reviewed_lifecycle_version :=
      coalesce(new.reviewed_lifecycle_version, 1);
  elsif new.reviewed_lifecycle_version is not null then
    raise exception 'authorable definitions have no reviewed lifecycle'
      using errcode = '22023';
  end if;
  return new;
end;

system_clawback_credits(p_session_id tex:
declare
  v_caller_role text;
  v_session text := nullif(btrim(p_session_id), '');
  v_grant_id uuid;
  v_user uuid;
  v_amount integer;
  v_claimed text;
  v_reversal_id uuid;
  v_prev integer;
  v_next integer;
begin
  v_caller_role := coalesce(
    nullif(current_setting('request.jwt.claim.role', true), ''),
    auth.role()
  );
  if v_caller_role <> 'service_role' then
    raise exception 'system_clawback_credits is service-role only';
  end if;
  if v_session is null then
    raise exception 'session id is required';
  end if;

  -- The pack grant this session minted. At most one exists: system_grant_credits'
  -- delivery claim for source 'purchase' is keyed on the session id (024), so the
  -- order/limit is belt-and-suspenders against out-of-band ledger writes.
  select id, user_id, amount
    into v_grant_id, v_user, v_amount
    from public.credit_ledger
   where source = 'purchase'
     and kind = 'grant'
     and metadata->>'stripe_session_id' = v_session
   order by created_at
   limit 1;
  if v_grant_id is null then
    return jsonb_build_object('ok', false, 'reason', 'no_pack_grant');
  end if;

  -- Claim-once, the exact mirror of the grant's own delivery claim (024): the
  -- reversal claims (source 'purchase_clawback', key = session) atomically. A
  -- redelivered refund/dispute conflicts here and no-ops — the ledger is never
  -- double-deducted.
  insert into public.credit_grant_idempotency (source, idempotency_key, user_id)
    values ('purchase_clawback', v_session, v_user)
    on conflict do nothing
    returning idempotency_key into v_claimed;
  if v_claimed is null then
    return jsonb_build_object('ok', false, 'reason', 'already_clawed_back');
  end if;

  -- Serialize against concurrent balance writers (the 018/103 lock discipline).
  -- Deliberately NO raise when the profiles row is gone: the ledger rows are the
  -- money truth and the reversal must not strand in a redelivery loop; the cache
  -- refresh below simply touches zero rows.
  perform 1 from public.profiles where id = v_user for update;

  v_prev := public.get_credit_balance(v_user);

  -- The reversal: the FULL granted amount as an UNALLOCATED 'spend' row.
  -- get_credit_balance counts it via its legacy_spends branch with no clamp, so
  -- the balance MAY go negative — a debt that nets against future grants
  -- (ruling 2026-07-26; goodwill = credit grants, never partial refunds).
  insert into public.credit_ledger (user_id, kind, amount, source, metadata)
    values (
      v_user, 'spend', v_amount, 'purchase_clawback',
      jsonb_build_object(
        'stripe_session_id', v_session,
        'reversed_ledger_id', v_grant_id,
        'reason', coalesce(p_reason, 'charge_reversal')
      )
    )
    returning id into v_reversal_id;

  update public.credit_grant_idempotency
     set ledger_id = v_reversal_id
   where source = 'purchase_clawback'
     and idempotency_key = v_session;

  insert into public.credit_transactions (user_id, amount, reason)
    values (v_user, -v_amount, 'purchase_clawback');

  v_next := public.get_credit_balance(v_user);
  update public.profiles
     set credits = v_next, updated_at = now()
   where id = v_user;

  perform public._audit_action(
    null,
    v_user,
    'system_clawback_credits',
    jsonb_build_object('source', 'purchase_clawback', 'amount', v_amount, 'stripe_session_id', v_session),
    jsonb_build_object('prev_balance', v_prev, 'new_balance', v_next, 'reversed_ledger_id', v_grant_id),
    coalesce(p_reason, 'charge_reversal')
  );

  return jsonb_build_object(
    'ok', true,
    'user_id', v_user,
    'amount', v_amount,
    'prev', v_prev,
    'next', v_next
  );
end;

surveyor_byok_status(p_provider text):
declare v_uid uuid;
begin
  v_uid := auth.uid();
  if v_uid is null then raise exception 'not authenticated'; end if;
  return query
    select k.provider, true, k.health, k.last_verified_at, k.last_checked_at, k.last_error_class,
           k.rotated_at, k.probe_tier, k.probe_checked_at, k.probe_model,
           k.probe_version, k.probe_profile
    from public.surveyor_byok_keys k
    where k.user_id = v_uid
      and (p_provider is null or k.provider = btrim(p_provider))
    order by k.provider;
end;

surveyor_byok_set_probe_tier(p_user uuid:
declare v_provider text; v_updated integer := 0; v_task jsonb; v_len integer;
begin
  if p_user is null then return false; end if;
  if p_tier is null or p_tier not in ('scout','journeyman','master') then
    raise exception 'invalid byok probe tier: %', p_tier;
  end if;

  -- THE PROFILE WALL (see the note above). Absent is always legal: a caller that records
  -- no texture is a 4-argument caller, not a broken one.
  if p_profile is not null then
    -- The type test stands ALONE, before anything that assumes an object: jsonb_object_keys
    -- raises its own error on a scalar, and SQL does not promise to short-circuit an OR, so
    -- folding these together would sometimes report the wrong fault.
    if jsonb_typeof(p_profile) <> 'object' then
      raise exception 'invalid byok probe profile: top level must be exactly {tasks, passes, tasksRun}';
    end if;
    if not (p_profile ?& array['tasks','passes','tasksRun'])
       or exists (select 1 from jsonb_object_keys(p_profile) k
                   where k not in ('tasks','passes','tasksRun')) then
      raise exception 'invalid byok probe profile: top level must be exactly {tasks, passes, tasksRun}';
    end if;
    if jsonb_typeof(p_profile->'tasks') <> 'array' then
      raise exception 'invalid byok probe profile: tasks must be an array of verdicts';
    end if;
    v_len := jsonb_array_length(p_profile->'tasks');
    -- An upper bound, not a guess at the exam size: it keeps a runaway caller from
    -- turning a verdict list into a payload, while leaving the exam free to grow.
    if v_len < 1 or v_len > 8 then
      raise exception 'invalid byok probe profile: tasks must hold between 1 and 8 verdicts, got %', v_len;
    end if;
    if jsonb_typeof(p_profile->'passes') <> 'number'
       or jsonb_typeof(p_profile->'tasksRun') <> 'number' then
      raise exception 'invalid byok probe profile: passes and tasksRun must be counts';
    end if;
    if (p_profile->>'tasksRun')::numeric <> v_len then
      raise exception 'invalid byok probe profile: tasksRun must equal the number of verdicts';
    end if;
    if (p_profile->>'passes')::numeric < 0 or (p_profile->>'passes')::numeric > v_len then
      raise exception 'invalid byok probe profile: passes must lie between 0 and the number of verdicts';
    end if;
    for v_task in select value from jsonb_array_elements(p_profile->'tasks') loop
      if jsonb_typeof(v_task) <> 'object' then
        raise exception 'invalid byok probe profile: each verdict must be exactly {key, passed, reasonClass}';
      end if;
      if not (v_task ?& array['key','passed','reasonClass'])
         or exists (select 1 from jsonb_object_keys(v_task) k
                     where k not in ('key','passed','reasonClass')) then
        raise exception 'invalid byok probe profile: each verdict must be exactly {key, passed, reasonClass}';
      end if;
      -- A BARE IDENTIFIER, which is what makes prose and ids structurally unrepresentable:
      -- no spaces, no punctuation, no length to hide a sentence in.
      if jsonb_typeof(v_task->'key') <> 'string'
         or (v_task->>'key') !~ '^[A-Za-z][A-Za-z0-9]{0,31}$' then
        raise exception 'invalid byok probe profile: a task key must be a bare identifier';
      end if;
      if jsonb_typeof(v_task->'passed') <> 'boolean' then
        raise exception 'invalid byok probe profile: passed must be a boolean verdict';
      end if;
      if not (jsonb_typeof(v_task->'reasonClass') = 'null'
              or (v_task->>'reasonClass') in
                 ('no_output','unsupported_emitted','dropped_at_wall','below_floor')) then
        raise exception 'invalid byok probe profile: reasonClass must be null or a declared reason class';
      end if;
      -- Pass and reason are two halves of one verdict; either half alone is a caller bug.
      if (v_task->>'passed') = 'true' and jsonb_typeof(v_task->'reasonClass') <> 'null' then
        raise exception 'invalid byok probe profile: a passed task carries no reason class';
      end if;
      if (v_task->>'passed') = 'false' and jsonb_typeof(v_task->'reasonClass') = 'null' then
        raise exception 'invalid byok probe profile: a failed task must name its reason class';
      end if;
    end loop;
  end if;

  v_provider := coalesce(nullif(btrim(p_provider), ''), 'anthropic');
  update public.surveyor_byok_keys
     set probe_tier       = p_tier,
         probe_checked_at = now(),
         probe_model      = nullif(btrim(p_model), ''),
         probe_version    = nullif(btrim(p_probe_version), ''),
         probe_profile    = p_profile
   where user_id = p_user and provider = v_provider;
  get diagnostics v_updated = row_count;
  return v_updated > 0;
end;

surveyor_byok_get(p_user uuid, p_provide:
declare v_cipher bytea; v_tier text; v_model text; v_version text; v_profile jsonb;
begin
  select k.ciphertext, k.probe_tier, k.probe_model, k.probe_version, k.probe_profile
    into v_cipher, v_tier, v_model, v_version, v_profile
  from public.surveyor_byok_keys k
  where k.user_id = p_user and k.provider = coalesce(nullif(btrim(p_provider), ''), 'anthropic');
  -- 139's contract: no row means no key, and the caller falls back to the server key.
  if v_cipher is null then return null; end if;
  -- CARRY-ALL: every probe column the row holds, so the edge never needs a second
  -- round-trip and no future reader has to ask why one of the five was left behind.
  -- probe_model is what binds the profile to a model: the edge renders coaching only when
  -- it matches the model actually about to answer (see the third amendment note above).
  return jsonb_build_object(
    'key',           pgp_sym_decrypt(v_cipher, public._surveyor_byok_secret()),
    'probe_tier',    v_tier,
    'probe_model',   v_model,
    'probe_version', v_version,
    'probe_profile', v_profile
  );
end;

spend_credits(feature text, p_profile te:
declare
  cost integer;
  remaining integer;
  current_balance integer;
  user_role text;
  new_spend_id uuid;
  needed integer;
  grant_row record;
  allocation integer;
  base_feature text;
  cfg_cost integer;
  v_tier text;
  v_mult numeric;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  -- SINGLE-SESSION BELT (161, §7.2): a superseded JWT can never move credits.
  perform public.assert_current_session();
  -- Trust-boundary gate (057): a banned/disabled/soft-deleted account may not
  -- spend, even with a still-valid JWT.
  if not public.account_is_active(auth.uid()) then
    raise exception 'account is not active';
  end if;

  -- CONFIG-FIRST cost resolution (114): strip a trailing '_fast' to the base feature,
  -- then — when a profile is supplied — read the per-profile config cost. Only an
  -- integer 1..12 is honoured; ANY miss/malformation falls through to the 057 CASE.
  base_feature := case when feature like '%\_fast' then left(feature, length(feature) - 5) else feature end;
  cfg_cost := null;
  if p_profile is not null then
    begin
      select nullif(v.value -> 'profiles' -> p_profile ->> base_feature, '')::integer
        into cfg_cost
        from public.system_config v
       where v.key = 'ai_credit_costs';
    exception when others then
      cfg_cost := null;
    end;
    if cfg_cost is not null and (cfg_cost < 1 or cfg_cost > 12) then
      cfg_cost := null;
    end if;
  end if;

  if cfg_cost is not null then
    cost := cfg_cost;
  else
    -- 057 CASE block + the Surveyor S1 (analysis, brief) + S3 (interpret, parley) +
    -- S4–S6 (customContent, styleOverhaul, constructSettlement, constructRealm) +
    -- S7 (autonomy) features. 180: narrative 3->5, progression 5->6 (optimal margins).
    cost := case feature
      when 'chronicle' then 2
      when 'narrative' then 5
      when 'dailyLife' then 4
      when 'progression' then 6
      when 'narrative_fast' then 2
      when 'dailyLife_fast' then 3
      when 'progression_fast' then 4
      when 'analysis' then 3
      when 'brief' then 4
      when 'interpret' then 5
      when 'parley' then 3
      when 'customContent' then 6
      when 'styleOverhaul' then 3
      when 'constructSettlement' then 6
      when 'constructRealm' then 8
      when 'autonomy' then 4
      else null
    end;
    if cost is null then raise exception 'unknown feature: %', feature; end if;
  end if;

  -- ── THE TIER MULTIPLIER (192) — machinery live, effect INERT ────────────────
  -- Reached only when a caller supplies a tier. No caller does yet, and even
  -- when one does, the config row this reads is deliberately unseeded, so the
  -- base cost stands. Four independent ways to be inert, all of them normal:
  -- p_tier null · tier outside the vocabulary · no 'ai_tier_multipliers' row ·
  -- multiplier of exactly 1. The base cost resolved above is never recomputed.
  --
  -- FORWARD-COMPATIBLE BY CONTRACT: an unrecognized tier string is treated as
  -- null and does NOT raise. The tier names are the design's WORKING names and
  -- the owner has not made the taste pick (§5), so a renamed or newly-added rung
  -- arriving from an edge that deployed ahead of the database must degrade to
  -- the ordinary price, never fail a paid call. Rejecting it here would turn a
  -- naming decision into an outage.
  v_tier := case when p_tier in ('scout', 'journeyman', 'master') then p_tier else null end;
  if v_tier is not null then
    v_mult := null;
    begin
      select nullif(v.value ->> v_tier, '')::numeric
        into v_mult
        from public.system_config v
       where v.key = 'ai_tier_multipliers';
    exception when others then
      v_mult := null;
    end;
    -- The sane band (header): operator-writable config may not move a charge
    -- more than half down or triple up. Anything outside is treated as absent.
    if v_mult is not null and (v_mult < 0.5 or v_mult > 3) then
      v_mult := null;
    end if;
    -- A multiplier of exactly 1 is the identity and skips the arithmetic, so an
    -- all-ones config is byte-identical to no config at all.
    if v_mult is not null and v_mult <> 1 then
      cost := greatest(1, least(12, round(cost * v_mult)))::integer;
    end if;
  end if;

  select role into user_role from public.profiles where id = auth.uid() for update;
  if user_role in ('developer', 'admin') or public.current_user_is_privileged() then
    insert into public.credit_ledger (user_id, kind, amount, source, metadata)
      values (auth.uid(), 'spend', cost, feature, jsonb_build_object('elevated', true))
      returning id into new_spend_id;
    return jsonb_build_object('ok', true, 'balance', -2, 'spend_id', new_spend_id, 'elevated', true);
  end if;

  current_balance := public.get_credit_balance(auth.uid());
  if current_balance < cost then
    return jsonb_build_object('ok', false, 'reason', 'insufficient_funds', 'balance', coalesce(current_balance, 0));
  end if;

  insert into public.credit_ledger (user_id, kind, amount, source, metadata)
    values (auth.uid(), 'spend', cost, feature, '{}'::jsonb)
    returning id into new_spend_id;
  needed := cost;

  for grant_row in
    select g.id, greatest(g.amount - coalesce(a.amount, 0), 0)::integer as available
    from public.credit_ledger g
    left join (
      select grant_id, sum(amount)::integer as amount
      from public.credit_spend_allocations group by grant_id
    ) a on a.grant_id = g.id
    where g.user_id = auth.uid()
      and g.kind = 'grant'
      and (g.expires_at is null or g.expires_at > now())
      and greatest(g.amount - coalesce(a.amount, 0), 0) > 0
    order by case when g.source = 'monthly_allowance' then 0 else 1 end,
      g.expires_at nulls last, g.created_at
    for update of g
  loop
    allocation := least(needed, grant_row.available);
    if allocation > 0 then
      insert into public.credit_spend_allocations (spend_id, grant_id, amount)
        values (new_spend_id, grant_row.id, allocation);
      needed := needed - allocation;
    end if;
    exit when needed <= 0;
  end loop;
  if needed > 0 then raise exception 'credit allocation failed'; end if;

  insert into public.credit_transactions (user_id, amount, reason)
    values (auth.uid(), -cost, feature);
  remaining := public.get_credit_balance(auth.uid());
  update public.profiles set credits = remaining, updated_at = now() where id = auth.uid();
  return jsonb_build_object('ok', true, 'balance', remaining, 'spend_id', new_spend_id, 'elevated', false);
end;

assert_create_route_half(p_expected json:
declare
  v_expected_length integer;
  v_next_length integer;
  v_entry jsonb;
  v_key text;
  v_expected_routes jsonb;
  v_next_routes jsonb;
  v_route jsonb;
begin
  if p_expected -> 'neighbourNetwork' is null then
    v_expected_length := 0;
  elsif jsonb_typeof(p_expected -> 'neighbourNetwork') = 'array' then
    v_expected_length := jsonb_array_length(p_expected -> 'neighbourNetwork');
  else
    raise exception 'base neighbourNetwork must be an array when present (%)', p_side
      using errcode = '22023';
  end if;
  if jsonb_typeof(p_next -> 'neighbourNetwork') is distinct from 'array' then
    raise exception 'CREATE_ROUTE must append a neighbour entry (%)', p_side
      using errcode = '22023';
  end if;
  v_next_length := jsonb_array_length(p_next -> 'neighbourNetwork');
  if v_next_length <> v_expected_length + 1 then
    raise exception 'CREATE_ROUTE must append exactly one neighbour entry (%)', p_side
      using errcode = '22023';
  end if;
  if (
    (p_next -> 'neighbourNetwork') - v_expected_length
  ) is distinct from coalesce(
    p_expected -> 'neighbourNetwork',
    '[]'::jsonb
  ) then
    raise exception 'CREATE_ROUTE must preserve the existing neighbour entries (%)', p_side
      using errcode = '22023';
  end if;
  v_entry := p_next -> 'neighbourNetwork' -> v_expected_length;
  if v_entry ->> 'linkId' is distinct from p_edge_id
    or v_entry ->> 'id' is distinct from p_other_id
  then
    raise exception 'the appended neighbour entry is not this route (%)', p_side
      using errcode = '22023';
  end if;

  foreach v_key in array array['config', '_config'] loop
    if not jsonb_exists(p_next, v_key) then
      continue;
    end if;
    v_expected_routes := coalesce(p_expected, '{}'::jsonb) #> array[v_key, '_userRoutes'];
    if v_expected_routes is null then
      v_expected_length := 0;
    elsif jsonb_typeof(v_expected_routes) = 'array' then
      v_expected_length := jsonb_array_length(v_expected_routes);
    else
      raise exception 'base %._userRoutes must be an array when present (%)', v_key, p_side
        using errcode = '22023';
    end if;
    v_next_routes := p_next #> array[v_key, '_userRoutes'];
    if jsonb_typeof(v_next_routes) is distinct from 'array' then
      raise exception 'CREATE_ROUTE must append a %._userRoutes row (%)', v_key, p_side
        using errcode = '22023';
    end if;
    if jsonb_array_length(v_next_routes) <> v_expected_length + 1 then
      raise exception 'CREATE_ROUTE must append exactly one %._userRoutes row (%)', v_key, p_side
        using errcode = '22023';
    end if;
    if (v_next_routes - v_expected_length)
      is distinct from coalesce(v_expected_routes, '[]'::jsonb)
    then
      raise exception 'CREATE_ROUTE must preserve existing %._userRoutes rows (%)', v_key, p_side
        using errcode = '22023';
    end if;
    v_route := v_next_routes -> v_expected_length;
    if v_route ->> 'routeId' is distinct from p_edge_id
      or v_route ->> 'atEventId' is distinct from p_event_id
      or v_route ->> 'provenance' is distinct from 'user'
    then
      raise exception 'the appended %._userRoutes row is not this user route (%)', v_key, p_side
        using errcode = '22023';
    end if;
  end loop;
end;

apply_create_route_command(p_expected_ow:
declare
  v_uid uuid := auth.uid();
  v_fingerprint text;
  v_claim jsonb;
  v_row public.settlements%rowtype;
  v_partner_row public.settlements%rowtype;
  v_receipt jsonb;
  v_reason text;
  v_mode text;
  v_low text;
  v_high text;
  v_edge_id text;
  v_expected_log_length integer;
  v_next_log_length integer;
  v_last_log_entry jsonb;
  v_locked_data jsonb;
  v_partner_locked_data jsonb;
  v_first uuid;
  v_second uuid;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if p_expected_owner is null or p_expected_owner <> v_uid then
    raise exception 'application command owner changed'
      using errcode = '42501';
  end if;
  if not public.account_is_active(v_uid) then
    raise exception 'account is not active'
      using errcode = '42501';
  end if;
  if p_save_id is null
    or p_partner_save_id is null
    or p_expected_revision is null
  then
    raise exception 'both save ids and the expected revision are required'
      using errcode = '22023';
  end if;
  if p_save_id = p_partner_save_id then
    raise exception 'a route needs two distinct settlements'
      using errcode = '22023';
  end if;
  if jsonb_typeof(p_event) <> 'object'
    or p_event ->> 'type' <> 'CREATE_ROUTE'
    or nullif(btrim(p_event ->> 'id'), '') is null
  then
    raise exception 'only CREATE_ROUTE is server-authoritative in this RPC'
      using errcode = '22023';
  end if;
  v_mode := p_event #>> '{payload,mode}';
  if v_mode is null or v_mode not in ('land', 'water') then
    raise exception 'CREATE_ROUTE requires a land or water mode'
      using errcode = '22023';
  end if;
  if jsonb_typeof(p_expected_data) <> 'object'
    or jsonb_typeof(p_expected_campaign_state) <> 'object'
    or jsonb_typeof(p_partner_expected_data) <> 'object'
    or jsonb_typeof(p_next_data) <> 'object'
    or jsonb_typeof(p_next_campaign_state) <> 'object'
    or jsonb_typeof(p_partner_next_data) <> 'object'
    or coalesce(p_next_campaign_state ->> 'phase', '') <> 'canon'
  then
    raise exception 'prepared canon-event projection is invalid'
      using errcode = '22023';
  end if;
  if jsonb_typeof(p_expected_campaign_state -> 'eventLog') is distinct from 'array'
    or jsonb_typeof(p_next_campaign_state -> 'eventLog') is distinct from 'array'
  then
    raise exception 'canon-event log projections must be arrays'
      using errcode = '22023';
  end if;
  if p_next_ai_data is not null and jsonb_typeof(p_next_ai_data) <> 'object' then
    raise exception 'p_next_ai_data must be an object or null'
      using errcode = '22023';
  end if;

  -- The deterministic edge identity (DESIGN_ROUTE_LIFECYCLE section 3). bytea
  -- comparison is UTF-8 byte order, which is codepoint order, and is immune to
  -- the database collation the text operators would otherwise consult.
  if convert_to(p_save_id::text, 'UTF8')
     <= convert_to(p_partner_save_id::text, 'UTF8')
  then
    v_low := p_save_id::text;
    v_high := p_partner_save_id::text;
  else
    v_low := p_partner_save_id::text;
    v_high := p_save_id::text;
  end if;
  v_edge_id := 'route.' || v_low || '.' || v_high || '.' || v_mode;
  if p_event #>> '{payload,routeId}' is distinct from v_edge_id then
    raise exception 'CREATE_ROUTE route id is not the deterministic edge identity'
      using errcode = '22023';
  end if;

  -- Envelope: outside the named surface, both rows must be byte-equal to the
  -- reviewed base. As in 183 this constrains the client-prepared projection; it
  -- does not claim to recompute the contents of the fields it does allow.
  if public.create_route_envelope_violation(p_expected_data, p_next_data) then
    raise exception 'CREATE_ROUTE changed a field outside its mutation surface'
      using errcode = '22023';
  end if;
  if public.create_route_envelope_violation(
    p_partner_expected_data,
    p_partner_next_data
  ) then
    raise exception 'CREATE_ROUTE changed a partner field outside its mutation surface'
      using errcode = '22023';
  end if;

  -- The initiating row owns the event-log append; the partner keeps its own
  -- timeline. Exactly one entry, the prior prefix intact, and it must be THIS
  -- command's event.
  v_expected_log_length := jsonb_array_length(
    p_expected_campaign_state -> 'eventLog'
  );
  v_next_log_length := jsonb_array_length(p_next_campaign_state -> 'eventLog');
  if v_next_log_length <> v_expected_log_length + 1 then
    raise exception 'CREATE_ROUTE must append exactly one event-log entry'
      using errcode = '22023';
  end if;
  if (
    (p_next_campaign_state -> 'eventLog') - v_expected_log_length
  ) is distinct from (
    p_expected_campaign_state -> 'eventLog'
  ) then
    raise exception 'CREATE_ROUTE must preserve the existing event-log prefix'
      using errcode = '22023';
  end if;
  v_last_log_entry := p_next_campaign_state
    -> 'eventLog'
    -> v_expected_log_length;
  if v_last_log_entry #>> '{event,type}' is distinct from 'CREATE_ROUTE'
    or v_last_log_entry #>> '{event,id}' is distinct from p_event ->> 'id'
  then
    raise exception 'event-log append does not match the command event'
      using errcode = '22023';
  end if;
  if (
    p_next_campaign_state
      - 'eventLog'
      - 'systemState'
      - 'editedAt'
      - 'narrativeDrift'
      - 'exportState'
  ) is distinct from (
    p_expected_campaign_state
      - 'eventLog'
      - 'systemState'
      - 'editedAt'
      - 'narrativeDrift'
      - 'exportState'
  ) then
    raise exception 'CREATE_ROUTE changed an unrelated campaign-state field'
      using errcode = '22023';
  end if;

  -- Both halves of the edge, proven against the same recomputed identity. The
  -- neighbour entry points AT the other endpoint; the provenance row names the
  -- route. Either half missing is a refusal, which is what makes a half-edge
  -- unrepresentable rather than merely unlikely.
  perform public.assert_create_route_half(
    p_expected_data,
    p_next_data,
    v_edge_id,
    p_partner_save_id::text,
    p_event ->> 'id',
    'settlement'
  );
  perform public.assert_create_route_half(
    p_partner_expected_data,
    p_partner_next_data,
    v_edge_id,
    p_save_id::text,
    p_event ->> 'id',
    'partner'
  );

  -- The server fingerprints every mutation-bearing input. No raw settlement,
  -- event prose, or campaign JSON is retained in the journal.
  v_fingerprint := encode(sha256(convert_to(
    jsonb_build_object(
      'kind', 'settlement.canon-event.apply',
      'saveId', p_save_id,
      'partnerSaveId', p_partner_save_id,
      'expectedRevision', p_expected_revision,
      'event', p_event,
      'expectedData', p_expected_data,
      'expectedCampaignState', p_expected_campaign_state,
      'expectedAiData', p_expected_ai_data,
      'partnerExpectedData', p_partner_expected_data,
      'nextData', p_next_data,
      'nextCampaignState', p_next_campaign_state,
      'partnerNextData', p_partner_next_data,
      'nextAiData', p_next_ai_data
    )::text,
    'UTF8'
  )), 'hex');

  v_claim := public.claim_application_command(
    v_uid,
    p_command_id,
    v_fingerprint,
    'settlement.canon-event.apply',
    p_save_id,
    p_expected_revision
  );

  if v_claim ->> 'status' = 'conflict' then
    return v_claim;
  end if;

  -- A completed duplicate returns the authoritative current rows. The receipt is
  -- historical identity; the projection may include legitimate later commands.
  if coalesce((v_claim ->> 'replayed')::boolean, false)
    and v_claim ->> 'status' <> 'claimed'
  then
    select * into v_row
      from public.settlements
     where id = p_save_id
       and user_id = v_uid;
    select * into v_partner_row
      from public.settlements
     where id = p_partner_save_id
       and user_id = v_uid;
    return jsonb_build_object(
      'status', v_claim ->> 'status',
      'reason', v_claim ->> 'reason',
      'replayed', true,
      'fingerprint', v_fingerprint,
      'routeId', v_edge_id,
      'revisionKind', 'base-projection-v1',
      'receipt', v_claim -> 'receipt',
      'settlement', v_row.data,
      'campaignState', v_row.campaign_state,
      'aiData', v_row.ai_data,
      'partnerSettlement', v_partner_row.data,
      'updatedAt', v_row.updated_at
    );
  end if;

  -- A separately committed claim has no safe automatic interpretation (183's
  -- rationale, unchanged): this path claims and applies in one transaction, so
  -- an orphan claim means an operator or service workflow intervened.
  if coalesce((v_claim ->> 'replayed')::boolean, false)
    and v_claim ->> 'status' = 'claimed'
  then
    perform public.mark_application_command_reconcile(
      v_uid,
      p_command_id,
      v_fingerprint,
      'abandoned_claim'
    );
    return jsonb_build_object(
      'status', 'reconcile-required',
      'reason', 'abandoned_claim',
      'replayed', true,
      'fingerprint', v_fingerprint,
      'routeId', v_edge_id,
      'revisionKind', 'base-projection-v1'
    );
  end if;

  -- Lock BOTH endpoints before comparing or writing either. The id order is what
  -- makes two concurrent routes over the same pair serialize instead of deadlock.
  if p_save_id < p_partner_save_id then
    v_first := p_save_id;
    v_second := p_partner_save_id;
  else
    v_first := p_partner_save_id;
    v_second := p_save_id;
  end if;
  perform 1
    from public.settlements
   where id = v_first
     and user_id = v_uid
     and access_state = 'active'
     for update;
  perform 1
    from public.settlements
   where id = v_second
     and user_id = v_uid
     and access_state = 'active'
     for update;

  select data into v_locked_data
    from public.settlements
   where id = p_save_id
     and user_id = v_uid
     and access_state = 'active';
  select data into v_partner_locked_data
    from public.settlements
   where id = p_partner_save_id
     and user_id = v_uid
     and access_state = 'active';

  if v_locked_data is null or v_partner_locked_data is null then
    v_reason := 'save_unavailable';
  elsif v_locked_data is distinct from p_expected_data then
    v_reason := 'base_projection_changed';
  elsif v_partner_locked_data is distinct from p_partner_expected_data then
    v_reason := 'partner_base_projection_changed';
  elsif not exists (
    select 1
      from public.settlements
     where id = p_save_id
       and user_id = v_uid
       and access_state = 'active'
       and campaign_state is not distinct from p_expected_campaign_state
       and (
         p_next_ai_data is null
         or ai_data is not distinct from p_expected_ai_data
       )
  ) then
    v_reason := 'base_projection_changed';
  else
    v_reason := null;
  end if;

  if v_reason is not null then
    v_receipt := jsonb_build_object(
      'saveId', p_save_id,
      'partnerSaveId', p_partner_save_id,
      'routeId', v_edge_id,
      'eventType', 'CREATE_ROUTE',
      'reason', v_reason
    );
    perform public.finalize_application_command(
      v_uid,
      p_command_id,
      v_fingerprint,
      'stale',
      v_receipt,
      v_reason
    );
    return jsonb_build_object(
      'status', 'stale',
      'reason', v_reason,
      'replayed', false,
      'fingerprint', v_fingerprint,
      'routeId', v_edge_id,
      'revisionKind', 'base-projection-v1',
      'receipt', v_receipt
    );
  end if;

  update public.settlements
     set data = p_next_data,
         campaign_state = p_next_campaign_state,
         ai_data = case
           when p_next_ai_data is null then ai_data
           else p_next_ai_data
         end,
         neighbour_links = p_next_data -> 'neighbourNetwork',
         updated_at = clock_timestamp()
   where id = p_save_id
     and user_id = v_uid
     and access_state = 'active'
     and data = p_expected_data
   returning * into v_row;
  if not found then
    raise exception 'the initiating route endpoint changed under its own lock'
      using errcode = '40001';
  end if;

  update public.settlements
     set data = p_partner_next_data,
         neighbour_links = p_partner_next_data -> 'neighbourNetwork',
         updated_at = clock_timestamp()
   where id = p_partner_save_id
     and user_id = v_uid
     and access_state = 'active'
     and data = p_partner_expected_data
   returning * into v_partner_row;
  if not found then
    raise exception 'the partner route endpoint changed under its own lock'
      using errcode = '40001';
  end if;

  v_receipt := jsonb_build_object(
    'saveId', p_save_id,
    'partnerSaveId', p_partner_save_id,
    'routeId', v_edge_id,
    'eventId', coalesce(p_event ->> 'id', p_command_id),
    'eventType', 'CREATE_ROUTE',
    'projectionValidation', 'client-prepared-constrained-envelope-v1',
    'revisionKind', 'base-projection-v1',
    'updatedAt', v_row.updated_at
  );
  if not public.finalize_application_command(
    v_uid,
    p_command_id,
    v_fingerprint,
    'applied',
    v_receipt,
    null
  ) then
    raise exception 'application command finalization failed'
      using errcode = '40001';
  end if;

  return jsonb_build_object(
    'status', 'applied',
    'replayed', false,
    'fingerprint', v_fingerprint,
    'routeId', v_edge_id,
    'revisionKind', 'base-projection-v1',
    'receipt', v_receipt,
    'settlement', v_row.data,
    'campaignState', v_row.campaign_state,
    'aiData', v_row.ai_data,
    'partnerSettlement', v_partner_row.data,
    'updatedAt', v_row.updated_at
  );
end;

set_my_email_preference(p_expected_user:
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if p_expected_user is null or v_uid <> p_expected_user then
    raise exception 'auth session changed before email preference mutation';
  end if;
  if not public.is_allowed_email_category(p_category) then
    raise exception 'unknown email category: %', p_category;
  end if;
  if p_enabled is null then raise exception 'enabled flag is required'; end if;

  insert into public.email_preferences (user_id)
  values (v_uid)
  on conflict (user_id) do nothing;

  if p_category = 'product_updates' then
    update public.email_preferences
       set product_updates = p_enabled,
           product_updates_decided_at = now(),
           updated_at = now()
     where user_id = v_uid;
  else
    execute format(
      'update public.email_preferences set %I = $1, updated_at = now() where user_id = $2',
      p_category
    ) using p_enabled, v_uid;
  end if;
end;

record_telemetry_consent_changes():
declare
  v_key text;
  v_source text := coalesce(nullif(current_setting('app.telemetry_consent_source', true), ''), 'system');
  v_version integer := coalesce((new.telemetry_consent ->> 'v')::integer, 1);
  v_before boolean;
  v_after boolean;
begin
  if v_source not in ('account', 'unsubscribe', 'system') then v_source := 'system'; end if;
  if v_version < 1 or v_version > 32767 then v_version := 1; end if;
  foreach v_key in array array['essential', 'research', 'ai_prose', 'market'] loop
    v_before := coalesce((old.telemetry_consent ->> v_key)::boolean, false);
    v_after := coalesce((new.telemetry_consent ->> v_key)::boolean, false);
    if v_before is distinct from v_after then
      insert into public.consent_change_records (
        user_id, consent_key, prior_value, new_value, consent_model_version, source
      ) values (
        new.id, v_key, v_before, v_after, v_version, v_source
      );
    end if;
  end loop;
  return new;
exception when invalid_text_representation then
  raise exception 'telemetry consent flags and version must have valid scalar types'
    using errcode = '22023';
end;

set_my_telemetry_consent(p_expected_user:
declare
  v_uid uuid := auth.uid();
  v_key text;
  v_old jsonb;
  v_changed text[] := array[]::text[];
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if p_expected_user is null or v_uid <> p_expected_user then
    raise exception 'auth session changed before telemetry consent mutation';
  end if;
  if p_source is distinct from 'account' then
    raise exception 'authenticated consent source must be account' using errcode = '22023';
  end if;
  if p_consent is null or jsonb_typeof(p_consent) <> 'object' then
    raise exception 'consent must be an object' using errcode = '22023';
  end if;
  if (p_consent - array['essential', 'research', 'ai_prose', 'market', 'v']) <> '{}'::jsonb then
    raise exception 'consent contains unknown keys' using errcode = '22023';
  end if;
  foreach v_key in array array['essential', 'research', 'ai_prose', 'market'] loop
    if jsonb_typeof(p_consent -> v_key) is distinct from 'boolean' then
      raise exception 'consent key % must be boolean', v_key using errcode = '22023';
    end if;
  end loop;
  if jsonb_typeof(p_consent -> 'v') is distinct from 'number'
     or (p_consent ->> 'v')::numeric <> trunc((p_consent ->> 'v')::numeric)
     or (p_consent ->> 'v')::numeric not between 1 and 32767 then
    raise exception 'consent version must be a positive small integer' using errcode = '22023';
  end if;

  select telemetry_consent into v_old from public.profiles where id = v_uid for update;
  if not found then raise exception 'profile not found'; end if;
  foreach v_key in array array['essential', 'research', 'ai_prose', 'market'] loop
    if coalesce((v_old ->> v_key)::boolean, false)
       is distinct from (p_consent ->> v_key)::boolean then
      v_changed := array_append(v_changed, v_key);
    end if;
  end loop;

  perform set_config('app.telemetry_consent_source', 'account', true);
  update public.profiles
     set telemetry_consent = p_consent,
         updated_at = now()
   where id = v_uid;

  return jsonb_build_object(
    'ok', true,
    'consent', p_consent,
    'changed_keys', to_jsonb(v_changed)
  );
exception when invalid_text_representation then
  raise exception 'consent flags and version must have valid scalar types'
    using errcode = '22023';
end;

insert_operator_direct_message(p_actor u:
declare
  v_id uuid;
  v_subject text := nullif(btrim(coalesce(p_subject, '')), '');
  v_body text := nullif(btrim(coalesce(p_body, '')), '');
  v_template text := coalesce(nullif(btrim(p_template), ''), 'custom_service');
  v_template_class text;
begin
  if p_target is null then raise exception 'target is required'; end if;
  if not exists (select 1 from public.profiles where id = p_target and deleted_at is null) then
    raise exception 'target profile not found or deleted';
  end if;
  if p_sender_role not in ('admin', 'developer', 'system') then
    raise exception 'invalid sender role' using errcode = '22023';
  end if;
  if p_class not in ('service', 'announcement') then
    raise exception 'invalid message class' using errcode = '22023';
  end if;
  if v_subject is null or length(v_subject) > 160 then
    raise exception 'subject must be between 1 and 160 characters' using errcode = '22023';
  end if;
  if v_body is null or length(v_body) > 10000 then
    raise exception 'body must be between 1 and 10000 characters' using errcode = '22023';
  end if;
  v_template_class := public.operator_message_class_for_template(v_template);
  if v_template_class is null then
    raise exception 'unknown operator message template: %', v_template using errcode = '22023';
  end if;
  if v_template_class is distinct from p_class then
    raise exception 'operator message template % requires class %, not %',
      v_template, v_template_class, p_class using errcode = '22023';
  end if;

  insert into public.operator_messages (
    kind, message_class, sender_role, sender_user_id, recipient_user_id,
    subject, body, template_key, status, sent_at
  ) values (
    'direct', p_class, p_sender_role, p_actor, p_target,
    v_subject, v_body, v_template, 'sent', now()
  ) returning id into v_id;

  insert into public.operator_message_receipts (message_id, user_id)
  values (v_id, p_target);
  return v_id;
end;

create_operator_direct_message(p_actor u:
declare
  v_role text;
  v_id uuid;
begin
  select role into v_role from public.profiles where id = p_actor;
  if v_role not in ('admin', 'developer') then
    raise exception 'not authorized: direct operator messages require admin or developer';
  end if;
  if not public.account_is_active(p_actor) then
    raise exception 'operator account is not active';
  end if;
  v_id := public.insert_operator_direct_message(
    p_actor, p_target, v_role, p_class, p_subject, p_body, p_template
  );
  perform public.write_audit(
    p_action => 'create_operator_direct_message',
    p_target_user_id => p_target,
    p_target_type => 'operator_message',
    p_target_id => v_id::text,
    p_after => jsonb_build_object(
      'class', p_class,
      'template', coalesce(nullif(btrim(p_template), ''), 'custom_service')
    ),
    p_user_notified => true,
    p_actor_id => p_actor
  );
  return jsonb_build_object(
    'message_id', v_id,
    'recipient_user_id', p_target,
    'email_status', 'pending'
  );
end;

list_my_operator_messages(p_limit intege:
declare
  v_uid uuid := auth.uid();
  v_limit integer := greatest(1, least(coalesce(p_limit, 100), 200));
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if (p_before_created_at is null) <> (p_before_id is null) then
    raise exception 'message cursor must be wholly null or wholly present'
      using errcode = '22023';
  end if;
  perform public.materialize_my_operator_broadcast_receipts(v_uid);
  return query
    select m.id, m.kind, m.message_class, m.sender_role, m.subject, m.body,
           m.template_key, m.created_at, r.delivered_at, r.read_at,
           r.dismissed_at, r.email_status
      from public.operator_message_receipts r
      join public.operator_messages m on m.id = r.message_id
       where r.user_id = v_uid
         and r.dismissed_at is null
       and (
         p_before_created_at is null
         or (m.created_at, m.id) < (p_before_created_at, p_before_id)
       )
     order by m.created_at desc, m.id desc
     limit v_limit;
end;

get_my_operator_message(p_message_id uui:
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  perform public.materialize_my_operator_broadcast_receipts(v_uid);
  return query
    select m.id, m.kind, m.message_class, m.sender_role, m.subject, m.body,
           m.template_key, m.created_at, r.delivered_at, r.read_at,
           r.dismissed_at, r.email_status
      from public.operator_message_receipts r
      join public.operator_messages m on m.id = r.message_id
     where r.user_id = v_uid and m.id = p_message_id;
end;

mark_operator_message_read(p_message_id:
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  perform public.materialize_my_operator_broadcast_receipts(v_uid);
  update public.operator_message_receipts r
     set read_at = coalesce(r.read_at, now())
   where r.message_id = p_message_id and r.user_id = v_uid;
  return query select * from public.get_my_operator_message(p_message_id);
end;

dismiss_operator_message(p_message_id uu:
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  perform public.materialize_my_operator_broadcast_receipts(v_uid);
  update public.operator_message_receipts r
     set read_at = coalesce(r.read_at, now()),
         dismissed_at = coalesce(r.dismissed_at, now())
   where r.message_id = p_message_id and r.user_id = v_uid;
  return query select * from public.get_my_operator_message(p_message_id);
end;

get_my_operator_unread_count():
declare
  v_uid uuid := auth.uid();
  v_count integer;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  perform public.materialize_my_operator_broadcast_receipts(v_uid);
  select count(*)::integer into v_count
    from public.operator_message_receipts r
   where r.user_id = v_uid and r.read_at is null and r.dismissed_at is null;
  return v_count;
end;

get_my_operator_service_export():
declare
  v_uid uuid := auth.uid();
  v_messages jsonb;
  v_consent jsonb;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  perform public.materialize_my_operator_broadcast_receipts(v_uid);
  select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at, x.id), '[]'::jsonb)
    into v_messages
    from (
      select m.id, m.kind, m.message_class, m.sender_role, m.subject, m.body,
             m.template_key, m.created_at, r.delivered_at, r.read_at, r.dismissed_at,
             r.email_status, r.email_delivered_at
        from public.operator_message_receipts r
        join public.operator_messages m on m.id = r.message_id
       where r.user_id = v_uid
    ) x;
  select coalesce(jsonb_agg(to_jsonb(c) order by c.created_at, c.id), '[]'::jsonb)
    into v_consent
    from (
      select r.id, r.consent_key, r.prior_value, r.new_value,
             r.consent_model_version, r.source, r.created_at
        from public.consent_change_records r
       where r.user_id = v_uid
    ) c;
  return jsonb_build_object(
    'operator_messages', v_messages,
    'consent_changes', v_consent
  );
end;

issue_warning_with_message(p_actor uuid,:
declare
  v_warning uuid;
  v_message uuid;
  v_severity text := coalesce(nullif(btrim(p_severity), ''), 'notice');
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  if not public.has_role(p_actor, array['support', 'admin', 'developer']) then
    raise exception 'not authorized';
  end if;
  if not public.account_is_active(p_actor) then
    raise exception 'operator account is not active';
  end if;
  if v_severity not in ('notice', 'minor', 'major', 'final') then
    raise exception 'invalid severity: %', v_severity;
  end if;
  if v_reason is null then raise exception 'a warning reason is required'; end if;
  insert into public.warnings (user_id, issued_by, severity, reason, user_notified)
  values (p_target, p_actor, v_severity, v_reason, true)
  returning id into v_warning;
  v_message := public.insert_operator_direct_message(
    p_actor, p_target, 'system', 'service', p_message_subject, p_message_body, 'warning'
  );
  perform public.write_audit(
    p_action => 'issue_warning', p_target_user_id => p_target,
    p_target_type => 'warning', p_target_id => v_warning::text,
    p_reason => v_reason,
    p_after => jsonb_build_object('severity', v_severity, 'message_id', v_message),
    p_user_notified => true, p_actor_id => p_actor
  );
  return jsonb_build_object('warning_id', v_warning, 'message_id', v_message);
end;

set_account_banned_with_message(p_actor:
declare
  v_was_banned boolean;
  v_message uuid;
begin
  if not public.has_role(p_actor, array['admin', 'developer']) then
    raise exception 'not authorized: banning an account requires admin or developer';
  end if;
  if not public.account_is_active(p_actor) then
    raise exception 'operator account is not active';
  end if;
  if p_banned is null then raise exception 'banned flag is required'; end if;
  select banned_at is not null into v_was_banned
    from public.profiles where id = p_target for update;
  if not found then raise exception 'target profile not found'; end if;

  update public.profiles
     set banned_at = case when p_banned then now() else null end,
         updated_at = now()
   where id = p_target;
  if p_banned then
    v_message := public.insert_operator_direct_message(
      p_actor, p_target, 'system', 'service', p_message_subject, p_message_body, 'ban_notice'
    );
  end if;
  perform public.write_audit(
    p_action => case when p_banned then 'ban_account' else 'unban_account' end,
    p_target_user_id => p_target,
    p_target_type => 'profile', p_target_id => p_target::text,
    p_reason => nullif(btrim(coalesce(p_reason, '')), ''),
    p_before => jsonb_build_object('banned', v_was_banned),
    p_after => jsonb_build_object('banned', p_banned, 'message_id', v_message),
    p_user_notified => p_banned, p_actor_id => p_actor
  );
  return jsonb_build_object('banned', p_banned, 'message_id', v_message);
end;

queue_operator_broadcast(p_actor uuid, p:
declare
  v_role text;
  v_id uuid;
  v_job uuid;
  v_now timestamptz := now();
  v_send_after timestamptz := v_now + interval '5 minutes';
  v_count integer;
  v_subject text := nullif(btrim(coalesce(p_subject, '')), '');
  v_body text := nullif(btrim(coalesce(p_body, '')), '');
  v_template text := coalesce(nullif(btrim(p_template), ''), 'custom_service');
  v_template_class text;
begin
  select role into v_role from public.profiles where id = p_actor;
  if v_role not in ('admin', 'developer') then raise exception 'not authorized'; end if;
  if not public.account_is_active(p_actor) then raise exception 'operator account is not active'; end if;
  if p_audience is distinct from 'all' then raise exception 'broadcast audience must be all'; end if;
  if p_two_key_amr_age_s is null or p_two_key_amr_age_s not between 0 and 300 then
    raise exception 'fresh password verification is required';
  end if;
  if p_class not in ('service', 'announcement') then raise exception 'invalid message class'; end if;
  if v_subject is null or length(v_subject) > 160 then raise exception 'invalid subject'; end if;
  if v_body is null or length(v_body) > 10000 then raise exception 'invalid body'; end if;
  v_template_class := public.operator_message_class_for_template(v_template);
  if v_template_class is null then
    raise exception 'unknown operator message template: %', v_template using errcode = '22023';
  end if;
  if v_template_class is distinct from p_class then
    raise exception 'operator message template % requires class %, not %',
      v_template, v_template_class, p_class using errcode = '22023';
  end if;

  select count(*)::integer into v_count
    from public.profiles p
   where p.created_at <= v_now and p.deleted_at is null;
  insert into public.operator_messages (
    kind, message_class, sender_role, sender_user_id, subject, body, template_key,
    audience, status, audience_snapshot_at, audience_count, created_at, send_after
  ) values (
    'broadcast', p_class, v_role, p_actor, v_subject, v_body, v_template,
    'all', 'queued', v_now, v_count, v_now, v_send_after
  ) returning id into v_id;
  insert into public.operator_message_delivery_jobs (
    message_id, audience_snapshot_at, next_attempt_at
  ) values (v_id, v_now, v_send_after)
  returning id into v_job;
  perform public.write_audit(
    p_action => 'queue_operator_broadcast', p_target_type => 'operator_message',
    p_target_id => v_id::text,
    p_after => jsonb_build_object(
      'class', p_class, 'template', v_template, 'audience', 'all',
      'audience_count', v_count, 'job_id', v_job, 'send_after', v_send_after
    ),
    p_user_notified => false, p_actor_id => p_actor
  );
  return jsonb_build_object(
    'message_id', v_id, 'job_id', v_job, 'status', 'queued',
    'send_after', v_send_after, 'audience_count', v_count
  );
end;

cancel_operator_broadcast(p_actor uuid,:
declare
  v_now timestamptz := now();
begin
  if not public.has_role(p_actor, array['admin', 'developer']) then
    raise exception 'not authorized';
  end if;
  if not public.account_is_active(p_actor) then raise exception 'operator account is not active'; end if;
  update public.operator_messages
     set status = 'canceled', canceled_at = v_now
   where id = p_message_id and kind = 'broadcast' and status = 'queued'
     and v_now < send_after;
  if not found then raise exception 'broadcast is not cancelable'; end if;
  update public.operator_message_delivery_jobs
     set status = 'canceled', completed_at = v_now, updated_at = v_now,
         lease_token = null, lease_expires_at = null
   where message_id = p_message_id;
  perform public.write_audit(
    p_action => 'cancel_operator_broadcast', p_target_type => 'operator_message',
    p_target_id => p_message_id::text,
    p_after => jsonb_build_object('status', 'canceled'), p_actor_id => p_actor
  );
  return jsonb_build_object(
    'message_id', p_message_id, 'status', 'canceled', 'canceled_at', v_now
  );
end;

claim_operator_message_delivery_jobs(p_l:
declare
  r record;
  v_limit integer := greatest(1, least(coalesce(p_limit, 4), 25));
  v_lease integer := greatest(30, least(coalesce(p_lease_seconds, 240), 900));
  v_token uuid;
begin
  for r in
    select j.id, j.message_id, j.audience_snapshot_at, j.attempts,
           j.status as prior_status, j.lease_token as prior_lease_token,
           j.cursor_created_at, j.cursor_user_id,
           m.message_class, m.subject, m.body
      from public.operator_message_delivery_jobs j
      join public.operator_messages m on m.id = j.message_id
     where m.kind = 'broadcast'
       and m.status in ('queued', 'sending')
       and m.send_after <= now()
       and (
         (j.status in ('pending', 'retry') and j.next_attempt_at <= now())
         or (j.status = 'processing' and j.lease_expires_at <= now())
       )
     order by j.next_attempt_at, j.created_at, j.id
     limit v_limit
     for update of j skip locked
  loop
    -- Taking over an expired job lease must never make an in-flight provider
    -- attempt eligible again. The old worker may have reached the provider even
    -- if it never recorded a result, so the only honest terminal state is
    -- delivery_outcome_unknown. The job row is already locked; result recording
    -- takes the same lock first, making the late-result/takeover race atomic.
    if r.prior_status = 'processing' then
      update public.operator_message_receipts receipt
         set email_status = 'failed',
             email_delivered_at = null,
             email_failure_reason = 'delivery_outcome_unknown',
             email_attempt_token = null,
             email_job_lease_token = null
       where receipt.message_id = r.message_id
         and receipt.email_status = 'sending'
         and receipt.email_job_lease_token = r.prior_lease_token;
    end if;

    -- A worker that crashes while holding its eighth lease must not strand the
    -- row in expired `processing` forever. Retire it before considering another
    -- claim; the in-account broadcast remains authoritative and visible.
    if r.attempts >= 8 then
      update public.operator_message_delivery_jobs j
         set status = 'failed', lease_token = null, lease_expires_at = null,
             last_error = coalesce(j.last_error, 'delivery lease expired at retry limit'),
             updated_at = now()
       where j.id = r.id;
      update public.operator_messages
         set status = 'sent', sent_at = now()
       where id = r.message_id and status in ('queued', 'sending');
      continue;
    end if;
    v_token := gen_random_uuid();
    update public.operator_message_delivery_jobs j
       set status = 'processing', lease_token = v_token,
           lease_expires_at = now() + make_interval(secs => v_lease),
           attempts = j.attempts + 1, updated_at = now(), last_error = null
     where j.id = r.id;
    update public.operator_messages
       set status = 'sending'
     where id = r.message_id and status = 'queued';
    job_id := r.id;
    message_id := r.message_id;
    lease_token := v_token;
    message_class := r.message_class;
    subject := r.subject;
    body := r.body;
    audience_snapshot_at := r.audience_snapshot_at;
    cursor_created_at := r.cursor_created_at;
    cursor_user_id := r.cursor_user_id;
    return next;
  end loop;
end;

renew_operator_message_delivery_job_leas:
declare
  v_job public.operator_message_delivery_jobs%rowtype;
  v_lease integer := greatest(30, least(coalesce(p_lease_seconds, 240), 900));
  v_expires timestamptz;
begin
  select * into v_job
    from public.operator_message_delivery_jobs
   where id = p_job_id
   for update;
  if not found
     or v_job.status <> 'processing'
     or v_job.lease_token is distinct from p_lease_token
     or v_job.lease_expires_at <= now() then
    raise exception 'delivery job lease is not active';
  end if;
  v_expires := now() + make_interval(secs => v_lease);
  update public.operator_message_delivery_jobs
     set lease_expires_at = v_expires, updated_at = now()
   where id = p_job_id;
  return jsonb_build_object(
    'job_id', p_job_id,
    'lease_token', p_lease_token,
    'lease_expires_at', v_expires
  );
end;

claim_operator_message_recipient(p_job_i:
declare
  v_job public.operator_message_delivery_jobs%rowtype;
  v_recipient record;
  v_reason text;
  v_attempt uuid := gen_random_uuid();
  v_idempotency uuid;
begin
  -- Lock job before receipt everywhere in this state machine. A late terminal
  -- result and an expired-lease takeover therefore cannot each win half a race.
  select j.* into v_job
    from public.operator_message_delivery_jobs j
    join public.operator_messages m on m.id = j.message_id
   where j.id = p_job_id and m.kind = 'broadcast'
   for update of j;
  if not found
     or v_job.status <> 'processing'
     or v_job.lease_token is distinct from p_lease_token
     or v_job.lease_expires_at <= now() then
    raise exception 'delivery job lease is not active';
  end if;
  if p_user_id is null then raise exception 'recipient is required'; end if;

  -- Consent and account status are checked at the attempt boundary, not trusted
  -- from the earlier discovery page. An unsubscribe between page and send wins.
  select p.email as account_email, p.disabled_at, p.banned_at,
         m.message_class,
         ep.product_updates, ep.product_updates_decided_at,
         ep.unsubscribe_token as account_unsubscribe_token
    into v_recipient
    from public.profiles p
    join public.operator_messages m on m.id = v_job.message_id
    left join public.email_preferences ep on ep.user_id = p.id
   where p.id = p_user_id
     and p.created_at <= v_job.audience_snapshot_at
     and p.deleted_at is null;

  claimed := false;
  attempt_token := null;
  email := null;
  unsubscribe_token := null;
  email_idempotency_key := null;
  if not found then return next; return; end if;

  v_reason := case
    when v_recipient.account_email is null
         or position('@' in v_recipient.account_email) = 0
      then 'no_email_on_account'
    when v_recipient.disabled_at is not null or v_recipient.banned_at is not null
      then 'account_inactive'
    when v_recipient.message_class = 'announcement'
         and not coalesce(
           v_recipient.product_updates
           and v_recipient.product_updates_decided_at is not null,
           false
         )
      then 'announcement_opt_out'
    when v_recipient.message_class = 'announcement'
         and v_recipient.account_unsubscribe_token is null
      then 'unsubscribe_token_unavailable'
    else null
  end;

  if v_reason is not null then
    update public.operator_message_receipts receipt
       set email_status = 'skipped',
           email_attempted_at = now(),
           email_delivered_at = null,
           email_failure_reason = v_reason,
           email_attempt_token = null,
           email_job_lease_token = null
     where receipt.message_id = v_job.message_id
       and receipt.user_id = p_user_id
       and receipt.email_status = 'pending';
    return next;
    return;
  end if;

  update public.operator_message_receipts receipt
     set email_status = 'sending',
         email_attempted_at = now(),
         email_delivered_at = null,
         email_failure_reason = null,
         email_attempt_token = v_attempt,
         email_job_lease_token = p_lease_token
   where receipt.message_id = v_job.message_id
     and receipt.user_id = p_user_id
     and receipt.email_status = 'pending'
  returning receipt.email_idempotency_key into v_idempotency;
  if not found then return next; return; end if;

  claimed := true;
  attempt_token := v_attempt;
  email := v_recipient.account_email;
  unsubscribe_token := case
    when v_recipient.message_class = 'announcement'
      then v_recipient.account_unsubscribe_token
    else null
  end;
  email_idempotency_key := v_idempotency;
  return next;
end;

record_operator_message_email_result(p_m:
declare
  v_status text;
  v_kind text;
  v_reason text := nullif(btrim(coalesce(p_failure_reason, '')), '');
  v_now timestamptz := now();
begin
  if p_status not in ('sent', 'failed', 'skipped') then
    raise exception 'invalid email result status';
  end if;
  if p_status <> 'sent' and v_reason is null then
    raise exception 'a failure reason is required';
  end if;
  if length(coalesce(p_provider, '')) > 80
     or length(coalesce(p_provider_id, '')) > 255
     or length(coalesce(v_reason, '')) > 500 then
    raise exception 'email result metadata is too long';
  end if;
  select m.kind into v_kind
    from public.operator_messages m
   where m.id = p_message_id;
  if v_kind = 'broadcast' then
    raise exception 'broadcast email results require a lease-bound delivery attempt';
  end if;
  update public.operator_message_receipts r
     set email_status = p_status,
         email_attempted_at = v_now,
         email_delivered_at = case when p_status = 'sent' then v_now else null end,
         email_provider = nullif(btrim(coalesce(p_provider, '')), ''),
         email_provider_id = nullif(btrim(coalesce(p_provider_id, '')), ''),
         email_failure_reason = case when p_status = 'sent' then null else v_reason end
   where r.message_id = p_message_id and r.user_id = p_user_id
     and v_kind = 'direct'
     and r.email_status = 'pending';
  if not found then
    -- Account deletion can race an external send, and a worker retry can replay a
    -- page after its prior results committed. Never recreate a purged receipt and
    -- never downgrade a terminal result.
    select r.email_status, r.email_delivered_at into v_status, v_now
      from public.operator_message_receipts r
     where r.message_id = p_message_id and r.user_id = p_user_id;
    return jsonb_build_object(
      'recorded', false, 'message_id', p_message_id, 'user_id', p_user_id,
      'email_status', v_status, 'email_delivered_at', v_now
    );
  end if;
  v_status := p_status;
  return jsonb_build_object(
    'recorded', true, 'message_id', p_message_id, 'user_id', p_user_id,
    'email_status', v_status,
    'email_delivered_at', case when p_status = 'sent' then v_now else null end
  );
end;

record_operator_message_delivery_result(:
declare
  v_job public.operator_message_delivery_jobs%rowtype;
  v_reason text := nullif(btrim(coalesce(p_failure_reason, '')), '');
  v_now timestamptz := now();
begin
  if p_status not in ('sent', 'failed', 'skipped') then
    raise exception 'invalid email result status';
  end if;
  if p_status <> 'sent' and v_reason is null then
    raise exception 'a failure reason is required';
  end if;
  if p_attempt_token is null then raise exception 'attempt token is required'; end if;
  if length(coalesce(p_provider, '')) > 80
     or length(coalesce(p_provider_id, '')) > 255
     or length(coalesce(v_reason, '')) > 500 then
    raise exception 'email result metadata is too long';
  end if;

  -- Deliberately do not reject solely because lease_expires_at passed. The job
  -- lock serializes this with takeover: a valid late provider result may win up
  -- to the instant a reclaimer terminalizes it as delivery_outcome_unknown.
  select j.* into v_job
    from public.operator_message_delivery_jobs j
    join public.operator_messages m on m.id = j.message_id
   where j.id = p_job_id and m.kind = 'broadcast'
   for update of j;
  if not found
     or v_job.status <> 'processing'
     or v_job.lease_token is distinct from p_lease_token then
    raise exception 'delivery job attempt is not current';
  end if;

  update public.operator_message_receipts receipt
     set email_status = p_status,
         email_delivered_at = case when p_status = 'sent' then v_now else null end,
         email_provider = nullif(btrim(coalesce(p_provider, '')), ''),
         email_provider_id = nullif(btrim(coalesce(p_provider_id, '')), ''),
         email_failure_reason = case when p_status = 'sent' then null else v_reason end,
         email_attempt_token = null,
         email_job_lease_token = null
   where receipt.message_id = v_job.message_id
     and receipt.user_id = p_user_id
     and receipt.email_status = 'sending'
     and receipt.email_attempt_token = p_attempt_token
     and receipt.email_job_lease_token = p_lease_token;
  if not found then
    raise exception 'recipient delivery attempt is not active';
  end if;

  return jsonb_build_object(
    'recorded', true,
    'job_id', p_job_id,
    'message_id', v_job.message_id,
    'user_id', p_user_id,
    'email_status', p_status,
    'email_delivered_at', case when p_status = 'sent' then v_now else null end
  );
end;

advance_operator_message_delivery_job(p_:
declare
  v_job public.operator_message_delivery_jobs%rowtype;
  v_now timestamptz := now();
begin
  select * into v_job from public.operator_message_delivery_jobs
   where id = p_job_id for update;
  if not found or v_job.status <> 'processing'
     or v_job.lease_token is distinct from p_lease_token
     or v_job.lease_expires_at <= v_now then
    raise exception 'delivery job lease is not active';
  end if;
  if (p_cursor_created_at is null) <> (p_cursor_user_id is null) then
    raise exception 'recipient cursor must be wholly null or wholly present';
  end if;
  if v_job.cursor_created_at is not null and p_cursor_created_at is not null
     and (p_cursor_created_at, p_cursor_user_id)
         < (v_job.cursor_created_at, v_job.cursor_user_id) then
    raise exception 'recipient cursor cannot move backward';
  end if;
  if coalesce(p_done, false) is false
     and (p_cursor_created_at is null
          or (p_cursor_created_at, p_cursor_user_id)
             is not distinct from (v_job.cursor_created_at, v_job.cursor_user_id)) then
    raise exception 'an unfinished page must advance the recipient cursor';
  end if;
  if exists (
    select 1
      from public.operator_message_receipts receipt
     where receipt.message_id = v_job.message_id
       and receipt.email_status = 'sending'
  ) then
    raise exception 'recipient delivery attempt is still in flight';
  end if;

  update public.operator_message_delivery_jobs
     set status = case when coalesce(p_done, false) then 'completed' else 'pending' end,
         cursor_created_at = p_cursor_created_at,
         cursor_user_id = p_cursor_user_id,
         lease_token = null, lease_expires_at = null,
         -- attempts counts consecutive failures at this cursor, not successful
         -- pages. Without this reset a healthy broadcast would be retired after
         -- eight batches (800 recipients at the default page size).
         attempts = 0,
         next_attempt_at = v_now, last_error = null,
         completed_at = case when coalesce(p_done, false) then v_now else null end,
         updated_at = v_now
   where id = p_job_id;
  if coalesce(p_done, false) then
    update public.operator_messages
       set status = 'sent', sent_at = v_now
     where id = v_job.message_id and status = 'sending';
  end if;
  return jsonb_build_object(
    'job_id', p_job_id,
    'status', case when coalesce(p_done, false) then 'completed' else 'pending' end,
    'cursor_created_at', p_cursor_created_at,
    'cursor_user_id', p_cursor_user_id,
    'completed_at', case when coalesce(p_done, false) then v_now else null end
  );
end;

fail_operator_message_delivery_job(p_job:
declare
  v_job public.operator_message_delivery_jobs%rowtype;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_status text;
  v_next timestamptz;
begin
  if v_reason is null or length(v_reason) > 500 then
    raise exception 'failure reason must be between 1 and 500 characters';
  end if;
  select * into v_job from public.operator_message_delivery_jobs
   where id = p_job_id for update;
  if not found or v_job.status <> 'processing'
     or v_job.lease_token is distinct from p_lease_token
     or v_job.lease_expires_at <= now() then
    raise exception 'delivery job lease is not active';
  end if;
  -- Releasing a job that owns a provider attempt cannot put that attempt back on
  -- the queue. Whether the provider accepted it is unknowable, so fail closed.
  update public.operator_message_receipts receipt
     set email_status = 'failed',
         email_delivered_at = null,
         email_failure_reason = 'delivery_outcome_unknown',
         email_attempt_token = null,
         email_job_lease_token = null
   where receipt.message_id = v_job.message_id
     and receipt.email_status = 'sending'
     and receipt.email_job_lease_token = p_lease_token;
  v_status := case when v_job.attempts >= 8 then 'failed' else 'retry' end;
  v_next := now() + make_interval(
    secs => least(3600, (30 * power(2::numeric, greatest(v_job.attempts - 1, 0)))::integer)
  );
  update public.operator_message_delivery_jobs
     set status = v_status, lease_token = null, lease_expires_at = null,
         last_error = v_reason, next_attempt_at = v_next, updated_at = now()
   where id = p_job_id;
  if v_status = 'failed' then
    update public.operator_messages
       set status = 'sent', sent_at = now()
     where id = v_job.message_id and status = 'sending';
  end if;
  return jsonb_build_object(
    'job_id', p_job_id, 'status', v_status,
    'attempt_count', v_job.attempts,
    'next_attempt_at', v_next, 'last_error', v_reason
  );
end;

purge_operator_records_on_profile_deleti:
begin
  if old.deleted_at is null and new.deleted_at is not null then
    delete from public.operator_message_receipts where user_id = new.id;
    delete from public.operator_messages
