run_operator_message_delivery():
declare
  v_config jsonb;
  v_request bigint;
begin
  select value into v_config from public.system_config
   where key = 'operator_message_delivery_cron';
  if v_config is null then return 'not_configured'; end if;
  if coalesce((v_config ->> 'enabled')::boolean, false) is not true then return 'disabled'; end if;
  if nullif(btrim(v_config ->> 'url'), '') is null
     or nullif(btrim(v_config ->> 'secret'), '') is null then
    return 'not_configured';
  end if;
  begin
    select net.http_post(
      url := v_config ->> 'url',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'x-cron-secret', v_config ->> 'secret'
      ),
      body := '{}'::jsonb
    ) into v_request;
  exception when undefined_function or undefined_table or invalid_schema_name then
    return 'pg_net_unavailable';
  end;
  return 'dispatched:' || coalesce(v_request::text, 'unknown');
exception when invalid_text_representation then
  return 'not_configured';
end;

civility_blocked(p_text text):
declare
  toks       text[];
  cands      text[] := '{}';
  tok        text;
  joined     text;
  i          int;
  j          int;
  n          int;
  run_end    int;
begin
  if coalesce(p_text, '') = '' then
    return false;
  end if;

  -- Tokenize the normalized text on any non-alphanumeric run.
  toks := array_remove(
            regexp_split_to_array(public.civility_normalize(p_text), '[^a-z0-9]+'),
            '');
  n := coalesce(array_length(toks, 1), 0);
  if n = 0 then
    return false;
  end if;

  cands := toks;

  -- Re-join runs of SHORT adjacent tokens, so `f u c k`, `fu ck` and `sh it` are
  -- candidates too. All contiguous sub-runs, not just maximal ones, so a fragment
  -- sitting inside a longer run of short words is still found.
  i := 1;
  while i <= n loop
    if char_length(toks[i]) > 2 then
      i := i + 1;
      continue;
    end if;
    run_end := i;
    while run_end < n and char_length(toks[run_end + 1]) <= 2 loop
      run_end := run_end + 1;
    end loop;
    for j in i .. run_end loop
      joined := toks[j];
      for k in (j + 1) .. least(run_end, j + 7) loop
        joined := joined || toks[k];
        cands := array_append(cands, joined);
      end loop;
    end loop;
    i := run_end + 1;
  end loop;

  foreach tok in array cands loop
    -- The allowlist wins outright (§9's known-collision escape hatch).
    if exists (select 1 from public.civility_allow a where a.term = tok) then
      continue;
    end if;
    if public._civility_token_hits(tok) then
      return true;
    end if;
  end loop;

  return false;
end;

_civility_token_hits(p_token text):
declare
  suffixes constant text[] := array['s','es','ed','er','ers','ing','ings','y','ty'];
  sfx      text;
  stem     text;
begin
  if coalesce(p_token, '') = '' then
    return false;
  end if;
  if public._civility_stem_hits(p_token) then
    return true;
  end if;
  foreach sfx in array suffixes loop
    if char_length(p_token) > char_length(sfx) and p_token like ('%' || sfx) then
      stem := left(p_token, char_length(p_token) - char_length(sfx));
      -- Both the bare stem and the stem with its silent `e` restored: English
      -- drops a final `e` before a vowel-initial suffix, so `rape` + `ing` is
      -- spelled `raping` and stripping `ing` alone yields `rap`, which matches
      -- nothing. Every inflected form of an e-final entry needs this.
      if public._civility_stem_hits(stem) or public._civility_stem_hits(stem || 'e') then
        return true;
      end if;
    end if;
  end loop;
  return false;
end;

_civility_stem_hits(p_stem text):
select exists (
  select 1
  from public.civility_terms t
  where t.term = p_stem
     or (
       regexp_replace(p_stem,  '(.)\1+', '\1', 'g')
         = regexp_replace(t.term, '(.)\1+', '\1', 'g')
       and char_length(p_stem) >= char_length(t.term)
     )
);

append_retention_cohorts(p_day date):
declare v_rows integer := 0;
begin
  insert into public.analytics_retention_cohorts (cohort_day, day_offset, actors, updated_at)
  select c.cohort_day, (p_day - c.cohort_day)::integer, count(*)::bigint, now()
    from (
      -- one row per actor active on p_day, carrying its first-contact day
      select a.actor_id, min(l.minted_at)::date as cohort_day
        from (
          select distinct e.actor_id
            from public.analytics_events e
           where e.actor_id is not null
             and e.created_at::date = p_day
        ) a
        join (
          select actor_id, created_at as minted_at from public.analytics_device_links
          union all
          select actor_id, created_at from public.analytics_identity_links
        ) l on l.actor_id = a.actor_id
       group by a.actor_id
    ) c
   where c.cohort_day <= p_day
   group by c.cohort_day
      on conflict (cohort_day, day_offset)
      do update set actors = excluded.actors, updated_at = excluded.updated_at;
  get diagnostics v_rows = row_count;
  return v_rows;
end;
